import re
import time

L2D = {"O": "0", "o": "0", "l": "1", "I": "1", "i": "1", "S": "5", "s": "5", "B": "8",
       "Z": "2", "z": "2", "G": "6", "D": "0", "Q": "0"}
D2L = {"0": "O", "1": "I", "5": "S", "8": "B", "2": "Z", "6": "G"}
# observed digit -> possible true digits (reverse of misread table)
REV = {"6": "05", "8": "03", "7": "12", "4": "19", "9": "34", "1": "47", "3": "589",
       "5": "6", "0": "68", "2": "7"}
DIG = "0123456789"
BIG = 3.0
MISS = 2.5


def _edits1(s):
    out = []
    n = len(s)
    for i in range(n):
        ch = s[i]
        if ch.isdigit():
            for r in REV.get(ch, ""):
                out.append(s[:i] + r + s[i + 1:])
            if i > 0 and s[i - 1] == ch:
                out.append(s[:i] + s[i + 1:])
    for i in range(n + 1):
        for d in DIG:
            out.append(s[:i] + d + s[i:])
    return out


def _render(cents, mark, grouped, with_mark=True):
    d = str(cents // 100)
    c = "%02d" % (cents % 100)
    if grouped and len(d) > 3:
        parts = []
        while len(d) > 3:
            parts.append(d[-3:])
            d = d[:-3]
        parts.append(d)
        d = "'".join(reversed(parts))
    return d + (mark if with_mark else "") + c


def _norm_num(tok):
    out = []
    for ch in tok:
        if ch.isdigit() or ch in ".,'":
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
    return "".join(out)


def _money_eval(s, c, mark, grouped):
    digits = "".join(ch for ch in s if ch.isdigit())
    nm = sum(1 for ch in s if ch in ".,")
    if nm > 1 or len(digits) < 3:
        return None
    if nm == 1:
        k = max(s.find("."), s.find(","))
        after = sum(1 for ch in s[k + 1:] if ch.isdigit())
        if after != 2:
            return None
    else:
        c += 1.0
    dollars = digits[:-2]
    if len(dollars) > 1 and dollars[0] == "0":
        return None
    v = int(digits)
    if v <= 0:
        return None
    r = _render(v, mark, grouped, nm == 1)
    s2 = s.replace(",", mark).replace(".", mark)
    if r != s2:
        c += 0.4
    return v, c


def money_cands(tok, mark, grouped):
    s = _norm_num(tok or "")
    res = {}
    if not s:
        return res

    def add(x, c):
        e = _money_eval(x, c, mark, grouped)
        if e is not None:
            v, cc = e
            if cc < res.get(v, 99):
                res[v] = cc

    add(s, 0.0)
    for x in _edits1(s):
        add(x, 1.0)
    return res


def qty_cands(tok):
    t = re.sub(r"(?i)\s*pcs?\s*$", "", (tok or "").strip())
    s = "".join(ch for ch in _norm_num(t) if ch.isdigit())
    res = {}
    if not s:
        return res

    def add(x, c):
        if not x or (len(x) > 1 and x[0] == "0"):
            return
        v = int(x)
        if 1 <= v <= 500 and c < res.get(v, 99):
            res[v] = c

    add(s, 0.0)
    for x in _edits1(s):
        add(x, 1.0)
    return res


def _chk(letters, d):
    p1 = ord(letters[0]) - 64 if "A" <= letters[0] <= "Z" else 0
    p2 = ord(letters[1]) - 64 if "A" <= letters[1] <= "Z" else 0
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10


def fix_code(tok):
    t = re.sub(r"[^A-Za-z0-9]", "", tok or "")
    if len(t) < 2:
        return "AA00000"
    lp = ""
    for ch in t[:2]:
        if ch.isdigit():
            lp += D2L.get(ch, "A")
        else:
            lp += ch.upper() if ch != "l" else "I"
    dp = ""
    for ch in t[2:]:
        if ch.isdigit():
            dp += ch
        elif ch in L2D:
            dp += L2D[ch]
    if len(dp) == 5 and _chk(lp, dp) == int(dp[4]):
        return lp + dp
    best = None
    for x in _edits1(dp):
        if len(x) == 5 and _chk(lp, x) == int(x[4]):
            best = x
            break
    if best is None:
        x = dp[:4] if len(dp) >= 4 else (dp + "0000")[:4]
        best = x + str(_chk(lp, x))
    return lp + best


CODE_RE = re.compile(r"^[A-Z0-9]{2}[0-9OlSBZGI]{3,7}$")
NUM_RE = re.compile(r"^[0-9OlSBZGI.,']{1,16}$")


def _plausible(tok):
    t = re.sub(r"\s*pcs$", "", tok)
    return bool(CODE_RE.match(t) or NUM_RE.match(t))


def _fit(tok, col):
    t = tok.strip()
    hasmark = ("." in t) or ("," in t)
    if col == "CODE":
        return 0.0 if CODE_RE.match(t) else 2.0
    if col == "QTY":
        if "pcs" in t:
            return 0.0
        if hasmark:
            return 2.0
        return 0.0 if len(t) <= 4 else 1.5
    if hasmark:
        return 0.0
    if CODE_RE.match(t) and t[:2].isalpha():
        return 2.0
    return 0.5 if len(t) >= 3 else 1.5


def parse(state, params):
    text = (state.get("input") or {}).get("text", "") or ""
    lines = text.split("\n")
    order = ["CODE", "QTY", "UNIT", "AMOUNT"]
    sep = None
    for ln in lines:
        if ln.strip().startswith("COLUMNS"):
            body = ln.split(":", 1)[1] if ":" in ln else ln[7:]
            names = re.findall(r"CODE|QTY|UNIT|AMOUNT", body)
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            m = re.search(r"(CODE|QTY|UNIT|AMOUNT)(.*?)(CODE|QTY|UNIT|AMOUNT)", body)
            if m:
                between = m.group(2)
                if "|" in between:
                    sep = "|"
                elif ";" in between:
                    sep = ";"
                elif "\t" in between:
                    sep = "\t"
                else:
                    sep = "   "
            break
    if sep is None:
        if any("|" in l for l in lines):
            sep = "|"
        elif any(";" in l for l in lines):
            sep = ";"
        elif any("\t" in l for l in lines):
            sep = "\t"
        else:
            sep = "   "

    def split(ln):
        if sep == "|":
            parts = ln.split("|")
        elif sep == ";":
            parts = ln.split(";")
        elif sep == "\t":
            parts = ln.split("\t")
        else:
            parts = re.split(r" {2,}|\t", ln)
        return [p.strip() for p in parts if p.strip()]

    sections = []
    cur = None
    total_tok = None
    items_tok = None
    money_toks = []
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith("MANIFEST") or s.startswith("COLUMNS"):
            continue
        if re.match(r"^==\s*SECTION", s):
            cur = {"tokens": [], "sub": None}
            sections.append(cur)
            continue
        if s.startswith("SUBTOTAL"):
            tok = s[8:].strip()
            if cur is None:
                cur = {"tokens": [], "sub": None}
                sections.append(cur)
            cur["sub"] = tok
            money_toks.append(tok)
            cur = None
            continue
        if s.startswith("TOTAL"):
            m = re.match(r"TOTAL\s+(.*?)\s+ITEMS\s*(.*)$", s)
            if m:
                total_tok = m.group(1).strip()
                items_tok = m.group(2).strip()
            else:
                total_tok = s[5:].strip()
            money_toks.append(total_tok)
            continue
        toks = split(s)
        if not toks or not all(_plausible(t) for t in toks):
            continue
        if cur is None:
            if sections and sections[-1]["sub"] is None:
                cur = sections[-1]
            else:
                cur = {"tokens": [], "sub": None}
                sections.append(cur)
        cur["tokens"].extend(toks)

    allm = list(money_toks)
    for sec in sections:
        allm.extend(sec["tokens"])
    dots = sum(t.count(".") for t in allm)
    commas = sum(t.count(",") for t in allm)
    mark = "," if commas > dots else "."
    grouped = any("'" in t for t in allm)

    out_secs = []
    for sec in sections:
        toks = sec["tokens"]
        n = len(toks)
        INF = 1e18
        dp = [INF] * (n + 1)
        bp = [None] * (n + 1)
        dp[0] = 0.0
        for i in range(n):
            if dp[i] >= INF:
                continue
            c = dp[i] + 3.0
            if c < dp[i + 1]:
                dp[i + 1] = c
                bp[i + 1] = (i, False)
            if i + 4 <= n:
                c = dp[i] + sum(_fit(toks[i + k], order[k]) for k in range(4))
                if c < dp[i + 4]:
                    dp[i + 4] = c
                    bp[i + 4] = (i, True)
        rows = []
        j = n
        while j > 0 and bp[j] is not None:
            i, isrow = bp[j]
            if isrow:
                rows.append(toks[i:i + 4])
            j = i
        rows.reverse()
        prow = []
        for r in rows:
            d = {order[k]: r[k] for k in range(4)}
            prow.append([d["CODE"], d["QTY"], d["UNIT"], d["AMOUNT"]])
        out_secs.append({"rows": prow, "sub": sec["sub"]})
    state["parsed"] = {"sections": out_secs, "total": total_tok, "items": items_tok,
                       "mark": mark, "grouped": grouped}
    return state


def _row_cands(row, mark, grouped):
    Q = qty_cands(row[1])
    U = money_cands(row[2], mark, grouped)
    A = money_cands(row[3], mark, grouped)
    rec = {}

    def put(q, u, c):
        k = (q, u)
        if c < rec.get(k, 99):
            rec[k] = c

    for q, cq in Q.items():
        for u, cu in U.items():
            if cq + cu <= 1.5:
                put(q, u, cq + cu + A.get(q * u, MISS))
    for a, ca in A.items():
        for q, cq in Q.items():
            if ca + cq <= 1.5 and a % q == 0:
                u = a // q
                put(q, u, ca + cq + U.get(u, MISS))
        for u, cu in U.items():
            if ca + cu <= 1.5 and u > 0 and a % u == 0:
                q = a // u
                if 1 <= q <= 500:
                    put(q, u, ca + cu + Q.get(q, MISS))
    if not rec:
        q = min(Q, key=lambda x: Q[x]) if Q else 1
        if U:
            u = min(U, key=lambda x: U[x])
        elif A:
            u = max(1, min(A, key=lambda x: A[x]) // q)
        else:
            u = 100
        rec[(q, u)] = 6.0
    items = sorted(rec.items(), key=lambda kv: kv[1])
    best = items[0][1]
    items = [kv for kv in items if kv[1] <= best + 3.5][:14]
    return [[kv[0][0], kv[0][1], kv[1]] for kv in items]


def solve(state, params):
    P = state["parsed"]
    mark, grouped = P["mark"], P["grouped"]
    sec_opts = []
    sec_data = []
    for sec in P["sections"]:
        cands = [_row_cands(r, mark, grouped) for r in sec["rows"]]
        codes = [fix_code(r[0]) for r in sec["rows"]]
        layers = []
        cur = {0: (0.0, None, None)}
        for ri, cl in enumerate(cands):
            nxt = {}
            for s, (c, _, _) in cur.items():
                for ci, (q, u, cc) in enumerate(cl):
                    ns = s + q * u
                    nc = c + cc
                    old = nxt.get(ns)
                    if old is None or nc < old[0]:
                        nxt[ns] = (nc, s, ci)
            if nxt:
                mn = min(v[0] for v in nxt.values())
                kept = [(k, v) for k, v in nxt.items() if v[0] <= mn + 4.0]
                if len(kept) > 1500:
                    kept.sort(key=lambda kv: kv[1][0])
                    kept = kept[:1500]
                nxt = dict(kept)
            layers.append(nxt)
            cur = nxt
        SUB = money_cands(sec["sub"], mark, grouped) if sec["sub"] else {}
        opts = []
        for s, (c, _, _) in cur.items():
            sc = SUB.get(s, BIG) if sec["sub"] else 0.0
            opts.append((c + sc, s))
        opts.sort()
        opts = opts[:40]
        sec_opts.append(opts)
        sec_data.append((layers, cands, codes))
    TOT = money_cands(P["total"], mark, grouped) if P.get("total") else {}
    comb = {0: (0.0, [])}
    for opts in sec_opts:
        nxt = {}
        for T, (c, path) in comb.items():
            for oc, s in opts:
                nT = T + s
                nc = c + oc
                if nT not in nxt or nc < nxt[nT][0]:
                    nxt[nT] = (nc, path + [s])
        kept = sorted(nxt.items(), key=lambda kv: kv[1][0])[:400]
        comb = dict(kept)
    bestc, bestpath = None, None
    for T, (c, path) in comb.items():
        tc = c + (TOT.get(T, BIG) if P.get("total") else 0.0)
        if bestc is None or tc < bestc:
            bestc, bestpath = tc, path
    items = []
    for si, (layers, cands, codes) in enumerate(sec_data):
        nrow = len(cands)
        choice = [0] * nrow
        if nrow and bestpath is not None and si < len(bestpath):
            s = bestpath[si]
            for ri in range(nrow - 1, -1, -1):
                ent = layers[ri].get(s)
                if ent is None:
                    choice = [0] * nrow
                    break
                choice[ri] = ent[2]
                s = ent[1]
        for ri in range(nrow):
            q, u, _ = cands[ri][choice[ri]]
            items.append({"code": codes[ri], "qty": int(q), "unit_cents": int(u)})
    state["output"] = {"items": items}
    return state

import re
import time

SPLIT_RE = re.compile(r'\s*\|\s*|;|\t| {2,}')
L2D = {'O': '0', 'o': '0', 'D': '0', 'Q': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
       'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', '7': 'T', '4': 'A', '3': 'B', '9': 'G'}
REV = {'6': '05', '8': '03', '7': '12', '4': '19', '9': '34', '1': '47', '3': '589',
       '5': '6', '0': '68', '2': '7'}
COLS = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
W_WILD = 2.5

RE_CODE = re.compile(r'[A-Z0-9]{2}[0-9A-Za-z]{3,7}')
RE_QTY = re.compile(r'[0-9OolISBZG]{1,4}(\s*pcs)?')
RE_MONEY = re.compile(r"[0-9OolISBZG.,']{2,14}")


def digit_edits(s, allow_ins=True):
    out = {s: 0}
    n = len(s)
    for i, ch in enumerate(s):
        if ch.isdigit():
            for y in REV.get(ch, ''):
                v = s[:i] + y + s[i + 1:]
                if v not in out:
                    out[v] = 1
            if i + 1 < n and s[i + 1] == ch:
                v = s[:i] + s[i + 1:]
                if v not in out:
                    out[v] = 1
    if allow_ins:
        for i in range(n + 1):
            for d in '0123456789':
                v = s[:i] + d + s[i:]
                if v not in out:
                    out[v] = 1
    return out


def clean_num(tok):
    return ''.join(L2D.get(c, c) for c in tok)


def parse_money(v):
    if '.' in v:
        a, b = v.split('.', 1)
        if len(b) != 2 or not a or not a.isdigit() or not b.isdigit():
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        return int(a) * 100 + int(b)
    if len(v) < 3 or not v.isdigit():
        return None
    a = v[:-2]
    if len(a) > 1 and a[0] == '0':
        return None
    return int(v)


def money_cands(tok):
    if tok is None:
        return {}
    t = clean_num(tok.replace(' ', ''))
    t = t.replace("'", '')
    t = re.sub(r'[^0-9.,]', '', t)
    t = t.replace(',', '.')
    if t.count('.') > 1:
        k = t.rfind('.')
        t = t[:k].replace('.', '') + t[k:]
    if not t or len(t) > 14:
        return {}
    res = {}
    for v, c in digit_edits(t).items():
        m = parse_money(v)
        if m is not None and m > 0:
            if m not in res or res[m] > c:
                res[m] = c
    return res


def qty_cands(tok):
    if tok is None:
        return {}
    t = re.sub(r'\s*pcs\s*$', '', tok.strip())
    t = clean_num(t)
    t = re.sub(r'[^0-9]', '', t)
    if not t or len(t) > 5:
        return {}
    res = {}
    for v, c in digit_edits(t).items():
        if not v or (len(v) > 1 and v[0] == '0'):
            continue
        q = int(v)
        if 1 <= q <= 500:
            if q not in res or res[q] > c:
                res[q] = c
    return res


def code_valid(L, d):
    if len(d) != 5 or not d.isdigit() or len(L) != 2:
        return False
    p1 = ord(L[0]) - 64
    p2 = ord(L[1]) - 64
    if not (1 <= p1 <= 26 and 1 <= p2 <= 26):
        return False
    s = int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2
    return s % 10 == int(d[4])


def fix_code(tok):
    if tok is None:
        return 'AA00000'
    t = tok.strip().replace(' ', '')
    L = ''
    for ch in t[:2]:
        if ch.isdigit():
            ch = D2L.get(ch, 'A')
        L += ch.upper()
    if len(L) < 2 or not L.isalpha():
        L = (L + 'AA')[:2]
        L = ''.join(c if 'A' <= c <= 'Z' else 'A' for c in L)
    d = re.sub(r'[^0-9]', '', clean_num(t[2:]))
    if code_valid(L, d):
        return L + d
    ed = digit_edits(d)
    for v in ed:
        if code_valid(L, v):
            return L + v
    for v1 in ed:
        if len(v1) < 4 or len(v1) > 6:
            continue
        for v in digit_edits(v1, allow_ins=(len(v1) == 4)):
            if code_valid(L, v):
                return L + v
    if len(d) > 5:
        d = d[:5]
    d = (d + '00000')[:5]
    return L + d


def tok_cost(tok, col, pcs):
    if col == 'CODE':
        if RE_CODE.fullmatch(tok):
            nl = sum(1 for c in tok[:2] if c.isalpha())
            if nl == 2:
                return 0
            if nl == 1:
                return 0.5
            return 2
        return 4
    if col == 'QTY':
        if RE_QTY.fullmatch(tok):
            has = 'pcs' in tok
            if pcs != has:
                return 1
            return 0
        return 4
    if RE_MONEY.fullmatch(tok):
        if re.search(r'[0-9]', tok):
            return 0
        return 1
    return 4


def plausible(tok, pcs):
    return any(tok_cost(tok, c, pcs) <= 2 for c in COLS)


def align(tokens, order, pcs):
    n = len(tokens)
    INF = 1e18
    SKIP, MISS = 3.0, 5.0
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(2):
            for p in range(4):
                if dp[i][p] < INF:
                    q = (p + 1) % 4
                    c = dp[i][p] + MISS
                    if c < dp[i][q] - 1e-9:
                        dp[i][q] = c
                        bk[i][q] = ('m', i, p)
        if i == n:
            break
        for p in range(4):
            if dp[i][p] >= INF:
                continue
            c = dp[i][p] + tok_cost(tokens[i], order[p], pcs)
            q = (p + 1) % 4
            if c < dp[i + 1][q]:
                dp[i + 1][q] = c
                bk[i + 1][q] = ('a', i, p)
            c = dp[i][p] + SKIP
            if c < dp[i + 1][p]:
                dp[i + 1][p] = c
                bk[i + 1][p] = ('s', i, p)
    ops = []
    i, p = n, 0
    guard = 0
    while not (i == 0 and p == 0) and guard < 10 * (n + 5):
        guard += 1
        b = bk[i][p]
        if b is None:
            break
        ops.append(b)
        i, p = b[1], b[2]
    ops.reverse()
    rows = []
    cur = {}
    for kind, ti, pp in ops:
        if kind == 's':
            continue
        col = order[pp]
        cur[col] = tokens[ti] if kind == 'a' else None
        if pp == 3:
            rows.append(cur)
            cur = {}
    out = []
    for r in rows:
        if any(r.get(c) is not None for c in COLS):
            out.append(r)
    return out


def build_triples(Q, U, A):
    trip = {}

    def add(c, q, u, a):
        k = (q, u)
        if k not in trip or trip[k][0] > c:
            trip[k] = (c, q, u, a)

    for q, cq in Q.items():
        for u, cu in U.items():
            c = cq + cu
            a = q * u
            ca = A.get(a)
            if ca is not None:
                add(c + ca, q, u, a)
            elif c == 0:
                add(W_WILD, q, u, a)
    A0 = [a for a, c in A.items() if c == 0]
    Q0 = [q for q, c in Q.items() if c == 0]
    U0 = [u for u, c in U.items() if c == 0]
    for a in A0:
        for q in Q0:
            if a % q == 0:
                add(W_WILD, q, a // q, a)
        for u in U0:
            if u > 0 and a % u == 0 and 1 <= a // u <= 500:
                add(W_WILD, a // u, u, a)
    lst = sorted(trip.values(), key=lambda t: t[0])
    if not lst:
        q = min(Q.items(), key=lambda x: x[1])[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: x[1])[0]
        elif A:
            a = min(A.items(), key=lambda x: x[1])[0]
            u = a // q
        else:
            u = 0
        lst = [(9.0, q, u, q * u)]
    return [list(t) for t in lst[:10]]


def solve_section(rows, S, deadline):
    n = len(rows)
    if n == 0:
        return [], True, 0
    choice = [r['tr'][0] for r in rows]
    total = sum(t[3] for t in choice)
    ccost = sum(t[0] for t in choice)
    if not S:
        return choice, True, total
    if total in S and S[total] == 0:
        return choice, True, total
    best_cost = ccost + (S[total] if total in S else 2.0)
    best = None
    for i, r in enumerate(rows):
        c0 = choice[i]
        for alt in r['tr'][1:]:
            ns = total - c0[3] + alt[3]
            if ns in S:
                c = ccost - c0[0] + alt[0] + S[ns]
                if c < best_cost - 1e-9:
                    best_cost = c
                    best = (i, alt)
    Sl = [(s, cs) for s, cs in S.items() if cs <= 1]
    for i, r in enumerate(rows):
        if time.perf_counter() > deadline:
            break
        c0 = choice[i]
        rest = total - c0[3]
        Q, U, A = r['Q'], r['U'], r['A']
        for s, cs in Sl:
            req = s - rest
            if req <= 0:
                continue
            base = ccost - c0[0] + cs
            if base >= best_cost:
                continue
            ca = A.get(req, 2.0)
            for q, cq in Q.items():
                if req % q:
                    continue
                u = req // q
                cu = U.get(u)
                if cu is None:
                    cu = W_WILD if cq == 0 else None
                if cu is None:
                    continue
                c = base + cq + cu + ca
                if c < best_cost - 1e-9:
                    best_cost = c
                    best = (i, [cq + cu + ca, q, u, req])
            if not Q:
                for u, cu in U.items():
                    if u and req % u == 0 and 1 <= req // u <= 500:
                        c = base + cu + W_WILD + ca
                        if c < best_cost - 1e-9:
                            best_cost = c
                            best = (i, [cu + ca + W_WILD, req // u, u, req])
    if best is not None:
        i, alt = best
        choice = list(choice)
        choice[i] = alt
        total = sum(t[3] for t in choice)
    return choice, (total in S and S[total] <= 1), total


def parse_doc(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.split('\n')
    order = list(COLS)
    sections = []
    total_tok = None
    items_tok = None
    cur = None
    for ln in lines:
        s = ln.strip('\r')
        st = s.strip()
        if not st:
            continue
        if st.startswith('COLUMNS'):
            names = re.findall(r'CODE|QTY|UNIT|AMOUNT', st)
            if sorted(names) == sorted(COLS):
                order = names
            continue
        if st.startswith('MANIFEST'):
            continue
        if re.match(r'^=+\s*SECTION', st):
            cur = {'lines': [], 'sub': None}
            sections.append(cur)
            continue
        m = re.match(r'^SUBTOTAL\s*(.*)$', st)
        if m:
            if cur is None:
                cur = {'lines': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = m.group(1).strip()
            cur = None
            continue
        m = re.match(r'^TOTAL\s*(.*?)\s*ITEMS\s*(.*)$', st)
        if m:
            total_tok = m.group(1).strip()
            items_tok = m.group(2).strip()
            continue
        m = re.match(r'^TOTAL\s*(.*)$', st)
        if m:
            total_tok = m.group(1).strip()
            continue
        if cur is None:
            if sections and sections[-1]['sub'] is None:
                cur = sections[-1]
            else:
                cur = {'lines': [], 'sub': None}
                sections.append(cur)
        cur['lines'].append(s)
    state['parsed'] = {'order': order, 'sections': sections, 'total': total_tok, 'items': items_tok}
    return state


def solve(state, params):
    t0 = time.perf_counter()
    deadline = t0 + 0.6
    P = state.get('parsed') or {'order': list(COLS), 'sections': [], 'total': None}
    order = P['order']
    sections = P['sections']
    alltoks = []
    for sec in sections:
        for ln in sec['lines']:
            alltoks.extend(x.strip() for x in SPLIT_RE.split(ln) if x.strip())
    npcs = sum(1 for x in alltoks if re.fullmatch(r'\S+\s*pcs', x))
    pcs = npcs >= 2
    sec_rows = []
    for sec in sections:
        toks = []
        for ln in sec['lines']:
            tl = [x.strip() for x in SPLIT_RE.split(ln) if x.strip()]
            if not tl:
                continue
            if all(plausible(x, pcs) for x in tl):
                toks.extend(tl)
        rows = align(toks, order, pcs)
        rr = []
        for r in rows:
            Q = qty_cands(r.get('QTY'))
            U = money_cands(r.get('UNIT'))
            A = money_cands(r.get('AMOUNT'))
            rr.append({'code': fix_code(r.get('CODE')), 'Q': Q, 'U': U, 'A': A,
                       'tr': build_triples(Q, U, A)})
        S = money_cands(sec['sub']) if sec['sub'] else {}
        sec_rows.append((rr, S))
    results = []
    for rr, S in sec_rows:
        results.append(list(solve_section(rr, S, deadline)))
    T = money_cands(P['total']) if P.get('total') else {}
    if T and len(results) > 1:
        grand = sum(r[2] for r in results)
        if grand not in T:
            unmatched = [i for i, r in enumerate(results) if not r[1]]
            if len(unmatched) == 1:
                i = unmatched[0]
                rr, S = sec_rows[i]
                S2 = dict(S)
                for tv, ct in T.items():
                    if ct == 0:
                        sv = tv - (grand - results[i][2])
                        if sv > 0 and (sv not in S2 or S2[sv] > 0.5):
                            S2[sv] = 0.5
                results[i] = list(solve_section(rr, S2, deadline + 0.2))
    elif T and len(results) == 1:
        rr, S = sec_rows[0]
        if not results[0][1]:
            S2 = dict(S)
            for tv, ct in T.items():
                if tv not in S2 or S2[tv] > ct + 0.5:
                    S2[tv] = ct + 0.5
            results[0] = list(solve_section(rr, S2, deadline + 0.2))
    items = []
    for (rr, S), res in zip(sec_rows, results):
        for r, t in zip(rr, res[0]):
            items.append({'code': r['code'], 'qty': int(t[1]), 'unit_cents': int(t[2])})
    state['output'] = {'items': items}
    state.pop('parsed', None)
    return state

import re

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
INV = {}
for _o, _ss in MIS.items():
    for _s in _ss:
        INV[_s] = INV.get(_s, '') + _o

LOOKD = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
         'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
LETTER_FROM_DIGIT = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
NUMCH = set("0123456789OolIiSsBZzG.,' ")
DIGLOOK = set("0123456789OolIiSsBZzG")
COLS = ["CODE", "QTY", "UNIT", "AMOUNT"]


def strip_pcs(t):
    return re.sub(r'(?i)\s*pcs\s*$', '', t.strip())


def norm_num(t):
    t = strip_pcs(t)
    out = []
    for c in t:
        if c.isdigit():
            out.append(c)
        elif c in LOOKD:
            out.append(LOOKD[c])
    return ''.join(out)


def edits1_list(d):
    res = []
    for i, ch in enumerate(d):
        for o in INV.get(ch, ''):
            res.append((d[:i] + o + d[i + 1:], 1.0))
    for i in range(len(d) - 1):
        if d[i] == d[i + 1]:
            res.append((d[:i] + d[i + 1:], 1.0))
    for i in range(len(d) + 1):
        for o in '0123456789':
            res.append((d[:i] + o + d[i:], 1.2))
    return res


def edits1(d):
    res = {}
    for s, c in edits1_list(d):
        if s not in res or res[s] > c:
            res[s] = c
    return res


def num_variants(d, lo, hi):
    res = {}
    for s, c in edits1(d).items():
        if not s:
            continue
        v = int(s)
        if lo <= v <= hi and (v not in res or res[v] > c):
            res[v] = c
    if d:
        v = int(d)
        if lo <= v <= hi:
            res[v] = 0.0
    return res


def dist(orig, obs):
    m = len(obs)
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] + (1.0 if j >= 2 and obs[j - 1] == obs[j - 2] else 2.5)
    for i in range(1, len(orig) + 1):
        oc = orig[i - 1]
        mis = MIS.get(oc, '')
        cur = [prev[0] + 1.2] + [0.0] * m
        for j in range(1, m + 1):
            sc = obs[j - 1]
            if sc == oc:
                sub = prev[j - 1]
            elif sc in mis:
                sub = prev[j - 1] + 1.0
            else:
                sub = prev[j - 1] + 2.5
            ins = cur[j - 1] + (1.0 if (j >= 2 and obs[j - 2] == sc) else 2.5)
            dele = prev[j] + 1.2
            v = sub
            if ins < v:
                v = ins
            if dele < v:
                v = dele
            cur[j] = v
        prev = cur
    return prev[m]


def z3(v):
    return str(v).zfill(3)


# ---------------- CODE repair ----------------

def code_ok(letters, s):
    if len(s) != 5:
        return False
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    d = [int(c) for c in s]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def solve_code(t):
    t = t.strip()
    letters = ''
    for c in t[:2]:
        if 'A' <= c.upper() <= 'Z' and c.isalpha():
            letters += c.upper()
        elif c in LETTER_FROM_DIGIT:
            letters += LETTER_FROM_DIGIT[c]
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    digs = ''
    for c in t[2:]:
        if c.isdigit():
            digs += c
        elif c in LOOKD:
            digs += LOOKD[c]
    if code_ok(letters, digs):
        return letters + digs
    # level 1: aggregate path counts
    counts = {}
    order = []
    l1 = edits1_list(digs)
    for s, c in l1:
        if code_ok(letters, s):
            if s not in counts:
                counts[s] = [c, 0]
                order.append(s)
            if c < counts[s][0]:
                counts[s][0] = c
            counts[s][1] += 1
    if order:
        best = None
        for s in order:
            c, n = counts[s]
            key = (c, -n)
            if best is None or key < best[0]:
                best = (key, s)
        return letters + best[1]
    # level 2
    l1d = edits1(digs)
    best = None
    for s, c in l1d.items():
        if not (4 <= len(s) <= 6):
            continue
        for s2, c2 in edits1_list(s):
            if len(s2) == 5 and code_ok(letters, s2):
                tot = c + c2
                if best is None or tot < best[0]:
                    best = (tot, s2)
    if best is not None:
        return letters + best[1]
    d4 = (digs[:4]).ljust(4, '0')
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    dd = [int(c) for c in d4]
    chk = (dd[0] + 2 * dd[1] + 3 * dd[2] + 4 * dd[3] + p1 + p2) % 10
    return letters + d4 + str(chk)


# ---------------- numeric row repair ----------------

def solve_row(oq, ou, oa):
    q0 = int(oq) if oq else None
    if q0 is not None and not (1 <= q0 <= 500):
        q0 = None
    u0 = int(ou) if ou else None
    if u0 is not None and u0 <= 0:
        u0 = None
    a0 = int(oa) if oa else None
    if a0 is not None and a0 <= 0:
        a0 = None
    if q0 is not None and u0 is not None and a0 is not None and q0 * u0 == a0:
        return [(0.0, q0, u0, a0)]
    Q1 = num_variants(oq, 1, 500)
    U1 = num_variants(ou, 1, 10 ** 12)
    A1 = num_variants(oa, 1, 10 ** 14)
    cands = {}

    def add(c, q, u, a):
        k = (q, u)
        if k not in cands or cands[k][0] > c:
            cands[k] = (c, a)

    for q, cq in Q1.items():
        for u, cu in U1.items():
            a = q * u
            ca = A1.get(a)
            if ca is not None:
                add(cq + cu + ca, q, u, a)
    bestc = min([v[0] for v in cands.values()]) if cands else 99.0
    if bestc > 1.0:
        def full(q, u):
            a = q * u
            return dist(str(q), oq) + dist(z3(u), ou) + dist(z3(a), oa)
        trial = set()
        if u0 is not None:
            for q in Q1:
                trial.add((q, u0))
        if q0 is not None:
            for u in U1:
                trial.add((q0, u))
        if a0 is not None:
            for q in Q1:
                if a0 % q == 0:
                    trial.add((q, a0 // q))
            for u in U1:
                if a0 % u == 0 and 1 <= a0 // u <= 500:
                    trial.add((a0 // u, u))
        if q0 is not None:
            for a in A1:
                if a % q0 == 0:
                    trial.add((q0, a // q0))
        if u0 is not None:
            for a in A1:
                if a % u0 == 0 and 1 <= a // u0 <= 500:
                    trial.add((a // u0, u0))
        for q, u in trial:
            if 1 <= q <= 500 and u > 0:
                add(full(q, u), q, u, q * u)
    if not cands:
        q = q0 if q0 is not None else 1
        u = u0 if u0 is not None else ((a0 // q) if a0 else 100)
        if u <= 0:
            u = 1
        return [(99.0, q, u, q * u)]
    lst = sorted([(v[0], k[0], k[1], v[1]) for k, v in cands.items()],
                 key=lambda x: (x[0], x[1], x[2]))
    b = lst[0][0]
    lst = [x for x in lst if x[0] <= b + 2.5][:8]
    return lst


def reconcile(rows_c, sub_obs):
    sel = [0] * len(rows_c)
    if sub_obs is None or not rows_c:
        return sel
    sobs = norm_num(sub_obs)
    if not sobs:
        return sel
    S0 = sum(rc[0][3] for rc in rows_c)
    best = (dist(z3(S0), sobs), -1, 0)
    if best[0] == 0:
        return sel
    for r, cl in enumerate(rows_c):
        for k in range(1, len(cl)):
            S = S0 - cl[0][3] + cl[k][3]
            c = (cl[k][0] - cl[0][0]) + dist(z3(S), sobs)
            if c < best[0] - 1e-9:
                best = (c, r, k)
    if best[1] >= 0:
        sel[best[1]] = best[2]
    return sel


# ---------------- tokenising ----------------

def codeish(t):
    if not (6 <= len(t) <= 8):
        return False
    for c in t[:2]:
        if not (c.isalpha() or c in LETTER_FROM_DIGIT):
            return False
    return all(c in DIGLOOK for c in t[2:])


def tok_fit(t, col):
    if col == 'CODE':
        if codeish(t):
            return 0
        return 3 if re.fullmatch(r'[A-Za-z0-9]{5,9}', t) else 8
    tt = strip_pcs(t)
    if not tt or any(c not in NUMCH for c in tt):
        return 8
    d = norm_num(tt)
    if not d:
        return 8
    if col == 'QTY':
        return 0 if (1 <= len(d) <= 4 and not re.search(r"[.,']", tt)) else 2
    return 0 if len(d) >= 2 else 1


def split_line(s, mode):
    if mode == 'pipe':
        parts = s.split('|')
    elif mode == 'semi':
        parts = s.split(';')
    elif mode == 'tab':
        parts = s.split('\t')
    else:
        parts = re.split(r' {2,}|\t', s)
    return [p.strip() for p in parts if p.strip()]


def segment(toks, order):
    n = len(toks)
    INF = 10 ** 9
    best = [INF] * (n + 1)
    back = [0] * (n + 1)
    best[0] = 0
    SKIP = 7
    for i in range(1, n + 1):
        best[i] = best[i - 1] + SKIP
        back[i] = 1
        if i >= 4:
            f = best[i - 4]
            for k in range(4):
                f += tok_fit(toks[i - 4 + k], order[k])
            if f <= best[i]:
                best[i] = f
                back[i] = 4
    rows = []
    i = n
    while i > 0:
        if back[i] == 4:
            rows.append(toks[i - 4:i])
            i -= 4
        else:
            i -= 1
    rows.reverse()
    return rows


def parse_doc(text):
    lines = text.split('\n')
    order = None
    mode = None
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            ms = list(re.finditer(r'CODE|QTY|UNIT|AMOUNT', rest))
            names = [m.group(0) for m in ms]
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            if len(ms) >= 2:
                sep = rest[ms[0].end():ms[1].start()]
                if '|' in sep:
                    mode = 'pipe'
                elif ';' in sep:
                    mode = 'semi'
                elif '\t' in sep:
                    mode = 'tab'
                else:
                    mode = 'space'
            break
    if order is None:
        order = list(COLS)
    if mode is None:
        body = '\n'.join(l for l in lines if not re.match(r'\s*(MANIFEST|COLUMNS|==|SUBTOTAL|TOTAL)', l))
        cnt = {'pipe': body.count('|'), 'semi': body.count(';'), 'tab': body.count('\t')}
        mode = max(cnt, key=lambda k: cnt[k]) if max(cnt.values()) > 0 else 'space'
    sections = []
    cur = None
    for ln in lines:
        st = ln.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if st.startswith('==') and 'SECTION' in st:
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'toks': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            continue
        toks = split_line(ln, mode)
        if not toks:
            continue
        good = False
        for t in toks:
            if min(tok_fit(t, c) for c in COLS) < 8:
                good = True
                break
        if not good:
            continue
        if cur is None:
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
        cur['toks'].extend(toks)
    return order, sections


def recover_manifest(state, params):
    items = []
    try:
        text = state.get('input', {}).get('text', '') or ''
        order, sections = parse_doc(text)
        idx = {c: order.index(c) for c in COLS}
        for sec in sections:
            rows = segment(sec['toks'], order)
            if not rows:
                continue
            codes = []
            rows_c = []
            for r in rows:
                codes.append(solve_code(r[idx['CODE']]))
                oq = norm_num(r[idx['QTY']])
                ou = norm_num(r[idx['UNIT']])
                oa = norm_num(r[idx['AMOUNT']])
                rows_c.append(solve_row(oq, ou, oa))
            sel = reconcile(rows_c, sec['sub'])
            for i in range(len(rows)):
                c = rows_c[i][sel[i]]
                items.append({'code': codes[i], 'qty': int(c[1]), 'unit_cents': int(c[2])})
    except Exception:
        pass
    state['output'] = {'items': items}
    return state

import re
import time
import itertools

LOOK = {'0': 'O', '1': 'l', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
CODE_D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
DIG = '0123456789'


def _inv():
    inv = {}
    for t, obs in MIS.items():
        for o in obs:
            inv.setdefault(o, []).append((t, 1.0 + 0.1 * (len(obs) - 1)))
    return inv


INV = _inv()
SPLIT = re.compile(r"\s*[|;\t]\s*| {2,}")
DIGLIKE = set("0123456789.,'OolISBZG")
MONEY_RE = re.compile(r"(0|[1-9]\d*)\.(\d\d)")
INT_RE = re.compile(r"[1-9]\d*")


def dist(t, s):
    n, m = len(t), len(s)
    INF = 1e9
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            c = row[j]
            if c >= INF:
                continue
            if i < n:
                a = t[i]
                if j < m:
                    b = s[j]
                    if a == b:
                        w = 0.0
                    elif LOOK.get(a) == b:
                        w = 0.3
                    elif b in MIS.get(a, ''):
                        w = 1.0 + 0.1 * (len(MIS[a]) - 1)
                    else:
                        w = 3.0
                    if c + w < dp[i + 1][j + 1]:
                        dp[i + 1][j + 1] = c + w
                    if j + 1 < m and a in DIG and s[j] == a and s[j + 1] == a:
                        if c + 1 < dp[i + 1][j + 2]:
                            dp[i + 1][j + 2] = c + 1
                if c + 1 < dp[i + 1][j]:
                    dp[i + 1][j] = c + 1
            if j < m and c + 3 < row[j + 1]:
                row[j + 1] = c + 3
    return dp[n][m]


def norm_obs(tok):
    s = tok.strip()
    s = re.sub(r"\s*pcs\s*$", "", s)
    s = s.replace("'", "").replace(" ", "").replace(",", ".")
    return s


def mapped(s):
    out = []
    cost = 0.0
    for ch in s:
        if ch in L2D:
            out.append(L2D[ch])
            cost += 0.3
        elif ch in DIG or ch == '.':
            out.append(ch)
        else:
            cost += 1
    return ''.join(out), cost


def edits1(s, allow_dot):
    out = []
    L = len(s)
    for i, ch in enumerate(s):
        for t, w in INV.get(ch, ()):
            out.append((s[:i] + t + s[i + 1:], w))
        if i + 1 < L and s[i + 1] == ch and ch in DIG:
            out.append((s[:i] + s[i + 1:], 1.0))
    for i in range(L + 1):
        for d in DIG:
            w = 1.0
            if (i > 0 and s[i - 1] == d) or (i < L and s[i] == d):
                w = 0.95
            out.append((s[:i] + d + s[i:], w))
    if allow_dot and '.' not in s and L >= 3:
        out.append((s[:-2] + '.' + s[-2:], 1.0))
    return out


def expand(base, bc, depth, allow_dot):
    best = {base: bc}
    frontier = {base: bc}
    for _ in range(depth):
        nf = {}
        for s, c in frontier.items():
            for s2, w in edits1(s, allow_dot):
                c2 = c + w
                if c2 < best.get(s2, 1e9):
                    best[s2] = c2
                    nf[s2] = c2
        frontier = nf
    return best


def money_parse(s):
    m = MONEY_RE.fullmatch(s)
    if not m:
        return None
    return int(m.group(1)) * 100 + int(m.group(2))


def money_str(c):
    return "%d.%02d" % (c // 100, c % 100)


def money_cands(tok, depth=1):
    s, bc = mapped(norm_obs(tok))
    res = {}
    for st, c in expand(s, bc, depth, True).items():
        v = money_parse(st)
        if v is not None and v > 0 and c < res.get(v, 1e9):
            res[v] = c
    return res


def qty_cands(tok, depth=2):
    s, bc = mapped(norm_obs(tok).replace('.', ''))
    res = {}
    for st, c in expand(s, bc, depth, False).items():
        if INT_RE.fullmatch(st):
            v = int(st)
            if 1 <= v <= 500 and c < res.get(v, 1e9):
                res[v] = c
    return res


def code_ok(L, D):
    if len(D) != 5 or not D.isdigit() or len(L) != 2:
        return False
    d = [int(x) for x in D]
    p = ord(L[0]) - 64 + ord(L[1]) - 64
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p) % 10 == d[4]


def solve_code(tok):
    s = re.sub(r"[^A-Za-z0-9]", "", tok)
    if len(s) < 2:
        return "AA00000"
    L = ''
    for ch in s[:2]:
        if ch in CODE_D2L:
            L += CODE_D2L[ch]
        elif ch.isalpha() and 'A' <= ch.upper() <= 'Z':
            L += ch.upper()
        else:
            L += 'A'
    D, _ = mapped(s[2:])
    D = D.replace('.', '')
    if code_ok(L, D):
        return L + D
    best = None
    frontier = {D: 0.0}
    seen = {D: 0.0}
    for depth in range(2):
        nf = {}
        for st, c in frontier.items():
            for s2, w in edits1(st, False):
                c2 = c + w
                if c2 < seen.get(s2, 1e9):
                    seen[s2] = c2
                    nf[s2] = c2
        frontier = nf
        cands = [(c, s2) for s2, c in nf.items() if code_ok(L, s2)]
        if cands:
            cands.sort()
            best = cands[0][1]
            break
    if best is None:
        D = (D + '00000')[:5]
        if D.isdigit():
            d = [int(x) for x in D]
            p = ord(L[0]) - 64 + ord(L[1]) - 64
            D = D[:4] + str((d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p) % 10)
        else:
            D = '00000'
        best = D
    return L + best


def qty_base(tok):
    s, c = mapped(norm_obs(tok).replace('.', ''))
    if INT_RE.fullmatch(s):
        v = int(s)
        if 1 <= v <= 500:
            return v, c
    return None, None


def money_base(tok):
    s, c = mapped(norm_obs(tok))
    v = money_parse(s)
    return v, c


def target_cands(qt, ut, at, targets, fast):
    oq = norm_obs(qt).replace('.', '')
    ou = norm_obs(ut)
    oa = norm_obs(at)
    Qc = qty_cands(qt, 1 if fast else 2)
    Uc = money_cands(ut, 1)
    out = {}
    for av in targets:
        if av <= 0:
            continue
        ca = dist(money_str(av), oa)
        for qv, c1 in Qc.items():
            if c1 > 2.1 or av % qv:
                continue
            uv = av // qv
            c = ca + c1 + dist(money_str(uv), ou)
            if c < out.get((qv, uv, av), 1e9):
                out[(qv, uv, av)] = c
        for uv, c2 in Uc.items():
            if av % uv:
                continue
            qv = av // uv
            if 1 <= qv <= 500:
                c = ca + c2 + dist(str(qv), oq)
                if c < out.get((qv, uv, av), 1e9):
                    out[(qv, uv, av)] = c
    return out


def solve_row(qt, ut, at, fast):
    q, cq = qty_base(qt)
    u, cu = money_base(ut)
    a, ca = money_base(at)
    if q is not None and u is not None and a is not None and q * u == a:
        return [(0.0, q, u, a)]
    oq = norm_obs(qt).replace('.', '')
    ou = norm_obs(ut)
    oa = norm_obs(at)
    Qc = qty_cands(qt, 1 if fast else 2)
    Uc = money_cands(ut, 1)
    Ac = money_cands(at, 1)
    cands = {}

    def add(key, c):
        if c < cands.get(key, 1e9):
            cands[key] = c
    if not fast or len(Qc) * len(Uc) < 4000:
        for qv, c1 in Qc.items():
            for uv, c2 in Uc.items():
                av = qv * uv
                c3 = Ac.get(av)
                if c3 is not None:
                    add((qv, uv, av), c1 + c2 + c3)
    Q1 = [(v, c) for v, c in Qc.items() if c <= 1.75]
    U1 = [(v, c) for v, c in Uc.items() if c <= 1.75]
    A1 = [(v, c) for v, c in Ac.items() if c <= 1.75]
    for qv, c1 in Q1:
        for uv, c2 in U1:
            if c1 + c2 > 1.75:
                continue
            av = qv * uv
            add((qv, uv, av), c1 + c2 + dist(money_str(av), oa))
    for qv, c1 in Q1:
        for av, c3 in A1:
            if c1 + c3 > 1.75:
                continue
            if av % qv == 0:
                uv = av // qv
                if uv > 0:
                    add((qv, uv, av), c1 + c3 + dist(money_str(uv), ou))
    for uv, c2 in U1:
        for av, c3 in A1:
            if c2 + c3 > 1.75:
                continue
            if av % uv == 0:
                qv = av // uv
                if 1 <= qv <= 500:
                    add((qv, uv, av), c2 + c3 + dist(str(qv), oq))
    lst = sorted((c, k[0], k[1], k[2]) for k, c in cands.items())
    if not lst:
        qv = q if q is not None else (min(Qc, key=Qc.get) if Qc else 1)
        uv = u if u is not None else (min(Uc, key=Uc.get) if Uc else 0)
        lst = [(9.0, qv, uv, qv * uv)]
    return lst[:8]


def tok_scores(t):
    core = re.sub(r"\s*pcs$", "", t)
    sc = 0 if re.fullmatch(r"[A-Z0-9]{2}[0-9OlISBZG]{4,6}", core) else 3
    sq = 0 if re.fullmatch(r"[0-9OlSBZG]{1,4}", core) else 3
    if re.fullmatch(r"[0-9OlSBZG']+[.,][0-9OlSBZG]{1,3}", core):
        sm = 0
    elif re.fullmatch(r"[0-9OlSBZG']{2,10}", core):
        sm = 1
    else:
        sm = 3
    if core != t:
        sq = 0
    return {'CODE': sc, 'QTY': sq, 'UNIT': sm, 'AMOUNT': sm}


def segment(tokens, order):
    n = len(tokens)
    if n == 0:
        return []
    scores = [tok_scores(t) for t in tokens]
    INF = 1e9
    dp = [INF] * (n + 1)
    bk = [None] * (n + 1)
    dp[0] = 0
    for i in range(n):
        if dp[i] >= INF:
            continue
        if dp[i] + 4 < dp[i + 1]:
            dp[i + 1] = dp[i] + 4
            bk[i + 1] = (i, False)
        if i + 4 <= n:
            c = dp[i] + sum(scores[i + k][order[k]] for k in range(4))
            if c < dp[i + 4]:
                dp[i + 4] = c
                bk[i + 4] = (i, True)
    rows = []
    j = n
    while j > 0:
        i, isrow = bk[j]
        if isrow:
            rows.append(tokens[i:i + 4])
        j = i
    rows.reverse()
    return rows


def plausible(t):
    core = re.sub(r"\s*pcs$", "", t)
    if not core or len(core) > 14:
        return False
    if not re.fullmatch(r"[A-Za-z0-9.,']+", core):
        return False
    bad = sum(1 for ch in core if ch not in DIGLIKE)
    good = len(core) - bad
    return bad <= 2 and good >= 1


def parse_doc(text):
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sections = []
    cur = None
    total = None
    items_n = None
    for raw in text.split('\n'):
        line = raw.strip()
        if not line:
            continue
        if re.match(r"MANIFEST\b", line):
            continue
        if re.match(r"COLUMNS\b", line):
            names = re.findall(r"CODE|QTY|UNIT|AMOUNT", line)
            if sorted(names) == sorted(order):
                order = names
            continue
        if re.match(r"==\s*SECTION\b", line):
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
            continue
        m = re.match(r"SUBTOTAL\b\s*(.*)$", line)
        if m:
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = m.group(1).strip()
            cur = None
            continue
        m = re.match(r"TOTAL\b\s*(.*?)\s*(?:ITEMS\s*(.*))?$", line)
        if m:
            total = m.group(1).strip()
            items_n = m.group(2)
            continue
        toks = [t for t in SPLIT.split(line) if t]
        if not toks or not all(plausible(t) for t in toks):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
        cur['tokens'].extend(toks)
    return order, sections, total, items_n


def section_options(rowc, sub, deadline):
    base_cost = sum(r[0][0] for r in rowc)
    amb = [i for i, r in enumerate(rowc) if len(r) > 1]
    obs_sub = norm_obs(sub) if sub else None
    cache = {}

    def subcost(v):
        if obs_sub is None:
            return 0.0
        if v not in cache:
            cache[v] = min(4.0, dist(money_str(v), obs_sub))
        return cache[v]
    k = 8
    while k > 1:
        prod = 1
        for i in amb:
            prod *= min(k, len(rowc[i]))
        if prod <= 3000:
            break
        k -= 1
    lists = [list(range(min(k, len(rowc[i])))) for i in amb]
    base_sum = sum(r[0][3] for r in rowc)
    opts = []
    for combo in itertools.product(*lists):
        if opts and time.perf_counter() > deadline:
            break
        c = base_cost
        s = base_sum
        for idx, ci in zip(amb, combo):
            if ci:
                c += rowc[idx][ci][0] - rowc[idx][0][0]
                s += rowc[idx][ci][3] - rowc[idx][0][3]
        if len(opts) >= 6 and c > opts[-1][0]:
            continue
        tc = c + subcost(s)
        opts.append((tc, s, combo))
        opts.sort(key=lambda x: x[0])
        opts = opts[:6]
    choices = []
    for tc, s, combo in opts:
        ch = [0] * len(rowc)
        for idx, ci in zip(amb, combo):
            ch[idx] = ci
        choices.append((tc, s, ch))
    return choices


def solve(text):
    t0 = time.perf_counter()
    deadline = t0 + 0.7
    order, sections, total, items_n = parse_doc(text)
    pos = {name: i for i, name in enumerate(order)}
    sec_rows = []
    for sec in sections:
        rows = segment(sec['tokens'], order)
        rc = []
        codes = []
        for r in rows:
            fast = time.perf_counter() > t0 + 0.4
            codes.append(solve_code(r[pos['CODE']]))
            rc.append(solve_row(r[pos['QTY']], r[pos['UNIT']], r[pos['AMOUNT']], fast))
        incons = [i for i, x in enumerate(rc) if x[0][0] > 0.5]
        if sec['sub'] and 0 < len(incons) <= 3 and time.perf_counter() < t0 + 0.5:
            tc = money_cands(sec['sub'], 1)
            tl = [v for v, c in tc.items() if c <= 1.2]
            tot_best = sum(x[0][3] for x in rc)
            for i in incons:
                others = tot_best - rc[i][0][3]
                extra = target_cands(rows[i][pos['QTY']], rows[i][pos['UNIT']],
                                     rows[i][pos['AMOUNT']], [t - others for t in tl],
                                     time.perf_counter() > t0 + 0.4)
                if extra:
                    d = {(x[1], x[2], x[3]): x[0] for x in rc[i]}
                    for kk, c in extra.items():
                        if c < d.get(kk, 1e9):
                            d[kk] = c
                    rc[i] = sorted((c, kk[0], kk[1], kk[2]) for kk, c in d.items())[:10]
        sec_rows.append((codes, rc))
    sec_opts = []
    for (codes, rc), sec in zip(sec_rows, sections):
        if not rc:
            sec_opts.append([(0.0, 0, [])])
            continue
        sec_opts.append(section_options(rc, sec['sub'], deadline))
    obs_tot = norm_obs(total) if total else None
    k = 6
    while k > 1:
        prod = 1
        for o in sec_opts:
            prod *= min(k, len(o))
        if prod <= 3000:
            break
        k -= 1
    lists = [o[:k] for o in sec_opts]
    best = None
    cache = {}
    for combo in itertools.product(*lists):
        c = sum(x[0] for x in combo)
        if best is not None and c >= best[0]:
            continue
        s = sum(x[1] for x in combo)
        if obs_tot:
            if s not in cache:
                cache[s] = min(4.0, dist(money_str(s), obs_tot))
            c += cache[s]
        if best is None or c < best[0]:
            best = (c, combo)
    items = []
    if best is None:
        return items
    for (codes, rc), opt in zip(sec_rows, best[1]):
        ch = opt[2]
        for i, r in enumerate(rc):
            cand = r[ch[i]] if i < len(ch) else r[0]
            items.append({'code': codes[i], 'qty': int(cand[1]), 'unit_cents': int(cand[2])})
    return items


def fallback(text):
    items = []
    try:
        order, sections, total, items_n = parse_doc(text)
        pos = {name: i for i, name in enumerate(order)}
        for sec in sections:
            for r in segment(sec['tokens'], order):
                q, _ = qty_base(r[pos['QTY']])
                u, _ = money_base(r[pos['UNIT']])
                items.append({'code': solve_code(r[pos['CODE']]),
                              'qty': int(q) if q else 1, 'unit_cents': int(u) if u else 0})
    except Exception:
        pass
    return items


def run(state, params):
    text = state.get("input", {}).get("text", "")
    try:
        items = solve(text)
    except Exception:
        items = fallback(text)
    state["output"] = {"items": items}
    return state

