            if c < counts[s][0]:
                counts[s][0] = c
            counts[s][1] += 1
    if order:
        best = None
        for s in order:
            c, n = counts[s]
            key = (c, -n)
            if best is None or key < best[0]:
                best = (key, s)
        return letters + best[1]
    l1 = {}
    for s, c in code_edit_list(digs):
        if s not in l1 or l1[s] > c:
            l1[s] = c
    best = None
    for s, c in l1.items():
        if not (4 <= len(s) <= 6):
            continue
        for s2, c2 in code_edit_list(s):
            if len(s2) == 5 and code_ok(letters, s2):
                tot = c + c2
                if best is None or tot < best[0]:
                    best = (tot, s2)
    if best is not None:
        return letters + best[1]
    d4 = digs[:4].ljust(4, '0')
    dd = [int(c) for c in d4]
    chk = (dd[0] + 2 * dd[1] + 3 * dd[2] + 4 * dd[3] + ord(letters[0]) - 64 + ord(letters[1]) - 64) % 10
    return letters + d4 + str(chk)


# ---------------- tokens / alignment ----------------

def tok_cost(t, col, pcs):
    if t == '':
        if col == 'QTY':
            return 1.0
        return 6.0 if col == 'CODE' else 4.0
    if col == 'CODE':
        if RE_CODE.fullmatch(t):
            nl = sum(1 for c in t[:2] if c.isalpha())
            bad = sum(1 for c in t[2:] if c.isalpha() and c not in L2D)
            base = 0.0 if nl == 2 else (0.5 if nl == 1 else 2.0)
            return base + 2.0 * bad
        return 5.0
    hp = has_pcs(t)
    tt = strip_pcs(t)
    if col == 'QTY':
        pen = 0.5 if (pcs is not None and hp != pcs) else 0.0
        if tt == '':
            return (0.8 + pen) if hp else 1.0
        if RE_QDIG.fullmatch(tt):
            return pen
        if RE_MON.fullmatch(tt):
            return 2.5 + pen
        return 5.0
    if hp:
        return 4.0
    if RE_MON.fullmatch(tt):
        if re.search(r'[0-9]', tt):
            return 0.0 if re.search(r'[.,]', tt) else 0.3
        return 1.0
    return 5.0


def plausible(t):
    return min(tok_cost(t, c, None) for c in COLS) <= 2.0


def align(toks, order, pcs):
    n = len(toks)
    INF = 1e18
    MISS = 5.0
    costs = [[tok_cost(t, order[p], pcs) for p in range(4)] for t, k in toks]
    skipc = [0.0 if k == 't' else (2.5 if t == '' else 3.0) for t, k in toks]
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(2):
            for p in range(4):
                if dp[i][p] < INF:
                    q = (p + 1) % 4
                    c = dp[i][p] + MISS
                    if c < dp[i][q] - 1e-9:
                        dp[i][q] = c
                        bk[i][q] = ('m', i, p)
        if i == n:
            break
        for p in range(4):
            if dp[i][p] >= INF:
                continue
            c = dp[i][p] + costs[i][p]
            q = (p + 1) % 4
            if c < dp[i + 1][q]:
                dp[i + 1][q] = c
                bk[i + 1][q] = ('a', i, p)
            c = dp[i][p] + skipc[i]
            if c < dp[i + 1][p]:
                dp[i + 1][p] = c
                bk[i + 1][p] = ('s', i, p)
    ops = []
    i, p = n, 0
    guard = 0
    while not (i == 0 and p == 0) and guard < 10 * (n + 5):
        guard += 1
        b = bk[i][p]
        if b is None:
            break
        ops.append(b)
        i, p = b[1], b[2]
    ops.reverse()
    rows = []
    cur = {}
    for kind, ti, pp in ops:
        if kind == 's':
            continue
        cur[order[pp]] = toks[ti][0] if kind == 'a' else None
        if pp == 3:
            rows.append(cur)
            cur = {}
    return [r for r in rows if any(r.get(c) is not None for c in COLS)]


def split_line(s, mode):
    if mode == 'pipe':
        parts = s.split('|')
    elif mode == 'semi':
        parts = s.split(';')
    elif mode == 'tab':
        parts = s.split('\t')
    else:
        parts = re.split(r' {3}|\t', s)
    return [p.strip() for p in parts]


def parse_doc(text):
    lines = text.split('\n')
    order = list(COLS)
    mode = None
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            ms = list(re.finditer(r'CODE|QTY|UNIT|AMOUNT', rest))
            names = [m.group(0) for m in ms]
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            if len(ms) >= 2:
                sep = rest[ms[0].end():ms[1].start()]
                if '|' in sep:
                    mode = 'pipe'
                elif ';' in sep:
                    mode = 'semi'
                elif '\t' in sep:
                    mode = 'tab'
                else:
                    mode = 'space'
            break
    if mode is None:
        body = '\n'.join(l for l in lines if not re.match(r'\s*(MANIFEST|COLUMNS|==|SUBTOTAL|TOTAL)', l))
        cnt = {'pipe': body.count('|'), 'semi': body.count(';'), 'tab': body.count('\t')}
        mode = max(cnt, key=lambda k: cnt[k]) if max(cnt.values()) > 0 else 'space'
    sections = []
    cur = None
    ttok = None
    itok = None
    for ln in lines:
        raw = ln.rstrip('\r')
        st = raw.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', st):
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                if sections and sections[-1]['sub'] is None:
                    cur = sections[-1]
                else:
                    cur = {'toks': [], 'sub': None}
                    sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s*(.*?)\s*ITEMS\s*(.*)$', st)
            if m:
                ttok = m.group(1).strip()
                itok = m.group(2).strip()
            else:
                ttok = st[5:].strip()
            continue
        parts = split_line(raw, mode)
        toks = []
        for k, p in enumerate(parts):
            kind = 't' if (p == '' and k == len(parts) - 1 and k > 0) else 'f'
            toks.append((p, kind))
        nonempty = [p for p, _ in toks if p]
        if not nonempty:
            continue
        if not any(plausible(p) for p in nonempty):
            continue
        if cur is None:
            if sections and sections[-1]['sub'] is None:
                cur = sections[-1]
            else:
                cur = {'toks': [], 'sub': None}
                sections.append(cur)
        cur['toks'].extend(toks)
    return order, sections, ttok, itok


# ---------------- numeric reasoning ----------------

def row_cands(r, Dm, Dq):
    Q, U, A = r['Q'], r['U'], r['A']
    trip = {}

    def add(c, q, u):
        k = (q, u)
        if k not in trip or trip[k] > c:
            trip[k] = c
    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(cq + cu + ca, q, u)
    best = min(trip.values()) if trip else 99.0
    if best > 0:
        for q, cq in Q.items():
            if cq > 1.5:
                continue
            for u, cu in U.items():
                if cq + cu <= 1.5 and (q, u) not in trip:
                    add(cq + cu + Dm(q * u, r['oa']), q, u)
        for a, ca in A.items():
            if ca > 1.5:
                continue
            for q, cq in Q.items():
                if ca + cq <= 1.5 and a % q == 0:
                    add(ca + cq + Dm(a // q, r['ou']), q, a // q)
            for u, cu in U.items():
                if ca + cu <= 1.5 and a % u == 0:
                    q = a // u
                    if 1 <= q <= 500:
                        add(ca + cu + Dq(q, r['oq']), q, u)
    if not trip:
        q = min(Q.items(), key=lambda x: x[1])[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: x[1])[0]
        elif A:
            u = max(1, min(A.items(), key=lambda x: x[1])[0] // q)
        else:
            u = 100
        return [[50.0, q, u, q * u]]
    lst = sorted([[c, k[0], k[1], k[0] * k[1]] for k, c in trip.items()], key=lambda x: x[0])
    return lst[:12]


def solve_section(rows, score, targets, deadline, Dm, Dq):
    if not rows:
        return [], 0, 0.0
    base = [r['tr'][0] for r in rows]
    tot = sum(t[3] for t in base)
    rc = sum(t[0] for t in base)
    s0 = score(tot)
    best_obj = rc + s0
    best_mod = None
    if s0 <= 0:
        return base, tot, best_obj
    alts = []
    bydelta = {}
    for i, r in enumerate(rows):
        b = base[i]
        for t in r['tr'][1:]:
            d = t[3] - b[3]
            if d == 0:
                continue
            dc = t[0] - b[0]
            alts.append((i, t, d, dc))
            ns = tot + d
            if ns > 0:
                obj = rc + dc + score(ns)
                if obj < best_obj - 1e-9:
                    best_obj = obj
                    best_mod = [(i, t)]
            bydelta.setdefault(d, []).append((dc, i, t))
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        if rc + st >= best_obj:
            continue
        need = tv - tot
        for (i, t, d, dc) in alts:
            if rc + dc + st >= best_obj:
                continue
            lst = bydelta.get(need - d)
            if not lst:
                continue
            for (dc2, j, t2) in lst:
                if j > i:
                    obj = rc + dc + dc2 + st
                    if obj < best_obj - 1e-9:
                        best_obj = obj
                        best_mod = [(i, t), (j, t2)]
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        for i, r in enumerate(rows):
            b = base[i]
            req = tv - (tot - b[3])
            if req <= 0:
                continue
            basec = rc - b[0] + st
            if basec >= best_obj:
                continue
            ca = r['A'].get(req)
            if ca is None:
                ca = Dm(req, r['oa'])
            if basec + ca >= best_obj:
                continue
            for q, cq in r['Q'].items():
                if req % q:
                    continue
                u = req // q
                cu = r['U'].get(u)
                if cu is None:
                    if cq > 0:
                        continue
                    cu = Dm(u, r['ou'])
                c = cq + cu + ca
                if basec + c < best_obj - 1e-9:
                    best_obj = basec + c
                    best_mod = [(i, [c, q, u, req])]
            for u, cu in r['U'].items():
                if cu > 0.5 or req % u:
                    continue
                q = req // u
                if 1 <= q <= 500 and q not in r['Q']:
                    c = cu + Dq(q, r['oq']) + ca
                    if basec + c < best_obj - 1e-9:
                        best_obj = basec + c
                        best_mod = [(i, [c, q, u, req])]
    choice = list(base)
    if best_mod:
        for i, t in best_mod:
            choice[i] = t
    tot = sum(t[3] for t in choice)
    return choice, tot, best_obj


def make_scorer(tok, dist):
    if tok is None or not tok.strip():
        return None, []
    C = money_cands(tok)
    o = mdigits(tok)
    cache = {}

    def f(s):
        v = C.get(s)
        if v is None:
            v = cache.get(s)
            if v is None:
                v = min(6.0, dist(str(s).zfill(3), o)) if s > 0 else 6.0
                cache[s] = v
        return v
    targ = sorted([(v, c) for v, c in C.items() if c <= 1.0], key=lambda x: (x[1], x[0]))[:10]
    return f, targ


def comb(fs, ft, off):
    def f(s):
        v = fs(s) if fs else 0.0
        if ft:
            v += ft(off + s)
        return v
    return f


def recover(state, params):
    t0 = time.perf_counter()
    state['output'] = {'items': []}
    text = (state.get('input') or {}).get('text', '') or ''
    try:
        order, sections, ttok, itok = parse_doc(text)
    except Exception:
        return state
    dist = make_dist()

    def Dm(c, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(c).zfill(3), obs))

    def Dq(q, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(q), obs))

    npcs = 0
    for sec in sections:
        for t, k in sec['toks']:
            if t and has_pcs(t):
                npcs += 1
    pcs = npcs >= 2
    secs = []
    for sec in sections:
        try:
            rows = align(sec['toks'], order, pcs)
        except Exception:
            rows = []
        rr = []
        for r in rows:
            tq, tu, ta = r.get('QTY'), r.get('UNIT'), r.get('AMOUNT')
            try:
                code = solve_code(r.get('CODE'))
            except Exception:
                code = 'AA00000'
            row = {'code': code, 'Q': qty_cands(tq), 'U': money_cands(tu), 'A': money_cands(ta),
                   'oq': digits_of(tq), 'ou': mdigits(tu), 'oa': mdigits(ta)}
            try:
                row['tr'] = row_cands(row, Dm, Dq)
            except Exception:
                row['tr'] = [[50.0, 1, 100, 100]]
            rr.append(row)
        fS, targ = make_scorer(sec['sub'], dist)
        secs.append({'rows': rr, 'fS': fS, 'targ': targ})

    results = [[[r['tr'][0] for r in s['rows']], 0, 0.0] for s in secs]

    def emit():
        items = []
        for s, res in zip(secs, results):
            for r, t in zip(s['rows'], res[0]):
                items.append({'code': r['code'], 'qty': int(t[1]), 'unit_cents': int(t[2])})
        state['output'] = {'items': items}
    emit()
    try:
        fT, Ttarg = make_scorer(ttok, dist)
        dl1 = t0 + 0.55
        for i, s in enumerate(secs):
            if len(secs) == 1:
                sc = comb(s['fS'], fT, 0)
                targ = list(s['targ']) + list(Ttarg)
            else:
                sc = comb(s['fS'], None, 0)
                targ = s['targ']
            ch, tt, obj = solve_section(s['rows'], sc, targ, dl1, Dm, Dq)
            results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
        dl2 = t0 + 0.8
        if fT and len(secs) > 1:
            for _ in range(3):
                if time.perf_counter() > dl2:
                    break
                grand = sum(r[1] for r in results)
                ct = fT(grand)
                if ct <= 0:
                    break
                best_gain = 1e-9
                best = None
                for i, s in enumerate(secs):
                    if time.perf_counter() > dl2 or not s['rows']:
                        continue
                    other = grand - results[i][1]
                    fS = s['fS']
                    sc = comb(fS, fT, other)
                    targ = list(s['targ']) + [(tv - other, c) for tv, c in Ttarg if tv - other > 0]
                    ch, tt, obj = solve_section(s['rows'], sc, targ, dl2, Dm, Dq)
                    old = results[i][2] + (fS(results[i][1]) if fS else 0.0) + ct
                    gain = old - obj
                    if gain > best_gain:
                        best_gain = gain
                        best = (i, ch, tt)
                if best is None:
                    break
                i, ch, tt = best
                results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
    except Exception:
        pass
    return state

change:
- **Taken from Y (the base).** Y scored higher, and its weakest outputs show that nearly all remaining loss comes from wrong codes, so Y's pipeline is the foundation. That covers:
  - separator detection from the COLUMNS line, keeping empty fields;
  - trailing-separator marking for wrapped rows and the noise-line filter;
  - the cyclic DP alignment;
  - weighted numeric candidate sets (misread, duplicate, lost digit, lost decimal mark);
  - derived-field row candidates scored by a probabilistic edit distance;
  - per-section subtotal reconciliation (one swap, two swaps, or rebuilding one row);
  - the iterative TOTAL pass across sections.
- **Taken from X.** X's tolerant separator regex is used as a fallback splitter. It only applies when the COLUMNS-derived split leaves a line as one implausible token but the regex splits it into at least 3 plausible fields. X's dropping of the item count also showed how costly a one-row shift is under positional scoring, which motivates the next change.
- **New: likelihood-based code repair.** Codes are repaired by a search of up to 3 edit levels using an explicit damage model:
  - a misread from original digit d has likelihood 1/|MIS[d]|, so a 7 that was really a 2 counts double;
  - duplicate removal and lost-digit insertion each have likelihood 1;
  - probabilities are summed over all edit paths that reach the same string;
  - edits are directed by length and the candidate set is pruned between levels.

