import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
REV = {}
for _o in sorted(MIS):
    for _s in MIS[_o]:
        REV[_s] = REV.get(_s, '') + _o

L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
       'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
COLS = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
C_MIS = 1.0
C_DUP = 1.0
C_LOST = 1.2
C_MARK = 0.5

RE_CODE = re.compile(r'[A-Za-z0-9]{2}[0-9A-Za-z]{2,8}')
RE_QDIG = re.compile(r'[0-9OolIiSsBZzG]{1,4}')
RE_MON = re.compile(r"[0-9OolIiSsBZzG.,']{1,14}")
SPLIT_RE = re.compile(r'\s*\|\s*|;|\t| {2,}')


def strip_pcs(t):
    return re.sub(r'(?i)\s*pcs\s*$', '', t.strip())


def has_pcs(t):
    return re.search(r'(?i)pcs\s*$', t.strip()) is not None


def digits_of(tok):
    if tok is None:
        return None
    s = strip_pcs(tok)
    return ''.join(L2D.get(c, c) for c in s if c.isdigit() or c in L2D)


def num_edits(s):
    out = {s: 0.0}
    n = len(s)

    def put(v, c):
        if v not in out or out[v] > c:
            out[v] = c
    for i, ch in enumerate(s):
        if ch.isdigit():
            for y in REV.get(ch, ''):
                put(s[:i] + y + s[i + 1:], C_MIS)
            if i + 1 < n and s[i + 1] == ch:
                put(s[:i] + s[i + 1:], C_DUP)
    for i in range(n + 1):
        for d in '0123456789':
            put(s[:i] + d + s[i:], C_LOST)
    return out


def norm_money(tok):
    t = ''.join(L2D.get(c, c) for c in tok)
    t = t.replace("'", '').replace(' ', '').replace(',', '.')
    t = re.sub(r'[^0-9.]', '', t)
    if t.count('.') > 1:
        k = t.rfind('.')
        t = t[:k].replace('.', '') + t[k:]
    return t


def mdigits(tok):
    if tok is None:
        return None
    return norm_money(tok).replace('.', '')


def parse_money(v):
    if '.' in v:
        a, b = v.split('.', 1)
        if len(b) != 2 or not a.isdigit() or not b.isdigit():
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        return (int(a) * 100 + int(b), False)
    if len(v) < 3 or not v.isdigit():
        return None
    if len(v) > 3 and v[0] == '0':
        return None
    return (int(v), True)


def money_cands(tok):
    if tok is None:
        return {}
    t = norm_money(tok)
    if not t or len(t) > 14:
        return {}
    res = {}
    for v, c in num_edits(t).items():
        m = parse_money(v)
        if m is None:
            continue
        val, nomark = m
        cc = c + (C_MARK if nomark else 0.0)
        if val > 0 and (val not in res or res[val] > cc):
            res[val] = cc
    return res


def qty_cands(tok):
    if tok is None:
        return {}
    t = digits_of(tok)
    if t == '':
        return {q: C_LOST for q in range(1, 10)}
    if len(t) > 5:
        return {}
    res = {}
    for v, c in num_edits(t).items():
        if not v or (len(v) > 1 and v[0] == '0'):
            continue
        q = int(v)
        if 1 <= q <= 500 and (q not in res or res[q] > c):
            res[q] = c
    return res


def make_dist():
    cache = {}

    def dist(orig, obs):
        k = orig + '|' + obs
        v = cache.get(k)
        if v is not None:
            return v
        m = len(obs)
        prev = [0.0] * (m + 1)
        for j in range(1, m + 1):
            prev[j] = prev[j - 1] + (1.0 if j >= 2 and obs[j - 1] == obs[j - 2] else 2.5)
        for i in range(1, len(orig) + 1):
            oc = orig[i - 1]
            mis = MIS.get(oc, '')
            cur = [prev[0] + 1.2] + [0.0] * m
            for j in range(1, m + 1):
                sc = obs[j - 1]
                if sc == oc:
                    sub = prev[j - 1]
                elif sc in mis:
                    sub = prev[j - 1] + 1.0
                else:
                    sub = prev[j - 1] + 2.5
                ins = cur[j - 1] + (1.0 if (j >= 2 and obs[j - 2] == sc) else 2.5)
                dele = prev[j] + 1.2
                b = sub
                if ins < b:
                    b = ins
                if dele < b:
                    b = dele
                cur[j] = b
            prev = cur
        r = prev[m]
        cache[k] = r
        return r
    return dist


# ---------------- codes ----------------

def code_ok(L, s):
    if len(s) != 5 or not s.isdigit():
        return False
    p1 = ord(L[0]) - 64
    p2 = ord(L[1]) - 64
    d = [int(c) for c in s]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def code_expand(s):
    out = []
    L = len(s)
    for i, ch in enumerate(s):
        for o in REV.get(ch, ''):
            out.append((s[:i] + o + s[i + 1:], 1.0 / len(MIS[o])))
    if L >= 5:
        for i in range(L - 1):
            if s[i] == s[i + 1]:
                out.append((s[:i] + s[i + 1:], 1.0))
    if L > 5:
        for i in range(L):
            out.append((s[:i] + s[i + 1:], 0.02))
    if L <= 4:
        for i in range(L + 1):
            for d in '0123456789':
                out.append((s[:i] + d + s[i:], 1.0))
    return out


def code_search(letters, digs):
    cur = {digs: 1.0}
    maxlev = 3
    for lev in range(1, maxlev + 1):
        nxt = {}
        for s, p in cur.items():
            for s2, w in code_expand(s):
                nxt[s2] = nxt.get(s2, 0.0) + p * w
        best = None
        for s, p in nxt.items():
            if len(s) == 5 and code_ok(letters, s):
                if best is None or p > best[0] + 1e-12:
                    best = (p, s)
        if best is not None:
            return best[1]
        remain = maxlev - lev
        items = [(s, p) for s, p in nxt.items() if abs(len(s) - 5) <= remain]
        items.sort(key=lambda x: -x[1])
        cur = dict(items[:500])
        if not cur:
            break
    return None


def solve_code(tok):
    if not tok:
        return 'AA00000'
    t = tok.replace(' ', '')
    letters = ''
    for c in t[:2]:
        if c.isalpha() and 'A' <= c.upper() <= 'Z':
            letters += c.upper()
        elif c in D2L:
            letters += D2L[c]
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    digs = ''.join(L2D.get(c, c) for c in t[2:] if c.isdigit() or c in L2D)
    if code_ok(letters, digs):
        return letters + digs
    if 1 <= len(digs) <= 9:
        r = code_search(letters, digs)
        if r is not None:
            return letters + r
    d4 = digs[:4].ljust(4, '0')
    dd = [int(c) for c in d4]
    chk = (dd[0] + 2 * dd[1] + 3 * dd[2] + 4 * dd[3] + ord(letters[0]) - 64 + ord(letters[1]) - 64) % 10
    return letters + d4 + str(chk)


# ---------------- tokens / alignment ----------------

def tok_cost(t, col, pcs):
    if t == '':
        if col == 'QTY':
            return 1.0
        return 6.0 if col == 'CODE' else 4.0
    if col == 'CODE':
        if RE_CODE.fullmatch(t):
            nl = sum(1 for c in t[:2] if c.isalpha())
            bad = sum(1 for c in t[2:] if c.isalpha() and c not in L2D)
            base = 0.0 if nl == 2 else (0.5 if nl == 1 else 2.0)
            return base + 2.0 * bad
        return 5.0
    hp = has_pcs(t)
    tt = strip_pcs(t)
    if col == 'QTY':
        pen = 0.5 if (pcs is not None and hp != pcs) else 0.0
        if tt == '':
            return (0.8 + pen) if hp else 1.0
        if RE_QDIG.fullmatch(tt):
            return pen
        if RE_MON.fullmatch(tt):
            return 2.5 + pen
        return 5.0
    if hp:
        return 4.0
    if RE_MON.fullmatch(tt):
        if re.search(r'[0-9]', tt):
            return 0.0 if re.search(r'[.,]', tt) else 0.3
        return 1.0
    return 5.0


def plausible(t):
    return min(tok_cost(t, c, None) for c in COLS) <= 2.0


def align(toks, order, pcs, lam):
    n = len(toks)
    INF = 1e18
    MISS = 5.0
    costs = [[tok_cost(t, order[p], pcs) for p in range(4)] for t, k in toks]
    skipc = [0.0 if k == 't' else (2.5 if t == '' else 3.0) for t, k in toks]
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(2):
            for p in range(4):
                if dp[i][p] < INF:
                    q = (p + 1) % 4
                    c = dp[i][p] + MISS + (lam if p == 3 else 0.0)
                    if c < dp[i][q] - 1e-9:
                        dp[i][q] = c
                        bk[i][q] = ('m', i, p)
        if i == n:
            break
        for p in range(4):
            if dp[i][p] >= INF:
                continue
            c = dp[i][p] + costs[i][p] + (lam if p == 3 else 0.0)
            q = (p + 1) % 4
            if c < dp[i + 1][q]:
                dp[i + 1][q] = c
                bk[i + 1][q] = ('a', i, p)
            c = dp[i][p] + skipc[i]
            if c < dp[i + 1][p]:
                dp[i + 1][p] = c
                bk[i + 1][p] = ('s', i, p)
    ops = []
    i, p = n, 0
    guard = 0
    while not (i == 0 and p == 0) and guard < 10 * (n + 5):
        guard += 1
        b = bk[i][p]
        if b is None:
            break
        ops.append(b)
        i, p = b[1], b[2]
    ops.reverse()
    rows = []
    cur = {}
    ncomp = 0
    for kind, ti, pp in ops:
        if kind == 's':
            continue
        cur[order[pp]] = toks[ti][0] if kind == 'a' else None
        if pp == 3:
            ncomp += 1
            rows.append(cur)
            cur = {}
    raw = dp[n][0] - lam * ncomp if dp[n][0] < INF else 1e9
    return [r for r in rows if any(r.get(c) is not None for c in COLS)], raw


def split_line(s, mode):
    if mode == 'pipe':
        parts = s.split('|')
    elif mode == 'semi':
        parts = s.split(';')
    elif mode == 'tab':
        parts = s.split('\t')
    else:
        parts = re.split(r' {3}|\t', s)
    return [p.strip() for p in parts]


def parse_doc(text):
    lines = text.split('\n')
    order = list(COLS)
    mode = None
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            ms = list(re.finditer(r'CODE|QTY|UNIT|AMOUNT', rest))
            names = [m.group(0) for m in ms]
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            if len(ms) >= 2:
                sep = rest[ms[0].end():ms[1].start()]
                if '|' in sep:
                    mode = 'pipe'
                elif ';' in sep:
                    mode = 'semi'
                elif '\t' in sep:
                    mode = 'tab'
                else:
                    mode = 'space'
            break
    if mode is None:
        body = '\n'.join(l for l in lines if not re.match(r'\s*(MANIFEST|COLUMNS|==|SUBTOTAL|TOTAL)', l))
        cnt = {'pipe': body.count('|'), 'semi': body.count(';'), 'tab': body.count('\t')}
        mode = max(cnt, key=lambda k: cnt[k]) if max(cnt.values()) > 0 else 'space'
    sections = []
    cur = None
    ttok = None
    itok = None
    for ln in lines:
        raw = ln.rstrip('\r')
        st = raw.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', st):
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                if sections and sections[-1]['sub'] is None:
                    cur = sections[-1]
                else:
                    cur = {'toks': [], 'sub': None}
                    sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s*(.*?)\s*ITEMS\s*(.*)$', st)
            if m:
                ttok = m.group(1).strip()
                itok = m.group(2).strip()
            else:
                ttok = st[5:].strip()
            continue
        parts = split_line(raw, mode)
        toks = []
        for k, p in enumerate(parts):
            kind = 't' if (p == '' and k == len(parts) - 1 and k > 0) else 'f'
            toks.append((p, kind))
        nonempty = [p for p, _ in toks if p]
        if not nonempty:
            continue
        if len(nonempty) == 1 and not plausible(nonempty[0]):
            alt = [x.strip() for x in SPLIT_RE.split(raw) if x.strip()]
            if len(alt) >= 3 and all(plausible(x) for x in alt):
                toks = [(x, 'f') for x in alt]
                nonempty = alt
        if not any(plausible(p) for p in nonempty):
            continue
        if cur is None:
            if sections and sections[-1]['sub'] is None:
                cur = sections[-1]
            else:
                cur = {'toks': [], 'sub': None}
                sections.append(cur)
        cur['toks'].extend(toks)
    return order, sections, ttok, itok


# ---------------- numeric reasoning ----------------

def row_cands(r, Dm, Dq):
    Q, U, A = r['Q'], r['U'], r['A']
    trip = {}

    def add(c, q, u):
        k = (q, u)
        if k not in trip or trip[k] > c:
            trip[k] = c
    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(cq + cu + ca, q, u)
    best = min(trip.values()) if trip else 99.0
    if best > 0:
        for q, cq in Q.items():
            if cq > 1.5:
                continue
            for u, cu in U.items():
                if cq + cu <= 1.5 and (q, u) not in trip:
                    add(cq + cu + Dm(q * u, r['oa']), q, u)
        for a, ca in A.items():
            if ca > 1.5:
                continue
            for q, cq in Q.items():
                if ca + cq <= 1.5 and a % q == 0:
                    add(ca + cq + Dm(a // q, r['ou']), q, a // q)
            for u, cu in U.items():
                if ca + cu <= 1.5 and a % u == 0:
                    q = a // u
                    if 1 <= q <= 500:
                        add(ca + cu + Dq(q, r['oq']), q, u)
    if not trip:
        q = min(Q.items(), key=lambda x: x[1])[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: x[1])[0]
        elif A:
            u = max(1, min(A.items(), key=lambda x: x[1])[0] // q)
        else:
            u = 100
        return [[50.0, q, u, q * u]]
    lst = sorted([[c, k[0], k[1], k[0] * k[1]] for k, c in trip.items()], key=lambda x: x[0])
    return lst[:12]


def solve_section(rows, score, targets, deadline, Dm, Dq):
    if not rows:
        return [], 0, 0.0
    base = [r['tr'][0] for r in rows]
    tot = sum(t[3] for t in base)
    rc = sum(t[0] for t in base)
    s0 = score(tot)
    best_obj = rc + s0
    best_mod = None
    if s0 <= 0:
        return base, tot, best_obj
    alts = []
    bydelta = {}
    for i, r in enumerate(rows):
        b = base[i]
        for t in r['tr'][1:]:
            d = t[3] - b[3]
            if d == 0:
                continue
            dc = t[0] - b[0]
            alts.append((i, t, d, dc))
            ns = tot + d
            if ns > 0:
                obj = rc + dc + score(ns)
                if obj < best_obj - 1e-9:
                    best_obj = obj
                    best_mod = [(i, t)]
            bydelta.setdefault(d, []).append((dc, i, t))
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        if rc + st >= best_obj:
            continue
        need = tv - tot
        for (i, t, d, dc) in alts:
            if rc + dc + st >= best_obj:
                continue
            lst = bydelta.get(need - d)
            if not lst:
                continue
            for (dc2, j, t2) in lst:
                if j > i:
                    obj = rc + dc + dc2 + st
                    if obj < best_obj - 1e-9:
                        best_obj = obj
                        best_mod = [(i, t), (j, t2)]
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        for i, r in enumerate(rows):
            b = base[i]
            req = tv - (tot - b[3])
            if req <= 0:
                continue
            basec = rc - b[0] + st
            if basec >= best_obj:
                continue
            ca = r['A'].get(req)
            if ca is None:
                ca = Dm(req, r['oa'])
            if basec + ca >= best_obj:
                continue
            for q, cq in r['Q'].items():
                if req % q:
                    continue
                u = req // q
                cu = r['U'].get(u)
                if cu is None:
                    if cq > 0:
                        continue
                    cu = Dm(u, r['ou'])
                c = cq + cu + ca
                if basec + c < best_obj - 1e-9:
                    best_obj = basec + c
                    best_mod = [(i, [c, q, u, req])]
            for u, cu in r['U'].items():
                if cu > 0.5 or req % u:
                    continue
                q = req // u
                if 1 <= q <= 500 and q not in r['Q']:
                    c = cu + Dq(q, r['oq']) + ca
                    if basec + c < best_obj - 1e-9:
                        best_obj = basec + c
                        best_mod = [(i, [c, q, u, req])]
    choice = list(base)
    if best_mod:
        for i, t in best_mod:
            choice[i] = t
    tot = sum(t[3] for t in choice)
    return choice, tot, best_obj


def make_scorer(tok, dist):
    if tok is None or not tok.strip():
        return None, []
    C = money_cands(tok)
    o = mdigits(tok)
    cache = {}

    def f(s):
        v = C.get(s)
        if v is None:
            v = cache.get(s)
            if v is None:
                v = min(6.0, dist(str(s).zfill(3), o)) if s > 0 else 6.0
                cache[s] = v
        return v
    targ = sorted([(v, c) for v, c in C.items() if c <= 1.0], key=lambda x: (x[1], x[0]))[:10]
    return f, targ


def comb(fs, ft, off):
    def f(s):
        v = fs(s) if fs else 0.0
        if ft:
            v += ft(off + s)
        return v
    return f


def align_all(sections, order, pcs, lam):
    out = []
    for sec in sections:
        try:
            out.append(align(sec['toks'], order, pcs, lam))
        except Exception:
            out.append(([], 0.0))
    return out


def recover(state, params):
    t0 = time.perf_counter()
    state['output'] = {'items': []}
    text = (state.get('input') or {}).get('text', '') or ''
    try:
        order, sections, ttok, itok = parse_doc(text)
    except Exception:
        return state
    dist = make_dist()

    def Dm(c, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(c).zfill(3), obs))

    def Dq(q, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(q), obs))

    npcs = 0
    for sec in sections:
        for t, k in sec['toks']:
            if t and has_pcs(t):
                npcs += 1
    pcs = npcs >= 2

    aligned = align_all(sections, order, pcs, 0.0)
    # item-count guided re-alignment
    try:
        tcount = None
        if itok:
            d = digits_of(itok)
            if d and len(d) <= 3:
                tcount = int(d)
        cnt0 = sum(len(a[0]) for a in aligned)
        base_cost = sum(a[1] for a in aligned)
        if tcount is not None and 6 <= tcount <= 60 and cnt0 != tcount and sections:
            lams = [-0.5, -1.0, -1.5, -2.0, -3.0, -4.0, -5.0] if tcount > cnt0 else [0.5, 1.0, 1.5, 2.0, 3.0, 4.0, 5.0]
            best = None
            for lam in lams:
                if time.perf_counter() - t0 > 0.25:
                    break
                al = align_all(sections, order, pcs, lam)
                c = sum(len(a[0]) for a in al)
                if c == tcount:
                    extra = sum(a[1] for a in al) - base_cost
                    if extra <= 6.0 and (best is None or extra < best[0] - 1e-9):
                        best = (extra, al)
            if best is not None:
                aligned = best[1]
    except Exception:
        pass

    secs = []
    for sec, (rows, _c) in zip(sections, aligned):
        rr = []
        for r in rows:
            tq, tu, ta = r.get('QTY'), r.get('UNIT'), r.get('AMOUNT')
            try:
                code = solve_code(r.get('CODE'))
            except Exception:
                code = 'AA00000'
            row = {'code': code, 'Q': qty_cands(tq), 'U': money_cands(tu), 'A': money_cands(ta),
                   'oq': digits_of(tq), 'ou': mdigits(tu), 'oa': mdigits(ta)}
            try:
                row['tr'] = row_cands(row, Dm, Dq)
            except Exception:
                row['tr'] = [[50.0, 1, 100, 100]]
            rr.append(row)
        fS, targ = make_scorer(sec['sub'], dist)
        secs.append({'rows': rr, 'fS': fS, 'targ': targ})

    results = [[[r['tr'][0] for r in s['rows']], 0, 0.0] for s in secs]

    def emit():
        items = []
        for s, res in zip(secs, results):
            for r, t in zip(s['rows'], res[0]):
                items.append({'code': r['code'], 'qty': int(t[1]), 'unit_cents': int(t[2])})
        state['output'] = {'items': items}
    emit()
    try:
        fT, Ttarg = make_scorer(ttok, dist)
        dl1 = t0 + 0.55
        for i, s in enumerate(secs):
            if len(secs) == 1:
                sc = comb(s['fS'], fT, 0)
                targ = list(s['targ']) + list(Ttarg)
            else:
                sc = comb(s['fS'], None, 0)
                targ = s['targ']
            ch, tt, obj = solve_section(s['rows'], sc, targ, dl1, Dm, Dq)
            results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
        dl2 = t0 + 0.8
        if fT and len(secs) > 1:
            for _ in range(3):
                if time.perf_counter() > dl2:
                    break
                grand = sum(r[1] for r in results)
                ct = fT(grand)
                if ct <= 0:
                    break
                best_gain = 1e-9
                best = None
                for i, s in enumerate(secs):
                    if time.perf_counter() > dl2 or not s['rows']:
                        continue
                    other = grand - results[i][1]
                    fS = s['fS']
                    sc = comb(fS, fT, other)
                    targ = list(s['targ']) + [(tv - other, c) for tv, c in Ttarg if tv - other > 0]
                    ch, tt, obj = solve_section(s['rows'], sc, targ, dl2, Dm, Dq)
                    old = results[i][2] + (fS(results[i][1]) if fS else 0.0) + ct
                    gain = old - obj
                    if gain > best_gain:
                        best_gain = gain
                        best = (i, ch, tt)
                if best is None:
                    break
                i, ch, tt = best
                results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
    except Exception:
        pass
    return state

import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
REV = {}
for _o in sorted(MIS):
    for _s in MIS[_o]:
        REV[_s] = REV.get(_s, '') + _o

L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
       'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
COLS = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
C_MIS = 1.0
C_DUP = 1.0
C_LOST = 1.2
C_MARK = 0.5

RE_CODE = re.compile(r'[A-Za-z0-9]{2}[0-9A-Za-z]{2,8}')
RE_QDIG = re.compile(r'[0-9OolIiSsBZzG]{1,4}')
RE_MON = re.compile(r"[0-9OolIiSsBZzG.,']{1,14}")


def strip_pcs(t):
    return re.sub(r'(?i)\s*pcs\s*$', '', t.strip())


def has_pcs(t):
    return re.search(r'(?i)pcs\s*$', t.strip()) is not None


def digits_of(tok):
    if tok is None:
        return None
    s = strip_pcs(tok)
    return ''.join(L2D.get(c, c) for c in s if c.isdigit() or c in L2D)


def num_edits(s):
    out = {s: 0.0}
    n = len(s)

    def put(v, c):
        if v not in out or out[v] > c:
            out[v] = c
    for i, ch in enumerate(s):
        if ch.isdigit():
            for y in REV.get(ch, ''):
                put(s[:i] + y + s[i + 1:], C_MIS)
            if i + 1 < n and s[i + 1] == ch:
                put(s[:i] + s[i + 1:], C_DUP)
    for i in range(n + 1):
        for d in '0123456789':
            put(s[:i] + d + s[i:], C_LOST)
    return out


def norm_money(tok):
    t = ''.join(L2D.get(c, c) for c in tok)
    t = t.replace("'", '').replace(' ', '').replace(',', '.')
    t = re.sub(r'[^0-9.]', '', t)
    if t.count('.') > 1:
        k = t.rfind('.')
        t = t[:k].replace('.', '') + t[k:]
    return t


def mdigits(tok):
    if tok is None:
        return None
    return norm_money(tok).replace('.', '')


def parse_money(v):
    if '.' in v:
        a, b = v.split('.', 1)
        if len(b) != 2 or not a.isdigit() or not b.isdigit():
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        return (int(a) * 100 + int(b), False)
    if len(v) < 3 or not v.isdigit():
        return None
    if len(v) > 3 and v[0] == '0':
        return None
    return (int(v), True)


def money_cands(tok):
    if tok is None:
        return {}
    t = norm_money(tok)
    if not t or len(t) > 14:
        return {}
    res = {}
    for v, c in num_edits(t).items():
        m = parse_money(v)
        if m is None:
            continue
        val, nomark = m
        cc = c + (C_MARK if nomark else 0.0)
        if val > 0 and (val not in res or res[val] > cc):
            res[val] = cc
    return res


def qty_cands(tok):
    if tok is None:
        return {}
    t = digits_of(tok)
    if t == '':
        return {q: C_LOST for q in range(1, 10)}
    if len(t) > 5:
        return {}
    res = {}
    for v, c in num_edits(t).items():
        if not v or (len(v) > 1 and v[0] == '0'):
            continue
        q = int(v)
        if 1 <= q <= 500 and (q not in res or res[q] > c):
            res[q] = c
    return res


def make_dist():
    cache = {}

    def dist(orig, obs):
        k = orig + '|' + obs
        v = cache.get(k)
        if v is not None:
            return v
        m = len(obs)
        prev = [0.0] * (m + 1)
        for j in range(1, m + 1):
            prev[j] = prev[j - 1] + (1.0 if j >= 2 and obs[j - 1] == obs[j - 2] else 2.5)
        for i in range(1, len(orig) + 1):
            oc = orig[i - 1]
            mis = MIS.get(oc, '')
            cur = [prev[0] + 1.2] + [0.0] * m
            for j in range(1, m + 1):
                sc = obs[j - 1]
                if sc == oc:
                    sub = prev[j - 1]
                elif sc in mis:
                    sub = prev[j - 1] + 1.0
                else:
                    sub = prev[j - 1] + 2.5
                ins = cur[j - 1] + (1.0 if (j >= 2 and obs[j - 2] == sc) else 2.5)
                dele = prev[j] + 1.2
                b = sub
                if ins < b:
                    b = ins
                if dele < b:
                    b = dele
                cur[j] = b
            prev = cur
        r = prev[m]
        cache[k] = r
        return r
    return dist


# ---------------- codes ----------------

def code_ok(L, s):
    if len(s) != 5 or not s.isdigit():
        return False
    p1 = ord(L[0]) - 64
    p2 = ord(L[1]) - 64
    d = [int(c) for c in s]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def code_split(tok):
    t = (tok or '').replace(' ', '')
    letters = ''
    for c in t[:2]:
        if c.isalpha() and 'A' <= c.upper() <= 'Z':
            letters += c.upper()
        elif c in D2L:
            letters += D2L[c]
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    digs = ''.join(L2D.get(c, c) for c in t[2:] if c.isdigit() or c in L2D)
    return letters, digs


def code_edit_list(d):
    res = []
    for i, ch in enumerate(d):
        for o in REV.get(ch, ''):
            res.append((d[:i] + o + d[i + 1:], C_MIS))
    for i in range(len(d) - 1):
        if d[i] == d[i + 1]:
            res.append((d[:i] + d[i + 1:], C_DUP))
    for i in range(len(d) + 1):
        for o in '0123456789':
            res.append((d[:i] + o + d[i:], C_LOST))
    return res


def code_fallback(letters, digs):
    d4 = digs[:4].ljust(4, '0')
    dd = [int(c) for c in d4]
    chk = (dd[0] + 2 * dd[1] + 3 * dd[2] + 4 * dd[3] + ord(letters[0]) - 64 + ord(letters[1]) - 64) % 10
    return letters + d4 + str(chk)


def solve_code(tok):
    if not tok:
        return 'AA00000'
    letters, digs = code_split(tok)
    if code_ok(letters, digs):
        return letters + digs
    counts = {}
    order = []
    for s, c in code_edit_list(digs):
        if code_ok(letters, s):
            if s not in counts:
                counts[s] = [c, 0]
                order.append(s)
            if c < counts[s][0]:
                counts[s][0] = c
            counts[s][1] += 1
    if order:
        best = None
        for s in order:
            c, n = counts[s]
            key = (c, -n)
            if best is None or key < best[0]:
                best = (key, s)
        return letters + best[1]
    l1 = {}
    for s, c in code_edit_list(digs):
        if s not in l1 or l1[s] > c:
            l1[s] = c
    best = None
    for s, c in l1.items():
        if not (4 <= len(s) <= 6):
            continue
        for s2, c2 in code_edit_list(s):
            if len(s2) == 5 and code_ok(letters, s2):
                tot = c + c2
                if best is None or tot < best[0]:
                    best = (tot, s2)
    if best is not None:
        return letters + best[1]
    return code_fallback(letters, digs)


# ---------------- tokens / alignment ----------------

def tok_cost(t, col, pcs):
    if t == '':
        if col == 'QTY':
            return 1.0
        return 6.0 if col == 'CODE' else 4.0
    if col == 'CODE':
        if RE_CODE.fullmatch(t):
            nl = sum(1 for c in t[:2] if c.isalpha())
            bad = sum(1 for c in t[2:] if c.isalpha() and c not in L2D)
            base = 0.0 if nl == 2 else (0.5 if nl == 1 else 2.0)
            return base + 2.0 * bad
        return 5.0
    hp = has_pcs(t)
    tt = strip_pcs(t)
    if col == 'QTY':
        pen = 0.5 if (pcs is not None and hp != pcs) else 0.0
        if tt == '':
            return (0.8 + pen) if hp else 1.0
        if RE_QDIG.fullmatch(tt):
            return pen
        if RE_MON.fullmatch(tt):
            return 2.5 + pen
        return 5.0
    if hp:
        return 4.0
    if RE_MON.fullmatch(tt):
        if re.search(r'[0-9]', tt):
            return 0.0 if re.search(r'[.,]', tt) else 0.3
        return 1.0
    return 5.0


def plausible(t):
    return min(tok_cost(t, c, None) for c in COLS) <= 2.0


def align(toks, order, pcs):
    n = len(toks)
    INF = 1e18
    MISS = 5.0
    costs = [[tok_cost(t, order[p], pcs) for p in range(4)] for t, k in toks]
    skipc = [0.0 if k == 't' else (2.5 if t == '' else 3.0) for t, k in toks]
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(2):
            for p in range(4):
                if dp[i][p] < INF:
                    q = (p + 1) % 4
                    c = dp[i][p] + MISS
                    if c < dp[i][q] - 1e-9:
                        dp[i][q] = c
                        bk[i][q] = ('m', i, p)
        if i == n:
            break
        for p in range(4):
            if dp[i][p] >= INF:
                continue
            c = dp[i][p] + costs[i][p]
            q = (p + 1) % 4
            if c < dp[i + 1][q]:
                dp[i + 1][q] = c
                bk[i + 1][q] = ('a', i, p)
            c = dp[i][p] + skipc[i]
            if c < dp[i + 1][p]:
                dp[i + 1][p] = c
                bk[i + 1][p] = ('s', i, p)
    ops = []
    i, p = n, 0
    guard = 0
    while not (i == 0 and p == 0) and guard < 10 * (n + 5):
        guard += 1
        b = bk[i][p]
        if b is None:
            break
        ops.append(b)
        i, p = b[1], b[2]
    ops.reverse()
    rows = []
    cur = {}
    for kind, ti, pp in ops:
        if kind == 's':
            continue
        cur[order[pp]] = toks[ti][0] if kind == 'a' else None
        if pp == 3:
            rows.append(cur)
            cur = {}
    return [r for r in rows if any(r.get(c) is not None for c in COLS)]


def split_line(s, mode):
    if mode == 'pipe':
        parts = s.split('|')
    elif mode == 'semi':
        parts = s.split(';')
    elif mode == 'tab':
        parts = s.split('\t')
    else:
        parts = re.split(r' {3}|\t', s)
    return [p.strip() for p in parts]


def parse_doc(text):
    lines = text.split('\n')
    order = list(COLS)
    mode = None
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            ms = list(re.finditer(r'CODE|QTY|UNIT|AMOUNT', rest))
            names = [m.group(0) for m in ms]
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            if len(ms) >= 2:
                sep = rest[ms[0].end():ms[1].start()]
                if '|' in sep:
                    mode = 'pipe'
                elif ';' in sep:
                    mode = 'semi'
                elif '\t' in sep:
                    mode = 'tab'
                else:
                    mode = 'space'
            break
    if mode is None:
        body = '\n'.join(l for l in lines if not re.match(r'\s*(MANIFEST|COLUMNS|==|SUBTOTAL|TOTAL)', l))
        cnt = {'pipe': body.count('|'), 'semi': body.count(';'), 'tab': body.count('\t')}
        mode = max(cnt, key=lambda k: cnt[k]) if max(cnt.values()) > 0 else 'space'
    sections = []
    cur = None
    ttok = None
    itok = None
    for ln in lines:
        raw = ln.rstrip('\r')
        st = raw.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', st):
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                if sections and sections[-1]['sub'] is None:
                    cur = sections[-1]
                else:
                    cur = {'toks': [], 'sub': None}
                    sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s*(.*?)\s*ITEMS\s*(.*)$', st)
            if m:
                ttok = m.group(1).strip()
                itok = m.group(2).strip()
            else:
                ttok = st[5:].strip()
            continue
        parts = split_line(raw, mode)
        toks = []
        for k, p in enumerate(parts):
            kind = 't' if (p == '' and k == len(parts) - 1 and k > 0) else 'f'
            toks.append((p, kind))
        nonempty = [p for p, _ in toks if p]
        if not nonempty:
            continue
        if not any(plausible(p) for p in nonempty):
            continue
        if cur is None:
            if sections and sections[-1]['sub'] is None:
                cur = sections[-1]
            else:
                cur = {'toks': [], 'sub': None}
                sections.append(cur)
        cur['toks'].extend(toks)
    return order, sections, ttok, itok


# ---------------- numeric reasoning ----------------

def row_cands(r, Dm, Dq):
    Q, U, A = r['Q'], r['U'], r['A']
    trip = {}

    def add(c, q, u):
        k = (q, u)
        if k not in trip or trip[k] > c:
            trip[k] = c
    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(cq + cu + ca, q, u)
    best = min(trip.values()) if trip else 99.0
    if best > 0:
        for q, cq in Q.items():
            if cq > 1.5:
                continue
            for u, cu in U.items():
                if cq + cu <= 1.5 and (q, u) not in trip:
                    add(cq + cu + Dm(q * u, r['oa']), q, u)
        for a, ca in A.items():
            if ca > 1.5:
                continue
            for q, cq in Q.items():
                if ca + cq <= 1.5 and a % q == 0:
                    add(ca + cq + Dm(a // q, r['ou']), q, a // q)
            for u, cu in U.items():
                if ca + cu <= 1.5 and a % u == 0:
                    q = a // u
                    if 1 <= q <= 500:
                        add(ca + cu + Dq(q, r['oq']), q, u)
    if not trip:
        q = min(Q.items(), key=lambda x: x[1])[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: x[1])[0]
        elif A:
            u = max(1, min(A.items(), key=lambda x: x[1])[0] // q)
        else:
            u = 100
        return [[50.0, q, u, q * u]]
    lst = sorted([[c, k[0], k[1], k[0] * k[1]] for k, c in trip.items()], key=lambda x: x[0])
    return lst[:12]


def solve_section(rows, score, targets, deadline, Dm, Dq):
    if not rows:
        return [], 0, 0.0
    base = [r['tr'][0] for r in rows]
    tot = sum(t[3] for t in base)
    rc = sum(t[0] for t in base)
    s0 = score(tot)
    best_obj = rc + s0
    best_mod = None
    if s0 <= 0:
        return base, tot, best_obj
    alts = []
    bydelta = {}
    for i, r in enumerate(rows):
        b = base[i]
        for t in r['tr'][1:]:
            d = t[3] - b[3]
            if d == 0:
                continue
            dc = t[0] - b[0]
            alts.append((i, t, d, dc))
            ns = tot + d
            if ns > 0:
                obj = rc + dc + score(ns)
                if obj < best_obj - 1e-9:
                    best_obj = obj
                    best_mod = [(i, t)]
            bydelta.setdefault(d, []).append((dc, i, t))
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        if rc + st >= best_obj:
            continue
        need = tv - tot
        for (i, t, d, dc) in alts:
            if rc + dc + st >= best_obj:
                continue
            lst = bydelta.get(need - d)
            if not lst:
                continue
            for (dc2, j, t2) in lst:
                if j > i:
                    obj = rc + dc + dc2 + st
                    if obj < best_obj - 1e-9:
                        best_obj = obj
                        best_mod = [(i, t), (j, t2)]
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        for i, r in enumerate(rows):
            b = base[i]
            req = tv - (tot - b[3])
            if req <= 0:
                continue
            basec = rc - b[0] + st
            if basec >= best_obj:
                continue
            ca = r['A'].get(req)
            if ca is None:
                ca = Dm(req, r['oa'])
            if basec + ca >= best_obj:
                continue
            for q, cq in r['Q'].items():
                if req % q:
                    continue
                u = req // q
                cu = r['U'].get(u)
                if cu is None:
                    if cq > 0:
                        continue
                    cu = Dm(u, r['ou'])
                c = cq + cu + ca
                if basec + c < best_obj - 1e-9:
                    best_obj = basec + c
                    best_mod = [(i, [c, q, u, req])]
            for u, cu in r['U'].items():
                if cu > 0.5 or req % u:
                    continue
                q = req // u
                if 1 <= q <= 500 and q not in r['Q']:
                    c = cu + Dq(q, r['oq']) + ca
                    if basec + c < best_obj - 1e-9:
                        best_obj = basec + c
                        best_mod = [(i, [c, q, u, req])]
    choice = list(base)
    if best_mod:
        for i, t in best_mod:
            choice[i] = t
    tot = sum(t[3] for t in choice)
    return choice, tot, best_obj


def make_scorer(tok, dist):
    if tok is None or not tok.strip():
        return None, []
    C = money_cands(tok)
    o = mdigits(tok)
    cache = {}

    def f(s):
        v = C.get(s)
        if v is None:
            v = cache.get(s)
            if v is None:
                v = min(6.0, dist(str(s).zfill(3), o)) if s > 0 else 6.0
                cache[s] = v
        return v
    targ = sorted([(v, c) for v, c in C.items() if c <= 1.0], key=lambda x: (x[1], x[0]))[:10]
    return f, targ


def comb(fs, ft, off):
    def f(s):
        v = fs(s) if fs else 0.0
        if ft:
            v += ft(off + s)
        return v
    return f


def recover(state, params):
    t0 = time.perf_counter()
    state['output'] = {'items': []}
    state['_ctoks'] = []
    state['_noise'] = []
    text = (state.get('input') or {}).get('text', '') or ''
    try:
        order, sections, ttok, itok = parse_doc(text)
    except Exception:
        return state
    dist = make_dist()

    def Dm(c, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(c).zfill(3), obs))

    def Dq(q, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(q), obs))

    npcs = 0
    for sec in sections:
        for t, k in sec['toks']:
            if t and has_pcs(t):
                npcs += 1
    pcs = npcs >= 2
    secs = []
    for sec in sections:
        try:
            rows = align(sec['toks'], order, pcs)
        except Exception:
            rows = []
        rr = []
        for r in rows:
            tq, tu, ta = r.get('QTY'), r.get('UNIT'), r.get('AMOUNT')
            try:
                code = solve_code(r.get('CODE'))
            except Exception:
                code = 'AA00000'
            row = {'code': code, 'ctok': r.get('CODE'), 'Q': qty_cands(tq), 'U': money_cands(tu),
                   'A': money_cands(ta), 'oq': digits_of(tq), 'ou': mdigits(tu), 'oa': mdigits(ta)}
            try:
                row['tr'] = row_cands(row, Dm, Dq)
            except Exception:
                row['tr'] = [[50.0, 1, 100, 100]]
            rr.append(row)
        fS, targ = make_scorer(sec['sub'], dist)
        secs.append({'rows': rr, 'fS': fS, 'targ': targ})

    results = [[[r['tr'][0] for r in s['rows']], 0, 0.0] for s in secs]

    def emit():
        items = []
        ctoks = []
        noise = []
        for s, res in zip(secs, results):
            for r, t in zip(s['rows'], res[0]):
                items.append({'code': r['code'], 'qty': int(t[1]), 'unit_cents': int(t[2])})
                ctoks.append(r['ctok'])
                if t[0] < 6.0:
                    if r['oq']:
                        noise.append([str(int(t[1])), r['oq']])
                    if r['ou']:
                        noise.append([str(int(t[2])).zfill(3), r['ou']])
                    if r['oa']:
                        noise.append([str(int(t[3])).zfill(3), r['oa']])
        state['output'] = {'items': items}
        state['_ctoks'] = ctoks
        state['_noise'] = noise
    emit()
    try:
        fT, Ttarg = make_scorer(ttok, dist)
        dl1 = t0 + 0.5
        for i, s in enumerate(secs):
            if len(secs) == 1:
                sc = comb(s['fS'], fT, 0)
                targ = list(s['targ']) + list(Ttarg)
            else:
                sc = comb(s['fS'], None, 0)
                targ = s['targ']
            ch, tt, obj = solve_section(s['rows'], sc, targ, dl1, Dm, Dq)
            results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
        dl2 = t0 + 0.72
        if fT and len(secs) > 1:
            for _ in range(3):
                if time.perf_counter() > dl2:
                    break
                grand = sum(r[1] for r in results)
                ct = fT(grand)
                if ct <= 0:
                    break
                best_gain = 1e-9
                best = None
                for i, s in enumerate(secs):
                    if time.perf_counter() > dl2 or not s['rows']:
                        continue
                    other = grand - results[i][1]
                    fS = s['fS']
                    sc = comb(fS, fT, other)
                    targ = list(s['targ']) + [(tv - other, c) for tv, c in Ttarg if tv - other > 0]
                    ch, tt, obj = solve_section(s['rows'], sc, targ, dl2, Dm, Dq)
                    old = results[i][2] + (fS(results[i][1]) if fS else 0.0) + ct
                    gain = old - obj
                    if gain > best_gain:
                        best_gain = gain
                        best = (i, ch, tt)
                if best is None:
                    break
                i, ch, tt = best
                results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
    except Exception:
        pass
    return state


# ---------------- node 2: noise profile + probabilistic code decoding ----------------

def learn_profile(noise, ctoks):
    mis = 0.0
    dup = 0.0
    lost = 0.0
    N = 0.0
    for pair in noise:
        o, s = pair[0], pair[1]
        if not o or s is None:
            continue
        N += len(o)
        if len(s) == len(o):
            d = sum(1 for a, b in zip(o, s) if a != b)
            mis += min(d, 2)
        elif len(s) == len(o) - 1:
            lost += 1
        elif len(s) == len(o) + 1:
            dup += 1
    for tok in ctoks:
        if not tok:
            continue
        L, d = code_split(tok)
        N += 5
        if len(d) == 4:
            lost += 1
        elif len(d) == 6:
            dup += 1
        elif len(d) == 5 and not code_ok(L, d):
            mis += 1.1
    den = N + 30.0
    return {'mis': (mis + 1.0) / den, 'dup': (dup + 0.5) / den, 'lost': (lost + 0.5) / den}


def prob_steps(s, w, R):
    out = []
    for i, ch in enumerate(s):
        for o in REV.get(ch, ''):
            out.append((s[:i] + o + s[i + 1:], w * R['mis'] / len(MIS[o])))
    for i in range(len(s) - 1):
        if s[i] == s[i + 1]:
            out.append((s[:i] + s[i + 1:], w * R['dup']))
    lw = w * R['lost'] / 10.0
    for i in range(len(s) + 1):
        for d in '0123456789':
            out.append((s[:i] + d + s[i:], lw))
    return out


def decode_code(tok, R):
    if not tok:
        return None
    letters, digs = code_split(tok)
    if code_ok(letters, digs):
        return letters + digs
    if len(digs) > 8:
        return None
    lvl1 = {}
    for s, w in prob_steps(digs, 1.0, R):
        lvl1[s] = lvl1.get(s, 0.0) + w
    good = {s: w for s, w in lvl1.items() if len(s) == 5 and code_ok(letters, s)}
    if not good:
        for s, w in lvl1.items():
            if not (4 <= len(s) <= 6):
                continue
            for s2, w2 in prob_steps(s, w, R):
                if len(s2) == 5 and code_ok(letters, s2):
                    good[s2] = good.get(s2, 0.0) + w2
    if not good:
        return None
    best = max(sorted(good), key=lambda k: good[k])
    return letters + best


def repair_codes(state, params):
    try:
        out = state.get('output') or {}
        items = out.get('items') or []
        ctoks = state.get('_ctoks') or []
        noise = state.get('_noise') or []
        if len(ctoks) != len(items):
            return state
        R = learn_profile(noise, ctoks)
        t0 = time.perf_counter()
        for it, tok in zip(items, ctoks):
            if time.perf_counter() - t0 > 0.15:
                break
            try:
                c = decode_code(tok, R)
            except Exception:
                c = None
            if c:
                it['code'] = c
        state['output'] = {'items': items}
    except Exception:
        pass
    return state

import re
import time
import math

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
REV = {}
for _o in sorted(MIS):
    for _s in MIS[_o]:
        REV[_s] = REV.get(_s, '') + _o

L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
       'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
COLS = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
C_MIS = 1.0
C_DUP = 1.0
C_LOST = 1.2
C_MARK = 0.5


def default_K():
    return {'mis': C_MIS, 'dup': C_DUP, 'lost': C_LOST, 'mark': C_MARK}


RE_CODE = re.compile(r'[A-Za-z0-9]{2}[0-9A-Za-z]{2,8}')
RE_QDIG = re.compile(r'[0-9OolIiSsBZzG]{1,4}')
RE_MON = re.compile(r"[0-9OolIiSsBZzG.,']{1,14}")


def noop(state, params):
    return state


def strip_pcs(t):
    return re.sub(r'(?i)\s*pcs\s*$', '', t.strip())


def has_pcs(t):
    return re.search(r'(?i)pcs\s*$', t.strip()) is not None


def digits_of(tok):
    if tok is None:
        return None
    s = strip_pcs(tok)
    return ''.join(L2D.get(c, c) for c in s if c.isdigit() or c in L2D)


def num_edits(s, K):
    out = {s: 0.0}
    n = len(s)
    cm, cd, cl = K['mis'], K['dup'], K['lost']

    def put(v, c):
        if v not in out or out[v] > c:
            out[v] = c
    for i, ch in enumerate(s):
        if ch.isdigit():
            for y in REV.get(ch, ''):
                put(s[:i] + y + s[i + 1:], cm)
            if i + 1 < n and s[i + 1] == ch:
                put(s[:i] + s[i + 1:], cd)
    for i in range(n + 1):
        for d in '0123456789':
            put(s[:i] + d + s[i:], cl)
    return out


def norm_money(tok):
    t = ''.join(L2D.get(c, c) for c in tok)
    t = t.replace("'", '').replace(' ', '').replace(',', '.')
    t = re.sub(r'[^0-9.]', '', t)
    if t.count('.') > 1:
        k = t.rfind('.')
        t = t[:k].replace('.', '') + t[k:]
    return t


def mdigits(tok):
    if tok is None:
        return None
    return norm_money(tok).replace('.', '')


def parse_money(v):
    if '.' in v:
        a, b = v.split('.', 1)
        if len(b) != 2 or not a.isdigit() or not b.isdigit():
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        return (int(a) * 100 + int(b), False)
    if len(v) < 3 or not v.isdigit():
        return None
    if len(v) > 3 and v[0] == '0':
        return None
    return (int(v), True)


def money_cands(tok, K):
    if tok is None:
        return {}
    t = norm_money(tok)
    if not t or len(t) > 14:
        return {}
    res = {}
    for v, c in num_edits(t, K).items():
        m = parse_money(v)
        if m is None:
            continue
        val, nomark = m
        cc = c + (K['mark'] if nomark else 0.0)
        if val > 0 and (val not in res or res[val] > cc):
            res[val] = cc
    return res


def qty_cands(tok, K):
    if tok is None:
        return {}
    t = digits_of(tok)
    if t == '':
        return {q: K['lost'] for q in range(1, 10)}
    if len(t) > 5:
        return {}
    res = {}
    for v, c in num_edits(t, K).items():
        if not v or (len(v) > 1 and v[0] == '0'):
            continue
        q = int(v)
        if 1 <= q <= 500 and (q not in res or res[q] > c):
            res[q] = c
    return res


def make_dist(K):
    cache = {}
    cm, cd, cl = K['mis'], K['dup'], K['lost']

    def dist(orig, obs):
        k = orig + '|' + obs
        v = cache.get(k)
        if v is not None:
            return v
        m = len(obs)
        prev = [0.0] * (m + 1)
        for j in range(1, m + 1):
            prev[j] = prev[j - 1] + (cd if j >= 2 and obs[j - 1] == obs[j - 2] else 2.5)
        for i in range(1, len(orig) + 1):
            oc = orig[i - 1]
            mis = MIS.get(oc, '')
            cur = [prev[0] + cl] + [0.0] * m
            for j in range(1, m + 1):
                sc = obs[j - 1]
                if sc == oc:
                    sub = prev[j - 1]
                elif sc in mis:
                    sub = prev[j - 1] + cm
                else:
                    sub = prev[j - 1] + 2.5
                ins = cur[j - 1] + (cd if (j >= 2 and obs[j - 2] == sc) else 2.5)
                dele = prev[j] + cl
                b = sub
                if ins < b:
                    b = ins
                if dele < b:
                    b = dele
                cur[j] = b
            prev = cur
        r = prev[m]
        cache[k] = r
        return r
    return dist


# ---------------- codes ----------------

def code_ok(L, s):
    if len(s) != 5 or not s.isdigit():
        return False
    p1 = ord(L[0]) - 64
    p2 = ord(L[1]) - 64
    d = [int(c) for c in s]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def code_split(tok):
    t = (tok or '').replace(' ', '')
    letters = ''
    for c in t[:2]:
        if c.isalpha() and 'A' <= c.upper() <= 'Z':
            letters += c.upper()
        elif c in D2L:
            letters += D2L[c]
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    digs = ''.join(L2D.get(c, c) for c in t[2:] if c.isdigit() or c in L2D)
    return letters, digs


def code_edit_list(d):
    res = []
    for i, ch in enumerate(d):
        for o in REV.get(ch, ''):
            res.append((d[:i] + o + d[i + 1:], C_MIS))
    for i in range(len(d) - 1):
        if d[i] == d[i + 1]:
            res.append((d[:i] + d[i + 1:], C_DUP))
    for i in range(len(d) + 1):
        for o in '0123456789':
            res.append((d[:i] + o + d[i:], C_LOST))
    return res


def code_fallback(letters, digs):
    d4 = digs[:4].ljust(4, '0')
    dd = [int(c) for c in d4]
    chk = (dd[0] + 2 * dd[1] + 3 * dd[2] + 4 * dd[3] + ord(letters[0]) - 64 + ord(letters[1]) - 64) % 10
    return letters + d4 + str(chk)


def solve_code(tok):
    if not tok:
        return 'AA00000'
    letters, digs = code_split(tok)
    if code_ok(letters, digs):
        return letters + digs
    counts = {}
    order = []
    for s, c in code_edit_list(digs):
        if code_ok(letters, s):
            if s not in counts:
                counts[s] = [c, 0]
                order.append(s)
            if c < counts[s][0]:
                counts[s][0] = c
            counts[s][1] += 1
    if order:
        best = None
        for s in order:
            c, n = counts[s]
            key = (c, -n)
            if best is None or key < best[0]:
                best = (key, s)
        return letters + best[1]
    l1 = {}
    for s, c in code_edit_list(digs):
        if s not in l1 or l1[s] > c:
            l1[s] = c
    best = None
    for s, c in l1.items():
        if not (4 <= len(s) <= 6):
            continue
        for s2, c2 in code_edit_list(s):
            if len(s2) == 5 and code_ok(letters, s2):
                tot = c + c2
                if best is None or tot < best[0]:
                    best = (tot, s2)
    if best is not None:
        return letters + best[1]
    return code_fallback(letters, digs)


# ---------------- tokens / alignment ----------------

def tok_cost(t, col, pcs):
    if t == '':
        if col == 'QTY':
            return 1.0
        return 6.0 if col == 'CODE' else 4.0
    if col == 'CODE':
        if RE_CODE.fullmatch(t):
            nl = sum(1 for c in t[:2] if c.isalpha())
            bad = sum(1 for c in t[2:] if c.isalpha() and c not in L2D)
            base = 0.0 if nl == 2 else (0.5 if nl == 1 else 2.0)
            return base + 2.0 * bad
        return 5.0
    hp = has_pcs(t)
    tt = strip_pcs(t)
    if col == 'QTY':
        pen = 0.5 if (pcs is not None and hp != pcs) else 0.0
        if tt == '':
            return (0.8 + pen) if hp else 1.0
        if RE_QDIG.fullmatch(tt):
            return pen
        if RE_MON.fullmatch(tt):
            return 2.5 + pen
        return 5.0
    if hp:
        return 4.0
    if RE_MON.fullmatch(tt):
        if re.search(r'[0-9]', tt):
            return 0.0 if re.search(r'[.,]', tt) else 0.3
        return 1.0
    return 5.0


def plausible(t):
    return min(tok_cost(t, c, None) for c in COLS) <= 2.0


def align(toks, order, pcs):
    n = len(toks)
    INF = 1e18
    MISS = 5.0
    costs = [[tok_cost(t, order[p], pcs) for p in range(4)] for t, k in toks]
    skipc = [0.0 if k == 't' else (2.5 if t == '' else 3.0) for t, k in toks]
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(2):
            for p in range(4):
                if dp[i][p] < INF:
                    q = (p + 1) % 4
                    c = dp[i][p] + MISS
                    if c < dp[i][q] - 1e-9:
                        dp[i][q] = c
                        bk[i][q] = ('m', i, p)
        if i == n:
            break
        for p in range(4):
            if dp[i][p] >= INF:
                continue
            c = dp[i][p] + costs[i][p]
            q = (p + 1) % 4
            if c < dp[i + 1][q]:
                dp[i + 1][q] = c
                bk[i + 1][q] = ('a', i, p)
            c = dp[i][p] + skipc[i]
            if c < dp[i + 1][p]:
                dp[i + 1][p] = c
                bk[i + 1][p] = ('s', i, p)
    ops = []
    i, p = n, 0
    guard = 0
    while not (i == 0 and p == 0) and guard < 10 * (n + 5):
        guard += 1
        b = bk[i][p]
        if b is None:
            break
        ops.append(b)
        i, p = b[1], b[2]
    ops.reverse()
    rows = []
    cur = {}
    for kind, ti, pp in ops:
        if kind == 's':
            continue
        cur[order[pp]] = toks[ti][0] if kind == 'a' else None
        if pp == 3:
            rows.append(cur)
            cur = {}
    return [r for r in rows if any(r.get(c) is not None for c in COLS)]


def split_line(s, mode):
    if mode == 'pipe':
        parts = s.split('|')
    elif mode == 'semi':
        parts = s.split(';')
    elif mode == 'tab':
        parts = s.split('\t')
    else:
        parts = re.split(r' {3}|\t', s)
    return [p.strip() for p in parts]


def parse_doc(text):
    lines = text.split('\n')
    order = list(COLS)
    mode = None
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            ms = list(re.finditer(r'CODE|QTY|UNIT|AMOUNT', rest))
            names = [m.group(0) for m in ms]
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            if len(ms) >= 2:
                sep = rest[ms[0].end():ms[1].start()]
                if '|' in sep:
                    mode = 'pipe'
                elif ';' in sep:
                    mode = 'semi'
                elif '\t' in sep:
                    mode = 'tab'
                else:
                    mode = 'space'
            break
    if mode is None:
        body = '\n'.join(l for l in lines if not re.match(r'\s*(MANIFEST|COLUMNS|==|SUBTOTAL|TOTAL)', l))
        cnt = {'pipe': body.count('|'), 'semi': body.count(';'), 'tab': body.count('\t')}
        mode = max(cnt, key=lambda k: cnt[k]) if max(cnt.values()) > 0 else 'space'
    sections = []
    cur = None
    ttok = None
    itok = None
    for ln in lines:
        raw = ln.rstrip('\r')
        st = raw.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', st):
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                if sections and sections[-1]['sub'] is None:
                    cur = sections[-1]
                else:
                    cur = {'toks': [], 'sub': None}
                    sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s*(.*?)\s*ITEMS\s*(.*)$', st)
            if m:
                ttok = m.group(1).strip()
                itok = m.group(2).strip()
            else:
                ttok = st[5:].strip()
            continue
        parts = split_line(raw, mode)
        toks = []
        for k, p in enumerate(parts):
            kind = 't' if (p == '' and k == len(parts) - 1 and k > 0) else 'f'
            toks.append((p, kind))
        nonempty = [p for p, _ in toks if p]
        if not nonempty:
            continue
        if not any(plausible(p) for p in nonempty):
            continue
        if cur is None:
            if sections and sections[-1]['sub'] is None:
                cur = sections[-1]
            else:
                cur = {'toks': [], 'sub': None}
                sections.append(cur)
        cur['toks'].extend(toks)
    return order, sections, ttok, itok


# ---------------- numeric reasoning ----------------

def row_cands(r, Dm, Dq):
    Q, U, A = r['Q'], r['U'], r['A']
    trip = {}

    def add(c, q, u):
        k = (q, u)
        if k not in trip or trip[k] > c:
            trip[k] = c
    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(cq + cu + ca, q, u)
    best = min(trip.values()) if trip else 99.0
    if best > 0:
        for q, cq in Q.items():
            if cq > 1.5:
                continue
            for u, cu in U.items():
                if cq + cu <= 1.5 and (q, u) not in trip:
                    add(cq + cu + Dm(q * u, r['oa']), q, u)
        for a, ca in A.items():
            if ca > 1.5:
                continue
            for q, cq in Q.items():
                if ca + cq <= 1.5 and a % q == 0:
                    add(ca + cq + Dm(a // q, r['ou']), q, a // q)
            for u, cu in U.items():
                if ca + cu <= 1.5 and a % u == 0:
                    q = a // u
                    if 1 <= q <= 500:
                        add(ca + cu + Dq(q, r['oq']), q, u)
    if not trip:
        q = min(Q.items(), key=lambda x: x[1])[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: x[1])[0]
        elif A:
            u = max(1, min(A.items(), key=lambda x: x[1])[0] // q)
        else:
            u = 100
        return [[50.0, q, u, q * u]]
    lst = sorted([[c, k[0], k[1], k[0] * k[1]] for k, c in trip.items()], key=lambda x: x[0])
    return lst[:12]


def solve_section(rows, score, targets, deadline, Dm, Dq):
    if not rows:
        return [], 0, 0.0
    base = [r['tr'][0] for r in rows]
    tot = sum(t[3] for t in base)
    rc = sum(t[0] for t in base)
    s0 = score(tot)
    best_obj = rc + s0
    best_mod = None
    if s0 <= 0:
        return base, tot, best_obj
    alts = []
    bydelta = {}
    for i, r in enumerate(rows):
        b = base[i]
        for t in r['tr'][1:]:
            d = t[3] - b[3]
            if d == 0:
                continue
            dc = t[0] - b[0]
            alts.append((i, t, d, dc))
            ns = tot + d
            if ns > 0:
                obj = rc + dc + score(ns)
                if obj < best_obj - 1e-9:
                    best_obj = obj
                    best_mod = [(i, t)]
            bydelta.setdefault(d, []).append((dc, i, t))
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        if rc + st >= best_obj:
            continue
        need = tv - tot
        for (i, t, d, dc) in alts:
            if rc + dc + st >= best_obj:
                continue
            lst = bydelta.get(need - d)
            if not lst:
                continue
            for (dc2, j, t2) in lst:
                if j > i:
                    obj = rc + dc + dc2 + st
                    if obj < best_obj - 1e-9:
                        best_obj = obj
                        best_mod = [(i, t), (j, t2)]
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        for i, r in enumerate(rows):
            b = base[i]
            req = tv - (tot - b[3])
            if req <= 0:
                continue
            basec = rc - b[0] + st
            if basec >= best_obj:
                continue
            ca = r['A'].get(req)
            if ca is None:
                ca = Dm(req, r['oa'])
            if basec + ca >= best_obj:
                continue
            for q, cq in r['Q'].items():
                if req % q:
                    continue
                u = req // q
                cu = r['U'].get(u)
                if cu is None:
                    if cq > 0:
                        continue
                    cu = Dm(u, r['ou'])
                c = cq + cu + ca
                if basec + c < best_obj - 1e-9:
                    best_obj = basec + c
                    best_mod = [(i, [c, q, u, req])]
            for u, cu in r['U'].items():
                if cu > 0.5 or req % u:
                    continue
                q = req // u
                if 1 <= q <= 500 and q not in r['Q']:
                    c = cu + Dq(q, r['oq']) + ca
                    if basec + c < best_obj - 1e-9:
                        best_obj = basec + c
                        best_mod = [(i, [c, q, u, req])]
    choice = list(base)
    if best_mod:
        for i, t in best_mod:
            choice[i] = t
    tot = sum(t[3] for t in choice)
    return choice, tot, best_obj


def make_scorer(tok, dist, K):
    if tok is None or not tok.strip():
        return None, []
    C = money_cands(tok, K)
    o = mdigits(tok)
    cache = {}

    def f(s):
        v = C.get(s)
        if v is None:
            v = cache.get(s)
            if v is None:
                v = min(6.0, dist(str(s).zfill(3), o)) if s > 0 else 6.0
                cache[s] = v
        return v
    targ = sorted([(v, c) for v, c in C.items() if c <= 1.0], key=lambda x: (x[1], x[0]))[:10]
    return f, targ


def comb(fs, ft, off):
    def f(s):
        v = fs(s) if fs else 0.0
        if ft:
            v += ft(off + s)
        return v
    return f


def recover(state, params):
    t0 = time.perf_counter()
    second = state.get('_K') is not None
    if '_pt0' not in state:
        state['_pt0'] = time.process_time()
    if second:
        used = time.process_time() - state['_pt0']
        budget = max(0.12, 0.88 - used)
        d_a, d_b = 0.65 * budget, 0.85 * budget
        K = dict(state['_K'])
    else:
        d_a, d_b = 0.5, 0.72
        K = default_K()
    prev_out = state.get('output')
    prev_ct = state.get('_ctoks')
    prev_noise = state.get('_noise')
    text = (state.get('input') or {}).get('text', '') or ''
    try:
        order, sections, ttok, itok = parse_doc(text)
    except Exception:
        if not second:
            state['output'] = {'items': []}
            state['_ctoks'] = []
            state['_noise'] = []
        return state
    if not second:
        state['output'] = {'items': []}
        state['_ctoks'] = []
        state['_noise'] = []
    dist = make_dist(K)

    def Dm(c, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(c).zfill(3), obs))

    def Dq(q, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(q), obs))

    try:
        npcs = 0
        for sec in sections:
            for t, k in sec['toks']:
                if t and has_pcs(t):
                    npcs += 1
        pcs = npcs >= 2
        secs = []
        for sec in sections:
            try:
                rows = align(sec['toks'], order, pcs)
            except Exception:
                rows = []
            rr = []
            for r in rows:
                tq, tu, ta = r.get('QTY'), r.get('UNIT'), r.get('AMOUNT')
                try:
                    code = solve_code(r.get('CODE'))
                except Exception:
                    code = 'AA00000'
                row = {'code': code, 'ctok': r.get('CODE'), 'Q': qty_cands(tq, K), 'U': money_cands(tu, K),
                       'A': money_cands(ta, K), 'oq': digits_of(tq), 'ou': mdigits(tu), 'oa': mdigits(ta)}
                try:
                    row['tr'] = row_cands(row, Dm, Dq)
                except Exception:
                    row['tr'] = [[50.0, 1, 100, 100]]
                rr.append(row)
            fS, targ = make_scorer(sec['sub'], dist, K)
            secs.append({'rows': rr, 'fS': fS, 'targ': targ})
    except Exception:
        if second:
            state['output'] = prev_out
            state['_ctoks'] = prev_ct
            state['_noise'] = prev_noise
        return state

    results = [[[r['tr'][0] for r in s['rows']], 0, 0.0] for s in secs]

    def emit():
        items = []
        ctoks = []
        noise = []
        for s, res in zip(secs, results):
            for r, t in zip(s['rows'], res[0]):
                items.append({'code': r['code'], 'qty': int(t[1]), 'unit_cents': int(t[2])})
                ctoks.append(r['ctok'])
                if t[0] < 6.0:
                    if r['oq']:
                        noise.append([str(int(t[1])), r['oq']])
                    if r['ou']:
                        noise.append([str(int(t[2])).zfill(3), r['ou']])
                    if r['oa']:
                        noise.append([str(int(t[3])).zfill(3), r['oa']])
        state['output'] = {'items': items}
        state['_ctoks'] = ctoks
        state['_noise'] = noise
    emit()
    try:
        fT, Ttarg = make_scorer(ttok, dist, K)
        dl1 = t0 + d_a
        for i, s in enumerate(secs):
            if len(secs) == 1:
                sc = comb(s['fS'], fT, 0)
                targ = list(s['targ']) + list(Ttarg)
            else:
                sc = comb(s['fS'], None, 0)
                targ = s['targ']
            ch, tt, obj = solve_section(s['rows'], sc, targ, dl1, Dm, Dq)
            results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
        dl2 = t0 + d_b
        if fT and len(secs) > 1:
            for _ in range(3):
                if time.perf_counter() > dl2:
                    break
                grand = sum(r[1] for r in results)
                ct = fT(grand)
                if ct <= 0:
                    break
                best_gain = 1e-9
                best = None
                for i, s in enumerate(secs):
                    if time.perf_counter() > dl2 or not s['rows']:
                        continue
                    other = grand - results[i][1]
                    fS = s['fS']
                    sc = comb(fS, fT, other)
                    targ = list(s['targ']) + [(tv - other, c) for tv, c in Ttarg if tv - other > 0]
                    ch, tt, obj = solve_section(s['rows'], sc, targ, dl2, Dm, Dq)
                    old = results[i][2] + (fS(results[i][1]) if fS else 0.0) + ct
                    gain = old - obj
                    if gain > best_gain:
                        best_gain = gain
                        best = (i, ch, tt)
                if best is None:
                    break
                i, ch, tt = best
                results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
    except Exception:
        pass
    return state


# ---------------- noise profile ----------------

def learn_profile(noise, ctoks):
    mis = 0.0
    dup = 0.0
    lost = 0.0
    N = 0.0
    for pair in noise:
        o, s = pair[0], pair[1]
        if not o or s is None:
            continue
        N += len(o)
        if len(s) == len(o):
            d = sum(1 for a, b in zip(o, s) if a != b)
            mis += min(d, 2)
        elif len(s) == len(o) - 1:
            lost += 1
        elif len(s) == len(o) + 1:
            dup += 1
    for tok in ctoks:
        if not tok:
            continue
        L, d = code_split(tok)
        N += 5
        if len(d) == 4:
            lost += 1
        elif len(d) == 6:
            dup += 1
        elif len(d) == 5 and not code_ok(L, d):
            mis += 1.1
    den = N + 30.0
    return {'mis': (mis + 1.0) / den, 'dup': (dup + 0.5) / den, 'lost': (lost + 0.5) / den}


def learn_costs(state, params):
    state['_rerun'] = False
    try:
        R = learn_profile(state.get('_noise') or [], state.get('_ctoks') or [])
        state['_R'] = R
        rm, rd, rl = R['mis'], R['dup'], R['lost']
        ref = (rm * rd * rl) ** (1.0 / 3.0)

        def cst(r, off):
            c = 1.0 + 0.4 * math.log(ref / r) + off
            return max(0.6, min(2.0, c))
        K = {'mis': cst(rm, 0.0), 'dup': cst(rd, 0.0), 'lost': cst(rl, 0.2), 'mark': C_MARK}
        D = default_K()
        dev = max(abs(K[k] - D[k]) for k in ('mis', 'dup', 'lost'))
        used = time.process_time() - state.get('_pt0', time.process_time())
        if dev > 0.15 and used < 0.45 and (state.get('output') or {}).get('items'):
            state['_K'] = K
            state['_rerun'] = True
    except Exception:
        state['_rerun'] = False
    return state


# ---------------- probabilistic code decoding ----------------

def prob_steps(s, w, R):
    out = []
    for i, ch in enumerate(s):
        for o in REV.get(ch, ''):
            out.append((s[:i] + o + s[i + 1:], w * R['mis'] / len(MIS[o])))
    for i in range(len(s) - 1):
        if s[i] == s[i + 1]:
            out.append((s[:i] + s[i + 1:], w * R['dup']))
    lw = w * R['lost'] / 10.0
    for i in range(len(s) + 1):
        for d in '0123456789':
            out.append((s[:i] + d + s[i:], lw))
    return out


def steps_to5(s, w, R):
    n = len(s)
    out = []
    if n == 6:
        for i in range(5):
            if s[i] == s[i + 1]:
                out.append((s[:i] + s[i + 1:], w * R['dup']))
    elif n == 5:
        for i, ch in enumerate(s):
            for o in REV.get(ch, ''):
                out.append((s[:i] + o + s[i + 1:], w * R['mis'] / len(MIS[o])))
    elif n == 4:
        lw = w * R['lost'] / 10.0
        for i in range(5):
            for d in '0123456789':
                out.append((s[:i] + d + s[i:], lw))
    return out


def decode_code(tok, R):
    if not tok:
        return None
    letters, digs = code_split(tok)
    if code_ok(letters, digs):
        return letters + digs
    if len(digs) > 8 or len(digs) < 3:
        return None
    lvl1 = {}
    for s, w in prob_steps(digs, 1.0, R):
        lvl1[s] = lvl1.get(s, 0.0) + w
    good = {}
    for s, w in lvl1.items():
        if len(s) == 5 and code_ok(letters, s):
            good[s] = good.get(s, 0.0) + w
    for s, w in lvl1.items():
        if not (4 <= len(s) <= 6):
            continue
        for s2, w2 in steps_to5(s, w, R):
            if code_ok(letters, s2):
                good[s2] = good.get(s2, 0.0) + w2
    if not good:
        return None
    best = max(sorted(good), key=lambda k: good[k])
    return letters + best


def repair_codes(state, params):
    try:
        out = state.get('output') or {}
        items = out.get('items') or []
        ctoks = state.get('_ctoks') or []
        noise = state.get('_noise') or []
        if len(ctoks) != len(items):
            return state
        R = learn_profile(noise, ctoks)
        t0 = time.perf_counter()
        for it, tok in zip(items, ctoks):
            if time.perf_counter() - t0 > 0.12:
                break
            try:
                c = decode_code(tok, R)
            except Exception:
                c = None
            if c:
                it['code'] = c
        state['output'] = {'items': items}
    except Exception:
        pass
    return state

import re
import time
import math

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
REV = {}
for _o in sorted(MIS):
    for _s in MIS[_o]:
        REV[_s] = REV.get(_s, '') + _o

L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
       'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
COLS = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
C_MIS = 1.0
C_DUP = 1.0
C_LOST = 1.2
C_MARK = 0.5


def default_K():
    return {'mis': C_MIS, 'dup': C_DUP, 'lost': C_LOST, 'mark': C_MARK}


RE_CODE = re.compile(r'[A-Za-z0-9]{2}[0-9A-Za-z]{2,8}')
RE_QDIG = re.compile(r'[0-9OolIiSsBZzG]{1,4}')
RE_MON = re.compile(r"[0-9OolIiSsBZzG.,']{1,14}")


def noop(state, params):
    return state


def strip_pcs(t):
    return re.sub(r'(?i)\s*pcs\s*$', '', t.strip())


def has_pcs(t):
    return re.search(r'(?i)pcs\s*$', t.strip()) is not None


def digits_of(tok):
    if tok is None:
        return None
    s = strip_pcs(tok)
    return ''.join(L2D.get(c, c) for c in s if c.isdigit() or c in L2D)


def num_edits(s, K):
    out = {s: 0.0}
    n = len(s)
    cm, cd, cl = K['mis'], K['dup'], K['lost']

    def put(v, c):
        if v not in out or out[v] > c:
            out[v] = c
    for i, ch in enumerate(s):
        if ch.isdigit():
            for y in REV.get(ch, ''):
                put(s[:i] + y + s[i + 1:], cm)
            if i + 1 < n and s[i + 1] == ch:
                put(s[:i] + s[i + 1:], cd)
    for i in range(n + 1):
        for d in '0123456789':
            put(s[:i] + d + s[i:], cl)
    return out


def norm_money(tok):
    t = ''.join(L2D.get(c, c) for c in tok)
    t = t.replace("'", '').replace(' ', '').replace(',', '.')
    t = re.sub(r'[^0-9.]', '', t)
    if t.count('.') > 1:
        k = t.rfind('.')
        t = t[:k].replace('.', '') + t[k:]
    return t


def mdigits(tok):
    if tok is None:
        return None
    return norm_money(tok).replace('.', '')


def parse_money(v):
    if '.' in v:
        a, b = v.split('.', 1)
        if len(b) != 2 or not a.isdigit() or not b.isdigit():
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        return (int(a) * 100 + int(b), False)
    if len(v) < 3 or not v.isdigit():
        return None
    if len(v) > 3 and v[0] == '0':
        return None
    return (int(v), True)


def money_cands(tok, K):
    if tok is None:
        return {}
    t = norm_money(tok)
    if not t or len(t) > 14:
        return {}
    res = {}
    for v, c in num_edits(t, K).items():
        m = parse_money(v)
        if m is None:
            continue
        val, nomark = m
        cc = c + (K['mark'] if nomark else 0.0)
        if val > 0 and (val not in res or res[val] > cc):
            res[val] = cc
    return res


def qty_cands(tok, K):
    if tok is None:
        return {}
    t = digits_of(tok)
    if t == '':
        return {q: K['lost'] for q in range(1, 10)}
    if len(t) > 5:
        return {}
    res = {}
    for v, c in num_edits(t, K).items():
        if not v or (len(v) > 1 and v[0] == '0'):
            continue
        q = int(v)
        if 1 <= q <= 500 and (q not in res or res[q] > c):
            res[q] = c
    return res


def make_dist(K):
    cache = {}
    cm, cd, cl = K['mis'], K['dup'], K['lost']

    def dist(orig, obs):
        k = orig + '|' + obs
        v = cache.get(k)
        if v is not None:
            return v
        m = len(obs)
        prev = [0.0] * (m + 1)
        for j in range(1, m + 1):
            prev[j] = prev[j - 1] + (cd if j >= 2 and obs[j - 1] == obs[j - 2] else 2.5)
        for i in range(1, len(orig) + 1):
            oc = orig[i - 1]
            mis = MIS.get(oc, '')
            cur = [prev[0] + cl] + [0.0] * m
            for j in range(1, m + 1):
                sc = obs[j - 1]
                if sc == oc:
                    sub = prev[j - 1]
                elif sc in mis:
                    sub = prev[j - 1] + cm
                else:
                    sub = prev[j - 1] + 2.5
                ins = cur[j - 1] + (cd if (j >= 2 and obs[j - 2] == sc) else 2.5)
                dele = prev[j] + cl
                b = sub
                if ins < b:
                    b = ins
                if dele < b:
                    b = dele
                cur[j] = b
            prev = cur
        r = prev[m]
        cache[k] = r
        return r
    return dist


# ---------------- codes ----------------

def code_ok(L, s):
    if len(s) != 5 or not s.isdigit():
        return False
    p1 = ord(L[0]) - 64
    p2 = ord(L[1]) - 64
    d = [int(c) for c in s]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def code_split(tok):
    t = (tok or '').replace(' ', '')
    letters = ''
    for c in t[:2]:
        if c.isalpha() and 'A' <= c.upper() <= 'Z':
            letters += c.upper()
        elif c in D2L:
            letters += D2L[c]
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    digs = ''.join(L2D.get(c, c) for c in t[2:] if c.isdigit() or c in L2D)
    return letters, digs


def code_edit_list(d):
    res = []
    for i, ch in enumerate(d):
        for o in REV.get(ch, ''):
            res.append((d[:i] + o + d[i + 1:], C_MIS))
    for i in range(len(d) - 1):
        if d[i] == d[i + 1]:
            res.append((d[:i] + d[i + 1:], C_DUP))
    for i in range(len(d) + 1):
        for o in '0123456789':
            res.append((d[:i] + o + d[i:], C_LOST))
    return res


def code_fallback(letters, digs):
    d4 = digs[:4].ljust(4, '0')
    dd = [int(c) for c in d4]
    chk = (dd[0] + 2 * dd[1] + 3 * dd[2] + 4 * dd[3] + ord(letters[0]) - 64 + ord(letters[1]) - 64) % 10
    return letters + d4 + str(chk)


def solve_code(tok):
    if not tok:
        return 'AA00000'
    letters, digs = code_split(tok)
    if code_ok(letters, digs):
        return letters + digs
    counts = {}
    order = []
    for s, c in code_edit_list(digs):
        if code_ok(letters, s):
            if s not in counts:
                counts[s] = [c, 0]
                order.append(s)
            if c < counts[s][0]:
                counts[s][0] = c
            counts[s][1] += 1
    if order:
        best = None
        for s in order:
            c, n = counts[s]
            key = (c, -n)
            if best is None or key < best[0]:
                best = (key, s)
        return letters + best[1]
    l1 = {}
    for s, c in code_edit_list(digs):
        if s not in l1 or l1[s] > c:
            l1[s] = c
    best = None
    for s, c in l1.items():
        if not (4 <= len(s) <= 6):
            continue
        for s2, c2 in code_edit_list(s):
            if len(s2) == 5 and code_ok(letters, s2):
                tot = c + c2
                if best is None or tot < best[0]:
                    best = (tot, s2)
    if best is not None:
        return letters + best[1]
    return code_fallback(letters, digs)


# ---------------- tokens / alignment ----------------

def tok_cost(t, col, pcs):
    if t == '':
        if col == 'QTY':
            return 1.0
        return 6.0 if col == 'CODE' else 4.0
    if col == 'CODE':
        if RE_CODE.fullmatch(t):
            nl = sum(1 for c in t[:2] if c.isalpha())
            bad = sum(1 for c in t[2:] if c.isalpha() and c not in L2D)
            base = 0.0 if nl == 2 else (0.5 if nl == 1 else 2.0)
            return base + 2.0 * bad
        return 5.0
    hp = has_pcs(t)
    tt = strip_pcs(t)
    if col == 'QTY':
        pen = 0.5 if (pcs is not None and hp != pcs) else 0.0
        if tt == '':
            return (0.8 + pen) if hp else 1.0
        if RE_QDIG.fullmatch(tt):
            return pen
        if RE_MON.fullmatch(tt):
            return 2.5 + pen
        return 5.0
    if hp:
        return 4.0
    if RE_MON.fullmatch(tt):
        if re.search(r'[0-9]', tt):
            return 0.0 if re.search(r'[.,]', tt) else 0.3
        return 1.0
    return 5.0


def plausible(t):
    return min(tok_cost(t, c, None) for c in COLS) <= 2.0


def align(toks, order, pcs):
    n = len(toks)
    INF = 1e18
    MISS = 5.0
    costs = [[tok_cost(t, order[p], pcs) for p in range(4)] for t, k in toks]
    skipc = [0.0 if k == 't' else (2.5 if t == '' else 3.0) for t, k in toks]
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(2):
            for p in range(4):
                if dp[i][p] < INF:
                    q = (p + 1) % 4
                    c = dp[i][p] + MISS
                    if c < dp[i][q] - 1e-9:
                        dp[i][q] = c
                        bk[i][q] = ('m', i, p)
        if i == n:
            break
        for p in range(4):
            if dp[i][p] >= INF:
                continue
            c = dp[i][p] + costs[i][p]
            q = (p + 1) % 4
            if c < dp[i + 1][q]:
                dp[i + 1][q] = c
                bk[i + 1][q] = ('a', i, p)
            c = dp[i][p] + skipc[i]
            if c < dp[i + 1][p]:
                dp[i + 1][p] = c
                bk[i + 1][p] = ('s', i, p)
    ops = []
    i, p = n, 0
    guard = 0
    while not (i == 0 and p == 0) and guard < 10 * (n + 5):
        guard += 1
        b = bk[i][p]
        if b is None:
            break
        ops.append(b)
        i, p = b[1], b[2]
    ops.reverse()
    rows = []
    cur = {}
    for kind, ti, pp in ops:
        if kind == 's':
            continue
        cur[order[pp]] = toks[ti][0] if kind == 'a' else None
        if pp == 3:
            rows.append(cur)
            cur = {}
    return [r for r in rows if any(r.get(c) is not None for c in COLS)]


def split_line(s, mode):
    if mode == 'pipe':
        parts = s.split('|')
    elif mode == 'semi':
        parts = s.split(';')
    elif mode == 'tab':
        parts = s.split('\t')
    else:
        parts = re.split(r' {3}|\t', s)
    return [p.strip() for p in parts]


def parse_doc(text):
    lines = text.split('\n')
    order = list(COLS)
    mode = None
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            ms = list(re.finditer(r'CODE|QTY|UNIT|AMOUNT', rest))
            names = [m.group(0) for m in ms]
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            if len(ms) >= 2:
                sep = rest[ms[0].end():ms[1].start()]
                if '|' in sep:
                    mode = 'pipe'
                elif ';' in sep:
                    mode = 'semi'
                elif '\t' in sep:
                    mode = 'tab'
                else:
                    mode = 'space'
            break
    if mode is None:
        body = '\n'.join(l for l in lines if not re.match(r'\s*(MANIFEST|COLUMNS|==|SUBTOTAL|TOTAL)', l))
        cnt = {'pipe': body.count('|'), 'semi': body.count(';'), 'tab': body.count('\t')}
        mode = max(cnt, key=lambda k: cnt[k]) if max(cnt.values()) > 0 else 'space'
    sections = []
    cur = None
    ttok = None
    itok = None
    for ln in lines:
        raw = ln.rstrip('\r')
        st = raw.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', st):
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                if sections and sections[-1]['sub'] is None:
                    cur = sections[-1]
                else:
                    cur = {'toks': [], 'sub': None}
                    sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s*(.*?)\s*ITEMS\s*(.*)$', st)
            if m:
                ttok = m.group(1).strip()
                itok = m.group(2).strip()
            else:
                ttok = st[5:].strip()
            continue
        parts = split_line(raw, mode)
        toks = []
        for k, p in enumerate(parts):
            kind = 't' if (p == '' and k == len(parts) - 1 and k > 0) else 'f'
            toks.append((p, kind))
        nonempty = [p for p, _ in toks if p]
        if not nonempty:
            continue
        if not any(plausible(p) for p in nonempty):
            continue
        if cur is None:
            if sections and sections[-1]['sub'] is None:
                cur = sections[-1]
            else:
                cur = {'toks': [], 'sub': None}
                sections.append(cur)
        cur['toks'].extend(toks)
    return order, sections, ttok, itok


# ---------------- numeric reasoning ----------------

def qcost(r, q, Dq):
    c = r['Q'].get(q)
    if c is not None:
        return c
    qd = r['_qd']
    c = qd.get(q)
    if c is None:
        c = Dq(q, r['oq'])
        qd[q] = c
    return c


def ucost(r, u, Dm):
    c = r['U'].get(u)
    if c is not None:
        return c
    ud = r['_ud']
    c = ud.get(u)
    if c is None:
        c = Dm(u, r['ou'])
        ud[u] = c
    return c


def row_cands(r, Dm, Dq):
    Q, U, A = r['Q'], r['U'], r['A']
    trip = {}

    def add(c, q, u):
        k = (q, u)
        if k not in trip or trip[k] > c:
            trip[k] = c
    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(cq + cu + ca, q, u)
    best = min(trip.values()) if trip else 99.0
    if best > 0:
        for q, cq in Q.items():
            if cq > 1.5:
                continue
            for u, cu in U.items():
                if cq + cu <= 1.5 and (q, u) not in trip:
                    add(cq + cu + Dm(q * u, r['oa']), q, u)
        for a, ca in A.items():
            if ca > 1.5:
                continue
            for q, cq in Q.items():
                if ca + cq <= 1.5 and a % q == 0:
                    add(ca + cq + Dm(a // q, r['ou']), q, a // q)
            for u, cu in U.items():
                if ca + cu <= 1.5 and a % u == 0:
                    q = a // u
                    if 1 <= q <= 500:
                        add(ca + cu + Dq(q, r['oq']), q, u)
    best = min(trip.values()) if trip else 99.0
    # deep reconstruction: factorise plausible amounts over all quantities
    if best > 0.9 and A:
        alist = sorted(A.items(), key=lambda x: (x[1], x[0]))[:16]
        for a, ca in alist:
            if ca > 1.3:
                continue
            top = min(500, a)
            for q in range(1, top + 1):
                if a % q:
                    continue
                cq = qcost(r, q, Dq)
                if ca + cq > 3.5:
                    continue
                u = a // q
                c = ca + cq + ucost(r, u, Dm)
                if c <= 4.5:
                    add(c, q, u)
    if not trip:
        q = min(Q.items(), key=lambda x: x[1])[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: x[1])[0]
        elif A:
            u = max(1, min(A.items(), key=lambda x: x[1])[0] // q)
        else:
            u = 100
        return [[50.0, q, u, q * u]]
    lst = sorted([[c, k[0], k[1], k[0] * k[1]] for k, c in trip.items()], key=lambda x: (x[0], x[1], x[2]))
    return lst[:12]


def solve_section(rows, score, targets, deadline, Dm, Dq):
    if not rows:
        return [], 0, 0.0
    base = [r['tr'][0] for r in rows]
    tot = sum(t[3] for t in base)
    rc = sum(t[0] for t in base)
    s0 = score(tot)
    best_obj = rc + s0
    best_mod = None
    if s0 <= 0:
        return base, tot, best_obj
    alts = []
    bydelta = {}
    for i, r in enumerate(rows):
        b = base[i]
        for t in r['tr'][1:]:
            d = t[3] - b[3]
            if d == 0:
                continue
            dc = t[0] - b[0]
            alts.append((i, t, d, dc))
            ns = tot + d
            if ns > 0:
                obj = rc + dc + score(ns)
                if obj < best_obj - 1e-9:
                    best_obj = obj
                    best_mod = [(i, t)]
            bydelta.setdefault(d, []).append((dc, i, t))
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        if rc + st >= best_obj:
            continue
        need = tv - tot
        for (i, t, d, dc) in alts:
            if rc + dc + st >= best_obj:
                continue
            lst = bydelta.get(need - d)
            if not lst:
                continue
            for (dc2, j, t2) in lst:
                if j > i:
                    obj = rc + dc + dc2 + st
                    if obj < best_obj - 1e-9:
                        best_obj = obj
                        best_mod = [(i, t), (j, t2)]
    # single-row residual factorisation over every quantity
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        for i, r in enumerate(rows):
            if time.perf_counter() > deadline:
                break
            b = base[i]
            req = tv - (tot - b[3])
            if req <= 0:
                continue
            basec = rc - b[0] + st
            if basec >= best_obj:
                continue
            ca = r['A'].get(req)
            if ca is None:
                ca = Dm(req, r['oa'])
            if basec + ca >= best_obj:
                continue
            top = min(500, req)
            for q in range(1, top + 1):
                if req % q:
                    continue
                cq = qcost(r, q, Dq)
                if basec + ca + cq >= best_obj:
                    continue
                u = req // q
                c = cq + ucost(r, u, Dm) + ca
                if basec + c < best_obj - 1e-9:
                    best_obj = basec + c
                    best_mod = [(i, [c, q, u, req])]
    choice = list(base)
    if best_mod:
        for i, t in best_mod:
            choice[i] = t
    tot = sum(t[3] for t in choice)
    return choice, tot, best_obj


def make_scorer(tok, dist, K):
    if tok is None or not tok.strip():
        return None, []
    C = money_cands(tok, K)
    o = mdigits(tok)
    cache = {}

    def f(s):
        v = C.get(s)
        if v is None:
            v = cache.get(s)
            if v is None:
                v = min(6.0, dist(str(s).zfill(3), o)) if s > 0 else 6.0
                cache[s] = v
        return v
    targ = sorted([(v, c) for v, c in C.items() if c <= 1.0], key=lambda x: (x[1], x[0]))[:10]
    return f, targ


def comb(fs, ft, off):
    def f(s):
        v = fs(s) if fs else 0.0
        if ft:
            v += ft(off + s)
        return v
    return f


def recover(state, params):
    t0 = time.perf_counter()
    second = state.get('_K') is not None
    if '_pt0' not in state:
        state['_pt0'] = time.process_time()
    if second:
        used = time.process_time() - state['_pt0']
        budget = max(0.12, 0.85 - used)
        d_a, d_b = 0.6 * budget, 0.82 * budget
        K = dict(state['_K'])
    else:
        d_a, d_b = 0.45, 0.66
        K = default_K()
    prev_out = state.get('output')
    prev_ct = state.get('_ctoks')
    prev_noise = state.get('_noise')
    text = (state.get('input') or {}).get('text', '') or ''
    try:
        order, sections, ttok, itok = parse_doc(text)
    except Exception:
        if not second:
            state['output'] = {'items': []}
            state['_ctoks'] = []
            state['_noise'] = []
        return state
    if not second:
        state['output'] = {'items': []}
        state['_ctoks'] = []
        state['_noise'] = []
    dist = make_dist(K)

    def Dm(c, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(c).zfill(3), obs))

    def Dq(q, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(q), obs))

    try:
        npcs = 0
        for sec in sections:
            for t, k in sec['toks']:
                if t and has_pcs(t):
                    npcs += 1
        pcs = npcs >= 2
        secs = []
        for sec in sections:
            try:
                rows = align(sec['toks'], order, pcs)
            except Exception:
                rows = []
            rr = []
            for r in rows:
                tq, tu, ta = r.get('QTY'), r.get('UNIT'), r.get('AMOUNT')
                try:
                    code = solve_code(r.get('CODE'))
                except Exception:
                    code = 'AA00000'
                row = {'code': code, 'ctok': r.get('CODE'), 'Q': qty_cands(tq, K), 'U': money_cands(tu, K),
                       'A': money_cands(ta, K), 'oq': digits_of(tq), 'ou': mdigits(tu), 'oa': mdigits(ta),
                       '_qd': {}, '_ud': {}}
                try:
                    row['tr'] = row_cands(row, Dm, Dq)
                except Exception:
                    row['tr'] = [[50.0, 1, 100, 100]]
                rr.append(row)
            fS, targ = make_scorer(sec['sub'], dist, K)
            secs.append({'rows': rr, 'fS': fS, 'targ': targ})
    except Exception:
        if second:
            state['output'] = prev_out
            state['_ctoks'] = prev_ct
            state['_noise'] = prev_noise
        return state

    results = [[[r['tr'][0] for r in s['rows']], 0, 0.0] for s in secs]

    def emit():
        items = []
        ctoks = []
        noise = []
        for s, res in zip(secs, results):
            for r, t in zip(s['rows'], res[0]):
                items.append({'code': r['code'], 'qty': int(t[1]), 'unit_cents': int(t[2])})
                ctoks.append(r['ctok'])
                if t[0] < 6.0:
                    if r['oq']:
                        noise.append([str(int(t[1])), r['oq']])
                    if r['ou']:
                        noise.append([str(int(t[2])).zfill(3), r['ou']])
                    if r['oa']:
                        noise.append([str(int(t[3])).zfill(3), r['oa']])
        state['output'] = {'items': items}
        state['_ctoks'] = ctoks
        state['_noise'] = noise
    emit()
    try:
        fT, Ttarg = make_scorer(ttok, dist, K)
        dl1 = t0 + d_a
        for i, s in enumerate(secs):
            if len(secs) == 1:
                sc = comb(s['fS'], fT, 0)
                targ = list(s['targ']) + list(Ttarg)
            else:
                sc = comb(s['fS'], None, 0)
                targ = s['targ']
            ch, tt, obj = solve_section(s['rows'], sc, targ, dl1, Dm, Dq)
            results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
        dl2 = t0 + d_b
        if fT and len(secs) > 1:
            for _ in range(3):
                if time.perf_counter() > dl2:
                    break
                grand = sum(r[1] for r in results)
                ct = fT(grand)
                if ct <= 0:
                    break
                best_gain = 1e-9
                best = None
                for i, s in enumerate(secs):
                    if time.perf_counter() > dl2 or not s['rows']:
                        continue
                    other = grand - results[i][1]
                    fS = s['fS']
                    sc = comb(fS, fT, other)
                    targ = list(s['targ']) + [(tv - other, c) for tv, c in Ttarg if tv - other > 0]
                    ch, tt, obj = solve_section(s['rows'], sc, targ, dl2, Dm, Dq)
                    old = results[i][2] + (fS(results[i][1]) if fS else 0.0) + ct
                    gain = old - obj
                    if gain > best_gain:
                        best_gain = gain
                        best = (i, ch, tt)
                if best is None:
                    break
                i, ch, tt = best
                results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
    except Exception:
        pass
    return state


# ---------------- noise profile ----------------

def learn_profile(noise, ctoks):
    mis = 0.0
    dup = 0.0
    lost = 0.0
    N = 0.0
    for pair in noise:
        o, s = pair[0], pair[1]
        if not o or s is None:
            continue
        N += len(o)
        if len(s) == len(o):
            d = sum(1 for a, b in zip(o, s) if a != b)
            mis += min(d, 2)
        elif len(s) == len(o) - 1:
            lost += 1
        elif len(s) == len(o) + 1:
            dup += 1
    for tok in ctoks:
        if not tok:
            continue
        L, d = code_split(tok)
        N += 5
        if len(d) == 4:
            lost += 1
        elif len(d) == 6:
            dup += 1
        elif len(d) == 5 and not code_ok(L, d):
            mis += 1.1
    den = N + 30.0
    return {'mis': (mis + 1.0) / den, 'dup': (dup + 0.5) / den, 'lost': (lost + 0.5) / den}


def learn_costs(state, params):
    state['_rerun'] = False
    try:
        R = learn_profile(state.get('_noise') or [], state.get('_ctoks') or [])
        state['_R'] = R
        rm, rd, rl = R['mis'], R['dup'], R['lost']
        ref = (rm * rd * rl) ** (1.0 / 3.0)

        def cst(r, off):
            c = 1.0 + 0.4 * math.log(ref / r) + off
            return max(0.6, min(2.0, c))
        K = {'mis': cst(rm, 0.0), 'dup': cst(rd, 0.0), 'lost': cst(rl, 0.2), 'mark': C_MARK}
        D = default_K()
        dev = max(abs(K[k] - D[k]) for k in ('mis', 'dup', 'lost'))
        used = time.process_time() - state.get('_pt0', time.process_time())
        if dev > 0.15 and used < 0.4 and (state.get('output') or {}).get('items'):
            state['_K'] = K
            state['_rerun'] = True
    except Exception:
        state['_rerun'] = False
    return state


# ---------------- probabilistic code decoding ----------------

def prob_steps(s, w, R):
    out = []
    for i, ch in enumerate(s):
        for o in REV.get(ch, ''):
            out.append((s[:i] + o + s[i + 1:], w * R['mis'] / len(MIS[o])))
    for i in range(len(s) - 1):
        if s[i] == s[i + 1]:
            out.append((s[:i] + s[i + 1:], w * R['dup']))
    lw = w * R['lost'] / 10.0
    for i in range(len(s) + 1):
        for d in '0123456789':
            out.append((s[:i] + d + s[i:], lw))
    return out


def steps_to5(s, w, R):
    n = len(s)
    out = []
    if n == 6:
        for i in range(5):
            if s[i] == s[i + 1]:
                out.append((s[:i] + s[i + 1:], w * R['dup']))
    elif n == 5:
        for i, ch in enumerate(s):
            for o in REV.get(ch, ''):
                out.append((s[:i] + o + s[i + 1:], w * R['mis'] / len(MIS[o])))
    elif n == 4:
        lw = w * R['lost'] / 10.0
        for i in range(5):
            for d in '0123456789':
                out.append((s[:i] + d + s[i:], lw))
    return out


def decode_code(tok, R):
    if not tok:
        return None
    letters, digs = code_split(tok)
    if code_ok(letters, digs):
        return letters + digs
    if len(digs) > 8 or len(digs) < 3:
        return None
    lvl1 = {}
    for s, w in prob_steps(digs, 1.0, R):
        lvl1[s] = lvl1.get(s, 0.0) + w
    good = {}
    for s, w in lvl1.items():
        if len(s) == 5 and code_ok(letters, s):
            good[s] = good.get(s, 0.0) + w
    for s, w in lvl1.items():
        if not (4 <= len(s) <= 6):
            continue
        for s2, w2 in steps_to5(s, w, R):
            if code_ok(letters, s2):
                good[s2] = good.get(s2, 0.0) + w2
    if not good:
        return None
    best = max(sorted(good), key=lambda k: good[k])
    return letters + best


def repair_codes(state, params):
    try:
        out = state.get('output') or {}
        items = out.get('items') or []
        ctoks = state.get('_ctoks') or []
        noise = state.get('_noise') or []
        if len(ctoks) != len(items):
            return state
        R = learn_profile(noise, ctoks)
        t0 = time.perf_counter()
        for it, tok in zip(items, ctoks):
            if time.perf_counter() - t0 > 0.1:
                break
            try:
                c = decode_code(tok, R)
            except Exception:
                c = None
            if c:
                it['code'] = c
        state['output'] = {'items': items}
    except Exception:
        pass
    return state

import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INV = {}
for _k, _v in MIS.items():
    for _c in _v:
        INV.setdefault(_c, []).append(_k)
L2D = {'O': '0', 'o': '0', 'D': '0', 'Q': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1', 'S': '5', 's': '5',
       'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
CM, CD, CP, CX, CG, CA = 2.5, 3.0, 3.0, 2.5, 8.0, 4.0


def norm_num(t):
    if t is None:
        return ''
    t = re.sub(r'\s*pcs\s*$', '', t.strip())
    out = []
    for ch in t:
        if ch.isdigit():
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
        elif ch in '.,':
            out.append('.')
        elif ch == "'":
            out.append("'")
    return ''.join(out)


def edit_cost(s, o, memo):
    key = s + '|' + o
    r = memo.get(key)
    if r is not None:
        return r
    n, m = len(s), len(o)
    INF = 1e9
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            c = row[j]
            if c >= INF:
                continue
            if j < m:
                v = c + CG
                if v < row[j + 1]:
                    row[j + 1] = v
            if i < n:
                si = s[i]
                nr = dp[i + 1]
                dc = CD if si.isdigit() else (CX if si == '.' else CA)
                if c + dc < nr[j]:
                    nr[j] = c + dc
                if j < m:
                    oj = o[j]
                    if si == oj:
                        v = c
                    elif si in MIS and oj in MIS[si]:
                        v = c + CM
                    elif (si == "'") != (oj == "'") or (si == '.') != (oj == '.'):
                        v = c + CG + 2
                    else:
                        v = c + CG
                    if v < nr[j + 1]:
                        nr[j + 1] = v
                    if j + 1 < m and si.isdigit() and oj == si and o[j + 1] == si:
                        v = c + CP
                        if v < nr[j + 2]:
                            nr[j + 2] = v
    r = dp[n][m]
    memo[key] = r
    return r


def fmt_money(c, grp):
    i, f = divmod(c, 100)
    s = str(i)
    if grp:
        p = []
        while len(s) > 3:
            p.insert(0, s[-3:])
            s = s[:-3]
        p.insert(0, s)
        s = "'".join(p)
    return s + '.' + ('%02d' % f)


def parse_money(s):
    s = s.replace("'", '')
    if s.count('.') != 1:
        return None
    a, b = s.split('.')
    if len(b) != 2 or not a or not a.isdigit() or not b.isdigit():
        return None
    if len(a) > 1 and a[0] == '0':
        return None
    return int(a) * 100 + int(b)


def inv_neigh(t, allow_ins, money):
    out = []
    L = len(t)
    for i in range(L):
        c = t[i]
        if c in INV:
            for y in INV[c]:
                out.append((t[:i] + y + t[i + 1:], CM))
        if c.isdigit() and i + 1 < L and t[i + 1] == c:
            out.append((t[:i] + t[i + 1:], CP))
    if allow_ins:
        for i in range(L + 1):
            for d in '0123456789':
                out.append((t[:i] + d + t[i:], CD))
    if money and '.' not in t:
        for i in range(max(0, L - 3), L + 1):
            out.append((t[:i] + '.' + t[i:], CX))
    return out


def money_cands(o):
    t = o.replace("'", '')
    res = {}
    v = parse_money(t)
    if v is not None:
        res[v] = 0.0
    lvl1 = inv_neigh(t, True, True)
    seen = {t: 0.0}
    for s, c in lvl1:
        if s in seen and seen[s] <= c:
            continue
        seen[s] = c
        v = parse_money(s)
        if v is not None and res.get(v, 99) > c:
            res[v] = c
    for s, c in lvl1:
        if c == CD:
            continue
        for s2, c2 in inv_neigh(s, False, True):
            cc = c + c2
            v = parse_money(s2)
            if v is not None and res.get(v, 99) > cc:
                res[v] = cc
    if '.' not in t:
        L = len(t)
        for i in range(L + 1):
            for d in '0123456789':
                s = t[:i] + d + t[i:]
                v = parse_money(s[:-2] + '.' + s[-2:]) if len(s) >= 3 else None
                if v is not None and res.get(v, 99) > CD + CX:
                    res[v] = CD + CX
    return res


def qty_cands(o):
    t = o.replace("'", '').replace('.', '')
    res = {}
    seen = {}
    frontier = [(t, 0.0)]
    for depth in range(3):
        nxt = []
        for s, c in frontier:
            if s in seen and seen[s] <= c:
                continue
            seen[s] = c
            if s and s.isdigit() and s[0] != '0':
                v = int(s)
                if 1 <= v <= 500 and res.get(v, 99) > c:
                    res[v] = c
            if depth < 2:
                for s2, c2 in inv_neigh(s, depth == 0 or len(s) < 1, False):
                    if len(s2) <= 4:
                        nxt.append((s2, c + c2))
        frontier = nxt
    return res


def code_decode(tok, memo):
    if tok is None:
        tok = ''
    tok = re.sub(r'[^0-9A-Za-z|]', '', tok)
    lets = ''
    k = 0
    while len(lets) < 2 and k < len(tok):
        ch = tok[k]
        if ch.isdigit():
            ch = D2L.get(ch, None)
            if ch is None:
                ch = 'A'
        elif ch == 'l' or ch == '|':
            ch = 'I'
        lets += ch.upper()
        k += 1
    while len(lets) < 2:
        lets += 'A'
    rest = norm_num(tok[k:]).replace('.', '').replace("'", '')
    p = ord(lets[0]) - 64 + ord(lets[1]) - 64

    def ok(d):
        return len(d) == 5 and d.isdigit() and (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p) % 10 == int(d[4])

    best = {}
    if ok(rest):
        return lets + rest
    if len(rest) == 6:
        for i in range(5):
            if rest[i] == rest[i + 1]:
                s2 = rest[:i] + rest[i + 1:]
                if ok(s2):
                    best[s2] = min(best.get(s2, 99), CP)
    frontier = [(rest, 0.0)]
    seen = {}
    for depth in range(2):
        nxt = []
        for s, c in frontier:
            for s2, c2 in inv_neigh(s, abs(len(s) - 5) > 0 or depth == 0, False):
                if abs(len(s2) - 5) > 1 - depth:
                    continue
                cc = c + c2
                if s2 in seen and seen[s2] <= cc:
                    continue
                seen[s2] = cc
                if ok(s2) and best.get(s2, 99) > cc:
                    best[s2] = cc
                nxt.append((s2, cc))
        frontier = nxt
    if not best:
        base = [rest]
        if len(rest) > 5:
            base = [rest[:i] + rest[i + 1:] for i in range(len(rest))] if len(rest) == 6 else [rest[:5]]
        elif len(rest) < 5:
            base = [(rest + '00000')[:5]]
        for b in base:
            for i in range(5):
                for d in '0123456789':
                    s2 = b[:i] + d + b[i + 1:]
                    if ok(s2):
                        cc = edit_cost(s2, rest, memo)
                        if best.get(s2, 99) > cc:
                            best[s2] = cc
    if not best:
        return lets + '00000'
    m = min(best.values())
    cands = sorted(s for s, c in best.items() if c <= m + 1e-9)
    return lets + cands[0]


def tok_fit(t):
    if t is None:
        return (5.0, 5.0, 5.0)
    s = t.strip()
    raw = re.sub(r'\s*pcs\s*$', '', s)
    haspcs = raw != s
    alnum = re.sub(r"[.,']", '', raw)
    c_code = 0.0 if (6 <= len(raw) <= 8 and raw[:2].isalnum() and re.fullmatch(r'[0-9OlISBZGo|]{3,6}', raw[2:] or 'x')
                     and (raw[0].isalpha() or raw[1].isalpha() or raw[0] in D2L)) else 6.0
    if c_code == 0.0 and not (raw[0].isalpha() and raw[1].isalpha()):
        c_code = 1.5
    hasmark = bool(re.search(r'[.,]', raw))
    if haspcs:
        c_qty = 0.0
    elif hasmark:
        c_qty = 5.0
    elif re.fullmatch(r"[0-9OlISBZGo]{0,4}", raw):
        c_qty = 0.0 if len(alnum) <= 3 else 2.0
    else:
        c_qty = 6.0
    if haspcs:
        c_m = 6.0
    elif re.fullmatch(r"[0-9OlISBZGo'.,]+", raw) and hasmark:
        c_m = 0.0
    elif re.fullmatch(r"[0-9OlISBZGo']+", raw):
        c_m = 1.0 if len(alnum) >= 3 else 2.5
    else:
        c_m = 6.0
    if c_code == 0.0 and raw[:2].isalpha():
        c_qty = max(c_qty, 6.0)
        c_m = max(c_m, 6.0)
    return (c_code, c_qty, c_m)


def is_data_token(t):
    s = t.strip()
    if s == '':
        return True
    return bool(re.fullmatch(r"[0-9A-Za-z|'.,]{1,16}(\s*pcs)?", s)) and not re.search(r'[a-z]{2,}', re.sub(r'pcs$', '', s))


def align(tokens, colkind):
    n = len(tokens)
    fits = [tok_fit(t) for t in tokens]
    INF = 1e18
    SKIP, MISS = 7.0, 7.0
    dp = [[INF] * 4 for _ in range(n + 1)]
    bp = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(3):
            for c in range(4):
                v = dp[i][c]
                if v >= INF:
                    continue
                nc = (c + 1) % 4
                if nc == 0:
                    continue
                if v + MISS < dp[i][nc]:
                    dp[i][nc] = v + MISS
                    bp[i][nc] = ('m', i, c)
        if i == n:
            break
        for c in range(4):
            v = dp[i][c]
            if v >= INF:
                continue
            f = fits[i][colkind[c]]
            nc = (c + 1) % 4
            if v + f < dp[i + 1][nc]:
                dp[i + 1][nc] = v + f
                bp[i + 1][nc] = ('t', i, c)
            if v + SKIP < dp[i + 1][c]:
                dp[i + 1][c] = v + SKIP
                bp[i + 1][c] = ('s', i, c)
    best = dp[n][0]
    endc = 0
    for c in range(1, 4):
        v = dp[n][c] + MISS * (4 - c)
        if v < best:
            best = v
            endc = c
    assign = []
    i, c = n, endc
    while not (i == 0 and c == 0):
        b = bp[i][c]
        if b is None:
            break
        kind, pi, pc = b
        if kind == 't':
            assign.append((pc, tokens[pi]))
        elif kind == 'm':
            assign.append((pc, None))
        else:
            assign.append(('skip', None))
        i, c = pi, pc
    assign.reverse()
    rows = []
    cur = [None] * 4
    started = False
    for a in assign:
        if a[0] == 'skip':
            continue
        col, tok = a
        if col == 0 and started:
            rows.append(cur)
            cur = [None] * 4
        started = True
        cur[col] = tok
    if started:
        rows.append(cur)
    return rows


def parse_doc(text):
    lines = text.split('\n')
    sep = ';'
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    for ln in lines:
        if ln.startswith('COLUMNS'):
            body = ln.split(':', 1)[1] if ':' in ln else ln[7:]
            body = body.lstrip(' ') if not body.startswith('\t') else body
            pos = []
            for nm in ['CODE', 'QTY', 'UNIT', 'AMOUNT']:
                k = body.find(nm)
                pos.append((k, nm))
            pos.sort()
            order = [nm for _, nm in pos]
            k0, n0 = pos[0]
            k1 = pos[1][0]
            sep = body[k0 + len(n0):k1]
            if sep.strip() == '|':
                sep = ' | '
            elif sep == '':
                sep = ';'
            break
    sections = []
    total_obs = None
    items_obs = None
    cur = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^==\s*SECTION', s):
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = s[8:].strip()
            cur = None
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', s)
            if m:
                total_obs = m.group(1).strip()
                items_obs = m.group(2).strip()
            else:
                total_obs = s[5:].strip()
            continue
        if sep == ' | ':
            parts = re.split(r'\s*\|\s*', ln.strip())
            trailing = ln.rstrip().endswith('|')
        elif sep == '\t':
            parts = ln.strip('\r\n').split('\t')
            trailing = ln.endswith('\t')
        elif sep.strip() == '' and len(sep) >= 2:
            parts = re.split(r' {3}', ln.rstrip('\r\n'))
            trailing = ln.endswith('   ')
        else:
            parts = ln.strip().split(sep)
            trailing = ln.strip().endswith(sep)
        if trailing and parts and parts[-1].strip() == '':
            parts = parts[:-1]
        if sep == ' | ' and parts and parts[0].strip() == '' and ln.strip().startswith('|'):
            parts = parts[1:]
        parts = [p.strip() for p in parts]
        good = [p for p in parts if p and is_data_token(p)]
        if not good:
            continue
        if len(parts) == 1 and not is_data_token(parts[0]):
            continue
        bad = [p for p in parts if p and not is_data_token(p)]
        if len(bad) * 2 >= len(parts):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
        for p in parts:
            if p and not is_data_token(p):
                continue
            cur['tokens'].append(p)
    return sep, order, sections, total_obs, items_obs


def row_hyps(qo, uo, ao, memo, grp, deadline):
    Cq = qty_cands(qo)
    Cu = money_cands(uo)
    Ca = money_cands(ao)
    H = {}

    def add(q, u, a, c):
        if q < 1 or q > 500 or u < 0:
            return
        k = (q, u)
        if H.get(k, (1e9,))[0] > c:
            H[k] = (c, q, u, a)

    def ucost(u):
        c = Cu.get(u)
        if c is None:
            c = edit_cost(fmt_money(u, grp), uo, memo)
        return c

    def acost(a):
        c = Ca.get(a)
        if c is None:
            c = edit_cost(fmt_money(a, grp), ao, memo)
        return c

    def qcost(q):
        c = Cq.get(q)
        if c is None:
            c = edit_cost(str(q), qo, memo)
        return c

    qs = sorted(Cq.items(), key=lambda x: (x[1], x[0]))
    us = sorted(Cu.items(), key=lambda x: (x[1], x[0]))
    as_ = sorted(Ca.items(), key=lambda x: (x[1], x[0]))
    BUD = 9.5
    for q, cq in qs:
        if cq > BUD:
            break
        for u, cu in us:
            if cq + cu > BUD:
                break
            a = q * u
            ca = Ca.get(a)
            if ca is not None and cq + cu + ca <= BUD:
                add(q, u, a, cq + cu + ca)
    best = min((h[0] for h in H.values()), default=99.0)
    lim = 3.1 if best <= 3.0 else 6.0
    tq = [x for x in qs if x[1] <= lim][:12]
    tu = [x for x in us if x[1] <= lim][:25]
    ta = [x for x in as_ if x[1] <= lim][:25]
    if best == 0.0:
        tq = [x for x in qs if x[1] == 0.0]
        tu = [x for x in us if x[1] == 0.0]
        ta = [x for x in as_ if x[1] == 0.0]
    for q, cq in tq:
        for u, cu in tu:
            if cq + cu >= best + 9:
                continue
            a = q * u
            add(q, u, a, cq + cu + acost(a))
        for a, ca in ta:
            if cq + ca >= best + 9:
                continue
            if a % q == 0:
                u = a // q
                add(q, u, a, cq + ca + ucost(u))
    for u, cu in tu:
        if u <= 0:
            continue
        for a, ca in ta:
            if cu + ca >= best + 9:
                continue
            if a % u == 0:
                q = a // u
                if 1 <= q <= 500:
                    add(q, u, a, cu + ca + qcost(q))
    best = min((h[0] for h in H.values()), default=99.0)
    if best > 4.0 and time.perf_counter() < deadline:
        tq = [x for x in qs if x[1] <= 3.1][:15]
        tu = [x for x in us if x[1] <= 3.1][:60]
        ta = [x for x in as_ if x[1] <= 3.1][:60]
        for q, cq in tq:
            for u, cu in tu:
                if cq + cu + 2.5 < best:
                    a = q * u
                    add(q, u, a, cq + cu + acost(a))
            for a, ca in ta:
                if cq + ca + 2.5 < best and a % q == 0:
                    u = a // q
                    add(q, u, a, cq + ca + ucost(u))
        best = min((h[0] for h in H.values()), default=99.0)
    if best > 6.0 and time.perf_counter() < deadline:
        for a, ca in as_[:30]:
            if ca > 6:
                break
            for q in range(1, 501):
                if a % q == 0:
                    u = a // q
                    c = ca + ucost(u)
                    if c < best + 6:
                        add(q, u, a, c + qcost(q))
    hl = sorted(H.values())
    if not hl:
        q = next(iter(Cq), 1)
        u = next(iter(Cu), 100)
        hl = [(30.0, q, u, q * u)]
    b = hl[0][0]
    return [h for h in hl if h[0] <= b + 10][:15], Cq


def reconcile_section(rr, sub_o, memo, grp, deadline):
    base_rows = [r['hyps'][0] for r in rr]
    base_cost = sum(h[0] for h in base_rows)
    base_sum = sum(h[3] for h in base_rows)

    def pack(sel):
        return [(rr[i]['code'], sel[i][1], sel[i][2]) for i in range(len(rr))]

    if sub_o is None or not rr:
        return [(base_cost, base_sum, pack(base_rows))]

    def scost(s):
        return edit_cost(fmt_money(s, grp), sub_o, memo)

    alts = {}

    def consider(sel_changes, rowcost):
        s = base_sum
        sel = list(base_rows)
        for i, h in sel_changes:
            s += h[3] - sel[i][3]
            sel[i] = h
        c = rowcost + scost(s)
        if s not in alts or alts[s][0] > c:
            alts[s] = (c, sel)

    consider([], base_cost)
    deltas = {}
    for i, r in enumerate(rr):
        for h in r['hyps'][1:]:
            d = h[3] - base_rows[i][3]
            dc = h[0] - base_rows[i][0]
            consider([(i, h)], base_cost + dc)
            if d not in deltas or deltas[d][0] > dc:
                deltas[d] = (dc, i, h)
    targets = {}
    v = parse_money(sub_o.replace("'", ''))
    if v is not None:
        targets[v] = 0.0
    for val, c in money_cands(sub_o).items():
        if c <= 3.5 and (val not in targets or targets[val] > c):
            targets[val] = c
    cur_best = min(a[0] for a in alts.values())
    for T, tc in targets.items():
        resid = T - base_sum
        if resid == 0:
            continue
        if time.perf_counter() > deadline:
            break
        dl = list(deltas.items())
        for d1, (c1, i1, h1) in dl:
            d2 = resid - d1
            if d2 in deltas:
                c2, i2, h2 = deltas[d2]
                if i2 != i1 and base_cost + c1 + c2 + tc < cur_best + 0.01:
                    consider([(i1, h1), (i2, h2)], base_cost + c1 + c2)
        for i, r in enumerate(rr):
            a2 = base_rows[i][3] + resid
            if a2 <= 0:
                continue
            ca = edit_cost(fmt_money(a2, grp), r['ao'], memo)
            if ca > 9:
                continue
            for q, cq in r['Cq'].items():
                if cq > 6 or a2 % q:
                    continue
                u = a2 // q
                cu = edit_cost(fmt_money(u, grp), r['uo'], memo)
                c = ca + cq + cu
                if c - base_rows[i][0] + base_cost + tc < cur_best + 0.01:
                    consider([(i, (c, q, u, a2))], base_cost + c - base_rows[i][0])
        cur_best = min(a[0] for a in alts.values())
    out = sorted(((c, s, pack(sel)) for s, (c, sel) in alts.items()), key=lambda x: x[0])
    return out[:12]


def solve_text(text):
    t0 = time.perf_counter()
    deadline = t0 + 0.6
    memo = {}
    sep, order, sections, total_obs, items_obs = parse_doc(text)
    colkind = [{'CODE': 0, 'QTY': 1, 'UNIT': 2, 'AMOUNT': 2}[c] for c in order]
    allmoney = []
    for sec in sections:
        for t in sec['tokens']:
            allmoney.append(t)
    grp = any("'" in t for t in allmoney) or (total_obs is not None and "'" in total_obs)
    idx = {c: i for i, c in enumerate(order)}
    sec_results = []
    for sec in sections:
        rows = align(sec['tokens'], colkind)
        rr = []
        for r in rows:
            qo = norm_num(r[idx['QTY']])
            uo = norm_num(r[idx['UNIT']])
            ao = norm_num(r[idx['AMOUNT']])
            hyps, Cq = row_hyps(qo, uo, ao, memo, grp, deadline)
            rr.append({'code': code_decode(r[idx['CODE']], memo), 'hyps': hyps, 'qo': qo, 'uo': uo, 'ao': ao,
                       'Cq': Cq})
        sub_o = norm_num(sec['sub']) if sec['sub'] is not None else None
        sec_results.append(reconcile_section(rr, sub_o, memo, grp, deadline))
    tot_o = norm_num(total_obs) if total_obs is not None else None
    if tot_o is not None and sec_results:
        cur = [0] * len(sec_results)

        def doc_cost(ch):
            c = 0.0
            s = 0
            for k, alts in enumerate(sec_results):
                cc, ss, _ = alts[ch[k]]
                c += cc
                s += ss
            return c + edit_cost(fmt_money(s, grp), tot_o, memo)

        bc = doc_cost(cur)
        improved = True
        it = 0
        while improved and it < 3:
            improved = False
            it += 1
            for k in range(len(sec_results)):
                for j in range(len(sec_results[k])):
                    if j == cur[k]:
                        continue
                    ch = list(cur)
                    ch[k] = j
                    c = doc_cost(ch)
                    if c < bc - 1e-9:
                        bc = c
                        cur = ch
                        improved = True
        chosen = [sec_results[k][cur[k]][2] for k in range(len(sec_results))]
    else:
        chosen = [alts[0][2] for alts in sec_results]
    items = []
    for rows in chosen:
        for (code, q, u) in rows:
            items.append({'code': code, 'qty': int(q), 'unit_cents': int(u)})
    return items


def run(state, params):
    text = state.get('input', {}).get('text', '')
    try:
        items = solve_text(text)
    except Exception:
        items = []
    state['output'] = {'items': items}
    return state

import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
REV = {}
for _o in sorted(MIS):
    for _s in MIS[_o]:
        REV[_s] = REV.get(_s, '') + _o

L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
       'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
COLS = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
C_MIS = 1.0
C_DUP = 1.0
C_LOST = 1.2
C_MARK = 0.5

RE_CODE = re.compile(r'[A-Za-z0-9]{2}[0-9A-Za-z]{2,8}')
RE_QDIG = re.compile(r'[0-9OolIiSsBZzG]{1,4}')
RE_MON = re.compile(r"[0-9OolIiSsBZzG.,']{1,14}")


def strip_pcs(t):
    return re.sub(r'(?i)\s*pcs\s*$', '', t.strip())


def has_pcs(t):
    return re.search(r'(?i)pcs\s*$', t.strip()) is not None


def digits_of(tok):
    if tok is None:
        return None
    s = strip_pcs(tok)
    return ''.join(L2D.get(c, c) for c in s if c.isdigit() or c in L2D)


def num_edits(s):
    out = {s: 0.0}
    n = len(s)

    def put(v, c):
        if v not in out or out[v] > c:
            out[v] = c
    for i, ch in enumerate(s):
        if ch.isdigit():
            for y in REV.get(ch, ''):
                put(s[:i] + y + s[i + 1:], C_MIS)
            if i + 1 < n and s[i + 1] == ch:
                put(s[:i] + s[i + 1:], C_DUP)
    for i in range(n + 1):
        for d in '0123456789':
            put(s[:i] + d + s[i:], C_LOST)
    return out


def norm_money(tok):
    t = ''.join(L2D.get(c, c) for c in tok)
    t = t.replace("'", '').replace(' ', '').replace(',', '.')
    t = re.sub(r'[^0-9.]', '', t)
    if t.count('.') > 1:
        k = t.rfind('.')
        t = t[:k].replace('.', '') + t[k:]
    return t


def mdigits(tok):
    if tok is None:
        return None
    return norm_money(tok).replace('.', '')


def parse_money(v):
    if '.' in v:
        a, b = v.split('.', 1)
        if len(b) != 2 or not a.isdigit() or not b.isdigit():
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        return (int(a) * 100 + int(b), False)
    if len(v) < 3 or not v.isdigit():
        return None
    if len(v) > 3 and v[0] == '0':
        return None
    return (int(v), True)


def money_cands(tok):
    if tok is None:
        return {}
    t = norm_money(tok)
    if not t or len(t) > 14:
        return {}
    res = {}
    for v, c in num_edits(t).items():
        m = parse_money(v)
        if m is None:
            continue
        val, nomark = m
        cc = c + (C_MARK if nomark else 0.0)
        if val > 0 and (val not in res or res[val] > cc):
            res[val] = cc
    return res


def qty_cands(tok):
    if tok is None:
        return {}
    t = digits_of(tok)
    if t == '':
        return {q: C_LOST for q in range(1, 10)}
    if len(t) > 5:
        return {}
    res = {}
    for v, c in num_edits(t).items():
        if not v or (len(v) > 1 and v[0] == '0'):
            continue
        q = int(v)
        if 1 <= q <= 500 and (q not in res or res[q] > c):
            res[q] = c
    return res


def make_dist():
    cache = {}

    def dist(orig, obs):
        k = orig + '|' + obs
        v = cache.get(k)
        if v is not None:
            return v
        m = len(obs)
        prev = [0.0] * (m + 1)
        for j in range(1, m + 1):
            prev[j] = prev[j - 1] + (1.0 if j >= 2 and obs[j - 1] == obs[j - 2] else 2.5)
        for i in range(1, len(orig) + 1):
            oc = orig[i - 1]
            mis = MIS.get(oc, '')
            cur = [prev[0] + 1.2] + [0.0] * m
            for j in range(1, m + 1):
                sc = obs[j - 1]
                if sc == oc:
                    sub = prev[j - 1]
                elif sc in mis:
                    sub = prev[j - 1] + 1.0
                else:
                    sub = prev[j - 1] + 2.5
                ins = cur[j - 1] + (1.0 if (j >= 2 and obs[j - 2] == sc) else 2.5)
                dele = prev[j] + 1.2
                b = sub
                if ins < b:
                    b = ins
                if dele < b:
                    b = dele
                cur[j] = b
            prev = cur
        r = prev[m]
        cache[k] = r
        return r
    return dist


# ---------------- codes ----------------

def code_ok(L, s):
    if len(s) != 5 or not s.isdigit():
        return False
    p1 = ord(L[0]) - 64
    p2 = ord(L[1]) - 64
    d = [int(c) for c in s]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def code_edit_list(d):
    res = []
    for i, ch in enumerate(d):
        for o in REV.get(ch, ''):
            res.append((d[:i] + o + d[i + 1:], C_MIS))
    for i in range(len(d) - 1):
        if d[i] == d[i + 1]:
            res.append((d[:i] + d[i + 1:], C_DUP))
    for i in range(len(d) + 1):
        for o in '0123456789':
            res.append((d[:i] + o + d[i:], C_LOST))
    return res


def code_parts(tok):
    t = (tok or '').replace(' ', '')
    letters = ''
    for c in t[:2]:
        if c.isalpha() and 'A' <= c.upper() <= 'Z':
            letters += c.upper()
        elif c in D2L:
            letters += D2L[c]
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    digs = ''.join(L2D.get(c, c) for c in t[2:] if c.isdigit() or c in L2D)
    return letters, digs


def solve_code(tok):
    if not tok:
        return 'AA00000'
    letters, digs = code_parts(tok)
    if code_ok(letters, digs):
        return letters + digs
    counts = {}
    order = []
    for s, c in code_edit_list(digs):
        if code_ok(letters, s):
            if s not in counts:
                counts[s] = [c, 0]
                order.append(s)
            if c < counts[s][0]:
                counts[s][0] = c
            counts[s][1] += 1
    if order:
        best = None
        for s in order:
            c, n = counts[s]
            key = (c, -n)
            if best is None or key < best[0]:
                best = (key, s)
        return letters + best[1]
    l1 = {}
    for s, c in code_edit_list(digs):
        if s not in l1 or l1[s] > c:
            l1[s] = c
    best = None
    for s, c in l1.items():
        if not (4 <= len(s) <= 6):
            continue
        for s2, c2 in code_edit_list(s):
            if len(s2) == 5 and code_ok(letters, s2):
                tot = c + c2
                if best is None or tot < best[0]:
                    best = (tot, s2)
    if best is not None:
        return letters + best[1]
    d4 = digs[:4].ljust(4, '0')
    dd = [int(c) for c in d4]
    chk = (dd[0] + 2 * dd[1] + 3 * dd[2] + 4 * dd[3] + ord(letters[0]) - 64 + ord(letters[1]) - 64) % 10
    return letters + d4 + str(chk)


# ---------------- tokens / alignment ----------------

def tok_cost(t, col, pcs):
    if t == '':
        if col == 'QTY':
            return 1.0
        return 6.0 if col == 'CODE' else 4.0
    if col == 'CODE':
        if RE_CODE.fullmatch(t):
            nl = sum(1 for c in t[:2] if c.isalpha())
            bad = sum(1 for c in t[2:] if c.isalpha() and c not in L2D)
            base = 0.0 if nl == 2 else (0.5 if nl == 1 else 2.0)
            return base + 2.0 * bad
        return 5.0
    hp = has_pcs(t)
    tt = strip_pcs(t)
    if col == 'QTY':
        pen = 0.5 if (pcs is not None and hp != pcs) else 0.0
        if tt == '':
            return (0.8 + pen) if hp else 1.0
        if RE_QDIG.fullmatch(tt):
            return pen
        if RE_MON.fullmatch(tt):
            return 2.5 + pen
        return 5.0
    if hp:
        return 4.0
    if RE_MON.fullmatch(tt):
        if re.search(r'[0-9]', tt):
            return 0.0 if re.search(r'[.,]', tt) else 0.3
        return 1.0
    return 5.0


def plausible(t):
    return min(tok_cost(t, c, None) for c in COLS) <= 2.0


def align(toks, order, pcs):
    n = len(toks)
    INF = 1e18
    MISS = 5.0
    costs = [[tok_cost(t, order[p], pcs) for p in range(4)] for t, k in toks]
    skipc = [0.0 if k == 't' else (2.5 if t == '' else 3.0) for t, k in toks]
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(2):
            for p in range(4):
                if dp[i][p] < INF:
                    q = (p + 1) % 4
                    c = dp[i][p] + MISS
                    if c < dp[i][q] - 1e-9:
                        dp[i][q] = c
                        bk[i][q] = ('m', i, p)
        if i == n:
            break
        for p in range(4):
            if dp[i][p] >= INF:
                continue
            c = dp[i][p] + costs[i][p]
            q = (p + 1) % 4
            if c < dp[i + 1][q]:
                dp[i + 1][q] = c
                bk[i + 1][q] = ('a', i, p)
            c = dp[i][p] + skipc[i]
            if c < dp[i + 1][p]:
                dp[i + 1][p] = c
                bk[i + 1][p] = ('s', i, p)
    ops = []
    i, p = n, 0
    guard = 0
    while not (i == 0 and p == 0) and guard < 10 * (n + 5):
        guard += 1
        b = bk[i][p]
        if b is None:
            break
        ops.append(b)
        i, p = b[1], b[2]
    ops.reverse()
    rows = []
    cur = {}
    for kind, ti, pp in ops:
        if kind == 's':
            continue
        cur[order[pp]] = toks[ti][0] if kind == 'a' else None
        if pp == 3:
            rows.append(cur)
            cur = {}
    return [r for r in rows if any(r.get(c) is not None for c in COLS)]


def split_line(s, mode):
    if mode == 'pipe':
        parts = s.split('|')
    elif mode == 'semi':
        parts = s.split(';')
    elif mode == 'tab':
        parts = s.split('\t')
    else:
        parts = re.split(r' {3}|\t', s)
    return [p.strip() for p in parts]


def parse_doc(text):
    lines = text.split('\n')
    order = list(COLS)
    mode = None
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            ms = list(re.finditer(r'CODE|QTY|UNIT|AMOUNT', rest))
            names = [m.group(0) for m in ms]
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            if len(ms) >= 2:
                sep = rest[ms[0].end():ms[1].start()]
                if '|' in sep:
                    mode = 'pipe'
                elif ';' in sep:
                    mode = 'semi'
                elif '\t' in sep:
                    mode = 'tab'
                else:
                    mode = 'space'
            break
    if mode is None:
        body = '\n'.join(l for l in lines if not re.match(r'\s*(MANIFEST|COLUMNS|==|SUBTOTAL|TOTAL)', l))
        cnt = {'pipe': body.count('|'), 'semi': body.count(';'), 'tab': body.count('\t')}
        mode = max(cnt, key=lambda k: cnt[k]) if max(cnt.values()) > 0 else 'space'
    sections = []
    cur = None
    ttok = None
    itok = None
    for ln in lines:
        raw = ln.rstrip('\r')
        st = raw.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', st):
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                if sections and sections[-1]['sub'] is None:
                    cur = sections[-1]
                else:
                    cur = {'toks': [], 'sub': None}
                    sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s*(.*?)\s*ITEMS\s*(.*)$', st)
            if m:
                ttok = m.group(1).strip()
                itok = m.group(2).strip()
            else:
                ttok = st[5:].strip()
            continue
        parts = split_line(raw, mode)
        toks = []
        for k, p in enumerate(parts):
            kind = 't' if (p == '' and k == len(parts) - 1 and k > 0) else 'f'
            toks.append((p, kind))
        nonempty = [p for p, _ in toks if p]
        if not nonempty:
            continue
        if not any(plausible(p) for p in nonempty):
            continue
        if cur is None:
            if sections and sections[-1]['sub'] is None:
                cur = sections[-1]
            else:
                cur = {'toks': [], 'sub': None}
                sections.append(cur)
        cur['toks'].extend(toks)
    return order, sections, ttok, itok


# ---------------- numeric reasoning ----------------

def row_cands(r, Dm, Dq):
    Q, U, A = r['Q'], r['U'], r['A']
    trip = {}

    def add(c, q, u):
        k = (q, u)
        if k not in trip or trip[k] > c:
            trip[k] = c
    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(cq + cu + ca, q, u)
    best = min(trip.values()) if trip else 99.0
    if best > 0:
        for q, cq in Q.items():
            if cq > 1.5:
                continue
            for u, cu in U.items():
                if cq + cu <= 1.5 and (q, u) not in trip:
                    add(cq + cu + Dm(q * u, r['oa']), q, u)
        for a, ca in A.items():
            if ca > 1.5:
                continue
            for q, cq in Q.items():
                if ca + cq <= 1.5 and a % q == 0:
                    add(ca + cq + Dm(a // q, r['ou']), q, a // q)
            for u, cu in U.items():
                if ca + cu <= 1.5 and a % u == 0:
                    q = a // u
                    if 1 <= q <= 500:
                        add(ca + cu + Dq(q, r['oq']), q, u)
    if not trip:
        q = min(Q.items(), key=lambda x: x[1])[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: x[1])[0]
        elif A:
            u = max(1, min(A.items(), key=lambda x: x[1])[0] // q)
        else:
            u = 100
        return [[50.0, q, u, q * u]]
    lst = sorted([[c, k[0], k[1], k[0] * k[1]] for k, c in trip.items()], key=lambda x: x[0])
    return lst[:12]


def solve_section(rows, score, targets, deadline, Dm, Dq):
    if not rows:
        return [], 0, 0.0
    base = [r['tr'][0] for r in rows]
    tot = sum(t[3] for t in base)
    rc = sum(t[0] for t in base)
    s0 = score(tot)
    best_obj = rc + s0
    best_mod = None
    if s0 <= 0:
        return base, tot, best_obj
    alts = []
    bydelta = {}
    for i, r in enumerate(rows):
        b = base[i]
        for t in r['tr'][1:]:
            d = t[3] - b[3]
            if d == 0:
                continue
            dc = t[0] - b[0]
            alts.append((i, t, d, dc))
            ns = tot + d
            if ns > 0:
                obj = rc + dc + score(ns)
                if obj < best_obj - 1e-9:
                    best_obj = obj
                    best_mod = [(i, t)]
            bydelta.setdefault(d, []).append((dc, i, t))
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        if rc + st >= best_obj:
            continue
        need = tv - tot
        for (i, t, d, dc) in alts:
            if rc + dc + st >= best_obj:
                continue
            lst = bydelta.get(need - d)
            if not lst:
                continue
            for (dc2, j, t2) in lst:
                if j > i:
                    obj = rc + dc + dc2 + st
                    if obj < best_obj - 1e-9:
                        best_obj = obj
                        best_mod = [(i, t), (j, t2)]
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        for i, r in enumerate(rows):
            b = base[i]
            req = tv - (tot - b[3])
            if req <= 0:
                continue
            basec = rc - b[0] + st
            if basec >= best_obj:
                continue
            ca = r['A'].get(req)
            if ca is None:
                ca = Dm(req, r['oa'])
            if basec + ca >= best_obj:
                continue
            for q, cq in r['Q'].items():
                if req % q:
                    continue
                u = req // q
                cu = r['U'].get(u)
                if cu is None:
                    if cq > 0:
                        continue
                    cu = Dm(u, r['ou'])
                c = cq + cu + ca
                if basec + c < best_obj - 1e-9:
                    best_obj = basec + c
                    best_mod = [(i, [c, q, u, req])]
            for u, cu in r['U'].items():
                if cu > 0.5 or req % u:
                    continue
                q = req // u
                if 1 <= q <= 500 and q not in r['Q']:
                    c = cu + Dq(q, r['oq']) + ca
                    if basec + c < best_obj - 1e-9:
                        best_obj = basec + c
                        best_mod = [(i, [c, q, u, req])]
    choice = list(base)
    if best_mod:
        for i, t in best_mod:
            choice[i] = t
    tot = sum(t[3] for t in choice)
    return choice, tot, best_obj


def make_scorer(tok, dist):
    if tok is None or not tok.strip():
        return None, []
    C = money_cands(tok)
    o = mdigits(tok)
    cache = {}

    def f(s):
        v = C.get(s)
        if v is None:
            v = cache.get(s)
            if v is None:
                v = min(6.0, dist(str(s).zfill(3), o)) if s > 0 else 6.0
                cache[s] = v
        return v
    targ = sorted([(v, c) for v, c in C.items() if c <= 1.0], key=lambda x: (x[1], x[0]))[:10]
    return f, targ


def comb(fs, ft, off):
    def f(s):
        v = fs(s) if fs else 0.0
        if ft:
            v += ft(off + s)
        return v
    return f


def recover(state, params):
    t0 = time.perf_counter()
    state['_t0'] = t0
    state['_rows'] = []
    state['output'] = {'items': []}
    text = (state.get('input') or {}).get('text', '') or ''
    try:
        order, sections, ttok, itok = parse_doc(text)
    except Exception:
        return state
    dist = make_dist()

    def Dm(c, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(c).zfill(3), obs))

    def Dq(q, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(q), obs))

    npcs = 0
    for sec in sections:
        for t, k in sec['toks']:
            if t and has_pcs(t):
                npcs += 1
    pcs = npcs >= 2
    secs = []
    for sec in sections:
        try:
            rows = align(sec['toks'], order, pcs)
        except Exception:
            rows = []
        rr = []
        for r in rows:
            tq, tu, ta = r.get('QTY'), r.get('UNIT'), r.get('AMOUNT')
            try:
                code = solve_code(r.get('CODE'))
            except Exception:
                code = 'AA00000'
            row = {'code': code, 'ct': r.get('CODE'), 'Q': qty_cands(tq), 'U': money_cands(tu),
                   'A': money_cands(ta), 'oq': digits_of(tq), 'ou': mdigits(tu), 'oa': mdigits(ta)}
            try:
                row['tr'] = row_cands(row, Dm, Dq)
            except Exception:
                row['tr'] = [[50.0, 1, 100, 100]]
            rr.append(row)
        fS, targ = make_scorer(sec['sub'], dist)
        secs.append({'rows': rr, 'fS': fS, 'targ': targ})

    results = [[[r['tr'][0] for r in s['rows']], 0, 0.0] for s in secs]

    def emit():
        items = []
        meta = []
        for s, res in zip(secs, results):
            for r, t in zip(s['rows'], res[0]):
                items.append({'code': r['code'], 'qty': int(t[1]), 'unit_cents': int(t[2])})
                meta.append({'ct': r['ct'], 'oq': r['oq'], 'ou': r['ou'], 'oa': r['oa'],
                             'q': int(t[1]), 'u': int(t[2]), 'a': int(t[3]), 'c': float(t[0])})
        state['output'] = {'items': items}
        state['_rows'] = meta
    emit()
    try:
        fT, Ttarg = make_scorer(ttok, dist)
        dl1 = t0 + 0.5
        for i, s in enumerate(secs):
            if len(secs) == 1:
                sc = comb(s['fS'], fT, 0)
                targ = list(s['targ']) + list(Ttarg)
            else:
                sc = comb(s['fS'], None, 0)
                targ = s['targ']
            ch, tt, obj = solve_section(s['rows'], sc, targ, dl1, Dm, Dq)
            results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
        dl2 = t0 + 0.7
        if fT and len(secs) > 1:
            for _ in range(3):
                if time.perf_counter() > dl2:
                    break
                grand = sum(r[1] for r in results)
                ct = fT(grand)
                if ct <= 0:
                    break
                best_gain = 1e-9
                best = None
                for i, s in enumerate(secs):
                    if time.perf_counter() > dl2 or not s['rows']:
                        continue
                    other = grand - results[i][1]
                    fS = s['fS']
                    sc = comb(fS, fT, other)
                    targ = list(s['targ']) + [(tv - other, c) for tv, c in Ttarg if tv - other > 0]
                    ch, tt, obj = solve_section(s['rows'], sc, targ, dl2, Dm, Dq)
                    old = results[i][2] + (fS(results[i][1]) if fS else 0.0) + ct
                    gain = old - obj
                    if gain > best_gain:
                        best_gain = gain
                        best = (i, ch, tt)
                if best is None:
                    break
                i, ch, tt = best
                results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
    except Exception:
        pass
    return state


# ---------------- damage profile ----------------

def op_counts(orig, obs):
    """Viterbi alignment orig->obs; returns (cost, mis, lost, dup)."""
    n, m = len(orig), len(obs)
    INF = 1e9
    dp = [[None] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = (0.0, 0, 0, 0)

    def upd(i, j, cand):
        cur = dp[i][j]
        if cur is None or cand[0] < cur[0]:
            dp[i][j] = cand
    for i in range(n + 1):
        for j in range(m + 1):
            v = dp[i][j]
            if v is None:
                continue
            c, a, b, d = v
            if j < m:
                upd(i, j + 1, (c + 3.0, a, b, d))
            if i < n:
                ch = orig[i]
                upd(i + 1, j, (c + 1.0, a, b + 1, d))
                if j < m:
                    x = obs[j]
                    if x == ch:
                        upd(i + 1, j + 1, (c, a, b, d))
                    elif x in MIS.get(ch, ''):
                        upd(i + 1, j + 1, (c + 1.0, a + 1, b, d))
                    else:
                        upd(i + 1, j + 1, (c + 3.0, a, b, d))
                    if j + 1 < m and x == ch and obs[j + 1] == ch:
                        upd(i + 1, j + 2, (c + 1.0, a, b, d + 1))
    r = dp[n][m]
    return r if r is not None else (INF, 0, 0, 0)


def profile_damage(state, params):
    rows = state.get('_rows') or []
    N = 0
    cm = cl = cd = 0.0
    try:
        for r in rows:
            pairs = [(str(r['q']), r.get('oq')), (str(r['u']).zfill(3), r.get('ou')),
                     (str(r['a']).zfill(3), r.get('oa'))]
            for orig, obs in pairs:
                if obs is None or len(orig) > 14 or len(obs) > 16:
                    continue
                if orig == obs:
                    N += len(orig)
                    continue
                c, a, b, d = op_counts(orig, obs)
                if c > 4.0:
                    continue
                N += len(orig)
                cm += a
                cl += b
                cd += d
            ct = r.get('ct')
            if ct:
                L, dg = code_parts(ct)
                N += 5
                if len(dg) == 4:
                    cl += 1
                elif len(dg) == 3:
                    cl += 2
                elif len(dg) == 6:
                    cd += 1
                elif len(dg) == 7:
                    cd += 2
                elif len(dg) == 5 and not code_ok(L, dg):
                    cm += 0.7
                    cl += 0.15
                    cd += 0.15
    except Exception:
        pass
    den = N + 40.0
    pm = (cm + 0.4) / den
    pl = (cl + 0.4) / den
    pd = (cd + 0.4) / den
    s = pm + pl + pd
    if s > 0.5:
        pm, pl, pd = pm * 0.5 / s, pl * 0.5 / s, pd * 0.5 / s
    state['_profile'] = {'pm': pm, 'pl': pl, 'pd': pd}
    return state


# ---------------- probabilistic code repair ----------------

def fwd_prob(s, o, pm, pl, pd, pk):
    m = len(o)
    f = [1.0] + [0.0] * m
    for c in s:
        mis = MIS[c]
        pmi = pm / len(mis)
        g = [0.0] * (m + 1)
        for j in range(m + 1):
            v = f[j]
            if v == 0.0:
                continue
            g[j] += v * pl
            if j < m:
                x = o[j]
                if x == c:
                    g[j + 1] += v * pk
                    if j + 1 < m and o[j + 1] == c:
                        g[j + 2] += v * pd
                elif x in mis:
                    g[j + 1] += v * pmi
        f = g
    return f[m]


def inv_step(s, target5):
    res = []
    n = len(s)
    if not target5 or n == 5:
        for i, ch in enumerate(s):
            for o in REV.get(ch, ''):
                res.append(s[:i] + o + s[i + 1:])
    if not target5 or n == 6:
        for i in range(n - 1):
            if s[i] == s[i + 1]:
                res.append(s[:i] + s[i + 1:])
    if not target5 or n == 4:
        for i in range(n + 1):
            for o in '0123456789':
                res.append(s[:i] + o + s[i:])
    return res


def code_candidates(L, d):
    out = set()
    if code_ok(L, d):
        out.add(d)
    l1 = set(inv_step(d, False))
    for s in l1:
        if len(s) == 5 and code_ok(L, s):
            out.add(s)
    for s in l1:
        if 4 <= len(s) <= 6:
            for t in inv_step(s, True):
                if code_ok(L, t):
                    out.add(t)
    return out


def repair_codes(state, params):
    try:
        t0 = state.get('_t0')
        start = time.perf_counter()
        deadline = (t0 + 0.92) if isinstance(t0, float) else (start + 0.2)
        if deadline < start + 0.05:
            deadline = start + 0.05
        prof = state.get('_profile') or {'pm': 0.02, 'pl': 0.02, 'pd': 0.02}
        pm, pl, pd = prof['pm'], prof['pl'], prof['pd']
        pk = max(0.3, 1.0 - pm - pl - pd)
        rows = state.get('_rows') or []
        items = state['output']['items']
        if len(rows) == len(items):
            for r, it in zip(rows, items):
                if time.perf_counter() > deadline:
                    break
                ct = r.get('ct')
                if not ct:
                    continue
                L, d = code_parts(ct)
                if not (3 <= len(d) <= 7):
                    continue
                cands = code_candidates(L, d)
                if not cands:
                    continue
                best = None
                for s in sorted(cands):
                    p = fwd_prob(s, d, pm, pl, pd, pk)
                    if best is None or p > best[0]:
                        best = (p, s)
                if best is not None and best[0] > 0:
                    it['code'] = L + best[1]
    except Exception:
        pass
    for k in ('_rows', '_profile', '_t0'):
        if k in state:
            del state[k]
    return state

import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INV = {}
for _k, _v in MIS.items():
    for _c in _v:
        INV.setdefault(_c, []).append(_k)
REV = {}
for _o in sorted(MIS):
    for _s in MIS[_o]:
        REV[_s] = REV.get(_s, '') + _o
L2D = {'O': '0', 'o': '0', 'D': '0', 'Q': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1', 'S': '5', 's': '5',
       'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
CM, CD, CP, CX, CG, CA = 2.5, 3.0, 3.0, 2.5, 8.0, 4.0
COLS = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
RE_CODE = re.compile(r'[A-Za-z0-9]{2}[0-9A-Za-z]{2,8}')
RE_QDIG = re.compile(r'[0-9OolIiSsBZzG]{1,4}')
RE_MON = re.compile(r"[0-9OolIiSsBZzG.,']{1,14}")


# ================= layout (from Y) =================

def strip_pcs(t):
    return re.sub(r'(?i)\s*pcs\s*$', '', t.strip())


def has_pcs(t):
    return re.search(r'(?i)pcs\s*$', t.strip()) is not None


def tok_cost(t, col, pcs):
    if t == '':
        if col == 'QTY':
            return 1.0
        return 6.0 if col == 'CODE' else 4.0
    if col == 'CODE':
        if RE_CODE.fullmatch(t):
            nl = sum(1 for c in t[:2] if c.isalpha())
            bad = sum(1 for c in t[2:] if c.isalpha() and c not in L2D)
            base = 0.0 if nl == 2 else (0.5 if nl == 1 else 2.0)
            return base + 2.0 * bad
        return 5.0
    hp = has_pcs(t)
    tt = strip_pcs(t)
    if col == 'QTY':
        pen = 0.5 if (pcs is not None and hp != pcs) else 0.0
        if tt == '':
            return (0.8 + pen) if hp else 1.0
        if RE_QDIG.fullmatch(tt):
            return pen
        if RE_MON.fullmatch(tt):
            return 2.5 + pen
        return 5.0
    if hp:
        return 4.0
    if RE_MON.fullmatch(tt):
        if re.search(r'[0-9]', tt):
            return 0.0 if re.search(r'[.,]', tt) else 0.3
        return 1.0
    return 5.0


def plausible(t):
    return min(tok_cost(t, c, None) for c in COLS) <= 2.0


def y_align(toks, order, pcs):
    n = len(toks)
    INF = 1e18
    MISS = 5.0
    costs = [[tok_cost(t, order[p], pcs) for p in range(4)] for t, k in toks]
    skipc = [0.0 if k == 't' else (2.5 if t == '' else 3.0) for t, k in toks]
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(2):
            for p in range(4):
                if dp[i][p] < INF:
                    q = (p + 1) % 4
                    c = dp[i][p] + MISS
                    if c < dp[i][q] - 1e-9:
                        dp[i][q] = c
                        bk[i][q] = ('m', i, p)
        if i == n:
            break
        for p in range(4):
            if dp[i][p] >= INF:
                continue
            c = dp[i][p] + costs[i][p]
            q = (p + 1) % 4
            if c < dp[i + 1][q]:
                dp[i + 1][q] = c
                bk[i + 1][q] = ('a', i, p)
            c = dp[i][p] + skipc[i]
            if c < dp[i + 1][p]:
                dp[i + 1][p] = c
                bk[i + 1][p] = ('s', i, p)
    ops = []
    i, p = n, 0
    guard = 0
    while not (i == 0 and p == 0) and guard < 10 * (n + 5):
        guard += 1
        b = bk[i][p]
        if b is None:
            break
        ops.append(b)
        i, p = b[1], b[2]
    ops.reverse()
    rows = []
    cur = {}
    for kind, ti, pp in ops:
        if kind == 's':
            continue
        cur[order[pp]] = toks[ti][0] if kind == 'a' else None
        if pp == 3:
            rows.append(cur)
            cur = {}
    return [r for r in rows if any(r.get(c) is not None for c in COLS)]


def split_line(s, mode):
    if mode == 'pipe':
        parts = s.split('|')
    elif mode == 'semi':
        parts = s.split(';')
    elif mode == 'tab':
        parts = s.split('\t')
    else:
        parts = re.split(r' {3}|\t', s)
    return [p.strip() for p in parts]


def y_parse_doc(text):
    lines = text.split('\n')
    order = list(COLS)
    mode = None
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            ms = list(re.finditer(r'CODE|QTY|UNIT|AMOUNT', rest))
            names = [m.group(0) for m in ms]
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            if len(ms) >= 2:
                sep = rest[ms[0].end():ms[1].start()]
                if '|' in sep:
                    mode = 'pipe'
                elif ';' in sep:
                    mode = 'semi'
                elif '\t' in sep:
                    mode = 'tab'
                else:
                    mode = 'space'
            break
    if mode is None:
        body = '\n'.join(l for l in lines if not re.match(r'\s*(MANIFEST|COLUMNS|==|SUBTOTAL|TOTAL)', l))
        cnt = {'pipe': body.count('|'), 'semi': body.count(';'), 'tab': body.count('\t')}
        mode = max(cnt, key=lambda k: cnt[k]) if max(cnt.values()) > 0 else 'space'
    sections = []
    cur = None
    ttok = None
    itok = None
    for ln in lines:
        raw = ln.rstrip('\r')
        st = raw.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', st):
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                if sections and sections[-1]['sub'] is None:
                    cur = sections[-1]
                else:
                    cur = {'toks': [], 'sub': None}
                    sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s*(.*?)\s*ITEMS\s*(.*)$', st)
            if m:
                ttok = m.group(1).strip()
                itok = m.group(2).strip()
            else:
                ttok = st[5:].strip()
            continue
        parts = split_line(raw, mode)
        toks = []
        for k, p in enumerate(parts):
            kind = 't' if (p == '' and k == len(parts) - 1 and k > 0) else 'f'
            toks.append([p, kind])
        nonempty = [p for p, _ in toks if p]
        if not nonempty:
            continue
        if not any(plausible(p) for p in nonempty):
            continue
        if cur is None:
            if sections and sections[-1]['sub'] is None:
                cur = sections[-1]
            else:
                cur = {'toks': [], 'sub': None}
                sections.append(cur)
        cur['toks'].extend(toks)
    return order, sections, ttok, itok


def parse_layout(state, params):
    state['_t0'] = time.perf_counter()
    text = (state.get('input') or {}).get('text', '') or ''
    secs = []
    ttok = None
    try:
        order, sections, ttok, itok = y_parse_doc(text)
        npcs = sum(1 for s in sections for t, k in s['toks'] if t and has_pcs(t))
        pcs = npcs >= 2
        for sec in sections:
            try:
                rows = y_align(sec['toks'], order, pcs)
            except Exception:
                rows = []
            secs.append({'rows': [[r.get(c) for c in COLS] for r in rows], 'sub': sec['sub']})
    except Exception:
        secs = []
    state['_secs'] = secs
    state['_tot'] = ttok
    state['output'] = {'items': []}
    return state


# ================= numeric MAP decoding (from X) =================

def norm_num(t):
    if t is None:
        return ''
    t = re.sub(r'\s*pcs\s*$', '', t.strip())
    out = []
    for ch in t:
        if ch.isdigit():
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
        elif ch in '.,':
            out.append('.')
        elif ch == "'":
            out.append("'")
    return ''.join(out)


def edit_cost(s, o, memo):
    key = s + '|' + o
    r = memo.get(key)
    if r is not None:
        return r
    n, m = len(s), len(o)
    INF = 1e9
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            c = row[j]
            if c >= INF:
                continue
            if j < m:
                v = c + CG
                if v < row[j + 1]:
                    row[j + 1] = v
            if i < n:
                si = s[i]
                nr = dp[i + 1]
                dc = CD if si.isdigit() else (CX if si == '.' else CA)
                if c + dc < nr[j]:
                    nr[j] = c + dc
                if j < m:
                    oj = o[j]
                    if si == oj:
                        v = c
                    elif si in MIS and oj in MIS[si]:
                        v = c + CM
                    elif (si == "'") != (oj == "'") or (si == '.') != (oj == '.'):
                        v = c + CG + 2
                    else:
                        v = c + CG
                    if v < nr[j + 1]:
                        nr[j + 1] = v
                    if j + 1 < m and si.isdigit() and oj == si and o[j + 1] == si:
                        v = c + CP
                        if v < nr[j + 2]:
                            nr[j + 2] = v
    r = dp[n][m]
    memo[key] = r
    return r


def fmt_money(c, grp):
    i, f = divmod(c, 100)
    s = str(i)
    if grp:
        p = []
        while len(s) > 3:
            p.insert(0, s[-3:])
            s = s[:-3]
        p.insert(0, s)
        s = "'".join(p)
    return s + '.' + ('%02d' % f)


def parse_money(s):
    s = s.replace("'", '')
    if s.count('.') != 1:
        return None
    a, b = s.split('.')
    if len(b) != 2 or not a or not a.isdigit() or not b.isdigit():
        return None
    if len(a) > 1 and a[0] == '0':
        return None
    return int(a) * 100 + int(b)


def inv_neigh(t, allow_ins, money):
    out = []
    L = len(t)
    for i in range(L):
        c = t[i]
        if c in INV:
            for y in INV[c]:
                out.append((t[:i] + y + t[i + 1:], CM))
        if c.isdigit() and i + 1 < L and t[i + 1] == c:
            out.append((t[:i] + t[i + 1:], CP))
    if allow_ins:
        for i in range(L + 1):
            for d in '0123456789':
                out.append((t[:i] + d + t[i:], CD))
    if money and '.' not in t:
        for i in range(max(0, L - 3), L + 1):
            out.append((t[:i] + '.' + t[i:], CX))
    return out


def money_cands(o):
    t = o.replace("'", '')
    res = {}
    v = parse_money(t)
    if v is not None:
        res[v] = 0.0
    lvl1 = inv_neigh(t, True, True)
    seen = {t: 0.0}
    for s, c in lvl1:
        if s in seen and seen[s] <= c:
            continue
        seen[s] = c
        v = parse_money(s)
        if v is not None and res.get(v, 99) > c:
            res[v] = c
    for s, c in lvl1:
        if c == CD:
            continue
        for s2, c2 in inv_neigh(s, False, True):
            cc = c + c2
            v = parse_money(s2)
            if v is not None and res.get(v, 99) > cc:
                res[v] = cc
    if '.' not in t:
        L = len(t)
        for i in range(L + 1):
            for d in '0123456789':
                s = t[:i] + d + t[i:]
                v = parse_money(s[:-2] + '.' + s[-2:]) if len(s) >= 3 else None
                if v is not None and res.get(v, 99) > CD + CX:
                    res[v] = CD + CX
    return res


def qty_cands(o):
    t = o.replace("'", '').replace('.', '')
    res = {}
    seen = {}
    frontier = [(t, 0.0)]
    for depth in range(3):
        nxt = []
        for s, c in frontier:
            if s in seen and seen[s] <= c:
                continue
            seen[s] = c
            if s and s.isdigit() and s[0] != '0':
                v = int(s)
                if 1 <= v <= 500 and res.get(v, 99) > c:
                    res[v] = c
            if depth < 2:
                for s2, c2 in inv_neigh(s, depth == 0 or len(s) < 1, False):
                    if len(s2) <= 4:
                        nxt.append((s2, c + c2))
        frontier = nxt
    return res


def code_parts(tok):
    t = re.sub(r'[^0-9A-Za-z|]', '', tok or '')
    letters = ''
    for c in t[:2]:
        if c.isalpha() and 'A' <= c.upper() <= 'Z' and c not in 'l|':
            letters += c.upper()
        elif c in D2L:
            letters += D2L[c]
        elif c in 'l|':
            letters += 'I'
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    digs = ''.join(L2D.get(c, c) for c in t[2:] if c.isdigit() or c in L2D)
    return letters, digs


def code_ok(L, s):
    if len(s) != 5 or not s.isdigit():
        return False
    p1 = ord(L[0]) - 64
    p2 = ord(L[1]) - 64
    d = [int(c) for c in s]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def code_decode(tok, memo):
    lets, rest = code_parts(tok)

    def ok(d):
        return code_ok(lets, d)

    if ok(rest):
        return lets + rest
    best = {}
    frontier = [(rest, 0.0)]
    seen = {}
    for depth in range(2):
        nxt = []
        for s, c in frontier:
            for s2, c2 in inv_neigh(s, True, False):
                if abs(len(s2) - 5) > 1 - depth:
                    continue
                cc = c + c2
                if s2 in seen and seen[s2] <= cc:
                    continue
                seen[s2] = cc
                if ok(s2) and best.get(s2, 99) > cc:
                    best[s2] = cc
                nxt.append((s2, cc))
        frontier = nxt
    if not best:
        base = [rest]
        if len(rest) > 5:
            base = [rest[:i] + rest[i + 1:] for i in range(len(rest))] if len(rest) == 6 else [rest[:5]]
        elif len(rest) < 5:
            base = [(rest + '00000')[:5]]
        for b in base:
            for i in range(5):
                for d in '0123456789':
                    s2 = b[:i] + d + b[i + 1:]
                    if ok(s2):
                        cc = edit_cost(s2, rest, memo)
                        if best.get(s2, 99) > cc:
                            best[s2] = cc
    if not best:
        return lets + '00000'
    m = min(best.values())
    cands = sorted(s for s, c in best.items() if c <= m + 1e-9)
    return lets + cands[0]


def row_hyps(qo, uo, ao, memo, grp, deadline):
    Cq = qty_cands(qo)
    Cu = money_cands(uo)
    Ca = money_cands(ao)
    H = {}

    def add(q, u, a, c):
        if q < 1 or q > 500 or u <= 0:
            return
        k = (q, u)
        if H.get(k, (1e9,))[0] > c:
            H[k] = (c, q, u, a)

    def ucost(u):
        c = Cu.get(u)
        if c is None:
            c = edit_cost(fmt_money(u, grp), uo, memo)
        return c

    def acost(a):
        c = Ca.get(a)
        if c is None:
            c = edit_cost(fmt_money(a, grp), ao, memo)
        return c

    def qcost(q):
        c = Cq.get(q)
        if c is None:
            c = edit_cost(str(q), qo, memo)
        return c

    qs = sorted(Cq.items(), key=lambda x: (x[1], x[0]))
    us = sorted(Cu.items(), key=lambda x: (x[1], x[0]))
    as_ = sorted(Ca.items(), key=lambda x: (x[1], x[0]))
    BUD = 9.5
    for q, cq in qs:
        if cq > BUD:
            break
        for u, cu in us:
            if cq + cu > BUD:
                break
            a = q * u
            ca = Ca.get(a)
            if ca is not None and cq + cu + ca <= BUD:
                add(q, u, a, cq + cu + ca)
    best = min((h[0] for h in H.values()), default=99.0)
    lim = 3.1 if best <= 3.0 else 6.0
    tq = [x for x in qs if x[1] <= lim][:12]
    tu = [x for x in us if x[1] <= lim][:25]
    ta = [x for x in as_ if x[1] <= lim][:25]
    if best == 0.0:
        tq = [x for x in qs if x[1] == 0.0]
        tu = [x for x in us if x[1] == 0.0]
        ta = [x for x in as_ if x[1] == 0.0]
    for q, cq in tq:
        for u, cu in tu:
            if cq + cu >= best + 9:
                continue
            a = q * u
            add(q, u, a, cq + cu + acost(a))
        for a, ca in ta:
            if cq + ca >= best + 9:
                continue
            if a % q == 0:
                u = a // q
                add(q, u, a, cq + ca + ucost(u))
    for u, cu in tu:
        if u <= 0:
            continue
        for a, ca in ta:
            if cu + ca >= best + 9:
                continue
            if a % u == 0:
                q = a // u
                if 1 <= q <= 500:
                    add(q, u, a, cu + ca + qcost(q))
    best = min((h[0] for h in H.values()), default=99.0)
    if best > 4.0 and time.perf_counter() < deadline:
        tq = [x for x in qs if x[1] <= 3.1][:15]
        tu = [x for x in us if x[1] <= 3.1][:60]
        ta = [x for x in as_ if x[1] <= 3.1][:60]
        for q, cq in tq:
            for u, cu in tu:
                if cq + cu + 2.5 < best:
                    a = q * u
                    add(q, u, a, cq + cu + acost(a))
            for a, ca in ta:
                if cq + ca + 2.5 < best and a % q == 0:
                    u = a // q
                    add(q, u, a, cq + ca + ucost(u))
        best = min((h[0] for h in H.values()), default=99.0)
    if best > 6.0 and time.perf_counter() < deadline:
        for a, ca in as_[:30]:
            if ca > 6:
                break
            for q in range(1, 501):
                if a % q == 0:
                    u = a // q
                    c = ca + ucost(u)
                    if c < best + 6:
                        add(q, u, a, c + qcost(q))
    hl = sorted(H.values())
    if not hl:
        q = min(Cq.items(), key=lambda x: x[1])[0] if Cq else 1
        u = min(Cu.items(), key=lambda x: x[1])[0] if Cu else 100
        hl = [(30.0, q, u, q * u)]
    b = hl[0][0]
    return [h for h in hl if h[0] <= b + 10][:15], Cq


def reconcile_section(rr, sub_o, memo, grp, deadline):
    base_rows = [r['hyps'][0] for r in rr]
    base_cost = sum(h[0] for h in base_rows)
    base_sum = sum(h[3] for h in base_rows)

    def pack(sel):
        return [(i, sel[i][1], sel[i][2], sel[i][3]) for i in range(len(rr))]

    if not sub_o or not rr:
        return [(base_cost, base_sum, pack(base_rows))]

    def scost(s):
        return edit_cost(fmt_money(s, grp), sub_o, memo)

    alts = {}

    def consider(sel_changes, rowcost):
        s = base_sum
        sel = list(base_rows)
        for i, h in sel_changes:
            s += h[3] - sel[i][3]
            sel[i] = h
        c = rowcost + scost(s)
        if s not in alts or alts[s][0] > c:
            alts[s] = (c, sel)

    consider([], base_cost)
    deltas = {}
    for i, r in enumerate(rr):
        for h in r['hyps'][1:]:
            d = h[3] - base_rows[i][3]
            dc = h[0] - base_rows[i][0]
            consider([(i, h)], base_cost + dc)
            if d not in deltas or deltas[d][0] > dc:
                deltas[d] = (dc, i, h)
    targets = {}
    v = parse_money(sub_o.replace("'", ''))
    if v is not None:
        targets[v] = 0.0
    for val, c in money_cands(sub_o).items():
        if c <= 3.5 and (val not in targets or targets[val] > c):
            targets[val] = c
    cur_best = min(a[0] for a in alts.values())
    for T, tc in targets.items():
        resid = T - base_sum
        if resid == 0:
            continue
        if time.perf_counter() > deadline:
            break
        for d1, (c1, i1, h1) in list(deltas.items()):
            d2 = resid - d1
            if d2 in deltas:
                c2, i2, h2 = deltas[d2]
                if i2 != i1 and base_cost + c1 + c2 + tc < cur_best + 0.01:
                    consider([(i1, h1), (i2, h2)], base_cost + c1 + c2)
        for i, r in enumerate(rr):
            a2 = base_rows[i][3] + resid
            if a2 <= 0:
                continue
            ca = edit_cost(fmt_money(a2, grp), r['ao'], memo)
            if ca > 9:
                continue
            for q, cq in r['Cq'].items():
                if cq > 6 or a2 % q:
                    continue
                u = a2 // q
                cu = edit_cost(fmt_money(u, grp), r['uo'], memo)
                c = ca + cq + cu
                if c - base_rows[i][0] + base_cost + tc < cur_best + 0.01:
                    consider([(i, (c, q, u, a2))], base_cost + c - base_rows[i][0])
        cur_best = min(a[0] for a in alts.values())
    out = sorted(((c, s, pack(sel)) for s, (c, sel) in alts.items()), key=lambda x: x[0])
    return out[:12]


def decode_numbers(state, params):
    t0 = state.get('_t0') or time.perf_counter()
    deadline = t0 + 0.6
    memo = {}
    secs = state.get('_secs') or []
    total_obs = state.get('_tot')
    items = []
    meta = []
    try:
        alltok = [t for s in secs for r in s['rows'] for t in r if t]
        grp = any("'" in t for t in alltok) or (total_obs is not None and "'" in total_obs) or \
            any(s['sub'] and "'" in s['sub'] for s in secs)
        sec_rr = []
        sec_results = []
        for sec in secs:
            rr = []
            for r in sec['rows']:
                qo, uo, ao = norm_num(r[1]), norm_num(r[2]), norm_num(r[3])
                hyps, Cq = row_hyps(qo, uo, ao, memo, grp, deadline)
                rr.append({'ct': r[0], 'hyps': hyps, 'qo': qo, 'uo': uo, 'ao': ao, 'Cq': Cq})
            sub_o = norm_num(sec['sub']) if sec['sub'] is not None else None
            sec_rr.append(rr)
            sec_results.append(reconcile_section(rr, sub_o, memo, grp, deadline))
        tot_o = norm_num(total_obs) if total_obs is not None else None
        cur = [0] * len(sec_results)
        if tot_o and sec_results:
            def doc_cost(ch):
                c = 0.0
                s = 0
                for k, alts in enumerate(sec_results):
                    cc, ss, _ = alts[ch[k]]
                    c += cc
                    s += ss
                return c + edit_cost(fmt_money(s, grp), tot_o, memo)
            bc = doc_cost(cur)
            improved = True
            it = 0
            while improved and it < 3:
                improved = False
                it += 1
                for k in range(len(sec_results)):
                    for j in range(len(sec_results[k])):
                        if j == cur[k]:
                            continue
                        ch = list(cur)
                        ch[k] = j
                        c = doc_cost(ch)
                        if c < bc - 1e-9:
                            bc = c
                            cur = ch
                            improved = True
        for k, rr in enumerate(sec_rr):
            for (i, q, u, a) in sec_results[k][cur[k]][2]:
                r = rr[i]
                items.append({'code': code_decode(r['ct'], memo), 'qty': int(q), 'unit_cents': int(u)})
                meta.append({'ct': r['ct'], 'oq': r['qo'].replace("'", '').replace('.', ''),
                             'ou': r['uo'].replace("'", '').replace('.', ''),
                             'oa': r['ao'].replace("'", '').replace('.', ''), 'q': int(q), 'u': int(u), 'a': int(a)})
    except Exception:
        pass
    state['output'] = {'items': items}
    state['_rows'] = meta
    for k in ('_secs', '_tot'):
        if k in state:
            del state[k]
    return state


# ================= damage profile + probabilistic code repair (from Y) =================

def op_counts(orig, obs):
    n, m = len(orig), len(obs)
    dp = [[None] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = (0.0, 0, 0, 0)

    def upd(i, j, cand):
        cur = dp[i][j]
        if cur is None or cand[0] < cur[0]:
            dp[i][j] = cand
    for i in range(n + 1):
        for j in range(m + 1):
            v = dp[i][j]
            if v is None:
                continue
            c, a, b, d = v
            if j < m:
                upd(i, j + 1, (c + 3.0, a, b, d))
            if i < n:
                ch = orig[i]
                upd(i + 1, j, (c + 1.0, a, b + 1, d))
                if j < m:
                    x = obs[j]
                    if x == ch:
                        upd(i + 1, j + 1, (c, a, b, d))
                    elif x in MIS.get(ch, ''):
                        upd(i + 1, j + 1, (c + 1.0, a + 1, b, d))
                    else:
                        upd(i + 1, j + 1, (c + 3.0, a, b, d))
                    if j + 1 < m and x == ch and obs[j + 1] == ch:
                        upd(i + 1, j + 2, (c + 1.0, a, b, d + 1))
    r = dp[n][m]
    return r if r is not None else (1e9, 0, 0, 0)


def profile_damage(state, params):
    rows = state.get('_rows') or []
    N = 0
    cm = cl = cd = 0.0
    try:
        for r in rows:
            pairs = [(str(r['q']), r.get('oq')), (str(r['u']).zfill(3), r.get('ou')),
                     (str(r['a']).zfill(3), r.get('oa'))]
            for orig, obs in pairs:
                if obs is None or len(orig) > 14 or len(obs) > 16:
                    continue
                if orig == obs:
                    N += len(orig)
                    continue
                c, a, b, d = op_counts(orig, obs)
                if c > 4.0:
                    continue
                N += len(orig)
                cm += a
                cl += b
                cd += d
            ct = r.get('ct')
            if ct:
                L, dg = code_parts(ct)
                N += 5
                if len(dg) < 5:
                    cl += 5 - len(dg)
                elif len(dg) > 5:
                    cd += len(dg) - 5
                elif not code_ok(L, dg):
                    cm += 0.7
                    cl += 0.15
                    cd += 0.15
    except Exception:
        pass
    den = N + 40.0
    pm = (cm + 0.4) / den
    pl = (cl + 0.4) / den
    pd = (cd + 0.4) / den
    s = pm + pl + pd
    if s > 0.5:
        pm, pl, pd = pm * 0.5 / s, pl * 0.5 / s, pd * 0.5 / s
    state['_profile'] = {'pm': pm, 'pl': pl, 'pd': pd}
    return state


def fwd_prob(s, o, pm, pl, pd, pk):
    m = len(o)
    f = [1.0] + [0.0] * m
    for c in s:
        mis = MIS[c]
        pmi = pm / len(mis)
        g = [0.0] * (m + 1)
        for j in range(m + 1):
            v = f[j]
            if v == 0.0:
                continue
            g[j] += v * pl
            if j < m:
                x = o[j]
                if x == c:
                    g[j + 1] += v * pk
                    if j + 1 < m and o[j + 1] == c:
                        g[j + 2] += v * pd
                elif x in mis:
                    g[j + 1] += v * pmi
        f = g
    return f[m]


def inv_step(s, target5):
    res = []
    n = len(s)
    if not target5 or n == 5:
        for i, ch in enumerate(s):
            for o in REV.get(ch, ''):
                res.append(s[:i] + o + s[i + 1:])
    if not target5 or n == 6:
        for i in range(n - 1):
            if s[i] == s[i + 1]:
                res.append(s[:i] + s[i + 1:])
    if not target5 or n == 4:
        for i in range(n + 1):
            for o in '0123456789':
                res.append(s[:i] + o + s[i:])
    return res


def code_candidates(L, d):
    out = set()
    if code_ok(L, d):
        out.add(d)
        return out
    l1 = set(inv_step(d, False))
    for s in l1:
        if len(s) == 5 and code_ok(L, s):
            out.add(s)
    for s in l1:
        if 4 <= len(s) <= 6:
            for t in inv_step(s, True):
                if code_ok(L, t):
                    out.add(t)
    if not out and 3 <= len(d) <= 7:
        l2 = set()
        for s in l1:
            if 3 <= len(s) <= 7:
                l2.update(x for x in inv_step(s, False) if 4 <= len(x) <= 6)
        for s in l2:
            for t in inv_step(s, True):
                if code_ok(L, t):
                    out.add(t)
    return out


def repair_codes(state, params):
    try:
        t0 = state.get('_t0')
        start = time.perf_counter()
        deadline = (t0 + 0.9) if isinstance(t0, float) else (start + 0.2)
        if deadline < start + 0.05:
            deadline = start + 0.05
        prof = state.get('_profile') or {'pm': 0.02, 'pl': 0.02, 'pd': 0.02}
        pm, pl, pd = prof['pm'], prof['pl'], prof['pd']
        pk = max(0.3, 1.0 - pm - pl - pd)
        rows = state.get('_rows') or []
        items = state['output']['items']
        if len(rows) == len(items):
            for r, it in zip(rows, items):
                if time.perf_counter() > deadline:
                    break
                ct = r.get('ct')
                if not ct:
                    continue
                L, d = code_parts(ct)
                if not (3 <= len(d) <= 7):
                    continue
                cands = code_candidates(L, d)
                if not cands:
                    continue
                best = None
                for s in sorted(cands):
                    p = fwd_prob(s, d, pm, pl, pd, pk)
                    if best is None or p > best[0]:
                        best = (p, s)
                if best is not None and best[0] > 0:
                    it['code'] = L + best[1]
    except Exception:
        pass
    for k in ('_rows', '_profile', '_t0'):
        if k in state:
            del state[k]
    return state

import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
REV = {}
for _o in sorted(MIS):
    for _s in MIS[_o]:
        REV[_s] = REV.get(_s, '') + _o

L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
       'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
COLS = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
C_MIS = 1.0
C_DUP = 1.0
C_LOST = 1.2
C_MARK = 0.5
C_LOCK = 1.5
LOCKF = 0.08

RE_CODE = re.compile(r'[A-Za-z0-9]{2}[0-9A-Za-z]{2,8}')
RE_QDIG = re.compile(r'[0-9OolIiSsBZzG]{1,4}')
RE_MON = re.compile(r"[0-9OolIiSsBZzG.,']{1,14}")


def strip_pcs(t):
    return re.sub(r'(?i)\s*pcs\s*$', '', t.strip())


def has_pcs(t):
    return re.search(r'(?i)pcs\s*$', t.strip()) is not None


def digits_of(tok):
    if tok is None:
        return None
    s = strip_pcs(tok)
    return ''.join(L2D.get(c, c) for c in s if c.isdigit() or c in L2D)


def digits_of_m(tok):
    s = strip_pcs(tok)
    d = ''
    m = ''
    for c in s:
        if c.isdigit():
            d += c
            m += '0'
        elif c in L2D:
            d += L2D[c]
            m += '1'
    return d, m


def num_edits(s, mask=None):
    out = {s: 0.0}
    n = len(s)

    def put(v, c):
        if v not in out or out[v] > c:
            out[v] = c
    for i, ch in enumerate(s):
        if ch.isdigit():
            extra = C_LOCK if (mask is not None and i < len(mask) and mask[i] == '1') else 0.0
            for y in REV.get(ch, ''):
                put(s[:i] + y + s[i + 1:], C_MIS + extra)
            if i + 1 < n and s[i + 1] == ch:
                put(s[:i] + s[i + 1:], C_DUP)
    for i in range(n + 1):
        for d in '0123456789':
            put(s[:i] + d + s[i:], C_LOST)
    return out


def norm_money_m(tok):
    chars = []
    mask = []
    for c in tok:
        if c in L2D:
            chars.append(L2D[c])
            mask.append('1')
        elif c.isdigit():
            chars.append(c)
            mask.append('0')
        elif c in ',.':
            chars.append('.')
            mask.append('0')
    t = ''.join(chars)
    m = ''.join(mask)
    if t.count('.') > 1:
        k = t.rfind('.')
        keep = [i for i in range(len(t)) if t[i] != '.' or i == k]
        t = ''.join(t[i] for i in keep)
        m = ''.join(m[i] for i in keep)
    return t, m


def norm_money(tok):
    return norm_money_m(tok)[0]


def mdigits(tok):
    if tok is None:
        return None
    return norm_money(tok).replace('.', '')


def parse_money(v):
    if '.' in v:
        a, b = v.split('.', 1)
        if len(b) != 2 or not a.isdigit() or not b.isdigit():
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        return (int(a) * 100 + int(b), False)
    if len(v) < 3 or not v.isdigit():
        return None
    if len(v) > 3 and v[0] == '0':
        return None
    return (int(v), True)


def money_cands(tok):
    if tok is None:
        return {}
    t, m = norm_money_m(tok)
    if not t or len(t) > 14:
        return {}
    res = {}
    for v, c in num_edits(t, m).items():
        mm = parse_money(v)
        if mm is None:
            continue
        val, nomark = mm
        cc = c + (C_MARK if nomark else 0.0)
        if val > 0 and (val not in res or res[val] > cc):
            res[val] = cc
    return res


def qty_cands(tok):
    if tok is None:
        return {}
    t, m = digits_of_m(tok)
    if t == '':
        return {q: C_LOST for q in range(1, 10)}
    if len(t) > 5:
        return {}
    res = {}
    for v, c in num_edits(t, m).items():
        if not v or (len(v) > 1 and v[0] == '0'):
            continue
        q = int(v)
        if 1 <= q <= 500 and (q not in res or res[q] > c):
            res[q] = c
    return res


def make_dist():
    cache = {}

    def dist(orig, obs):
        k = orig + '|' + obs
        v = cache.get(k)
        if v is not None:
            return v
        m = len(obs)
        prev = [0.0] * (m + 1)
        for j in range(1, m + 1):
            prev[j] = prev[j - 1] + (1.0 if j >= 2 and obs[j - 1] == obs[j - 2] else 2.5)
        for i in range(1, len(orig) + 1):
            oc = orig[i - 1]
            mis = MIS.get(oc, '')
            cur = [prev[0] + 1.2] + [0.0] * m
            for j in range(1, m + 1):
                sc = obs[j - 1]
                if sc == oc:
                    sub = prev[j - 1]
                elif sc in mis:
                    sub = prev[j - 1] + 1.0
                else:
                    sub = prev[j - 1] + 2.5
                ins = cur[j - 1] + (1.0 if (j >= 2 and obs[j - 2] == sc) else 2.5)
                dele = prev[j] + 1.2
                b = sub
                if ins < b:
                    b = ins
                if dele < b:
                    b = dele
                cur[j] = b
            prev = cur
        r = prev[m]
        cache[k] = r
        return r
    return dist


# ---------------- codes ----------------

def code_ok(L, s):
    if len(s) != 5 or not s.isdigit():
        return False
    p1 = ord(L[0]) - 64
    p2 = ord(L[1]) - 64
    d = [int(c) for c in s]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def code_edit_list(d, mask=None):
    res = []
    for i, ch in enumerate(d):
        extra = C_LOCK if (mask is not None and i < len(mask) and mask[i] == '1') else 0.0
        for o in REV.get(ch, ''):
            res.append((d[:i] + o + d[i + 1:], C_MIS + extra))
    for i in range(len(d) - 1):
        if d[i] == d[i + 1]:
            res.append((d[:i] + d[i + 1:], C_DUP))
    for i in range(len(d) + 1):
        for o in '0123456789':
            res.append((d[:i] + o + d[i:], C_LOST))
    return res


def code_parts(tok):
    t = (tok or '').replace(' ', '')
    letters = ''
    for c in t[:2]:
        if c.isalpha() and 'A' <= c.upper() <= 'Z':
            letters += c.upper()
        elif c in D2L:
            letters += D2L[c]
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    digs = ''.join(L2D.get(c, c) for c in t[2:] if c.isdigit() or c in L2D)
    return letters, digs


def code_parts_m(tok):
    L, _ = code_parts(tok)
    t = (tok or '').replace(' ', '')
    d = ''
    m = ''
    for c in t[2:]:
        if c.isdigit():
            d += c
            m += '0'
        elif c in L2D:
            d += L2D[c]
            m += '1'
    return L, d, m


def solve_code(tok):
    if not tok:
        return 'AA00000'
    letters, digs, mask = code_parts_m(tok)
    if code_ok(letters, digs):
        return letters + digs
    counts = {}
    order = []
    for s, c in code_edit_list(digs, mask):
        if code_ok(letters, s):
            if s not in counts:
                counts[s] = [c, 0]
                order.append(s)
            if c < counts[s][0]:
                counts[s][0] = c
            counts[s][1] += 1
    if order:
        best = None
        for s in order:
            c, n = counts[s]
            key = (c, -n)
            if best is None or key < best[0]:
                best = (key, s)
        return letters + best[1]
    l1 = {}
    for s, c in code_edit_list(digs, mask):
        if s not in l1 or l1[s] > c:
            l1[s] = c
    best = None
    for s, c in l1.items():
        if not (4 <= len(s) <= 6):
            continue
        for s2, c2 in code_edit_list(s):
            if len(s2) == 5 and code_ok(letters, s2):
                tot = c + c2
                if best is None or tot < best[0]:
                    best = (tot, s2)
    if best is not None:
        return letters + best[1]
    d4 = digs[:4].ljust(4, '0')
    dd = [int(c) for c in d4]
    chk = (dd[0] + 2 * dd[1] + 3 * dd[2] + 4 * dd[3] + ord(letters[0]) - 64 + ord(letters[1]) - 64) % 10
    return letters + d4 + str(chk)


# ---------------- tokens / alignment ----------------

def tok_cost(t, col, pcs):
    if t == '':
        if col == 'QTY':
            return 1.0
        return 6.0 if col == 'CODE' else 4.0
    if col == 'CODE':
        if RE_CODE.fullmatch(t):
            nl = sum(1 for c in t[:2] if c.isalpha())
            bad = sum(1 for c in t[2:] if c.isalpha() and c not in L2D)
            base = 0.0 if nl == 2 else (0.5 if nl == 1 else 2.0)
            return base + 2.0 * bad
        return 5.0
    hp = has_pcs(t)
    tt = strip_pcs(t)
    if col == 'QTY':
        pen = 0.5 if (pcs is not None and hp != pcs) else 0.0
        if tt == '':
            return (0.8 + pen) if hp else 1.0
        if RE_QDIG.fullmatch(tt):
            return pen
        if RE_MON.fullmatch(tt):
            return 2.5 + pen
        return 5.0
    if hp:
        return 4.0
    if RE_MON.fullmatch(tt):
        if re.search(r'[0-9]', tt):
            return 0.0 if re.search(r'[.,]', tt) else 0.3
        return 1.0
    return 5.0


def plausible(t):
    return min(tok_cost(t, c, None) for c in COLS) <= 2.0


def align(toks, order, pcs):
    n = len(toks)
    INF = 1e18
    MISS = 5.0
    costs = [[tok_cost(t, order[p], pcs) for p in range(4)] for t, k in toks]
    skipc = [0.0 if k == 't' else (2.5 if t == '' else 3.0) for t, k in toks]
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(2):
            for p in range(4):
                if dp[i][p] < INF:
                    q = (p + 1) % 4
                    c = dp[i][p] + MISS
                    if c < dp[i][q] - 1e-9:
                        dp[i][q] = c
                        bk[i][q] = ('m', i, p)
        if i == n:
            break
        for p in range(4):
            if dp[i][p] >= INF:
                continue
            c = dp[i][p] + costs[i][p]
            q = (p + 1) % 4
            if c < dp[i + 1][q]:
                dp[i + 1][q] = c
                bk[i + 1][q] = ('a', i, p)
            c = dp[i][p] + skipc[i]
            if c < dp[i + 1][p]:
                dp[i + 1][p] = c
                bk[i + 1][p] = ('s', i, p)
    ops = []
    i, p = n, 0
    guard = 0
    while not (i == 0 and p == 0) and guard < 10 * (n + 5):
        guard += 1
        b = bk[i][p]
        if b is None:
            break
        ops.append(b)
        i, p = b[1], b[2]
    ops.reverse()
    rows = []
    cur = {}
    for kind, ti, pp in ops:
        if kind == 's':
            continue
        cur[order[pp]] = toks[ti][0] if kind == 'a' else None
        if pp == 3:
            rows.append(cur)
            cur = {}
    return [r for r in rows if any(r.get(c) is not None for c in COLS)]


def split_line(s, mode):
    if mode == 'pipe':
        parts = s.split('|')
    elif mode == 'semi':
        parts = s.split(';')
    elif mode == 'tab':
        parts = s.split('\t')
    else:
        parts = re.split(r' {3}|\t', s)
    return [p.strip() for p in parts]


def parse_doc(text):
    lines = text.split('\n')
    order = list(COLS)
    mode = None
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            ms = list(re.finditer(r'CODE|QTY|UNIT|AMOUNT', rest))
            names = [m.group(0) for m in ms]
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            if len(ms) >= 2:
                sep = rest[ms[0].end():ms[1].start()]
                if '|' in sep:
                    mode = 'pipe'
                elif ';' in sep:
                    mode = 'semi'
                elif '\t' in sep:
                    mode = 'tab'
                else:
                    mode = 'space'
            break
    if mode is None:
        body = '\n'.join(l for l in lines if not re.match(r'\s*(MANIFEST|COLUMNS|==|SUBTOTAL|TOTAL)', l))
        cnt = {'pipe': body.count('|'), 'semi': body.count(';'), 'tab': body.count('\t')}
        mode = max(cnt, key=lambda k: cnt[k]) if max(cnt.values()) > 0 else 'space'
    sections = []
    cur = None
    ttok = None
    itok = None
    for ln in lines:
        raw = ln.rstrip('\r')
        st = raw.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', st):
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                if sections and sections[-1]['sub'] is None:
                    cur = sections[-1]
                else:
                    cur = {'toks': [], 'sub': None}
                    sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s*(.*?)\s*ITEMS\s*(.*)$', st)
            if m:
                ttok = m.group(1).strip()
                itok = m.group(2).strip()
            else:
                ttok = st[5:].strip()
            continue
        parts = split_line(raw, mode)
        toks = []
        for k, p in enumerate(parts):
            kind = 't' if (p == '' and k == len(parts) - 1 and k > 0) else 'f'
            toks.append((p, kind))
        nonempty = [p for p, _ in toks if p]
        if not nonempty:
            continue
        if not any(plausible(p) for p in nonempty):
            continue
        if cur is None:
            if sections and sections[-1]['sub'] is None:
                cur = sections[-1]
            else:
                cur = {'toks': [], 'sub': None}
                sections.append(cur)
        cur['toks'].extend(toks)
    return order, sections, ttok, itok


# ---------------- numeric reasoning ----------------

def row_cands(r, Dm, Dq):
    Q, U, A = r['Q'], r['U'], r['A']
    trip = {}

    def add(c, q, u):
        k = (q, u)
        if k not in trip or trip[k] > c:
            trip[k] = c
    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(cq + cu + ca, q, u)
    best = min(trip.values()) if trip else 99.0
    if best > 0:
        for q, cq in Q.items():
            if cq > 1.5:
                continue
            for u, cu in U.items():
                if cq + cu <= 1.5 and (q, u) not in trip:
                    add(cq + cu + Dm(q * u, r['oa']), q, u)
        for a, ca in A.items():
            if ca > 1.5:
                continue
            for q, cq in Q.items():
                if ca + cq <= 1.5 and a % q == 0:
                    add(ca + cq + Dm(a // q, r['ou']), q, a // q)
            for u, cu in U.items():
                if ca + cu <= 1.5 and a % u == 0:
                    q = a // u
                    if 1 <= q <= 500:
                        add(ca + cu + Dq(q, r['oq']), q, u)
    if not trip:
        q = min(Q.items(), key=lambda x: x[1])[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: x[1])[0]
        elif A:
            u = max(1, min(A.items(), key=lambda x: x[1])[0] // q)
        else:
            u = 100
        return [[50.0, q, u, q * u]]
    lst = sorted([[c, k[0], k[1], k[0] * k[1]] for k, c in trip.items()], key=lambda x: x[0])
    return lst[:12]


def solve_section(rows, score, targets, deadline, Dm, Dq):
    if not rows:
        return [], 0, 0.0
    base = [r['tr'][0] for r in rows]
    tot = sum(t[3] for t in base)
    rc = sum(t[0] for t in base)
    s0 = score(tot)
    best_obj = rc + s0
    best_mod = None
    if s0 <= 0:
        return base, tot, best_obj
    alts = []
    bydelta = {}
    for i, r in enumerate(rows):
        b = base[i]
        for t in r['tr'][1:]:
            d = t[3] - b[3]
            if d == 0:
                continue
            dc = t[0] - b[0]
            alts.append((i, t, d, dc))
            ns = tot + d
            if ns > 0:
                obj = rc + dc + score(ns)
                if obj < best_obj - 1e-9:
                    best_obj = obj
                    best_mod = [(i, t)]
            bydelta.setdefault(d, []).append((dc, i, t))
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        if rc + st >= best_obj:
            continue
        need = tv - tot
        for (i, t, d, dc) in alts:
            if rc + dc + st >= best_obj:
                continue
            lst = bydelta.get(need - d)
            if not lst:
                continue
            for (dc2, j, t2) in lst:
                if j > i:
                    obj = rc + dc + dc2 + st
                    if obj < best_obj - 1e-9:
                        best_obj = obj
                        best_mod = [(i, t), (j, t2)]
    for tv, _ in targets:
        if time.perf_counter() > deadline:
            break
        st = score(tv)
        for i, r in enumerate(rows):
            b = base[i]
            req = tv - (tot - b[3])
            if req <= 0:
                continue
            basec = rc - b[0] + st
            if basec >= best_obj:
                continue
            ca = r['A'].get(req)
            if ca is None:
                ca = Dm(req, r['oa'])
            if basec + ca >= best_obj:
                continue
            for q, cq in r['Q'].items():
                if req % q:
                    continue
                u = req // q
                cu = r['U'].get(u)
                if cu is None:
                    if cq > 0:
                        continue
                    cu = Dm(u, r['ou'])
                c = cq + cu + ca
                if basec + c < best_obj - 1e-9:
                    best_obj = basec + c
                    best_mod = [(i, [c, q, u, req])]
            for u, cu in r['U'].items():
                if cu > 0.5 or req % u:
                    continue
                q = req // u
                if 1 <= q <= 500 and q not in r['Q']:
                    c = cu + Dq(q, r['oq']) + ca
                    if basec + c < best_obj - 1e-9:
                        best_obj = basec + c
                        best_mod = [(i, [c, q, u, req])]
    choice = list(base)
    if best_mod:
        for i, t in best_mod:
            choice[i] = t
    tot = sum(t[3] for t in choice)
    return choice, tot, best_obj


def make_scorer(tok, dist):
    if tok is None or not tok.strip():
        return None, []
    C = money_cands(tok)
    o = mdigits(tok)
    cache = {}

    def f(s):
        v = C.get(s)
        if v is None:
            v = cache.get(s)
            if v is None:
                v = min(6.0, dist(str(s).zfill(3), o)) if s > 0 else 6.0
                cache[s] = v
        return v
    targ = sorted([(v, c) for v, c in C.items() if c <= 1.0], key=lambda x: (x[1], x[0]))[:10]
    return f, targ


def comb(fs, ft, off):
    def f(s):
        v = fs(s) if fs else 0.0
        if ft:
            v += ft(off + s)
        return v
    return f


def recover(state, params):
    t0 = time.perf_counter()
    state['_t0'] = t0
    state['_rows'] = []
    state['output'] = {'items': []}
    text = (state.get('input') or {}).get('text', '') or ''
    try:
        order, sections, ttok, itok = parse_doc(text)
    except Exception:
        return state
    dist = make_dist()

    def Dm(c, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(c).zfill(3), obs))

    def Dq(q, obs):
        if obs is None:
            return 4.0
        return min(9.0, dist(str(q), obs))

    npcs = 0
    for sec in sections:
        for t, k in sec['toks']:
            if t and has_pcs(t):
                npcs += 1
    pcs = npcs >= 2
    secs = []
    for sec in sections:
        try:
            rows = align(sec['toks'], order, pcs)
        except Exception:
            rows = []
        rr = []
        for r in rows:
            tq, tu, ta = r.get('QTY'), r.get('UNIT'), r.get('AMOUNT')
            try:
                code = solve_code(r.get('CODE'))
            except Exception:
                code = 'AA00000'
            row = {'code': code, 'ct': r.get('CODE'), 'Q': qty_cands(tq), 'U': money_cands(tu),
                   'A': money_cands(ta), 'oq': digits_of(tq), 'ou': mdigits(tu), 'oa': mdigits(ta)}
            try:
                row['tr'] = row_cands(row, Dm, Dq)
            except Exception:
                row['tr'] = [[50.0, 1, 100, 100]]
            rr.append(row)
        fS, targ = make_scorer(sec['sub'], dist)
        secs.append({'rows': rr, 'fS': fS, 'targ': targ})

    results = [[[r['tr'][0] for r in s['rows']], 0, 0.0] for s in secs]

    def emit():
        items = []
        meta = []
        for s, res in zip(secs, results):
            for r, t in zip(s['rows'], res[0]):
                items.append({'code': r['code'], 'qty': int(t[1]), 'unit_cents': int(t[2])})
                meta.append({'ct': r['ct'], 'oq': r['oq'], 'ou': r['ou'], 'oa': r['oa'],
                             'q': int(t[1]), 'u': int(t[2]), 'a': int(t[3]), 'c': float(t[0])})
        state['output'] = {'items': items}
        state['_rows'] = meta
    emit()
    try:
        fT, Ttarg = make_scorer(ttok, dist)
        dl1 = t0 + 0.5
        for i, s in enumerate(secs):
            if len(secs) == 1:
                sc = comb(s['fS'], fT, 0)
                targ = list(s['targ']) + list(Ttarg)
            else:
                sc = comb(s['fS'], None, 0)
                targ = s['targ']
            ch, tt, obj = solve_section(s['rows'], sc, targ, dl1, Dm, Dq)
            results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
        dl2 = t0 + 0.7
        if fT and len(secs) > 1:
            for _ in range(3):
                if time.perf_counter() > dl2:
                    break
                grand = sum(r[1] for r in results)
                ct = fT(grand)
                if ct <= 0:
                    break
                best_gain = 1e-9
                best = None
                for i, s in enumerate(secs):
                    if time.perf_counter() > dl2 or not s['rows']:
                        continue
                    other = grand - results[i][1]
                    fS = s['fS']
                    sc = comb(fS, fT, other)
                    targ = list(s['targ']) + [(tv - other, c) for tv, c in Ttarg if tv - other > 0]
                    ch, tt, obj = solve_section(s['rows'], sc, targ, dl2, Dm, Dq)
                    old = results[i][2] + (fS(results[i][1]) if fS else 0.0) + ct
                    gain = old - obj
                    if gain > best_gain:
                        best_gain = gain
                        best = (i, ch, tt)
                if best is None:
                    break
                i, ch, tt = best
                results[i] = [ch, tt, sum(t[0] for t in ch)]
        emit()
    except Exception:
        pass
    return state


# ---------------- damage profile ----------------

def op_counts(orig, obs):
    n, m = len(orig), len(obs)
    INF = 1e9
    dp = [[None] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = (0.0, 0, 0, 0)

    def upd(i, j, cand):
        cur = dp[i][j]
        if cur is None or cand[0] < cur[0]:
            dp[i][j] = cand
    for i in range(n + 1):
        for j in range(m + 1):
            v = dp[i][j]
            if v is None:
                continue
            c, a, b, d = v
            if j < m:
                upd(i, j + 1, (c + 3.0, a, b, d))
            if i < n:
                ch = orig[i]
                upd(i + 1, j, (c + 1.0, a, b + 1, d))
                if j < m:
                    x = obs[j]
                    if x == ch:
                        upd(i + 1, j + 1, (c, a, b, d))
                    elif x in MIS.get(ch, ''):
                        upd(i + 1, j + 1, (c + 1.0, a + 1, b, d))
                    else:
                        upd(i + 1, j + 1, (c + 3.0, a, b, d))
                    if j + 1 < m and x == ch and obs[j + 1] == ch:
                        upd(i + 1, j + 2, (c + 1.0, a, b, d + 1))
    r = dp[n][m]
    return r if r is not None else (INF, 0, 0, 0)


def profile_damage(state, params):
    rows = state.get('_rows') or []
    N = 0
    cm = cl = cd = 0.0
    try:
        for r in rows:
            pairs = [(str(r['q']), r.get('oq')), (str(r['u']).zfill(3), r.get('ou')),
                     (str(r['a']).zfill(3), r.get('oa'))]
            for orig, obs in pairs:
                if obs is None or len(orig) > 14 or len(obs) > 16:
                    continue
                if orig == obs:
                    N += len(orig)
                    continue
                c, a, b, d = op_counts(orig, obs)
                if c > 4.0:
                    continue
                N += len(orig)
                cm += a
                cl += b
                cd += d
            ct = r.get('ct')
            if ct:
                L, dg = code_parts(ct)
                N += 5
                if len(dg) == 4:
                    cl += 1
                elif len(dg) == 3:
                    cl += 2
                elif len(dg) == 6:
                    cd += 1
                elif len(dg) == 7:
                    cd += 2
                elif len(dg) == 5 and not code_ok(L, dg):
                    cm += 0.7
                    cl += 0.15
                    cd += 0.15
    except Exception:
        pass
    den = N + 40.0
    pm = (cm + 0.4) / den
    pl = (cl + 0.4) / den
    pd = (cd + 0.4) / den
    s = pm + pl + pd
    if s > 0.5:
        pm, pl, pd = pm * 0.5 / s, pl * 0.5 / s, pd * 0.5 / s
    state['_profile'] = {'pm': pm, 'pl': pl, 'pd': pd}
    return state


# ---------------- probabilistic code repair ----------------

def fwd_prob(s, o, mask, pm, pl, pd, pk):
    m = len(o)
    f = [1.0] + [0.0] * m
    for c in s:
        mis = MIS[c]
        pmi = pm / len(mis)
        g = [0.0] * (m + 1)
        for j in range(m + 1):
            v = f[j]
            if v == 0.0:
                continue
            g[j] += v * pl
            if j < m:
                x = o[j]
                if x == c:
                    g[j + 1] += v * pk
                    if j + 1 < m and o[j + 1] == c:
                        g[j + 2] += v * pd
                elif x in mis:
                    lk = LOCKF if (j < len(mask) and mask[j] == '1') else 1.0
                    g[j + 1] += v * pmi * lk
        f = g
    return f[m]


def inv_step(s, target5):
    res = []
    n = len(s)
    if not target5 or n == 5:
        for i, ch in enumerate(s):
            for o in REV.get(ch, ''):
                res.append(s[:i] + o + s[i + 1:])
    if not target5 or n == 6:
        for i in range(n - 1):
            if s[i] == s[i + 1]:
                res.append(s[:i] + s[i + 1:])
    if not target5 or n == 4:
        for i in range(n + 1):
            for o in '0123456789':
                res.append(s[:i] + o + s[i:])
    return res


def code_candidates(L, d):
    out = set()
    if code_ok(L, d):
        out.add(d)
    l1 = set(inv_step(d, False))
    for s in l1:
        if len(s) == 5 and code_ok(L, s):
            out.add(s)
    for s in l1:
        if 4 <= len(s) <= 6:
            for t in inv_step(s, True):
                if code_ok(L, t):
                    out.add(t)
    return out


def repair_codes(state, params):
    try:
        t0 = state.get('_t0')
        start = time.perf_counter()
        deadline = (t0 + 0.92) if isinstance(t0, float) else (start + 0.2)
        if deadline < start + 0.05:
            deadline = start + 0.05
        prof = state.get('_profile') or {'pm': 0.02, 'pl': 0.02, 'pd': 0.02}
        pm, pl, pd = prof['pm'], prof['pl'], prof['pd']
        pk = max(0.3, 1.0 - pm - pl - pd)
        rows = state.get('_rows') or []
        items = state['output']['items']
        if len(rows) == len(items):
            for r, it in zip(rows, items):
                if time.perf_counter() > deadline:
                    break
                ct = r.get('ct')
                if not ct:
                    continue
                L, d, mask = code_parts_m(ct)
                if not (3 <= len(d) <= 7):
                    continue
                cands = code_candidates(L, d)
                if not cands:
                    continue
                best = None
                for s in sorted(cands):
                    p = fwd_prob(s, d, mask, pm, pl, pd, pk)
                    if best is None or p > best[0]:
                        best = (p, s)
                if best is not None and best[0] > 0:
                    it['code'] = L + best[1]
    except Exception:
        pass
    for k in ('_rows', '_profile', '_t0'):
        if k in state:
            del state[k]
    return state

import re
import time

LOOK_TO_DIGIT = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
                 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
DIGIT_TO_LETTER = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
MISREAD = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
           '6': '50', '7': '12', '8': '30', '9': '43'}
INV_MIS = {}
for _d, _outs in MISREAD.items():
    for _e in _outs:
        INV_MIS.setdefault(_e, []).append(_d)

C_LOOK = 0.2
C_SUB = 1.0
C_DEL = 1.1
C_INS = 1.25
C_MARK = 0.3
C_JUNKCH = 1.5

NAMES = ("CODE", "QTY", "UNIT", "AMOUNT")


# ---------------------------------------------------------------- layout
def detect_layout(lines):
    sep = None
    order = list(NAMES)
    for ln in lines:
        if ln.strip().startswith("COLUMNS"):
            body = ln.split(":", 1)[1] if ":" in ln else ln[len("COLUMNS"):]
            found = []
            for m in re.finditer(r"CODE|QTY|UNIT|AMOUNT", body):
                found.append((m.start(), m.end(), m.group(0)))
            if len(found) >= 2:
                between = body[found[0][1]:found[1][0]]
                if "|" in between:
                    sep = "|"
                elif ";" in between:
                    sep = ";"
                elif "\t" in between:
                    sep = "\t"
                elif "   " in between or len(between) >= 2:
                    sep = "sp"
            names = [f[2] for f in found]
            if len(names) == 4 and sorted(names) == sorted(NAMES):
                order = names
            break
    return sep, order


def split_line(ln, sep):
    if sep == "|":
        parts = ln.split("|")
    elif sep == ";":
        parts = ln.split(";")
    elif sep == "\t":
        parts = ln.split("\t")
    elif sep == "sp":
        parts = re.split(r" {2,}|\t", ln)
    else:
        parts = re.split(r"\s*\|\s*|;|\t| {2,}", ln)
    return [p.strip() for p in parts if p.strip() != ""]


TOKEN_RE = re.compile(r"^[0-9A-Zl.,']+$")


def token_ok(p):
    q = p
    if q.endswith("pcs"):
        q = q[:-3].strip()
    if q == "":
        return False
    return bool(TOKEN_RE.match(q)) and len(q) <= 16


def is_keyword(s):
    return (s.startswith("MANIFEST") or s.startswith("COLUMNS") or s.startswith("==")
            or s.startswith("SUBTOTAL") or s.startswith("TOTAL"))


def type_cost(tok, col):
    t = tok
    pcs = False
    if t.endswith("pcs"):
        pcs = True
        t = t[:-3].strip()
    has_mark = ("." in t) or ("," in t)
    if col == "CODE":
        if pcs or has_mark:
            return 4.0
        if 6 <= len(t) <= 8 and (t[0].isalpha() or t[1].isalpha()):
            return 0.0
        if 6 <= len(t) <= 8:
            return 1.5
        return 4.0
    if col == "QTY":
        if pcs:
            return 0.0
        if has_mark:
            return 4.0
        if len(t) <= 4:
            return 0.3
        return 3.0
    if pcs:
        return 4.0
    if has_mark:
        return 0.0
    if len(t) >= 6 and t[0].isalpha() and t[1].isalpha():
        return 4.0
    if len(t) >= 3:
        return 1.0
    return 3.0


def chunk_tokens(tokens, order):
    n = len(tokens)
    if n % 4 == 0:
        ok = True
        for i, t in enumerate(tokens):
            if type_cost(t, order[i % 4]) >= 3.0:
                ok = False
                break
        if ok:
            return [tokens[i:i + 4] for i in range(0, n, 4)]
    INF = 1e18
    SKIP_TOK = 5.0
    SKIP_SLOT = 5.0
    best = [[INF] * 4 for _ in range(n + 1)]
    back = [[None] * 4 for _ in range(n + 1)]
    best[0][0] = 0.0
    for i in range(n + 1):
        for j in range(4):
            c = best[i][j]
            if c >= INF:
                continue
            if j < 3:
                if c + SKIP_SLOT < best[i][j + 1]:
                    best[i][j + 1] = c + SKIP_SLOT
                    back[i][j + 1] = (i, j, "skipslot")
            if i < n:
                nj = (j + 1) % 4
                nc = c + type_cost(tokens[i], order[j])
                if nc < best[i + 1][nj]:
                    best[i + 1][nj] = nc
                    back[i + 1][nj] = (i, j, "assign")
                nc = c + SKIP_TOK
                if nc < best[i + 1][j]:
                    best[i + 1][j] = nc
                    back[i + 1][j] = (i, j, "skiptok")
    endj = 0
    if best[n][0] >= INF:
        endj = min(range(4), key=lambda j: best[n][j])
    ops = []
    i, j = n, endj
    while back[i][j] is not None:
        pi, pj, op = back[i][j]
        ops.append((pi, pj, op))
        i, j = pi, pj
    ops.reverse()
    rows = []
    cur = [None] * 4
    for pi, pj, op in ops:
        if op == "assign":
            cur[pj] = tokens[pi]
            if pj == 3:
                rows.append(cur)
                cur = [None] * 4
        elif op == "skipslot":
            cur[pj] = None
            if pj == 3:
                rows.append(cur)
                cur = [None] * 4
    if any(x is not None for x in cur):
        rows.append(cur)
    return rows


def parse_layout(state, params):
    inp = state.get("input")
    text = inp.get("text", "") if isinstance(inp, dict) else ""
    if not isinstance(text, str):
        text = ""
    lines = text.replace("\r", "").split("\n")
    sep, order = detect_layout(lines)
    sections = []
    cur = None
    for ln in lines:
        s = ln.strip()
        if s == "":
            continue
        if s.startswith("==") and "SECTION" in s:
            cur = []
            sections.append(cur)
            continue
        if is_keyword(s):
            continue
        parts = split_line(ln, sep)
        if not parts or not all(token_ok(p) for p in parts):
            continue
        if cur is None:
            cur = []
            sections.append(cur)
        cur.extend(parts)
    rows = []
    for toks in sections:
        for r in chunk_tokens(toks, order):
            rows.append(r)
    state["layout"] = {"order": order, "rows": rows}
    return state


# ---------------------------------------------------------------- candidates
def normalize_digits(s):
    out = []
    cost = 0.0
    for ch in s:
        if ch.isdigit():
            out.append(ch)
        elif ch in LOOK_TO_DIGIT:
            out.append(LOOK_TO_DIGIT[ch])
            cost += C_LOOK
        else:
            cost += C_JUNKCH
    return "".join(out), cost


def edits1(s):
    res = {}
    n = len(s)
    for i in range(n):
        ch = s[i]
        if not ch.isdigit():
            continue
        for d in INV_MIS.get(ch, ()):
            t = s[:i] + d + s[i + 1:]
            if res.get(t, 99) > C_SUB:
                res[t] = C_SUB
        if i + 1 < n and s[i + 1] == ch:
            t = s[:i] + s[i + 1:]
            if res.get(t, 99) > C_DEL:
                res[t] = C_DEL
    for i in range(n + 1):
        for d in "0123456789":
            t = s[:i] + d + s[i:]
            if res.get(t, 99) > C_INS:
                res[t] = C_INS
    return res


def expand(base, level):
    allc = dict(base)
    frontier = dict(base)
    for _ in range(level):
        nf = {}
        for s, c in frontier.items():
            for t, ec in edits1(s).items():
                nc = c + ec
                if nc < allc.get(t, 99) and nc < nf.get(t, 99):
                    nf[t] = nc
        for t, c in nf.items():
            if c < allc.get(t, 99):
                allc[t] = c
        frontier = nf
    return allc


def good_int(s):
    return s != "" and (s == "0" or s[0] != "0")


def money_base(tok):
    t = tok.replace("'", "").replace(" ", "")
    idx = max(t.rfind("."), t.rfind(","))
    if idx >= 0:
        ip, ic = normalize_digits(t[:idx])
        fp, fc = normalize_digits(t[idx + 1:])
        return ip + "." + fp, ic + fc, False
    d, c = normalize_digits(t)
    return d, c + C_MARK, True


def money_cands(tok, level):
    s, bc, lost = money_base(tok)
    strs = expand({s: bc}, level)
    out = {}
    for st, c in strs.items():
        if "." in st:
            ip, fp = st.split(".", 1)
            if len(fp) != 2 or not good_int(ip):
                continue
            v = int(ip) * 100 + int(fp)
        else:
            if len(st) < 3:
                continue
            ip = st[:-2]
            if not good_int(ip):
                continue
            v = int(st)
        if v <= 0:
            continue
        if c < out.get(v, 99):
            out[v] = c
    return out


def qty_cands(tok, level):
    t = tok
    if t.endswith("pcs"):
        t = t[:-3]
    t = t.replace(" ", "")
    s, bc = normalize_digits(t)
    strs = expand({s: bc}, level)
    out = {}
    for st, c in strs.items():
        if not st or st[0] == "0" or len(st) > 3:
            continue
        v = int(st)
        if 1 <= v <= 500 and c < out.get(v, 99):
            out[v] = c
    return out


def check_ok(letters, digs):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    d = [int(x) for x in digs]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def solve_code(tok):
    if tok is None:
        return ""
    t = tok.replace(" ", "")
    if len(t) < 2:
        return t
    letters = []
    for ch in t[:2]:
        if ch.isalpha():
            letters.append("I" if ch == "l" else ch.upper())
        else:
            letters.append(DIGIT_TO_LETTER.get(ch, "A"))
    L = "".join(letters)
    if not ("A" <= L[0] <= "Z" and "A" <= L[1] <= "Z"):
        L = "AA"
    rest, bc = normalize_digits(t[2:])
    if len(rest) == 5 and check_ok(L, rest):
        return L + rest
    for level in (1, 2):
        strs = expand({rest: bc}, level)
        best = None
        bestc = 99
        for st in sorted(strs):
            c = strs[st]
            if len(st) == 5 and c < bestc and check_ok(L, st):
                best, bestc = st, c
        if best is not None:
            return L + best
    r = (rest + "00000")[:5]
    return L + r


def best_of(d):
    if not d:
        return None, 99
    k = min(d, key=lambda v: (d[v], v))
    return k, d[k]


def solve_numbers(qtok, utok, atok, deadline):
    if qtok is None or utok is None or atok is None:
        q0 = best_of(qty_cands(qtok, 1))[0] if qtok else None
        u0 = best_of(money_cands(utok, 1))[0] if utok else None
        a0 = best_of(money_cands(atok, 1))[0] if atok else None
        if q0 is None and u0 and a0 and a0 % u0 == 0 and 1 <= a0 // u0 <= 500:
            q0 = a0 // u0
        if u0 is None and q0 and a0 and a0 % q0 == 0:
            u0 = a0 // q0
        return (q0 or 1), (u0 or 0)
    Q1 = qty_cands(qtok, 1)
    U1 = money_cands(utok, 1)
    A1 = money_cands(atok, 1)
    best = None
    bestc = 99.0
    Ql = sorted(Q1.items(), key=lambda x: (x[1], x[0]))
    Ul = sorted(U1.items(), key=lambda x: (x[1], x[0]))
    for q, cq in Ql:
        if cq >= bestc:
            break
        for u, cu in Ul:
            c = cq + cu
            if c >= bestc:
                break
            ca = A1.get(q * u)
            if ca is not None and c + ca < bestc:
                bestc = c + ca
                best = (q, u)
    if (best is None or bestc >= 2.0) and time.perf_counter() < deadline:
        Q2 = qty_cands(qtok, 2)
        Q2l = sorted(Q2.items(), key=lambda x: (x[1], x[0]))
        for q, cq in Q2l:
            if cq >= bestc:
                break
            for u, cu in Ul:
                c = cq + cu
                if c >= bestc:
                    break
                ca = A1.get(q * u)
                if ca is not None and c + ca < bestc:
                    bestc = c + ca
                    best = (q, u)
        if time.perf_counter() < deadline:
            A2 = money_cands(atok, 2)
            for q, cq in Ql:
                if cq >= bestc:
                    break
                for u, cu in Ul:
                    c = cq + cu
                    if c >= bestc:
                        break
                    ca = A2.get(q * u)
                    if ca is not None and c + ca < bestc:
                        bestc = c + ca
                        best = (q, u)
        if time.perf_counter() < deadline:
            U2 = money_cands(utok, 2)
            Al = sorted(A1.items(), key=lambda x: (x[1], x[0]))
            for q, cq in Ql:
                if cq >= bestc:
                    break
                for a, ca in Al:
                    c = cq + ca
                    if c >= bestc:
                        break
                    if a % q:
                        continue
                    cu = U2.get(a // q)
                    if cu is not None and c + cu < bestc:
                        bestc = c + cu
                        best = (q, a // q)
    if best is not None:
        return best
    q0, cq = best_of(Q1)
    u0, cu = best_of(U1)
    a0, ca = best_of(A1)
    if q0 is None:
        q0 = 1
    if u0 is None:
        u0 = a0 // q0 if a0 else 0
    return q0, u0


def solve_rows(state, params):
    t0 = time.perf_counter()
    deadline = t0 + 0.7
    lay = state.get("layout", {})
    order = lay.get("order", list(NAMES))
    items = []
    for r in lay.get("rows", []):
        f = {}
        for i, name in enumerate(order):
            f[name] = r[i] if i < len(r) else None
        try:
            code = solve_code(f["CODE"])
        except Exception:
            code = ""
        try:
            q, u = solve_numbers(f["QTY"], f["UNIT"], f["AMOUNT"], deadline)
        except Exception:
            q, u = 1, 0
        items.append({"code": code, "qty": int(q), "unit_cents": int(u)})
    state["output"] = {"items": items}
    return state

import re
import time

L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
INV = {'0': '68', '1': '47', '2': '7', '3': '589', '4': '19', '5': '6',
       '6': '05', '7': '12', '8': '03', '9': '34'}
C_FIX = 0.2
C_MIS = 1.0
C_DEL = 1.1
C_INS = 1.3
C_MARK = 0.3
BIG = 25.0


def _digits(s):
    out = []
    c = 0.0
    for ch in s:
        if ch.isdigit():
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
            c += C_FIX
        else:
            return None, 0.0
    return ''.join(out), c


def _edits(d, allow_ins=True):
    res = [(d, 0.0)]
    n = len(d)
    for i in range(n):
        for o in INV.get(d[i], ''):
            res.append((d[:i] + o + d[i + 1:], C_MIS))
    for i in range(1, n):
        if d[i] == d[i - 1]:
            res.append((d[:i] + d[i + 1:], C_DEL))
    if allow_ins:
        for i in range(n + 1):
            for x in '0123456789':
                res.append((d[:i] + x + d[i:], C_INS))
    return res


def _code_ok(c):
    p1 = ord(c[0]) - 64
    p2 = ord(c[1]) - 64
    d = [int(x) for x in c[2:]]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def code_cands(tok):
    s = tok.strip().replace(' ', '')
    if len(s) < 5 or len(s) > 9:
        return None
    lc = 0.0
    lets = ''
    for ch in s[:2]:
        if 'A' <= ch <= 'Z':
            lets += ch
        elif ch in D2L:
            lets += D2L[ch]
            lc += C_FIX
        else:
            return None
    dg, c = _digits(s[2:])
    if dg is None:
        return None
    lc += c
    best = {}
    for d2, ec in _edits(dg, allow_ins=(len(dg) < 5)):
        if len(d2) != 5:
            continue
        code = lets + d2
        if _code_ok(code):
            cc = lc + ec
            if code not in best or cc < best[code]:
                best[code] = cc
    if best:
        return sorted(best.items(), key=lambda kv: (kv[1], kv[0]))
    if len(dg) == 5:
        return [(lets + dg, lc + 3.0)]
    if len(dg) > 5:
        return [(lets + dg[:5], lc + 4.0)]
    return [(lets + (dg + '00000')[:5], lc + 4.0)]


def qty_cands(tok):
    s = re.sub(r'\s*pcs\s*$', '', tok.strip())
    s = s.replace(' ', '')
    if not s or len(s) > 5:
        return None
    dg, c = _digits(s)
    if dg is None:
        return None
    out = {}
    for d2, ec in _edits(dg):
        if not d2 or (len(d2) > 1 and d2[0] == '0'):
            continue
        v = int(d2)
        if 1 <= v <= 500:
            cc = c + ec
            if v not in out or cc < out[v]:
                out[v] = cc
    return out if out else None


def money_cands(tok):
    s = tok.strip().replace("'", '').replace(' ', '')
    if not s or len(s) > 14:
        return None
    marks = [i for i, ch in enumerate(s) if ch in '.,']
    out = {}

    def add(intp, frac, cost):
        if len(frac) != 2 or not intp:
            return
        if len(intp) > 1 and intp[0] == '0':
            return
        v = int(intp + frac)
        if v <= 0:
            return
        if v not in out or cost < out[v]:
            out[v] = cost

    if len(marks) > 1:
        return None
    if len(marks) == 1:
        m = marks[0]
        ip, c1 = _digits(s[:m])
        fp, c2 = _digits(s[m + 1:])
        if ip is None or fp is None:
            return None
        c = c1 + c2
        if len(fp) == 2:
            for i2, ec in _edits(ip):
                add(i2, fp, c + ec)
            for f2, ec in _edits(fp, allow_ins=False):
                if ec > 0:
                    add(ip, f2, c + ec)
        else:
            for f2, ec in _edits(fp, allow_ins=(len(fp) < 2)):
                add(ip, f2, c + ec)
    else:
        dg, c = _digits(s)
        if dg is None or len(dg) < 2:
            return None
        c += C_MARK
        for d2, ec in _edits(dg):
            if len(d2) >= 3:
                add(d2[:-2], d2[-2:], c + ec)
    return out if out else None


def _best(d):
    return min(d.items(), key=lambda kv: (kv[1], kv[0]))


def _top(d):
    m = min(d.values())
    return [(k, c) for k, c in d.items() if c <= m + 0.9]


def _joint(Q, U, A):
    best = None

    def consider(q, u, cost):
        nonlocal best
        key = (cost, q, u)
        if best is None or key < best:
            best = key

    Qt = _top(Q)
    Ut = _top(U)
    At = _top(A)
    for q, cq in Q.items():
        for u, cu in Ut:
            a = q * u
            if a in A:
                consider(q, u, cq + cu + A[a])
        for a, ca in At:
            if a % q == 0:
                u = a // q
                if u in U:
                    consider(q, u, cq + U[u] + ca)
    for u, cu in U.items():
        for q, cq in Qt:
            a = q * u
            if a in A:
                consider(q, u, cq + cu + A[a])
    return best


def parse_layout(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.split('\n')
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    ci = None
    for i, ln in enumerate(lines):
        if 'COLUMNS' in ln:
            ci = i
            body = ln.split('COLUMNS', 1)[1].lstrip(':').strip()
            pos = []
            for name in order:
                m = re.search(r'\b' + name + r'\b', body)
                if m:
                    pos.append((m.start(), name, m.end()))
            pos.sort()
            if len(pos) == 4:
                order = [p[1] for p in pos]
                between = body[pos[0][2]:pos[1][0]]
                if '|' in between:
                    sep = '|'
                elif ';' in between:
                    sep = ';'
                elif '\t' in between:
                    sep = '\t'
                else:
                    sep = '   '
            break
    if ci is None:
        ci = 0
        for i, ln in enumerate(lines):
            if ln.startswith('MANIFEST'):
                ci = i
                break
    ti = len(lines)
    for i in range(len(lines) - 1, ci, -1):
        if re.match(r'^\s*TOTAL\b', lines[i]):
            ti = i
            break
    toks = []
    lspans = []
    for li in range(ci + 1, ti):
        ln = lines[li]
        st = ln.strip()
        if not st:
            continue
        if re.match(r'^=+\s*SECTION\b', st) or re.match(r'^SECTION\b', st):
            toks.append({'s': st, 'k': 'sec', 'l': len(lspans)})
            lspans.append([len(toks) - 1, len(toks), 'm'])
            continue
        if re.match(r'^SUBTOTAL\b', st):
            toks.append({'s': st, 'k': 'sub', 'l': len(lspans)})
            lspans.append([len(toks) - 1, len(toks), 'm'])
            continue
        if sep == '|':
            parts = st.split('|')
        elif sep == ';':
            parts = st.split(';')
        elif sep == '\t':
            parts = st.split('\t')
            if len(parts) == 1:
                parts = re.split(r'\s{3,}', st)
        else:
            parts = re.split(r'\s{2,}|\t', st)
        parts = [p.strip() for p in parts if p.strip()]
        if not parts:
            continue
        a = len(toks)
        for p in parts:
            toks.append({'s': p, 'k': 'f', 'l': len(lspans)})
        lspans.append([a, len(toks), 'f'])
    state['order'] = order
    state['tokens'] = toks
    state['lines'] = lspans
    return state


def viterbi(state, params):
    t0 = time.perf_counter()
    order = state['order']
    toks = state['tokens']
    lines = state['lines']
    T = len(toks)
    ftype = {'CODE': 'c', 'QTY': 'q', 'UNIT': 'm', 'AMOUNT': 'm'}
    fcache = {}

    def fc(i, t):
        key = (i, t)
        if key not in fcache:
            s = toks[i]['s']
            if t == 'c':
                r = code_cands(s)
            elif t == 'q':
                r = qty_cands(s)
            else:
                r = money_cands(s)
            fcache[key] = r
        return fcache[key]

    junky = []
    for a, b, k in lines:
        if k != 'f':
            junky.append(False)
            continue
        ok = True
        for i in range(a, b):
            if fc(i, 'c') is not None or fc(i, 'q') is not None or fc(i, 'm') is not None:
                ok = False
                break
        junky.append(ok)
    jcost = [1.0 if j else 12.0 for j in junky]
    TOK_SKIP = 5.0
    LAY = 0.3
    rcache = {}

    def row_score(idx):
        if idx in rcache:
            return rcache[idx]
        f = {}
        for name, i in zip(order, idx):
            f[name] = fc(i, ftype[name])
        if any(v is None for v in f.values()):
            res = (BIG, None)
            rcache[idx] = res
            return res
        code, ccost = f['CODE'][0]
        Q, U, A = f['QTY'], f['UNIT'], f['AMOUNT']
        if time.perf_counter() - t0 < 0.7:
            j = _joint(Q, U, A)
        else:
            j = None
        if j is not None:
            cost, q, u = j
            res = (ccost + cost, [code, q, u])
        else:
            q, cq = _best(Q)
            u, cu = _best(U)
            a, ca = _best(A)
            res = (ccost + cq + cu + ca + 4.0, [code, q, u])
        rcache[idx] = res
        return res

    INF = float('inf')
    dp = [INF] * (T + 1)
    bp = [None] * (T + 1)
    dp[0] = 0.0
    linestart = set(sp[0] for sp in lines)
    nl = len(lines)

    def relax(j, c, b):
        if c < dp[j] - 1e-12:
            dp[j] = c
            bp[j] = b

    for i in range(T):
        if dp[i] == INF:
            continue
        base = dp[i]
        tk = toks[i]
        if tk['k'] != 'f':
            relax(i + 1, base, ('m', i))
            continue
        relax(i + 1, base + TOK_SKIP, ('s', i))
        li = tk['l']
        if i == lines[li][0]:
            relax(lines[li][1], base + jcost[li], ('L', i))
        stack = [([i], LAY if i not in linestart else 0.0)]
        while stack:
            picks, lc = stack.pop()
            if len(picks) == 4:
                sc, vals = row_score(tuple(picks))
                if vals is None:
                    continue
                relax(picks[-1] + 1, base + lc + sc, ('r', i, picks, vals))
                continue
            p = picks[-1]
            cl = toks[p]['l']
            if p + 1 < lines[cl][1]:
                stack.append((picks + [p + 1], lc))
                continue
            nxt = cl + 1
            if nxt < nl and lines[nxt][2] == 'f':
                stack.append((picks + [lines[nxt][0]], lc + LAY))
                if junky[nxt] and nxt + 1 < nl and lines[nxt + 1][2] == 'f':
                    stack.append((picks + [lines[nxt + 1][0]], lc + LAY + jcost[nxt]))
    rows = []
    j = T
    while j > 0 and bp[j] is not None:
        b = bp[j]
        if b[0] == 'r':
            rows.append(b[3])
        j = b[1]
    rows.reverse()
    items = []
    for code, q, u in rows:
        items.append({'code': code, 'qty': int(q), 'unit_cents': int(u)})
    state['output'] = {'items': items}
    return state


def run(state, params):
    try:
        state = parse_layout(state, params)
        state = viterbi(state, params)
    except Exception:
        state['output'] = {'items': []}
    for k in ('tokens', 'lines', 'order'):
        state.pop(k, None)
    if 'output' not in state:
        state['output'] = {'items': []}
    return state

import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INV_MIS = {}
for _o, _ss in MIS.items():
    for _s in _ss:
        INV_MIS[_s] = INV_MIS.get(_s, '') + _o
D2LSHOW = {'0': 'Oo', '1': 'lIi', '5': 'Ss', '8': 'B', '2': 'Zz', '6': 'G'}
L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
LET2DIG = {'O': '0', 'I': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6'}
DIG2LET = {v: k for k, v in LET2DIG.items()}
DIGITS = '0123456789'
SUBCAP = 4.0
TOTCAP = 4.0


def _subc(t, s):
    if t == s:
        return 0.0
    if t in DIGITS:
        if s in D2LSHOW.get(t, ''):
            return 1.0
        if s in MIS[t]:
            return 1.0
        if s in DIGITS:
            return 3.0
        return 4.0
    if t.isalpha():
        if LET2DIG.get(t) == s:
            return 1.0
        return 4.0
    if t in '.,' and s in '.,':
        return 2.0
    return 4.0


def dist(S, T):
    """Weighted channel cost of shown string S given original string T."""
    n = len(T)
    m = len(S)
    INF = 99.0
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            v = row[j]
            if v >= INF:
                continue
            if j < m and row[j + 1] > v + 3.0:
                row[j + 1] = v + 3.0
            if i < n:
                t = T[i]
                nxt = dp[i + 1]
                if t in DIGITS or t in '.,':
                    lc = 1.0
                elif t == "'":
                    lc = 1.5
                else:
                    lc = 3.0
                if nxt[j] > v + lc:
                    nxt[j] = v + lc
                if j < m:
                    c = v + _subc(t, S[j])
                    if nxt[j + 1] > c:
                        nxt[j + 1] = c
                    if j + 1 < m and t in DIGITS and S[j] == t and S[j + 1] == t:
                        if nxt[j + 2] > v + 1.0:
                            nxt[j + 2] = v + 1.0
    return dp[n][m]


def fmt_money(c, mark, grouped):
    ip = c // 100
    fp = c % 100
    s = str(ip)
    if grouped and len(s) > 3:
        parts = []
        while len(s) > 3:
            parts.append(s[-3:])
            s = s[:-3]
        parts.append(s)
        s = "'".join(reversed(parts))
    return s + mark + ('%02d' % fp)


def strip_pcs(tok):
    return re.sub(r'\s*pcs\s*$', '', tok.strip()).strip()


def normalize_num(tok, money):
    base = 0
    out = []
    for ch in tok:
        if ch in DIGITS:
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
            base += 1
        elif ch in '.,':
            if money:
                if 'M' in out:
                    base += 2
                else:
                    out.append('M')
            else:
                base += 2
        elif ch == "'" or ch == ' ':
            continue
        else:
            base += 2
    return tuple(out), base


def neighbors(s):
    res = set()
    L = len(s)
    for i in range(L):
        ch = s[i]
        if ch == 'M':
            continue
        for o in INV_MIS.get(ch, ''):
            res.add(s[:i] + (o,) + s[i + 1:])
        if i > 0 and s[i - 1] == ch:
            res.add(s[:i] + s[i + 1:])
    for i in range(L + 1):
        for d in DIGITS:
            res.add(s[:i] + (d,) + s[i:])
    return res


def eval_num(s, money):
    if money:
        if 'M' in s:
            k = s.index('M')
            ip = s[:k]
            fp = s[k + 1:]
            if len(fp) != 2 or len(ip) < 1:
                return None
            if len(ip) > 1 and ip[0] == '0':
                return None
            return int(''.join(ip) + ''.join(fp)), 0
        if len(s) < 3:
            return None
        ip = s[:-2]
        if len(ip) > 1 and ip[0] == '0':
            return None
        return int(''.join(s)), 1
    else:
        if len(s) < 1 or len(s) > 3:
            return None
        if s[0] == '0':
            return None
        v = int(''.join(s))
        if v < 1 or v > 500:
            return None
        return v, 0


def gen_num(tok, money, maxedits):
    start, base = normalize_num(tok, money)
    seen = {start: 0}
    frontier = [start]
    for lev in range(1, maxedits + 1):
        nf = []
        for s in frontier:
            for t in neighbors(s):
                if t not in seen:
                    seen[t] = lev
                    nf.append(t)
        frontier = nf
    out = {}
    for s, e in seen.items():
        r = eval_num(s, money)
        if r is None:
            continue
        v, x = r
        c = base + e + x
        if v not in out or out[v] > c:
            out[v] = c
    return out


def code_ok(c):
    if len(c) != 7:
        return False
    a, b = c[0], c[1]
    if not ('A' <= a <= 'Z' and 'A' <= b <= 'Z'):
        return False
    ds = c[2:]
    if not ds.isdigit():
        return False
    d = [int(x) for x in ds]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + ord(a) - 64 + ord(b) - 64) % 10 == d[4]


def fix_code(tok):
    s = re.sub(r'\s', '', tok)
    if len(s) < 2:
        s = (s + 'XX')[:2]
    lets = []
    base = 0
    for ch in s[:2]:
        if 'A' <= ch <= 'Z':
            lets.append([(ch, 0)])
        elif ch in DIG2LET:
            lets.append([(DIG2LET[ch], 1)])
        elif ch.isalpha():
            lets.append([(ch.upper(), 1)])
        else:
            lets.append([(chr(65 + k), 2) for k in range(26)])
    r = []
    for ch in s[2:]:
        if ch in DIGITS:
            r.append(ch)
        elif ch in L2D:
            r.append(L2D[ch])
            base += 1
        else:
            base += 2
    start = tuple(r)
    seen = {start: 0}
    frontier = [start]
    best = None
    for lev in range(0, 3):
        if lev > 0:
            nf = []
            for x in frontier:
                for t in neighbors(x):
                    if t not in seen:
                        seen[t] = lev
                        nf.append(t)
            frontier = nf
        cands = []
        for x in frontier:
            if len(x) != 5:
                continue
            ds = ''.join(x)
            for l1, c1 in lets[0]:
                for l2, c2 in lets[1]:
                    c = l1 + l2 + ds
                    if code_ok(c):
                        cands.append((base + lev + c1 + c2, c))
        if cands:
            cands.sort()
            best = cands[0]
            break
    if best is not None:
        return best[1]
    ds = ''.join(start)
    ds = (ds + '00000')[:5]
    return lets[0][0][0] + lets[1][0][0] + ds


KEY_RE = re.compile(r'\b(CODE|QTY|UNIT|AMOUNT)\b')
CODEISH = re.compile(r"^[A-Za-z0-9]{2}[0-9OolIiSsBZzG]{3,8}$")
NUMISH = re.compile(r"^[0-9OolIiSsBZzG.,']*(\s*pcs)?$")


def parse_doc(text):
    lines = text.replace('\r', '').split('\n')
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        st = ln.strip()
        if st.startswith('COLUMNS'):
            ms = list(KEY_RE.finditer(ln))
            if len(ms) >= 2:
                names = [m.group(1) for m in ms]
                if len(names) == 4 and len(set(names)) == 4:
                    order = names
                sp = ln[ms[0].end():ms[1].start()]
                if '|' in sp:
                    sep = '|'
                elif ';' in sp:
                    sep = ';'
                elif '\t' in sp:
                    sep = '\t'
                else:
                    sep = '   '
            break

    def split_line(s):
        s = s.strip()
        if sep in ('|', ';'):
            s = s.strip(sep).strip()
            return [t.strip() for t in s.split(sep)]
        if sep == '\t':
            s = s.strip('\t ')
            return [t.strip() for t in s.split('\t')]
        return [t.strip() for t in s.split('   ')]

    def is_data(toks):
        if not [t for t in toks if t]:
            return False
        for t in toks:
            if not t:
                continue
            if CODEISH.match(t) or NUMISH.match(t):
                continue
            return False
        return True

    sections = []
    cur = None
    total_tok = None
    items_tok = None
    for ln in lines:
        st = ln.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^==\s*SECTION', st):
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', st)
            if m:
                total_tok = m.group(1).strip()
                items_tok = m.group(2).strip()
            else:
                total_tok = st[5:].strip()
            continue
        toks = split_line(st)
        if not is_data(toks):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
        cur['tokens'].extend(toks)
    out_secs = []
    for sec in sections:
        toks = sec['tokens']
        rows = []
        for i in range(0, len(toks), 4):
            grp = toks[i:i + 4]
            if len(grp) < 4:
                if not any(grp):
                    continue
                grp = grp + [''] * (4 - len(grp))
            rows.append(dict(zip(order, grp)))
        if rows or sec['sub'] is not None:
            out_secs.append({'rows': rows, 'sub': sec['sub']})
    return out_secs, total_tok, items_tok


def detect_style(secs, total_tok):
    toks = []
    for sec in secs:
        for r in sec['rows']:
            toks.append(r['UNIT'])
            toks.append(r['AMOUNT'])
        if sec['sub']:
            toks.append(sec['sub'])
    if total_tok:
        toks.append(total_tok)
    dot = sum(t.count('.') for t in toks)
    com = sum(t.count(',') for t in toks)
    mark = ',' if com > dot else '.'
    grouped = any("'" in t for t in toks)
    return mark, grouped


def row_candidates(row, ctx, K):
    mark = ctx['mark']
    grouped = ctx['grouped']
    qtok = strip_pcs(row['QTY'])
    utok = row['UNIT'].strip()
    atok = row['AMOUNT'].strip()
    Q = gen_num(qtok, False, 1)
    U = gen_num(utok, True, 1)
    A = gen_num(atok, True, 1)
    cands = {}

    def add(q, u, a, c):
        key = (q, u)
        if key not in cands or cands[key][0] > c:
            cands[key] = (c, q, u, a)

    for q, cq in Q.items():
        for u, cu in U.items():
            a = q * u
            ca = A.get(a)
            if ca is not None:
                add(q, u, a, cq + cu + ca)
    best = min([v[0] for v in cands.values()]) if cands else 99
    if best >= 2 and time.perf_counter() < ctx['deadline']:
        cache = {}

        def dmon(tok, v):
            k = ('m', tok, v)
            if k not in cache:
                cache[k] = dist(tok, fmt_money(v, mark, grouped))
            return cache[k]

        def dq(v):
            k = ('q', v)
            if k not in cache:
                cache[k] = dist(qtok, str(v))
            return cache[k]

        for lim in (0, 1):
            Q0 = [(q, c) for q, c in Q.items() if c <= lim]
            U0 = [(u, c) for u, c in U.items() if c <= lim]
            A0 = [(a, c) for a, c in A.items() if c <= lim]
            for q, cq in Q0:
                for u, cu in U0:
                    if cq + cu <= lim:
                        a = q * u
                        add(q, u, a, cq + cu + dmon(atok, a))
                for a, ca in A0:
                    if cq + ca <= lim and a > 0 and a % q == 0:
                        u = a // q
                        add(q, u, a, cq + ca + dmon(utok, u))
            for u, cu in U0:
                if u <= 0:
                    continue
                for a, ca in A0:
                    if cu + ca <= lim and a % u == 0:
                        q = a // u
                        if 1 <= q <= 500:
                            add(q, u, a, cu + ca + dq(q))
            best = min([v[0] for v in cands.values()]) if cands else 99
            if best < 3 or time.perf_counter() > ctx['deadline']:
                break
    if not cands:
        q = min(Q.items(), key=lambda x: (x[1], x[0]))[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: (x[1], x[0]))[0]
        elif A:
            a0 = min(A.items(), key=lambda x: (x[1], x[0]))[0]
            u = a0 // q
        else:
            u = 0
        add(q, u, q * u, 9.0)
    lst = sorted(cands.values(), key=lambda x: (x[0], x[1], x[2]))
    return lst[:K]


def section_search(rcands, subtok, ctx, B=400, M=40, DEV=6.0):
    states = {0: (0.0, ())}
    for cl in rcands:
        ns = {}
        for s, (c, path) in states.items():
            for ci, (rc, q, u, a) in enumerate(cl):
                t = s + a
                nc = c + rc
                if t not in ns or ns[t][0] > nc:
                    ns[t] = (nc, path + (ci,))
        if not ns:
            continue
        items = sorted(ns.items(), key=lambda x: x[1][0])
        bc = items[0][1][0]
        items = [it for it in items if it[1][0] <= bc + DEV][:B]
        states = dict(items)
    items = sorted(states.items(), key=lambda x: x[1][0])
    res = []
    if subtok is None:
        for s, (c, path) in items[:M]:
            res.append((c, s, path))
        return res
    S1 = gen_num(subtok, True, 1)
    mark = ctx['mark']
    grouped = ctx['grouped']
    for idx, (s, (c, path)) in enumerate(items):
        sc = S1.get(s)
        if sc is None:
            if idx < 40 and time.perf_counter() < ctx['deadline'] + 0.1:
                sc = dist(subtok, fmt_money(s, mark, grouped))
            else:
                sc = SUBCAP
        sc = min(sc, SUBCAP)
        res.append((c + sc, s, path))
    res.sort(key=lambda x: x[0])
    return res[:M]


def _solve_text(text, t0):
    secs, total_tok, items_tok = parse_doc(text)
    mark, grouped = detect_style(secs, total_tok)
    ctx = {'mark': mark, 'grouped': grouped, 'deadline': t0 + 0.5}
    all_rc = []
    codes = []
    for sec in secs:
        rcs = []
        cs = []
        for r in sec['rows']:
            rcs.append(row_candidates(r, ctx, 8))
            cs.append(fix_code(r['CODE']))
        all_rc.append(rcs)
        codes.append(cs)
    sec_res = []
    for si, sec in enumerate(secs):
        sec_res.append(section_search(all_rc[si], sec['sub'], ctx))
    states = {0: (0.0, ())}
    for si in range(len(sec_res)):
        res = sec_res[si]
        if not res:
            res = [(0.0, 0, ())]
            sec_res[si] = res
        ns = {}
        for s, (c, ch) in states.items():
            for k, (sc, ss, path) in enumerate(res):
                t = s + ss
                nc = c + sc
                if t not in ns or ns[t][0] > nc:
                    ns[t] = (nc, ch + (k,))
        items = sorted(ns.items(), key=lambda x: x[1][0])[:500]
        states = dict(items)
    items = sorted(states.items(), key=lambda x: x[1][0])
    best = None
    if total_tok and items:
        T1 = gen_num(total_tok, True, 1)
        for idx, (s, (c, ch)) in enumerate(items):
            tc = T1.get(s)
            if tc is None:
                if idx < 40 and time.perf_counter() < ctx['deadline'] + 0.2:
                    tc = dist(total_tok, fmt_money(s, mark, grouped))
                else:
                    tc = TOTCAP
            tc = min(tc, TOTCAP)
            v = c + tc
            if best is None or v < best[0]:
                best = (v, ch)
    elif items:
        best = (items[0][1][0], items[0][1][1])
    choice = best[1] if best else ()
    out = []
    for si in range(len(secs)):
        res = sec_res[si]
        if res and si < len(choice) and choice[si] < len(res):
            path = res[choice[si]][2]
        else:
            path = ()
        for ri in range(len(all_rc[si])):
            ci = path[ri] if ri < len(path) else 0
            cl = all_rc[si][ri]
            rc = cl[ci] if ci < len(cl) else cl[0]
            out.append({'code': codes[si][ri], 'qty': int(rc[1]), 'unit_cents': int(rc[2])})
    return out


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get('input', {}) or {}
    text = inp.get('text', '') or ''
    try:
        items = _solve_text(text, t0)
    except Exception:
        items = []
    state['output'] = {'items': items}
    return state

import re
import time

LOOK_D2L = {'0': 'O', '1': 'l', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
LOOK_L2D = {'O': '0', 'I': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6'}
MISREAD = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50',
           '7': '12', '8': '30', '9': '43'}
NORM_DIG = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8',
            'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
DIGITS = '0123456789'


def _sub_table():
    t = {}
    for d, l in LOOK_D2L.items():
        t[d + l] = 1.0
    for l, d in LOOK_L2D.items():
        t[l + d] = 1.0
    for d, ms in MISREAD.items():
        for m in ms:
            t[d + m] = 1.0
    return t


def _make_align():
    SUB = _sub_table()
    cache = {}

    def sub(a, b):
        if a == b:
            return 0.0
        c = SUB.get(a + b)
        if c is not None:
            return c
        if a.isdigit() and b.isdigit():
            return 3.0
        return 4.0

    def dele(a):
        if a.isdigit():
            return 1.2
        if a == '.' or a == ',':
            return 1.0
        return 4.0

    def align(t, o):
        key = (t, o)
        r = cache.get(key)
        if r is not None:
            return r
        if t == o:
            cache[key] = 0.0
            return 0.0
        m = len(o)
        prev = [0.0] * (m + 1)
        for j in range(1, m + 1):
            prev[j] = prev[j - 1] + 3.0
        for i in range(1, len(t) + 1):
            tc = t[i - 1]
            dc = dele(tc)
            cur = [prev[0] + dc] * (m + 1)
            for j in range(1, m + 1):
                oc = o[j - 1]
                b = prev[j - 1] + sub(tc, oc)
                x = prev[j] + dc
                if x < b:
                    b = x
                y = cur[j - 1] + (1.1 if oc == tc else 3.0)
                if y < b:
                    b = y
                cur[j] = b
            prev = cur
        r = prev[m]
        cache[key] = r
        return r

    return align


def segment(state, params):
    inp = state.get("input") or {}
    text = inp.get("text", "") or ""
    lines = text.split("\n")
    sep = ';'
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln.split('COLUMNS', 1)[1]
            names = re.findall(r'CODE|QTY|UNIT|AMOUNT', body)
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            mm = re.search(r'(CODE|QTY|UNIT|AMOUNT)(.*?)(CODE|QTY|UNIT|AMOUNT)', body)
            if mm:
                between = mm.group(2)
                if '|' in between:
                    sep = '|'
                elif '\t' in between:
                    sep = '\t'
                elif ';' in between:
                    sep = ';'
                elif '  ' in between:
                    sep = 'SP'
            break

    def split_line(ln):
        if sep == '|':
            parts = ln.split('|')
        elif sep == ';':
            parts = ln.split(';')
        elif sep == '\t':
            parts = ln.split('\t')
        else:
            parts = re.split(r' {2,}|\t', ln)
        return [p.strip() for p in parts if p.strip() != '']

    tokre = re.compile(r"^[A-Za-z0-9.,']+(\s*pcs)?$")
    sections = []
    cur = []
    total_obs = None
    items_obs = None
    allmoney = []
    for raw in lines:
        ln = raw.strip()
        if not ln:
            continue
        if ln.startswith('MANIFEST') or ln.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', ln):
            if cur:
                sections.append({"tokens": cur, "sub": None})
                cur = []
            continue
        if ln.startswith('SUBTOTAL'):
            v = ln[len('SUBTOTAL'):].strip()
            sections.append({"tokens": cur, "sub": v})
            allmoney.append(v)
            cur = []
            continue
        if ln.startswith('TOTAL'):
            mm = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', ln)
            if mm:
                total_obs = mm.group(1).strip()
                items_obs = mm.group(2).strip()
            else:
                total_obs = ln[5:].strip()
            allmoney.append(total_obs)
            continue
        toks = split_line(ln)
        if not toks:
            continue
        if not all(tokre.match(t) for t in toks):
            continue
        cur.extend(toks)
    if cur:
        sections.append({"tokens": cur, "sub": None})

    def tcost(tok, f):
        if f == 'CODE':
            if re.match(r'^[A-Z0-9]{2}[0-9A-Za-z]{4,6}$', tok) and re.search(r'[A-Z]', tok[:2]):
                return 0.0
            if 5 <= len(tok) <= 9 and re.search(r'[A-Z]', tok):
                return 1.0
            return 6.0
        if f == 'QTY':
            if 'pcs' in tok:
                return 0.0
            if re.match(r'^[0-9OlSBZG]{1,4}$', tok):
                return 0.0 if len(tok) <= 3 else 1.0
            return 4.0
        if re.search(r"[.,']", tok) and re.match(r"^[0-9OlSBZG.,']+$", tok):
            return 0.0
        if 'pcs' in tok:
            return 5.0
        if re.match(r'^[0-9OlSBZG]+$', tok):
            return 1.0 if len(tok) >= 3 else 2.0
        if re.search(r'[A-Z]', tok[:2]) and len(tok) >= 6:
            return 5.0
        return 3.0

    rows_by_sec = []
    for sec in sections:
        toks = sec["tokens"]
        n = len(toks)
        INF = 1e18
        dp = [[INF] * 4 for _ in range(n + 1)]
        bk = [[None] * 4 for _ in range(n + 1)]
        dp[0][0] = 0.0
        for i in range(n):
            for s in range(4):
                c = dp[i][s]
                if c >= INF:
                    continue
                nc = c + tcost(toks[i], order[s])
                ns = (s + 1) % 4
                if nc < dp[i + 1][ns]:
                    dp[i + 1][ns] = nc
                    bk[i + 1][ns] = (s, 1)
                nc = c + 5.0
                if nc < dp[i + 1][s]:
                    dp[i + 1][s] = nc
                    bk[i + 1][s] = (s, 0)
        rows = []
        if n and dp[n][0] < INF:
            assigned = []
            s = 0
            i = n
            while i > 0:
                ps, take = bk[i][s]
                if take:
                    assigned.append((i - 1, ps))
                s = ps
                i -= 1
            assigned.reverse()
            row = {}
            for idx, f in assigned:
                row[order[f]] = toks[idx]
                if f == 3:
                    rows.append([row.get('CODE', ''), row.get('QTY', ''), row.get('UNIT', ''),
                                 row.get('AMOUNT', '')])
                    row = {}
        else:
            for k in range(0, n - 3, 4):
                ch = toks[k:k + 4]
                row = {order[f]: ch[f] for f in range(4)}
                rows.append([row['CODE'], row['QTY'], row['UNIT'], row['AMOUNT']])
        rows_by_sec.append(rows)
        for r in rows:
            allmoney.append(r[2])
            allmoney.append(r[3])

    dot = sum(1 for t in allmoney if t and re.search(r'\.\d\d$', t))
    com = sum(1 for t in allmoney if t and re.search(r',\d\d$', t))
    mark = ',' if com > dot else '.'
    grouped = any(t and "'" in t for t in allmoney)
    state["seg"] = {
        "sections": [{"rows": rows_by_sec[i], "sub": sections[i]["sub"]} for i in range(len(sections))],
        "total": total_obs, "items": items_obs, "mark": mark, "grouped": grouped,
    }
    return state


def decode(state, params):
    t0 = time.process_time()
    seg = state.get("seg") or {"sections": [], "total": None, "mark": ".", "grouped": False}
    mark = seg["mark"]
    grouped = seg["grouped"]
    align = _make_align()

    def render(c):
        if c < 0:
            c = 0
        ip = str(c // 100)
        if grouped and len(ip) > 3:
            g = []
            while len(ip) > 3:
                g.append(ip[-3:])
                ip = ip[:-3]
            g.append(ip)
            ip = "'".join(reversed(g))
        return ip + mark + '%02d' % (c % 100)

    def parse_clean(s):
        if s is None:
            return None
        s2 = s.replace("'", '')
        if not re.match(r'^\d+' + re.escape(mark) + r'\d\d$', s2):
            return None
        v = int(s2.replace(mark, ''))
        if render(v) != s:
            return None
        return v

    def obs_qty(s):
        return re.sub(r'\s*pcs$', '', s or '').strip()

    def money_digits(o):
        d = ''.join(NORM_DIG.get(ch, ch) for ch in o)
        return ''.join(ch for ch in d if ch.isdigit())

    mcache = {}

    def money_cands(o):
        if o in mcache:
            return mcache[o]
        D = money_digits(o)
        vals = set()
        if D:
            vals.add(D)
            for i in range(len(D)):
                vals.add(D[:i] + D[i + 1:])
                for d in DIGITS:
                    if d != D[i]:
                        vals.add(D[:i] + d + D[i + 1:])
            for i in range(len(D) + 1):
                for d in DIGITS:
                    vals.add(D[:i] + d + D[i:])
        res = {}
        for v in vals:
            if not v or len(v) > 10:
                continue
            c = int(v)
            if c <= 0 or c in res:
                continue
            res[c] = align(render(c), o)
        lst = sorted(res.items(), key=lambda x: x[1])
        mcache[o] = lst
        return lst

    qcache = {}

    def qty_costs(o):
        if o in qcache:
            return qcache[o]
        lo = len(o)
        lst = []
        for q in range(1, 501):
            s = str(q)
            if abs(len(s) - lo) > 2:
                continue
            lst.append((align(s, o), q))
        if not lst:
            lst = [(9.0, q) for q in range(1, 501)]
        lst.sort()
        qcache[o] = lst
        return lst

    def checkd(code6):
        p1 = ord(code6[0]) - 64
        p2 = ord(code6[1]) - 64
        d = [int(x) for x in code6[2:6]]
        return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10

    def decode_code(o):
        if re.match(r'^[A-Z]{2}\d{5}$', o) and checkd(o[:6]) == int(o[6]):
            return o
        o2 = o if len(o) >= 2 else (o + 'AA')[:2]
        lopts = []
        for ch in o2[:2]:
            opts = []
            if 'A' <= ch <= 'Z':
                opts.append(ch)
            if ch in '018526':
                opts.append({'0': 'O', '1': 'I', '8': 'B', '5': 'S', '2': 'Z', '6': 'G'}[ch])
            if ch == 'l':
                opts.append('I')
            if 'a' <= ch <= 'z':
                opts.append(ch.upper())
            if not opts:
                opts = ['A']
            lopts.append(opts)
        letters_list = [a + b for a in lopts[0] for b in lopts[1]]
        D = money_digits(o2[2:])
        bases = set()
        if len(D) >= 4:
            b = D[:4]
            bases.add(b)
            for i in range(4):
                for d in DIGITS:
                    bases.add(b[:i] + d + b[i + 1:])
        for i in range(len(D)):
            s = D[:i] + D[i + 1:]
            if len(s) >= 4:
                bases.add(s[:4])
        if len(D) <= 5:
            for i in range(len(D) + 1):
                for d in DIGITS:
                    s = D[:i] + d + D[i:]
                    if len(s) >= 4:
                        bases.add(s[:4])
        if len(D) < 3:
            bases.add((D + '0000')[:4])
        best = None
        bc = 1e18
        for L in letters_list:
            for b in sorted(bases):
                c6 = L + b
                fc = c6 + str(checkd(c6))
                c = align(fc, o)
                if c < bc:
                    bc = c
                    best = fc
        return best if best else 'AA00000'

    def decode_row(r):
        code_o, q_o, u_o, a_o = r
        qo = obs_qty(q_o)
        code = decode_code(code_o)
        u0 = parse_clean(u_o)
        a0 = parse_clean(a_o)
        q0 = int(qo) if re.match(r'^\d{1,3}$', qo) else None
        if q0 is not None and 1 <= q0 <= 500 and u0 is not None and a0 is not None and q0 * u0 == a0:
            return code, [(0.0, q0, u0, a0)]
        qc = qty_costs(qo)
        uc = money_cands(u_o)
        ac = money_cands(a_o)
        ucd = dict(uc)
        acd = dict(ac)
        la = len(a_o)

        def cu(u):
            v = ucd.get(u)
            if v is None:
                v = align(render(u), u_o)
                ucd[u] = v
            return v

        def ca(a):
            v = acd.get(a)
            if v is None:
                v = align(render(a), a_o)
                acd[a] = v
            return v

        cands = {}
        best = [1e18]

        def add(c, q, u):
            key = (q, u)
            if key not in cands or cands[key] > c:
                cands[key] = c
            if c < best[0]:
                best[0] = c

        for c1, q in qc[:6]:
            for u, c2 in uc[:6]:
                add(c1 + c2 + ca(q * u), q, u)
        margin = 2.5
        tl = t0 + 0.8
        if ac and qc:
            for a, c1 in ac:
                if c1 + qc[0][0] > best[0] + margin:
                    break
                for c2, q in qc:
                    if c1 + c2 > best[0] + margin:
                        break
                    if a % q:
                        continue
                    u = a // q
                    c = c1 + c2 + cu(u)
                    if c <= best[0] + margin:
                        add(c, q, u)
                if time.process_time() > tl:
                    break
        if uc and qc:
            for u, c1 in uc:
                if c1 + qc[0][0] > best[0] + margin:
                    break
                for c2, q in qc:
                    if c1 + c2 > best[0] + margin:
                        break
                    a = q * u
                    if a not in acd:
                        lb = abs(len(render(a)) - la) * 1.0
                        if c1 + c2 + lb > best[0] + margin:
                            continue
                    c = c1 + c2 + ca(a)
                    if c <= best[0] + margin:
                        add(c, q, u)
                if time.process_time() > tl:
                    break
        lst = sorted(((c, q, u, q * u) for (q, u), c in cands.items() if c <= best[0] + margin),
                     key=lambda x: (x[0], abs(x[1] - (q0 or x[1])), x[1], x[2]))
        if not lst:
            q = q0 if q0 and 1 <= q0 <= 500 else 1
            u = u0 if u0 else 0
            lst = [(0.0, q, u, q * u)]
        return code, lst[:10]

    def quick_row(r):
        code_o, q_o, u_o, a_o = r
        qo = money_digits(obs_qty(q_o))
        q = int(qo[:3]) if qo else 1
        q = min(max(q, 1), 500)
        D = money_digits(u_o)
        u = int(D[:10]) if D else 0
        cd = money_digits(code_o[2:])
        code = (code_o[:2].upper() + (cd + '00000')[:5]) if len(code_o) >= 2 else 'AA00000'
        return code, [(0.0, q, u, q * u)]

    secs = []
    for sec in seg["sections"]:
        rows = []
        for r in sec["rows"]:
            if time.process_time() - t0 > 0.75:
                rows.append(quick_row(r))
            else:
                rows.append(decode_row(r))
        secs.append(rows)

    choice = [[0] * len(rows) for rows in secs]

    def sub_cost(si, s):
        o = seg["sections"][si]["sub"]
        if not o:
            return 0.0
        return min(align(render(s), o), 6.0)

    def tot_cost(t):
        o = seg.get("total")
        if not o:
            return 0.0
        return min(align(render(t), o), 6.0)

    sums = [sum(secs[si][k][1][0][3] for k in range(len(secs[si]))) for si in range(len(secs))]
    for _ in range(3):
        improved = False
        if time.process_time() - t0 > 0.9:
            break
        for si in range(len(secs)):
            for k in range(len(secs[si])):
                alts = secs[si][k][1]
                if len(alts) < 2:
                    continue
                curc = alts[choice[si][k]]
                base_tot = sum(sums)
                bo = curc[0] + sub_cost(si, sums[si]) + tot_cost(base_tot)
                bj = choice[si][k]
                for j, alt in enumerate(alts):
                    if j == choice[si][k]:
                        continue
                    ns = sums[si] - curc[3] + alt[3]
                    nt = base_tot - curc[3] + alt[3]
                    ob = alt[0] + sub_cost(si, ns) + tot_cost(nt)
                    if ob < bo - 1e-9:
                        bo = ob
                        bj = j
                if bj != choice[si][k]:
                    sums[si] = sums[si] - curc[3] + alts[bj][3]
                    choice[si][k] = bj
                    improved = True
        if not improved:
            break

    items = []
    for si in range(len(secs)):
        for k, (code, alts) in enumerate(secs[si]):
            c, q, u, a = alts[choice[si][k]]
            items.append({"code": str(code), "qty": int(q), "unit_cents": int(u)})
    state["output"] = {"items": items}
    return state

import re
import time

L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
       'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
DIG2LET = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
INV_MIS = {}
for _d, _outs in MIS.items():
    for _e in _outs:
        INV_MIS.setdefault(_e, []).append(_d)
DIGITS = '0123456789'
C_LOOK = 0.2
C_SUB = 1.0
C_DEL = 1.1
C_INS = 1.25
C_MARK = 0.3
C_JUNK = 1.5
C_OTHER = 2.5
C_EXTRA = 3.0
SUBCAP = 3.0
TOTCAP = 3.0
NAMES = ('CODE', 'QTY', 'UNIT', 'AMOUNT')
KEY_RE = re.compile(r'\b(CODE|QTY|UNIT|AMOUNT)\b')
CODEISH = re.compile(r"^[A-Za-z0-9]{2}[0-9OolIiSsBZzG]{3,8}$")
NUMISH = re.compile(r"^[0-9OolIiSsBZzG.,']+(\s*pcs)?$")


# ------------------------------------------------------------ layout
def parse_doc(text):
    lines = text.replace('\r', '').split('\n')
    order = list(NAMES)
    sep = ';'
    for ln in lines:
        st = ln.strip()
        if st.startswith('COLUMNS'):
            ms = list(KEY_RE.finditer(ln))
            if len(ms) >= 2:
                names = [m.group(1) for m in ms]
                if len(names) == 4 and len(set(names)) == 4:
                    order = names
                sp = ln[ms[0].end():ms[1].start()]
                if '|' in sp:
                    sep = '|'
                elif ';' in sp:
                    sep = ';'
                elif '\t' in sp:
                    sep = '\t'
                else:
                    sep = 'sp'
            break

    def split_line(s):
        s = s.strip()
        if sep in ('|', ';'):
            s = s.strip(sep).strip()
            parts = s.split(sep)
        elif sep == '\t':
            parts = s.split('\t')
        else:
            parts = re.split(r' {2,}|\t', s)
        return [t.strip() for t in parts]

    def is_data(toks):
        ne = [t for t in toks if t]
        if not ne:
            return False
        for t in ne:
            if CODEISH.match(t) or NUMISH.match(t):
                continue
            return False
        return True

    sections = []
    cur = None
    total_tok = None
    for ln in lines:
        st = ln.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^==\s*SECTION', st):
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', st)
            if m:
                total_tok = m.group(1).strip()
            else:
                total_tok = st[5:].strip()
            continue
        toks = split_line(st)
        if not is_data(toks):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
        cur['tokens'].extend([t for t in toks if t])
    out = []
    for sec in sections:
        rows = []
        for r in chunk_tokens(sec['tokens'], order):
            d = {}
            for i, nm in enumerate(order):
                v = r[i] if i < len(r) else None
                d[nm] = v if v is not None else ''
            rows.append(d)
        if rows or sec['sub'] is not None:
            out.append({'rows': rows, 'sub': sec['sub']})
    return out, total_tok


def type_cost(tok, col):
    t = tok
    pcs = False
    if t.endswith('pcs'):
        pcs = True
        t = t[:-3].strip()
    has_mark = ('.' in t) or (',' in t)
    if col == 'CODE':
        if pcs or has_mark:
            return 4.0
        if 6 <= len(t) <= 8 and (t[0].isalpha() or t[1].isalpha()):
            return 0.0
        if 6 <= len(t) <= 8:
            return 1.5
        return 4.0
    if col == 'QTY':
        if pcs:
            return 0.0
        if has_mark:
            return 4.0
        if len(t) <= 4:
            return 0.3
        return 3.0
    if pcs:
        return 4.0
    if has_mark:
        return 0.0
    if len(t) >= 6 and t[0].isalpha() and t[1].isalpha():
        return 4.0
    if len(t) >= 3:
        return 1.0
    return 3.0


def chunk_tokens(tokens, order):
    n = len(tokens)
    if n % 4 == 0:
        ok = True
        for i, t in enumerate(tokens):
            if type_cost(t, order[i % 4]) >= 3.0:
                ok = False
                break
        if ok:
            return [tokens[i:i + 4] for i in range(0, n, 4)]
    INF = 1e18
    SKIP_TOK = 5.0
    SKIP_SLOT = 5.0
    best = [[INF] * 4 for _ in range(n + 1)]
    back = [[None] * 4 for _ in range(n + 1)]
    best[0][0] = 0.0
    for i in range(n + 1):
        for j in range(4):
            c = best[i][j]
            if c >= INF:
                continue
            if j < 3 and c + SKIP_SLOT < best[i][j + 1]:
                best[i][j + 1] = c + SKIP_SLOT
                back[i][j + 1] = (i, j, 'skipslot')
            if i < n:
                nj = (j + 1) % 4
                nc = c + type_cost(tokens[i], order[j])
                if nc < best[i + 1][nj]:
                    best[i + 1][nj] = nc
                    back[i + 1][nj] = (i, j, 'assign')
                nc = c + SKIP_TOK
                if nc < best[i + 1][j]:
                    best[i + 1][j] = nc
                    back[i + 1][j] = (i, j, 'skiptok')
    endj = 0
    if best[n][0] >= INF:
        endj = min(range(4), key=lambda j: best[n][j])
    ops = []
    i, j = n, endj
    while back[i][j] is not None:
        pi, pj, op = back[i][j]
        ops.append((pi, pj, op))
        i, j = pi, pj
    ops.reverse()
    rows = []
    cur = [None] * 4
    for pi, pj, op in ops:
        if op == 'assign':
            cur[pj] = tokens[pi]
            if pj == 3:
                rows.append(cur)
                cur = [None] * 4
        elif op == 'skipslot':
            cur[pj] = None
            if pj == 3:
                rows.append(cur)
                cur = [None] * 4
    if any(x is not None for x in cur):
        rows.append(cur)
    return rows


# ------------------------------------------------------------ channel
def normalize_digits(s):
    out = []
    cost = 0.0
    for ch in s:
        if ch in DIGITS:
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
            cost += C_LOOK
        else:
            cost += C_JUNK
    return ''.join(out), cost


def edits1(s):
    res = {}
    n = len(s)
    for i in range(n):
        ch = s[i]
        if ch not in DIGITS:
            continue
        for d in INV_MIS.get(ch, ()):
            t = s[:i] + d + s[i + 1:]
            if res.get(t, 99) > C_SUB:
                res[t] = C_SUB
        if i + 1 < n and s[i + 1] == ch:
            t = s[:i] + s[i + 1:]
            if res.get(t, 99) > C_DEL:
                res[t] = C_DEL
    for i in range(n + 1):
        for d in DIGITS:
            t = s[:i] + d + s[i:]
            if res.get(t, 99) > C_INS:
                res[t] = C_INS
    return res


def expand(base, level):
    allc = dict(base)
    frontier = dict(base)
    for _ in range(level):
        nf = {}
        for s, c in frontier.items():
            for t, ec in edits1(s).items():
                nc = c + ec
                if nc < allc.get(t, 99) and nc < nf.get(t, 99):
                    nf[t] = nc
        for t, c in nf.items():
            if c < allc.get(t, 99):
                allc[t] = c
        frontier = nf
    return allc


def good_int(s):
    return s != '' and (s == '0' or s[0] != '0')


def money_base(tok):
    t = (tok or '').replace("'", '').replace(' ', '')
    idx = max(t.rfind('.'), t.rfind(','))
    if idx >= 0:
        ip, ic = normalize_digits(t[:idx])
        fp, fc = normalize_digits(t[idx + 1:])
        return ip + '.' + fp, ic + fc
    d, c = normalize_digits(t)
    return d, c + C_MARK


def money_cands(tok, level):
    s, bc = money_base(tok)
    strs = expand({s: bc}, level)
    out = {}
    for st, c in strs.items():
        if '.' in st:
            ip, fp = st.split('.', 1)
            if len(fp) != 2 or not good_int(ip):
                continue
            v = int(ip) * 100 + int(fp)
        else:
            if len(st) < 3:
                continue
            if not good_int(st[:-2]):
                continue
            v = int(st)
        if v <= 0:
            continue
        if c < out.get(v, 99):
            out[v] = c
    return out


def qty_strip(tok):
    t = (tok or '').strip()
    if t.endswith('pcs'):
        t = t[:-3]
    return t.replace(' ', '')


def qty_cands(tok, level):
    s, bc = normalize_digits(qty_strip(tok))
    strs = expand({s: bc}, level)
    out = {}
    for st, c in strs.items():
        if not st or st[0] == '0' or len(st) > 3:
            continue
        v = int(st)
        if 1 <= v <= 500 and c < out.get(v, 99):
            out[v] = c
    return out


def norm_money(tok):
    return (tok or '').replace("'", '').replace(' ', '').replace(',', '.')


def fmt_true(v):
    return '%d.%02d' % (v // 100, v % 100)


def sub_cost(t, s):
    if t == s:
        return 0.0
    if t == '.':
        return 3.0
    if s in DIGITS:
        if s in MIS.get(t, ''):
            return C_SUB
        return C_OTHER
    if L2D.get(s) == t:
        return C_LOOK
    return 3.0


def dist(S, T):
    n = len(T)
    m = len(S)
    INF = 99.0
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            v = row[j]
            if v >= INF:
                continue
            if j < m and row[j + 1] > v + C_EXTRA:
                row[j + 1] = v + C_EXTRA
            if i < n:
                t = T[i]
                nxt = dp[i + 1]
                lc = C_MARK if t == '.' else C_INS
                if nxt[j] > v + lc:
                    nxt[j] = v + lc
                if j < m:
                    c = v + sub_cost(t, S[j])
                    if nxt[j + 1] > c:
                        nxt[j + 1] = c
                    if t != '.' and j + 1 < m and S[j] == t and S[j + 1] == t:
                        c = v + C_DEL
                        if nxt[j + 2] > c:
                            nxt[j + 2] = c
    return dp[n][m]


# ------------------------------------------------------------ codes
def check_ok(l1, l2, digs):
    d = [int(x) for x in digs]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + ord(l1) - 64 + ord(l2) - 64) % 10 == d[4]


def fix_code(tok):
    t = re.sub(r'\s', '', tok or '')
    if len(t) < 2:
        t = (t + 'AA')[:2]
    lets = []
    for ch in t[:2]:
        if 'A' <= ch <= 'Z':
            lets.append([(ch, 0.0)])
        elif ch in DIG2LET:
            lets.append([(DIG2LET[ch], C_LOOK)])
        elif ch == 'l':
            lets.append([('I', C_LOOK)])
        elif ch.isalpha():
            lets.append([(ch.upper(), 0.5)])
        else:
            lets.append([(chr(65 + k), 2.0) for k in range(26)])
    rest, bc = normalize_digits(t[2:])
    for level in (0, 1, 2):
        strs = expand({rest: bc}, level)
        best = None
        for st, c in strs.items():
            if len(st) != 5:
                continue
            for l1, c1 in lets[0]:
                for l2, c2 in lets[1]:
                    if check_ok(l1, l2, st):
                        key = (c + c1 + c2, l1 + l2 + st)
                        if best is None or key < best:
                            best = key
        if best is not None:
            return best[1]
    return lets[0][0][0] + lets[1][0][0] + (rest + '00000')[:5]


# ------------------------------------------------------------ rows
def row_info(row):
    qtok, utok, atok = row['QTY'], row['UNIT'], row['AMOUNT']
    info = {'qs': qty_strip(qtok), 'us': norm_money(utok), 'as': norm_money(atok)}
    Q1 = qty_cands(qtok, 1)
    U1 = money_cands(utok, 1)
    A1 = money_cands(atok, 1)
    info['Q1'] = Q1
    info['U1'] = U1
    info['A1'] = A1
    info['Ql'] = sorted(Q1.items(), key=lambda x: (x[1], x[0]))
    info['Ul'] = sorted(U1.items(), key=lambda x: (x[1], x[0]))
    info['Al'] = sorted(A1.items(), key=lambda x: (x[1], x[0]))
    info['cache'] = {}
    return info


def dmon(info, which, v):
    cache = info['cache']
    k = (which, v)
    r = cache.get(k)
    if r is None:
        if which == 'q':
            r = dist(info['qs'], str(v))
        else:
            r = dist(info[which], fmt_true(v))
        cache[k] = r
    return r


def row_candidates(info, deadline):
    cands = {}

    def add(q, u, c):
        if u <= 0 or q < 1 or q > 500:
            return
        k = (q, u)
        o = cands.get(k)
        if o is None or o[0] > c:
            cands[k] = (c, q, u, q * u)

    Ql, Ul, Al, A1 = info['Ql'], info['Ul'], info['Al'], info['A1']
    full = bool(info['qs']) and bool(info['us']) and bool(info['as'])
    if full:
        for q, cq in Ql:
            for u, cu in Ul:
                ca = A1.get(q * u)
                if ca is not None:
                    add(q, u, cq + cu + ca)
    best = min([v[0] for v in cands.values()]) if cands else 99.0
    if best >= 1.9 and time.perf_counter() < deadline:
        for lim in (1.3, 2.6):
            calls = 0
            Q0 = [x for x in Ql if x[1] <= lim]
            U0 = [x for x in Ul if x[1] <= lim]
            A0 = [x for x in Al if x[1] <= lim]
            if lim < 2.0:
                for q, cq in Q0:
                    for u, cu in U0:
                        if cq + cu > lim:
                            break
                        add(q, u, cq + cu + dmon(info, 'as', q * u))
            for q, cq in Q0:
                for a, ca in A0:
                    if cq + ca > lim:
                        break
                    if a % q:
                        continue
                    if calls > 300:
                        break
                    calls += 1
                    add(q, a // q, cq + ca + dmon(info, 'us', a // q))
            for u, cu in U0:
                for a, ca in A0:
                    if cu + ca > lim:
                        break
                    if a % u:
                        continue
                    q = a // u
                    if 1 <= q <= 500 and calls <= 600:
                        calls += 1
                        add(q, u, cu + ca + dmon(info, 'q', q))
            best = min([v[0] for v in cands.values()]) if cands else 99.0
            if best < 2.6 or time.perf_counter() > deadline:
                break
    if not cands:
        q = Ql[0][0] if Ql else 1
        if Ul:
            u = Ul[0][0]
        elif Al:
            u = max(1, Al[0][0] // q)
        else:
            u = 1
        cands[(q, u)] = (9.0, q, u, q * u)
    lst = sorted(cands.values(), key=lambda x: (x[0], x[1], x[2]))
    b = lst[0][0]
    return [x for x in lst if x[0] <= b + 4.0][:8]


# ------------------------------------------------------------ sums
def section_search(rcl, subtok, S1, deadline):
    B = 300
    DEV = 4.0
    M = 30
    layers = []
    states = {0: 0.0}
    for cl in rcl:
        ns = {}
        bp = {}
        for s, c in states.items():
            for ci, cand in enumerate(cl):
                t = s + cand[3]
                nc = c + cand[0]
                o = ns.get(t)
                if o is None or o > nc:
                    ns[t] = nc
                    bp[t] = (s, ci)
        items = sorted(ns.items(), key=lambda x: (x[1], x[0]))
        bc = items[0][1]
        items = [it for it in items if it[1] <= bc + DEV][:B]
        states = dict(items)
        layers.append(bp)
    final = sorted(states.items(), key=lambda x: (x[1], x[0]))
    scored = []
    has_sub = bool(subtok)
    ns_sub = norm_money(subtok) if has_sub else ''
    for idx, (s, c) in enumerate(final):
        if not has_sub:
            sc = 0.0
        else:
            sc = S1.get(s)
            if sc is None:
                if idx < 60 and time.perf_counter() < deadline:
                    sc = dist(ns_sub, fmt_true(s))
                else:
                    sc = SUBCAP
            sc = min(sc, SUBCAP)
        scored.append((c + sc, s, c, sc))
    scored.sort()
    res = []
    for tot, s, c, sc in scored[:M]:
        path = []
        cur = s
        for L in range(len(layers) - 1, -1, -1):
            ps, ci = layers[L][cur]
            path.append(ci)
            cur = ps
        path.reverse()
        res.append((tot, s, path, sc))
    return res


def repair_section(rcl, infos, res, S1, deadline):
    best = res[0]
    s = best[1]
    path = best[2]
    chosen = [rcl[i][path[i]] for i in range(len(rcl))]
    order_i = sorted(range(len(rcl)), key=lambda i: (-chosen[i][0], i))
    suspects = [i for i in order_i if chosen[i][0] >= 0.9][:3]
    Sl = sorted([(c, v) for v, c in S1.items() if c <= 1.3])[:40]
    changed = False
    for i in suspects:
        if time.perf_counter() > deadline:
            break
        info = infos[i]
        rest = s - chosen[i][3]
        have = set((x[1], x[2]) for x in rcl[i])
        new = {}
        calls = 0
        Qs = [x for x in info['Ql'] if x[1] <= 1.3]
        Us = [x for x in info['Ul'] if x[1] <= 1.3]
        for cs, S in Sl:
            a = S - rest
            if a <= 0:
                continue
            for q, cq in Qs:
                if a % q == 0 and calls < 300:
                    u = a // q
                    if (q, u) in have:
                        continue
                    calls += 1
                    c = cq + dmon(info, 'us', u) + dmon(info, 'as', a)
                    if c <= 6.0 and c < new.get((q, u), 99):
                        new[(q, u)] = c
            for u, cu in Us:
                if u > 0 and a % u == 0 and calls < 300:
                    q = a // u
                    if 1 <= q <= 500 and (q, u) not in have:
                        calls += 1
                        c = cu + dmon(info, 'q', q) + dmon(info, 'as', a)
                        if c <= 6.0 and c < new.get((q, u), 99):
                            new[(q, u)] = c
        if new:
            add = sorted([(c, q, u, q * u) for (q, u), c in new.items()])[:4]
            rcl[i] = sorted(rcl[i] + add, key=lambda x: (x[0], x[1], x[2]))
            changed = True
    return changed


# ------------------------------------------------------------ main
def _solve_text(text, t0):
    secs, total_tok = parse_doc(text)
    d_rows = t0 + 0.45
    d_rep = t0 + 0.65
    d_sum = t0 + 0.75
    all_rc = []
    all_info = []
    codes = []
    for sec in secs:
        rcs = []
        infs = []
        cs = []
        for r in sec['rows']:
            info = row_info(r)
            infs.append(info)
            rcs.append(row_candidates(info, d_rows))
            cs.append(fix_code(r['CODE']))
        all_rc.append(rcs)
        all_info.append(infs)
        codes.append(cs)
    sec_res = []
    for si, sec in enumerate(secs):
        subtok = sec['sub']
        S1 = money_cands(subtok, 1) if subtok else {}
        res = section_search(all_rc[si], subtok, S1, d_sum)
        if subtok and res and res[0][3] >= 0.9 and all_rc[si] and time.perf_counter() < d_rep:
            if repair_section(all_rc[si], all_info[si], res, S1, d_rep):
                res = section_search(all_rc[si], subtok, S1, d_sum)
        sec_res.append(res)
    states = {0: (0.0, ())}
    for res in sec_res:
        ns = {}
        for s, (c, ch) in states.items():
            for k, r in enumerate(res):
                t = s + r[1]
                nc = c + r[0]
                o = ns.get(t)
                if o is None or o[0] > nc:
                    ns[t] = (nc, ch + (k,))
        states = dict(sorted(ns.items(), key=lambda x: (x[1][0], x[0]))[:400])
    items = sorted(states.items(), key=lambda x: (x[1][0], x[0]))
    choice = items[0][1][1] if items else ()
    if total_tok and items:
        T1 = money_cands(total_tok, 1)
        nt = norm_money(total_tok)
        bestv = None
        for idx, (s, (c, ch)) in enumerate(items):
            tc = T1.get(s)
            if tc is None:
                if idx < 60 and time.perf_counter() < d_sum + 0.05:
                    tc = dist(nt, fmt_true(s))
                else:
                    tc = TOTCAP
            v = c + min(tc, TOTCAP)
            if bestv is None or v < bestv:
                bestv = v
                choice = ch
    out = []
    for si in range(len(secs)):
        res = sec_res[si]
        path = res[choice[si]][2] if (si < len(choice) and choice[si] < len(res)) else []
        for ri in range(len(all_rc[si])):
            cl = all_rc[si][ri]
            ci = path[ri] if ri < len(path) else 0
            rc = cl[ci] if ci < len(cl) else cl[0]
            out.append({'code': codes[si][ri], 'qty': int(rc[1]), 'unit_cents': int(rc[2])})
    return out


def _fallback(text):
    secs, total_tok = parse_doc(text)
    out = []
    dl = time.perf_counter() + 0.2
    for sec in secs:
        for r in sec['rows']:
            try:
                info = row_info(r)
                rc = row_candidates(info, dl)[0]
                q, u = rc[1], rc[2]
            except Exception:
                q, u = 1, 0
            try:
                code = fix_code(r['CODE'])
            except Exception:
                code = ''
            out.append({'code': code, 'qty': int(q), 'unit_cents': int(u)})
    return out


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get('input', {}) or {}
    text = inp.get('text', '') if isinstance(inp, dict) else ''
    if not isinstance(text, str):
        text = ''
    try:
        items = _solve_text(text, t0)
    except Exception:
        try:
            items = _fallback(text)
        except Exception:
            items = []
    state['output'] = {'items': items}
    return state

import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INV_MIS = {}
for _o, _ss in MIS.items():
    for _s in _ss:
        INV_MIS[_s] = INV_MIS.get(_s, '') + _o
D2LSHOW = {'0': 'Oo', '1': 'lIi', '5': 'Ss', '8': 'B', '2': 'Zz', '6': 'G'}
L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
LET2DIG = {'O': '0', 'I': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6'}
DIG2LET = {v: k for k, v in LET2DIG.items()}
DIGITS = '0123456789'
SUBCAP = 4.0
TOTCAP = 4.0
LOOK = set('OolIiSsBZzG')


def _subc(t, s):
    if t == s:
        return 0.0
    if t in DIGITS:
        if s in D2LSHOW.get(t, ''):
            return 1.0
        if s in MIS[t]:
            return 1.0
        if s in DIGITS:
            return 3.0
        return 4.0
    if t.isalpha():
        if LET2DIG.get(t) == s:
            return 1.0
        return 4.0
    if t in '.,' and s in '.,':
        return 2.0
    return 4.0


def dist(S, T):
    n = len(T)
    m = len(S)
    INF = 99.0
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            v = row[j]
            if v >= INF:
                continue
            if j < m and row[j + 1] > v + 3.0:
                row[j + 1] = v + 3.0
            if i < n:
                t = T[i]
                nxt = dp[i + 1]
                if t in DIGITS or t in '.,':
                    lc = 1.0
                elif t == "'":
                    lc = 1.5
                else:
                    lc = 3.0
                if nxt[j] > v + lc:
                    nxt[j] = v + lc
                if j < m:
                    c = v + _subc(t, S[j])
                    if nxt[j + 1] > c:
                        nxt[j + 1] = c
                    if j + 1 < m and t in DIGITS and S[j] == t and S[j + 1] == t:
                        if nxt[j + 2] > v + 1.0:
                            nxt[j + 2] = v + 1.0
    return dp[n][m]


def fmt_money(c, mark, grouped):
    ip = c // 100
    fp = c % 100
    s = str(ip)
    if grouped and len(s) > 3:
        parts = []
        while len(s) > 3:
            parts.append(s[-3:])
            s = s[:-3]
        parts.append(s)
        s = "'".join(reversed(parts))
    return s + mark + ('%02d' % fp)


def strip_pcs(tok):
    return re.sub(r'\s*pcs\s*$', '', tok.strip()).strip()


def normalize_num(tok, money):
    base = 0
    out = []
    for ch in tok:
        if ch in DIGITS:
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
            base += 1
        elif ch in '.,':
            if money:
                if 'M' in out:
                    base += 2
                else:
                    out.append('M')
            else:
                base += 2
        elif ch == "'" or ch == ' ':
            continue
        else:
            base += 2
    return tuple(out), base


def neighbors(s):
    res = set()
    L = len(s)
    for i in range(L):
        ch = s[i]
        if ch == 'M':
            continue
        for o in INV_MIS.get(ch, ''):
            res.add(s[:i] + (o,) + s[i + 1:])
        if i > 0 and s[i - 1] == ch:
            res.add(s[:i] + s[i + 1:])
    for i in range(L + 1):
        for d in DIGITS:
            res.add(s[:i] + (d,) + s[i:])
    return res


def eval_num(s, money):
    if money:
        if 'M' in s:
            k = s.index('M')
            ip = s[:k]
            fp = s[k + 1:]
            if len(fp) != 2 or len(ip) < 1:
                return None
            if len(ip) > 1 and ip[0] == '0':
                return None
            return int(''.join(ip) + ''.join(fp)), 0
        if len(s) < 3:
            return None
        ip = s[:-2]
        if len(ip) > 1 and ip[0] == '0':
            return None
        return int(''.join(s)), 1
    else:
        if len(s) < 1 or len(s) > 3:
            return None
        if s[0] == '0':
            return None
        v = int(''.join(s))
        if v < 1 or v > 500:
            return None
        return v, 0


def gen_num(tok, money, maxedits):
    start, base = normalize_num(tok, money)
    seen = {start: 0}
    frontier = [start]
    for lev in range(1, maxedits + 1):
        nf = []
        for s in frontier:
            for t in neighbors(s):
                if t not in seen:
                    seen[t] = lev
                    nf.append(t)
        frontier = nf
    out = {}
    for s, e in seen.items():
        r = eval_num(s, money)
        if r is None:
            continue
        v, x = r
        c = base + e + x
        if v not in out or out[v] > c:
            out[v] = c
    return out


def code_ok(c):
    if len(c) != 7:
        return False
    a, b = c[0], c[1]
    if not ('A' <= a <= 'Z' and 'A' <= b <= 'Z'):
        return False
    ds = c[2:]
    if not ds.isdigit():
        return False
    d = [int(x) for x in ds]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + ord(a) - 64 + ord(b) - 64) % 10 == d[4]


def fix_code(tok):
    s = re.sub(r'\s', '', tok)
    if len(s) < 2:
        s = (s + 'XX')[:2]
    lets = []
    base = 0
    for ch in s[:2]:
        if 'A' <= ch <= 'Z':
            lets.append([(ch, 0)])
        elif ch in DIG2LET:
            lets.append([(DIG2LET[ch], 1)])
        elif ch.isalpha():
            lets.append([(ch.upper(), 1)])
        else:
            lets.append([(chr(65 + k), 2) for k in range(26)])
    r = []
    for ch in s[2:]:
        if ch in DIGITS:
            r.append(ch)
        elif ch in L2D:
            r.append(L2D[ch])
            base += 1
        else:
            base += 2
    start = tuple(r)
    seen = {start: 0}
    frontier = [start]
    best = None
    for lev in range(0, 3):
        if lev > 0:
            nf = []
            for x in frontier:
                for t in neighbors(x):
                    if t not in seen:
                        seen[t] = lev
                        nf.append(t)
            frontier = nf
        cands = []
        for x in frontier:
            if len(x) != 5:
                continue
            ds = ''.join(x)
            for l1, c1 in lets[0]:
                for l2, c2 in lets[1]:
                    c = l1 + l2 + ds
                    if code_ok(c):
                        cands.append((base + lev + c1 + c2, c))
        if cands:
            cands.sort()
            best = cands[0]
            break
    if best is not None:
        return best[1]
    ds = ''.join(start)
    ds = (ds + '00000')[:5]
    return lets[0][0][0] + lets[1][0][0] + ds


KEY_RE = re.compile(r'\b(CODE|QTY|UNIT|AMOUNT)\b')
CODEISH = re.compile(r"^[A-Za-z0-9]{2}[0-9OolIiSsBZzG]{3,8}$")
NUMISH = re.compile(r"^[0-9OolIiSsBZzG.,']*(\s*pcs)?$")


def slot_cost(tok, slot):
    if tok == '':
        if slot == 'CODE':
            return 6.0
        if slot == 'QTY':
            return 1.0
        return 3.0
    has_pcs = 'pcs' in tok
    core = strip_pcs(tok) if has_pcs else tok
    has_mark = any(ch in ".,'" for ch in core)
    first2 = core[:2]
    strong_let = sum(1 for ch in first2 if 'A' <= ch <= 'Z' and ch not in LOOK)
    codeish = bool(CODEISH.match(core)) and not has_mark and not has_pcs
    numish = bool(NUMISH.match(tok))
    if slot == 'CODE':
        if has_pcs or has_mark:
            return 6.0
        if codeish and strong_let >= 1:
            return 0.0
        if codeish:
            return 1.5
        return 4.0
    if strong_let >= 1:
        return 6.0
    if not numish:
        return 4.0
    if codeish and len(core) >= 6 and any(ch.isalpha() for ch in first2):
        base_c = 1.5
    else:
        base_c = 0.0
    if slot == 'QTY':
        if has_pcs:
            return base_c
        if has_mark:
            return base_c + 3.0
        nd = len(core)
        if nd > 4:
            return base_c + 2.5
        if nd == 4:
            return base_c + 1.0
        return base_c
    if has_pcs:
        return 5.0
    if has_mark:
        return base_c
    return base_c + 0.6


def segment(line_toks, order):
    toks = [t for lt in line_toks for t in lt]
    n = len(toks)
    INF = 1e18
    dp = [INF] * (n + 1)
    bk = [None] * (n + 1)
    dp[0] = 0.0
    for i in range(n):
        v = dp[i]
        if v >= INF:
            continue
        if i + 4 <= n:
            c = v + sum(slot_cost(toks[i + k], order[k]) for k in range(4))
            if c < dp[i + 4]:
                dp[i + 4] = c
                bk[i + 4] = ('r', i)
        else:
            c = v
            for k in range(4):
                if i + k < n:
                    c += slot_cost(toks[i + k], order[k])
                else:
                    c += slot_cost('', order[k]) + 0.5
            if c < dp[n]:
                dp[n] = c
                bk[n] = ('p', i)
        c = v + (2.0 if toks[i] == '' else 3.5)
        if c < dp[i + 1]:
            dp[i + 1] = c
            bk[i + 1] = ('s', i)
    rows = []
    j = n
    while j > 0 and bk[j] is not None:
        kind, i = bk[j]
        if kind in ('r', 'p'):
            grp = toks[i:j]
            grp = grp + [''] * (4 - len(grp))
            rows.append(dict(zip(order, grp)))
        j = i
    rows.reverse()
    return rows


def parse_doc(text):
    lines = text.replace('\r', '').split('\n')
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        st = ln.strip()
        if st.startswith('COLUMNS'):
            ms = list(KEY_RE.finditer(ln))
            if len(ms) >= 2:
                names = [m.group(1) for m in ms]
                if len(names) == 4 and len(set(names)) == 4:
                    order = names
                sp = ln[ms[0].end():ms[1].start()]
                if '|' in sp:
                    sep = '|'
                elif ';' in sp:
                    sep = ';'
                elif '\t' in sp:
                    sep = '\t'
                else:
                    sep = '   '
            break

    def split_line(s):
        if sep in ('|', ';', '\t'):
            return [t.strip() for t in s.split(sep)]
        return [t.strip() for t in s.split('   ')]

    def is_data(toks):
        if not [t for t in toks if t]:
            return False
        for t in toks:
            if not t:
                continue
            if CODEISH.match(t) or NUMISH.match(t):
                continue
            return False
        return True

    sections = []
    cur = None
    total_tok = None
    for ln in lines:
        st = ln.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^==\s*SECTION', st):
            cur = {'lines': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'lines': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', st)
            if m:
                total_tok = m.group(1).strip()
            else:
                total_tok = st[5:].strip()
            continue
        toks = split_line(ln)
        if not is_data(toks):
            continue
        if cur is None:
            cur = {'lines': [], 'sub': None}
            sections.append(cur)
        cur['lines'].append(toks)
    out_secs = []
    for sec in sections:
        rows = segment(sec['lines'], order) if sec['lines'] else []
        if rows or sec['sub'] is not None:
            out_secs.append({'rows': rows, 'sub': sec['sub']})
    return out_secs, total_tok


def detect_style(secs, total_tok):
    toks = []
    for sec in secs:
        for r in sec['rows']:
            toks.append(r['UNIT'])
            toks.append(r['AMOUNT'])
        if sec['sub']:
            toks.append(sec['sub'])
    if total_tok:
        toks.append(total_tok)
    dot = sum(t.count('.') for t in toks)
    com = sum(t.count(',') for t in toks)
    mark = ',' if com > dot else '.'
    grouped = any("'" in t for t in toks)
    return mark, grouped


def row_candidates(row, ctx, K):
    mark = ctx['mark']
    grouped = ctx['grouped']
    qtok = strip_pcs(row['QTY'])
    utok = row['UNIT'].strip()
    atok = row['AMOUNT'].strip()
    Q = gen_num(qtok, False, 1)
    U = gen_num(utok, True, 1)
    A = gen_num(atok, True, 1)
    cands = {}

    def add(q, u, a, c):
        key = (q, u)
        if key not in cands or cands[key][0] > c:
            cands[key] = (c, q, u, a)

    for q, cq in Q.items():
        for u, cu in U.items():
            a = q * u
            ca = A.get(a)
            if ca is not None:
                add(q, u, a, cq + cu + ca)
    best = min([v[0] for v in cands.values()]) if cands else 99
    if best >= 2 and time.perf_counter() < ctx['deadline']:
        cache = {}

        def dmon(tok, v):
            k = ('m', tok, v)
            if k not in cache:
                cache[k] = dist(tok, fmt_money(v, mark, grouped))
            return cache[k]

        def dq(v):
            k = ('q', v)
            if k not in cache:
                cache[k] = dist(qtok, str(v))
            return cache[k]

        for lim in (0, 1):
            Q0 = [(q, c) for q, c in Q.items() if c <= lim]
            U0 = [(u, c) for u, c in U.items() if c <= lim]
            A0 = [(a, c) for a, c in A.items() if c <= lim]
            for q, cq in Q0:
                for u, cu in U0:
                    if cq + cu <= lim:
                        a = q * u
                        add(q, u, a, cq + cu + dmon(atok, a))
                for a, ca in A0:
                    if cq + ca <= lim and a > 0 and a % q == 0:
                        u = a // q
                        add(q, u, a, cq + ca + dmon(utok, u))
            for u, cu in U0:
                if u <= 0:
                    continue
                for a, ca in A0:
                    if cu + ca <= lim and a % u == 0:
                        q = a // u
                        if 1 <= q <= 500:
                            add(q, u, a, cu + ca + dq(q))
            best = min([v[0] for v in cands.values()]) if cands else 99
            if best < 3 or time.perf_counter() > ctx['deadline']:
                break
    if not cands:
        q = min(Q.items(), key=lambda x: (x[1], x[0]))[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: (x[1], x[0]))[0]
        elif A:
            a0 = min(A.items(), key=lambda x: (x[1], x[0]))[0]
            u = a0 // q
        else:
            u = 0
        add(q, u, q * u, 9.0)
    lst = sorted(cands.values(), key=lambda x: (x[0], x[1], x[2]))
    return lst[:K]


def section_search(rcands, subtok, ctx, B=400, M=40, DEV=6.0):
    states = {0: (0.0, ())}
    for cl in rcands:
        ns = {}
        for s, (c, path) in states.items():
            for ci, (rc, q, u, a) in enumerate(cl):
                t = s + a
                nc = c + rc
                if t not in ns or ns[t][0] > nc:
                    ns[t] = (nc, path + (ci,))
        if not ns:
            continue
        items = sorted(ns.items(), key=lambda x: x[1][0])
        bc = items[0][1][0]
        items = [it for it in items if it[1][0] <= bc + DEV][:B]
        states = dict(items)
    items = sorted(states.items(), key=lambda x: x[1][0])
    res = []
    if subtok is None:
        for s, (c, path) in items[:M]:
            res.append((c, s, path))
        return res
    S1 = gen_num(subtok, True, 1)
    mark = ctx['mark']
    grouped = ctx['grouped']
    for idx, (s, (c, path)) in enumerate(items):
        sc = S1.get(s)
        if sc is None:
            if idx < 40 and time.perf_counter() < ctx['deadline'] + 0.1:
                sc = dist(subtok, fmt_money(s, mark, grouped))
            else:
                sc = SUBCAP
        sc = min(sc, SUBCAP)
        res.append((c + sc, s, path))
    res.sort(key=lambda x: x[0])
    return res[:M]


def _solve_text(text, t0):
    secs, total_tok = parse_doc(text)
    mark, grouped = detect_style(secs, total_tok)
    ctx = {'mark': mark, 'grouped': grouped, 'deadline': t0 + 0.5}
    all_rc = []
    codes = []
    for sec in secs:
        rcs = []
        cs = []
        for r in sec['rows']:
            rcs.append(row_candidates(r, ctx, 8))
            cs.append(fix_code(r['CODE']))
        all_rc.append(rcs)
        codes.append(cs)
    sec_res = []
    for si, sec in enumerate(secs):
        sec_res.append(section_search(all_rc[si], sec['sub'], ctx))
    states = {0: (0.0, ())}
    for si in range(len(sec_res)):
        res = sec_res[si]
        if not res:
            res = [(0.0, 0, ())]
            sec_res[si] = res
        ns = {}
        for s, (c, ch) in states.items():
            for k, (sc, ss, path) in enumerate(res):
                t = s + ss
                nc = c + sc
                if t not in ns or ns[t][0] > nc:
                    ns[t] = (nc, ch + (k,))
        items = sorted(ns.items(), key=lambda x: x[1][0])[:500]
        states = dict(items)
    items = sorted(states.items(), key=lambda x: x[1][0])
    best = None
    if total_tok and items:
        T1 = gen_num(total_tok, True, 1)
        for idx, (s, (c, ch)) in enumerate(items):
            tc = T1.get(s)
            if tc is None:
                if idx < 40 and time.perf_counter() < ctx['deadline'] + 0.2:
                    tc = dist(total_tok, fmt_money(s, mark, grouped))
                else:
                    tc = TOTCAP
            tc = min(tc, TOTCAP)
            v = c + tc
            if best is None or v < best[0]:
                best = (v, ch)
    elif items:
        best = (items[0][1][0], items[0][1][1])
    choice = best[1] if best else ()
    out = []
    for si in range(len(secs)):
        res = sec_res[si]
        if res and si < len(choice) and choice[si] < len(res):
            path = res[choice[si]][2]
        else:
            path = ()
        for ri in range(len(all_rc[si])):
            ci = path[ri] if ri < len(path) else 0
            cl = all_rc[si][ri]
            rc = cl[ci] if ci < len(cl) else cl[0]
            out.append({'code': codes[si][ri], 'qty': int(rc[1]), 'unit_cents': int(rc[2])})
    return out


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get('input', {}) or {}
    text = inp.get('text', '') or ''
    try:
        items = _solve_text(text, t0)
    except Exception:
        items = []
    state['output'] = {'items': items}
    return state

import re
import time

C_SUB = 2.0
C_LOST = 2.2
C_DBL = 2.0
C_MARK = 1.5
C_BAD = 8.0
C_HUGE = 30.0
CAP = 11.0
DIGITS = '0123456789'
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
INV = {'0': ['6', '8'], '1': ['4', '7'], '2': ['7'], '3': ['5', '8', '9'],
       '4': ['1', '9'], '5': ['6'], '6': ['0', '5'], '7': ['1', '2'],
       '8': ['0', '3'], '9': ['3', '4']}
SUBC = {'0': 2.7, '1': 2.7, '2': 2.0, '3': 2.7, '4': 2.7, '5': 2.7,
        '6': 2.7, '7': 2.7, '8': 2.7, '9': 2.7}
DIG = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
       'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
LET = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}


def _render(v, grouped):
    ip = str(v // 100)
    fp = '%02d' % (v % 100)
    if grouped and len(ip) > 3:
        parts = []
        while len(ip) > 3:
            parts.append(ip[-3:])
            ip = ip[:-3]
        parts.append(ip)
        ip = "'".join(reversed(parts))
    return ip + '.' + fp


def _parse_canon(s, grouped):
    if not s or len(s) < 4 or s[-3] != '.':
        return None
    fp = s[-2:]
    ip = s[:-3]
    if not fp.isdigit():
        return None
    raw = ip.replace("'", "")
    if not raw.isdigit():
        return None
    v = int(raw) * 100 + int(fp)
    if _render(v, grouped) != s:
        return None
    return v


def _qexact(s):
    if s and s.isdigit() and s[0] != '0' and len(s) <= 3:
        v = int(s)
        if 1 <= v <= 500:
            return v
    return None


def _digit_edits(s):
    out = []
    n = len(s)
    for i in range(n):
        ch = s[i]
        if ch in INV:
            for t in INV[ch]:
                out.append((s[:i] + t + s[i + 1:], SUBC[t]))
            if i > 0 and s[i - 1] == ch:
                out.append((s[:i] + s[i + 1:], C_DBL))
    for i in range(n + 1):
        for d in DIGITS:
            if i > 0 and s[i - 1] == d:
                continue
            out.append((s[:i] + d + s[i:], C_LOST))
    return out


def _money_cands(O, grouped):
    res = {}
    if O is None:
        return res

    def add(s, c):
        v = _parse_canon(s, grouped)
        if v is not None and v > 0:
            e = res.get(v)
            if e is None or e > c:
                res[v] = c
    if '.' in O:
        add(O, 0.0)
        for s, c in _digit_edits(O):
            add(s, c)
    else:
        for s, c in [(O, 0.0)] + _digit_edits(O):
            if len(s) >= 3:
                add(s[:-2] + '.' + s[-2:], c + C_MARK)
    return res


def _qty_cands(O):
    res = {}

    def add(s, c):
        v = _qexact(s)
        if v is not None:
            e = res.get(v)
            if e is None or e > c:
                res[v] = c
    add(O, 0.0)
    for s, c in _digit_edits(O):
        add(s, c)
    return res


def _align(T, O):
    n = len(T)
    m = len(O)

    def ins(i, o):
        if o in INV:
            if (i > 0 and T[i - 1] == o) or (i < n and T[i] == o):
                return C_DBL
            return C_BAD
        return C_HUGE

    def dele(t):
        if t in INV:
            return C_LOST
        if t == '.':
            return C_MARK
        return C_HUGE
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] + ins(0, O[j - 1])
    for i in range(1, n + 1):
        t = T[i - 1]
        dt = dele(t)
        cur = [prev[0] + dt] + [0.0] * m
        for j in range(1, m + 1):
            o = O[j - 1]
            if t == o:
                sc = 0.0
            elif t in INV and o in INV:
                sc = SUBC[t] if o in MIS[t] else C_BAD
            else:
                sc = C_HUGE
            v = prev[j - 1] + sc
            v2 = prev[j] + dt
            if v2 < v:
                v = v2
            v3 = cur[j - 1] + ins(i, o)
            if v3 < v:
                v = v3
            cur[j] = v
        prev = cur
    return prev[m]


def _code_decode(tok):
    t = ''.join(ch for ch in tok if not ch.isspace())
    if len(t) < 2:
        t = (t + 'AA')[:2]
    Ls = []
    for ch in t[:2]:
        if 'A' <= ch <= 'Z':
            Ls.append(ch)
        elif ch in LET:
            Ls.append(LET[ch])
        elif ch in ('l', '|'):
            Ls.append('I')
        elif 'a' <= ch <= 'z':
            Ls.append(ch.upper())
        else:
            Ls.append('A')
    L = ''.join(Ls)
    D = ''.join(ch if ch in INV else DIG.get(ch, '?') for ch in t[2:])
    p = ord(L[0]) - 64 + ord(L[1]) - 64

    def ok(s):
        if len(s) != 5 or '?' in s:
            return False
        return (int(s[0]) + 2 * int(s[1]) + 3 * int(s[2]) + 4 * int(s[3]) + p) % 10 == int(s[4])
    if ok(D):
        return L + D

    def edits(s, rem):
        n = len(s)
        out = []
        if abs(n - 5) <= rem - 1:
            for i in range(n):
                ch = s[i]
                if ch == '?':
                    for d in DIGITS:
                        out.append((s[:i] + d + s[i + 1:], C_SUB))
                elif ch in INV:
                    for tt in INV[ch]:
                        out.append((s[:i] + tt + s[i + 1:], SUBC[tt]))
        if abs(n - 1 - 5) <= rem - 1:
            for i in range(n):
                if i > 0 and s[i - 1] == s[i]:
                    out.append((s[:i] + s[i + 1:], C_DBL))
                elif s[i] == '?':
                    out.append((s[:i] + s[i + 1:], C_SUB))
        if abs(n + 1 - 5) <= rem - 1:
            for i in range(n + 1):
                for d in DIGITS:
                    if i > 0 and s[i - 1] == d:
                        continue
                    out.append((s[:i] + d + s[i:], C_LOST))
        return out
    best = None
    lvl = {D: 0.0}
    if len(D) <= 8:
        for rem in (2, 1):
            nxt = {}
            for s, c in lvl.items():
                for s2, c2 in edits(s, rem):
                    cc = c + c2
                    e = nxt.get(s2)
                    if e is None or e > cc:
                        nxt[s2] = cc
            for s2, cc in nxt.items():
                if ok(s2) and (best is None or cc < best[0]):
                    best = (cc, s2)
            if best is not None:
                break
            lvl = nxt
    if best is not None:
        return L + best[1]
    ds = [c for c in D if c in INV]
    ds = (ds + ['0'] * 4)[:4]
    s4 = ''.join(ds)
    ck = (int(s4[0]) + 2 * int(s4[1]) + 3 * int(s4[2]) + 4 * int(s4[3]) + p) % 10
    return L + s4 + str(ck)


def _norm_money(t):
    out = []
    for ch in t:
        if ch in INV:
            out.append(ch)
        elif ch in DIG:
            out.append(DIG[ch])
        elif ch == '.' or ch == ',':
            out.append('.')
        elif ch == "'":
            out.append("'")
    return ''.join(out)


def _norm_qty(t):
    t = re.sub(r'\s*pcs\s*$', '', t.strip())
    return ''.join(ch if ch in INV else DIG.get(ch, '') for ch in t)


def _split(s, sepkind):
    if sepkind == 'pipe':
        parts = s.split('|')
    elif sepkind == 'semi':
        parts = s.split(';')
    elif sepkind == 'tab':
        parts = s.split('\t')
    else:
        parts = re.split(r'\s{2,}|\t', s)
    return [x.strip() for x in parts if x.strip()]


def _fieldlike(t):
    t2 = re.sub(r'\s*pcs$', '', t).strip()
    if t2 == '':
        return t.endswith('pcs')
    if re.fullmatch(r"[A-Z0-9Il]{2}[0-9OlISBZG]{2,8}", t2):
        return True
    if re.fullmatch(r"[0-9OlISBZG.,']+", t2):
        return True
    return False


def _fit(t, kind, pcs):
    t = t.strip()
    has_pcs = t.endswith('pcs')
    core = re.sub(r'\s*pcs$', '', t).strip()
    if kind == 'CODE':
        if has_pcs:
            return 5.0
        if re.fullmatch(r"[A-Z0-9Il]{2}[0-9OlISBZG]{3,7}", core):
            if re.search(r'[A-Z]', core[:2]):
                return 0.0
            return 1.0
        return 4.0
    if kind == 'QTY':
        if pcs:
            return 0.0 if has_pcs else 4.0
        if has_pcs:
            return 4.0
        if re.fullmatch(r"[0-9OlISBZG]{1,4}", core):
            return 0.0
        return 3.0
    if has_pcs:
        return 5.0
    if re.search(r"[.,']", core):
        return 0.0
    if re.fullmatch(r"[0-9OlISBZG]{3,}", core):
        return 0.8
    return 2.5


def _segment(toks, kinds, pcs):
    n = len(toks)
    if n == 0:
        return []
    INF = float('inf')
    dp = [[INF] * 4 for _ in range(n + 1)]
    bp = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    fits = [[_fit(t, k, pcs) for k in kinds] for t in toks]
    for i in range(n):
        for s in range(4):
            c = dp[i][s]
            if c == INF:
                continue
            ns = (s + 1) % 4
            cc = c + fits[i][s]
            if cc < dp[i + 1][ns]:
                dp[i + 1][ns] = cc
                bp[i + 1][ns] = (s, True)
            cs = c + 6.0
            if cs < dp[i + 1][s]:
                dp[i + 1][s] = cs
                bp[i + 1][s] = (s, False)
    s = 0
    used = []
    for i in range(n, 0, -1):
        e = bp[i][s]
        if e is None:
            break
        ps, u = e
        if u:
            used.append(i - 1)
        s = ps
    used.reverse()
    t2 = [toks[i] for i in used]
    return [t2[i:i + 4] for i in range(0, len(t2) - 3, 4)]


def _row_hyps(r, grouped, expensive, t0):
    qo, uo, ao = r['qo'], r['uo'], r['ao']
    q0 = _qexact(qo)
    u0 = _parse_canon(uo, grouped)
    a0 = _parse_canon(ao, grouped)
    if q0 and u0 and a0 and q0 * u0 == a0:
        r['Q'] = None
        return [(0.0, q0, u0, a0)]
    Q = _qty_cands(qo)
    U = _money_cands(uo, grouped)
    A = _money_cands(ao, grouped)
    r['Q'] = Q
    r['U'] = U
    r['A'] = A
    H = {}

    def put(c, q, u, a):
        if c >= CAP:
            return
        k = (q, u)
        e = H.get(k)
        if e is None or e[0] > c:
            H[k] = (c, q, u, a)
    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                put(cq + cu + ca, q, u, q * u)
    best = min([h[0] for h in H.values()]) if H else 99.0
    if best > 2.6 and expensive and time.process_time() - t0 < 0.7:
        lim = min(CAP, best + 4.5)
        for q, cq in Q.items():
            for a, ca in A.items():
                base = cq + ca
                if base + 3.5 >= lim or a % q:
                    continue
                u = a // q
                if u <= 0 or u in U:
                    continue
                put(base + _align(_render(u, grouped), uo), q, u, a)
        for u, cu in U.items():
            for a, ca in A.items():
                base = cu + ca
                if base + 3.5 >= lim or a % u:
                    continue
                q = a // u
                if q < 1 or q > 500 or q in Q:
                    continue
                put(base + _align(str(q), qo), q, u, a)
        la = len(ao)
        for q, cq in Q.items():
            if cq > 2.8:
                continue
            for u, cu in U.items():
                if cq + cu > 2.8:
                    continue
                a = q * u
                if a in A:
                    continue
                ra = _render(a, grouped)
                if cq + cu + 2.0 * abs(len(ra) - la) + 2.0 >= lim:
                    continue
                put(cq + cu + _align(ra, ao), q, u, a)
    hl = sorted(H.values())
    if hl:
        b = hl[0][0]
        hl = [h for h in hl if h[0] <= b + 7.0][:6]
        return hl
    q = min(Q.items(), key=lambda kv: (kv[1], kv[0]))[0] if Q else 1
    if U:
        u = min(U.items(), key=lambda kv: (kv[1], kv[0]))[0]
    elif A:
        a = min(A.items(), key=lambda kv: (kv[1], kv[0]))[0]
        u = max(1, a // q)
    else:
        u = 100
    hl = [(14.0, q, u, q * u)]
    if A:
        a = min(A.items(), key=lambda kv: (kv[1], kv[0]))[0]
        if a % q == 0 and a // q != u and a // q > 0:
            hl.append((14.5, q, a // q, a))
    return hl


def _make_tfn(S, obs, grouped):
    cache = {}

    def f(v):
        if obs is None:
            return 0.0
        c = S.get(v)
        if c is not None:
            return c
        if v not in cache:
            if v <= 0:
                cache[v] = 9.0
            else:
                cache[v] = min(_align(_render(v, grouped), obs), 9.0)
        return cache[v]
    return f


def _beam(hls, tfn, BW=300):
    beam = {0: (0.0, 0, 0)}
    hist = []
    for hl in hls:
        nb = {}
        for s, e in beam.items():
            c = e[0]
            for k, h in enumerate(hl):
                ns = s + h[3]
                nc = c + h[0]
                x = nb.get(ns)
                if x is None or x[0] > nc:
                    nb[ns] = (nc, s, k)
        if len(nb) > BW:
            nb = dict(sorted(nb.items(), key=lambda kv: (kv[1][0], kv[0]))[:BW])
        hist.append(nb)
        beam = nb
    fin = sorted(beam.items(), key=lambda kv: (kv[1][0], kv[0]))[:40]
    sc = sorted([(e[0] + tfn(s), s) for s, e in fin])
    return sc, hist


def _back(hist, s):
    ks = []
    for i in range(len(hist) - 1, -1, -1):
        c, ps, k = hist[i][s]
        ks.append(k)
        s = ps
    ks.reverse()
    return ks


def _repair(rows, ch, targets, grouped, cur_best, t0):
    total_rows = sum(h[0] for h in ch)
    cur_sum = sum(h[3] for h in ch)
    best = None
    idx = sorted(range(len(rows)), key=lambda i: (-ch[i][0], i))
    for i in idx:
        if time.process_time() - t0 > 0.8:
            break
        r = rows[i]
        if r.get('Q') is None:
            continue
        Q, U, A = r['Q'], r['U'], r['A']
        rest_c = total_rows - ch[i][0]
        rest_s = cur_sum - ch[i][3]
        for v, tc in targets:
            a = v - rest_s
            if a <= 0:
                continue
            base = rest_c + tc
            if base >= cur_best:
                continue
            ca = A.get(a)
            if ca is None:
                ca = _align(_render(a, grouped), r['ao'])
            if base + ca >= cur_best:
                continue
            for q, cq in Q.items():
                if a % q:
                    continue
                u = a // q
                if u <= 0:
                    continue
                cu = U.get(u)
                if cu is None:
                    if base + ca + cq + 3.5 >= cur_best:
                        continue
                    cu = _align(_render(u, grouped), r['uo'])
                tot = base + ca + cq + cu
                if tot < cur_best:
                    cur_best = tot
                    best = (i, (cq + cu + ca, q, u, a))
            for u, cu in U.items():
                if a % u:
                    continue
                q = a // u
                if q < 1 or q > 500 or q in Q:
                    continue
                if base + ca + cu + 3.5 >= cur_best:
                    continue
                cq = _align(str(q), r['qo'])
                tot = base + ca + cq + cu
                if tot < cur_best:
                    cur_best = tot
                    best = (i, (cq + cu + ca, q, u, a))
    if best is None:
        return None
    nch = list(ch)
    nch[best[0]] = best[1]
    return cur_best, nch


def _run(text, t0):
    lines = text.split('\n')
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sepkind = None
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln[ln.index('COLUMNS') + 7:]
            ms = list(re.finditer(r'CODE|QTY|UNIT|AMOUNT', body))
            names = [m.group(0) for m in ms]
            if len(ms) >= 4 and len(set(names[:4])) == 4:
                order = names[:4]
                bt = body[ms[0].end():ms[1].start()]
                if '|' in bt:
                    sepkind = 'pipe'
                elif ';' in bt:
                    sepkind = 'semi'
                elif '\t' in bt:
                    sepkind = 'tab'
                else:
                    sepkind = 'sp'
            break
    if sepkind is None:
        if ' | ' in text:
            sepkind = 'pipe'
        elif ';' in text:
            sepkind = 'semi'
        elif '\t' in text:
            sepkind = 'tab'
        else:
            sepkind = 'sp'
    pcs = 'pcs' in text
    sections = []
    cur = None
    total_tok = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if s.startswith('==') and 'SECTION' in s:
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
            continue
        m = re.fullmatch(r'SUBTOTAL\s+(\S+)', s)
        if m:
            if cur is None:
                cur = {'toks': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = m.group(1)
            cur = None
            continue
        m = re.fullmatch(r'TOTAL\s+(\S+)\s+ITEMS\s+(\S+)', s)
        if m:
            total_tok = m.group(1)
            cur = None
            continue
        toks = _split(s, sepkind)
        if not toks or not all(_fieldlike(t) for t in toks):
            continue
        if cur is None:
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
        cur['toks'].extend(toks)
    ci = order.index('CODE')
    qi = order.index('QTY')
    ui = order.index('UNIT')
    ai = order.index('AMOUNT')
    money_toks = []
    for sec in sections:
        chunks = _segment(sec['toks'], order, pcs)
        sec['chunks'] = chunks
        for c in chunks:
            money_toks.append(c[ui])
            money_toks.append(c[ai])
        if sec['sub']:
            money_toks.append(sec['sub'])
    if total_tok:
        money_toks.append(total_tok)
    grouped = any("'" in t for t in money_toks)
    secres = []
    for sec in sections:
        rows = []
        for c in sec['chunks']:
            rows.append({'code': _code_decode(c[ci]), 'qo': _norm_qty(c[qi]),
                         'uo': _norm_money(c[ui]), 'ao': _norm_money(c[ai])})
        if not rows:
            continue
        for r in rows:
            r['hl'] = _row_hyps(r, grouped, time.process_time() - t0 < 0.7, t0)
        subobs = _norm_money(sec['sub']) if sec['sub'] else None
        S = _money_cands(subobs, grouped) if subobs else {}
        tfn = _make_tfn(S, subobs, grouped)
        sc, hist = _beam([r['hl'] for r in rows], tfn)
        alts = []
        for tc, s in sc[:5]:
            ks = _back(hist, s)
            ch = [rows[i]['hl'][k] for i, k in enumerate(ks)]
            alts.append((tc, s, ch))
        if alts and alts[0][0] > 3.9 and subobs is not None and time.process_time() - t0 < 0.8:
            targets = sorted(S.items(), key=lambda kv: (kv[1], kv[0]))[:4]
            res = _repair(rows, alts[0][2], targets, grouped, alts[0][0], t0)
            if res:
                alts.insert(0, (res[0], sum(h[3] for h in res[1]), res[1]))
        secres.append({'rows': rows, 'alts': alts, 'tfn': tfn})
    if not secres:
        return []
    tobs = _norm_money(total_tok) if total_tok else None
    T = _money_cands(tobs, grouped) if tobs else {}
    ttf = _make_tfn(T, tobs, grouped)
    gb = {0: (0.0, [])}
    for sr in secres:
        nb = {}
        for s, (c, path) in gb.items():
            for j, (ac, asum, ch) in enumerate(sr['alts']):
                ns = s + asum
                nc = c + ac
                e = nb.get(ns)
                if e is None or e[0] > nc:
                    nb[ns] = (nc, path + [j])
        if len(nb) > 200:
            nb = dict(sorted(nb.items(), key=lambda kv: (kv[1][0], kv[0]))[:200])
        gb = nb
    bestg = None
    for s, (c, path) in gb.items():
        tot = c + ttf(s)
        if bestg is None or (tot, s) < (bestg[0], bestg[1]):
            bestg = (tot, s, path)
    chosen = []
    for i, sr in enumerate(secres):
        a = sr['alts'][bestg[2][i]]
        chosen.append([a[0], a[1], a[2]])
    if tobs is not None and time.process_time() - t0 < 0.8:
        gsum = sum(c[1] for c in chosen)
        tcur = ttf(gsum)
        if tcur > 1.9:
            T_top = sorted(T.items(), key=lambda kv: (kv[1], kv[0]))[:3]
            for i, sr in enumerate(secres):
                if time.process_time() - t0 > 0.85:
                    break
                ac, asum, ch = chosen[i]
                rest = gsum - asum
                targets = []
                for v, tc in T_top:
                    tg = v - rest
                    if tg > 0:
                        targets.append((tg, tc + sr['tfn'](tg)))
                if not targets:
                    continue
                res = _repair(sr['rows'], ch, targets, grouped, ac + tcur, t0)
                if res:
                    nch = res[1]
                    nsum = sum(h[3] for h in nch)
                    chosen[i] = [sum(h[0] for h in nch) + sr['tfn'](nsum), nsum, nch]
                    gsum = sum(c[1] for c in chosen)
                    tcur = ttf(gsum)
                    if tcur <= 1.9:
                        break
    items = []
    for i, sr in enumerate(secres):
        ch = chosen[i][2]
        for r, h in zip(sr['rows'], ch):
            items.append({'code': r['code'], 'qty': int(h[1]), 'unit_cents': int(h[2])})
    return items


def solve(state, params):
    t0 = time.process_time()
    inp = state.get('input') or {}
    text = inp.get('text', '') if isinstance(inp, dict) else ''
    if not isinstance(text, str):
        text = ''
    try:
        items = _run(text, t0)
    except Exception:
        items = []
    state['output'] = {'items': items}
    return state

import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INV_MIS = {}
for _o, _ss in MIS.items():
    for _s in _ss:
        INV_MIS[_s] = INV_MIS.get(_s, '') + _o
D2LSHOW = {'0': 'Oo', '1': 'lIi', '5': 'Ss', '8': 'B', '2': 'Zz', '6': 'G'}
L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
LET2DIG = {'O': '0', 'I': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6'}
DIG2LET = {v: k for k, v in LET2DIG.items()}
DIGITS = '0123456789'
SUBCAP = 4.0
TOTCAP = 4.0


def _subc(t, s):
    if t == s:
        return 0.0
    if t in DIGITS:
        if s in D2LSHOW.get(t, ''):
            return 1.0
        if s in MIS[t]:
            return 1.0
        if s in DIGITS:
            return 3.0
        return 4.0
    if t.isalpha():
        if LET2DIG.get(t) == s:
            return 1.0
        return 4.0
    if t in '.,' and s in '.,':
        return 2.0
    return 4.0


def dist(S, T):
    n = len(T)
    m = len(S)
    INF = 99.0
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            v = row[j]
            if v >= INF:
                continue
            if j < m and row[j + 1] > v + 3.0:
                row[j + 1] = v + 3.0
            if i < n:
                t = T[i]
                nxt = dp[i + 1]
                if t in DIGITS or t in '.,':
                    lc = 1.0
                elif t == "'":
                    lc = 1.5
                else:
                    lc = 3.0
                if nxt[j] > v + lc:
                    nxt[j] = v + lc
                if j < m:
                    c = v + _subc(t, S[j])
                    if nxt[j + 1] > c:
                        nxt[j + 1] = c
                    if j + 1 < m and t in DIGITS and S[j] == t and S[j + 1] == t:
                        if nxt[j + 2] > v + 1.0:
                            nxt[j + 2] = v + 1.0
    return dp[n][m]


def fmt_money(c, mark, grouped):
    ip = c // 100
    fp = c % 100
    s = str(ip)
    if grouped and len(s) > 3:
        parts = []
        while len(s) > 3:
            parts.append(s[-3:])
            s = s[:-3]
        parts.append(s)
        s = "'".join(reversed(parts))
    return s + mark + ('%02d' % fp)


def strip_pcs(tok):
    return re.sub(r'\s*pcs\s*$', '', tok.strip()).strip()


def normalize_num(tok, money):
    base = 0
    out = []
    for ch in tok:
        if ch in DIGITS:
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
            base += 1
        elif ch in '.,':
            if money:
                if 'M' in out:
                    base += 2
                else:
                    out.append('M')
            else:
                base += 2
        elif ch == "'" or ch == ' ':
            continue
        else:
            base += 2
    return tuple(out), base


def neighbors(s):
    res = set()
    L = len(s)
    for i in range(L):
        ch = s[i]
        if ch == 'M':
            continue
        for o in INV_MIS.get(ch, ''):
            res.add(s[:i] + (o,) + s[i + 1:])
        if i > 0 and s[i - 1] == ch:
            res.add(s[:i] + s[i + 1:])
    for i in range(L + 1):
        for d in DIGITS:
            res.add(s[:i] + (d,) + s[i:])
    return res


def eval_num(s, money):
    if money:
        if 'M' in s:
            k = s.index('M')
            ip = s[:k]
            fp = s[k + 1:]
            if len(fp) != 2 or len(ip) < 1:
                return None
            if len(ip) > 1 and ip[0] == '0':
                return None
            return int(''.join(ip) + ''.join(fp)), 0
        if len(s) < 3:
            return None
        ip = s[:-2]
        if len(ip) > 1 and ip[0] == '0':
            return None
        return int(''.join(s)), 1
    else:
        if len(s) < 1 or len(s) > 3:
            return None
        if s[0] == '0':
            return None
        v = int(''.join(s))
        if v < 1 or v > 500:
            return None
        return v, 0


def gen_num(tok, money, maxedits):
    start, base = normalize_num(tok, money)
    seen = {start: 0}
    frontier = [start]
    for lev in range(1, maxedits + 1):
        nf = []
        for s in frontier:
            for t in neighbors(s):
                if t not in seen:
                    seen[t] = lev
                    nf.append(t)
        frontier = nf
    out = {}
    for s, e in seen.items():
        r = eval_num(s, money)
        if r is None:
            continue
        v, x = r
        c = base + e + x
        if v not in out or out[v] > c:
            out[v] = c
    return out


def code_ok(c):
    if len(c) != 7:
        return False
    a, b = c[0], c[1]
    if not ('A' <= a <= 'Z' and 'A' <= b <= 'Z'):
        return False
    ds = c[2:]
    if not ds.isdigit():
        return False
    d = [int(x) for x in ds]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + ord(a) - 64 + ord(b) - 64) % 10 == d[4]


def fix_code(tok):
    s = re.sub(r'\s', '', tok)
    if len(s) < 2:
        s = (s + 'XX')[:2]
    lets = []
    base = 0
    for ch in s[:2]:
        if 'A' <= ch <= 'Z':
            lets.append([(ch, 0)])
        elif ch in DIG2LET:
            lets.append([(DIG2LET[ch], 1)])
        elif ch.isalpha():
            lets.append([(ch.upper(), 1)])
        else:
            lets.append([(chr(65 + k), 2) for k in range(26)])
    r = []
    for ch in s[2:]:
        if ch in DIGITS:
            r.append(ch)
        elif ch in L2D:
            r.append(L2D[ch])
            base += 1
        else:
            base += 2
    start = tuple(r)
    seen = {start: 0}
    frontier = [start]
    best = None
    for lev in range(0, 3):
        if lev > 0:
            nf = []
            for x in frontier:
                for t in neighbors(x):
                    if t not in seen:
                        seen[t] = lev
                        nf.append(t)
            frontier = nf
        cands = []
        for x in frontier:
            if len(x) != 5:
                continue
            ds = ''.join(x)
            for l1, c1 in lets[0]:
                for l2, c2 in lets[1]:
                    c = l1 + l2 + ds
                    if code_ok(c):
                        cands.append((base + lev + c1 + c2, c))
        if cands:
            cands.sort()
            best = cands[0]
            break
    if best is not None:
        return best[1]
    ds = ''.join(start)
    ds = (ds + '00000')[:5]
    return lets[0][0][0] + lets[1][0][0] + ds


KEY_RE = re.compile(r'\b(CODE|QTY|UNIT|AMOUNT)\b')
CODEISH = re.compile(r"^[A-Za-z0-9]{2}[0-9OolIiSsBZzG]{2,8}$")
NUMISH = re.compile(r"^[0-9OolIiSsBZzG.,']*(\s*pcs)?$")


def tok_cost(tok, col):
    if tok == '':
        return 1.0
    has_pcs = 'pcs' in tok
    t = strip_pcs(tok)
    has_mark = ('.' in t) or (',' in t)
    strong_code = any(ch.isalpha() and ch not in 'OlSBZG' for ch in t)
    weak_code = (len(t) >= 5 and not has_mark and "'" not in t
                 and len(t) >= 2 and t[0].isalpha() and t[1].isalpha())
    if col == 'CODE':
        if strong_code:
            return 0.0
        if weak_code:
            return 0.5
        if has_mark or has_pcs or "'" in t:
            return 5.0
        return 2.5
    if strong_code:
        return 5.0
    extra = 1.5 if weak_code else 0.0
    if col == 'QTY':
        if has_pcs:
            return 0.0 + extra
        if has_mark or "'" in t:
            return 3.0 + extra
        L = len(t)
        if L <= 3:
            return 0.0 + extra
        if L == 4:
            return 0.7 + extra
        return 2.0 + extra
    if has_pcs:
        return 5.0
    if has_mark:
        return 0.0 + extra
    return (1.0 if len(t) >= 3 else 2.0) + extra


def segment(toks, order):
    n = len(toks)
    INF = 1e18
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(4):
            for c in range(4):
                if dp[i][c] < INF:
                    nc = (c + 1) % 4
                    v = dp[i][c] + 3.0
                    if v < dp[i][nc] - 1e-12:
                        dp[i][nc] = v
                        bk[i][nc] = ('miss', i, c)
        if i == n:
            break
        tok = toks[i]
        for c in range(4):
            if dp[i][c] >= INF:
                continue
            nc = (c + 1) % 4
            v = dp[i][c] + tok_cost(tok, order[c])
            if v < dp[i + 1][nc] - 1e-12:
                dp[i + 1][nc] = v
                bk[i + 1][nc] = ('use', i, c)
            v = dp[i][c] + (2.0 if tok == '' else 6.0)
            if v < dp[i + 1][c] - 1e-12:
                dp[i + 1][c] = v
                bk[i + 1][c] = ('skip', i, c)
    ops = []
    i, c = n, 0
    guard = 0
    while bk[i][c] is not None and guard < 10 * (n + 10):
        op, pi, pc = bk[i][c]
        ops.append((op, pi))
        i, c = pi, pc
        guard += 1
    ops.reverse()
    rows = []
    cur = {}
    c = 0
    for op, ti in ops:
        if op == 'skip':
            continue
        cur[order[c]] = toks[ti] if op == 'use' else ''
        c += 1
        if c == 4:
            if any(cur[k] for k in order):
                rows.append(cur)
            cur = {}
            c = 0
    return rows


def parse_doc(text):
    lines = text.replace('\r', '').split('\n')
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        st = ln.strip()
        if st.startswith('COLUMNS'):
            ms = list(KEY_RE.finditer(ln))
            if len(ms) >= 2:
                names = [m.group(1) for m in ms]
                if len(names) == 4 and len(set(names)) == 4:
                    order = names
                sp = ln[ms[0].end():ms[1].start()]
                if '|' in sp:
                    sep = '|'
                elif ';' in sp:
                    sep = ';'
                elif '\t' in sp:
                    sep = '\t'
                else:
                    sep = '   '
            break

    def split_line(s):
        if sep in ('|', ';', '\t'):
            return [t.strip() for t in s.split(sep)]
        return [t.strip() for t in s.split('   ')]

    def is_data(toks):
        if not [t for t in toks if t]:
            return False
        for t in toks:
            if not t:
                continue
            if CODEISH.match(t) or NUMISH.match(t):
                continue
            return False
        return True

    sections = []
    cur = None
    total_tok = None
    items_tok = None
    for ln in lines:
        st = ln.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^==\s*SECTION', st):
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', st)
            if m:
                total_tok = m.group(1).strip()
                items_tok = m.group(2).strip()
            else:
                total_tok = st[5:].strip()
            continue
        toks = split_line(ln)
        if not is_data(toks):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
        cur['tokens'].extend(toks)
    out_secs = []
    for sec in sections:
        rows = segment(sec['tokens'], order)
        if rows or sec['sub'] is not None:
            out_secs.append({'rows': rows, 'sub': sec['sub']})
    return out_secs, total_tok, items_tok


def detect_style(secs, total_tok):
    toks = []
    for sec in secs:
        for r in sec['rows']:
            toks.append(r['UNIT'])
            toks.append(r['AMOUNT'])
        if sec['sub']:
            toks.append(sec['sub'])
    if total_tok:
        toks.append(total_tok)
    dot = sum(t.count('.') for t in toks)
    com = sum(t.count(',') for t in toks)
    mark = ',' if com > dot else '.'
    grouped = any("'" in t for t in toks)
    return mark, grouped


def row_candidates(row, ctx, K):
    mark = ctx['mark']
    grouped = ctx['grouped']
    qtok = strip_pcs(row['QTY'])
    utok = row['UNIT'].strip()
    atok = row['AMOUNT'].strip()
    Q = gen_num(qtok, False, 1)
    U = gen_num(utok, True, 1)
    A = gen_num(atok, True, 1)
    cands = {}

    def add(q, u, a, c):
        key = (q, u)
        if key not in cands or cands[key][0] > c:
            cands[key] = (c, q, u, a)

    for q, cq in Q.items():
        for u, cu in U.items():
            a = q * u
            ca = A.get(a)
            if ca is not None:
                add(q, u, a, cq + cu + ca)
    best = min([v[0] for v in cands.values()]) if cands else 99
    if best >= 2 and time.perf_counter() < ctx['deadline']:
        cache = {}

        def dmon(tok, v):
            k = ('m', tok, v)
            if k not in cache:
                cache[k] = dist(tok, fmt_money(v, mark, grouped))
            return cache[k]

        def dq(v):
            k = ('q', v)
            if k not in cache:
                cache[k] = dist(qtok, str(v))
            return cache[k]

        for lim in (0, 1):
            Q0 = [(q, c) for q, c in Q.items() if c <= lim]
            U0 = [(u, c) for u, c in U.items() if c <= lim]
            A0 = [(a, c) for a, c in A.items() if c <= lim]
            for q, cq in Q0:
                for u, cu in U0:
                    if cq + cu <= lim:
                        a = q * u
                        add(q, u, a, cq + cu + dmon(atok, a))
                for a, ca in A0:
                    if cq + ca <= lim and a > 0 and a % q == 0:
                        u = a // q
                        add(q, u, a, cq + ca + dmon(utok, u))
            for u, cu in U0:
                if u <= 0:
                    continue
                for a, ca in A0:
                    if cu + ca <= lim and a % u == 0:
                        q = a // u
                        if 1 <= q <= 500:
                            add(q, u, a, cu + ca + dq(q))
            best = min([v[0] for v in cands.values()]) if cands else 99
            if best < 3 or time.perf_counter() > ctx['deadline']:
                break
    if not cands:
        q = min(Q.items(), key=lambda x: (x[1], x[0]))[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: (x[1], x[0]))[0]
        elif A:
            a0 = min(A.items(), key=lambda x: (x[1], x[0]))[0]
            u = a0 // q
        else:
            u = 0
        add(q, u, q * u, 9.0)
    lst = sorted(cands.values(), key=lambda x: (x[0], x[1], x[2]))
    return lst[:K]


def section_search(rcands, subtok, ctx, B=400, M=40, DEV=6.0):
    states = {0: (0.0, ())}
    for cl in rcands:
        ns = {}
        for s, (c, path) in states.items():
            for ci, (rc, q, u, a) in enumerate(cl):
                t = s + a
                nc = c + rc
                if t not in ns or ns[t][0] > nc:
                    ns[t] = (nc, path + (ci,))
        if not ns:
            continue
        items = sorted(ns.items(), key=lambda x: x[1][0])
        bc = items[0][1][0]
        items = [it for it in items if it[1][0] <= bc + DEV][:B]
        states = dict(items)
    items = sorted(states.items(), key=lambda x: x[1][0])
    res = []
    if subtok is None:
        for s, (c, path) in items[:M]:
            res.append((c, s, path))
        return res
    S1 = gen_num(subtok, True, 1)
    mark = ctx['mark']
    grouped = ctx['grouped']
    for idx, (s, (c, path)) in enumerate(items):
        sc = S1.get(s)
        if sc is None:
            if idx < 40 and time.perf_counter() < ctx['deadline'] + 0.1:
                sc = dist(subtok, fmt_money(s, mark, grouped))
            else:
                sc = SUBCAP
        sc = min(sc, SUBCAP)
        res.append((c + sc, s, path))
    res.sort(key=lambda x: x[0])
    return res[:M]


def _solve_text(text, t0):
    secs, total_tok, items_tok = parse_doc(text)
    mark, grouped = detect_style(secs, total_tok)
    ctx = {'mark': mark, 'grouped': grouped, 'deadline': t0 + 0.5}
    all_rc = []
    codes = []
    for sec in secs:
        rcs = []
        cs = []
        for r in sec['rows']:
            rcs.append(row_candidates(r, ctx, 8))
            cs.append(fix_code(r['CODE']))
        all_rc.append(rcs)
        codes.append(cs)
    sec_res = []
    for si, sec in enumerate(secs):
        sec_res.append(section_search(all_rc[si], sec['sub'], ctx))
    states = {0: (0.0, ())}
    for si in range(len(sec_res)):
        res = sec_res[si]
        if not res:
            res = [(0.0, 0, ())]
            sec_res[si] = res
        ns = {}
        for s, (c, ch) in states.items():
            for k, (sc, ss, path) in enumerate(res):
                t = s + ss
                nc = c + sc
                if t not in ns or ns[t][0] > nc:
                    ns[t] = (nc, ch + (k,))
        items = sorted(ns.items(), key=lambda x: x[1][0])[:500]
        states = dict(items)
    items = sorted(states.items(), key=lambda x: x[1][0])
    best = None
    if total_tok and items:
        T1 = gen_num(total_tok, True, 1)
        for idx, (s, (c, ch)) in enumerate(items):
            tc = T1.get(s)
            if tc is None:
                if idx < 40 and time.perf_counter() < ctx['deadline'] + 0.2:
                    tc = dist(total_tok, fmt_money(s, mark, grouped))
                else:
                    tc = TOTCAP
            tc = min(tc, TOTCAP)
            v = c + tc
            if best is None or v < best[0]:
                best = (v, ch)
    elif items:
        best = (items[0][1][0], items[0][1][1])
    choice = best[1] if best else ()
    out = []
    for si in range(len(secs)):
        res = sec_res[si]
        if res and si < len(choice) and choice[si] < len(res):
            path = res[choice[si]][2]
        else:
            path = ()
        for ri in range(len(all_rc[si])):
            ci = path[ri] if ri < len(path) else 0
            cl = all_rc[si][ri]
            rc = cl[ci] if ci < len(cl) else cl[0]
            out.append({'code': codes[si][ri], 'qty': int(rc[1]), 'unit_cents': int(rc[2])})
    return out


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get('input', {}) or {}
    text = inp.get('text', '') or ''
    try:
        items = _solve_text(text, t0)
    except Exception:
        items = []
    state['output'] = {'items': items}
    return state

import re
import time
import heapq

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INV_MIS = {}
for _o, _ss in MIS.items():
    for _s in _ss:
        INV_MIS[_s] = INV_MIS.get(_s, '') + _o
D2LSHOW = {'0': 'Oo', '1': 'lIi', '5': 'Ss', '8': 'B', '2': 'Zz', '6': 'G'}
L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
LET2DIG = {'O': '0', 'I': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6'}
DIG2LET = {v: k for k, v in LET2DIG.items()}
DIGITS = '0123456789'
SUBCAP = 4.0
TOTCAP = 4.0


def _subc(t, s):
    if t == s:
        return 0.0
    if t in DIGITS:
        if s in D2LSHOW.get(t, ''):
            return 1.0
        if s in MIS[t]:
            return 1.0
        if s in DIGITS:
            return 3.0
        return 4.0
    if t.isalpha():
        if LET2DIG.get(t) == s:
            return 1.0
        return 4.0
    if t in '.,' and s in '.,':
        return 2.0
    return 4.0


def dist(S, T):
    n = len(T)
    m = len(S)
    INF = 99.0
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            v = row[j]
            if v >= INF:
                continue
            if j < m and row[j + 1] > v + 3.0:
                row[j + 1] = v + 3.0
            if i < n:
                t = T[i]
                nxt = dp[i + 1]
                if t in DIGITS or t in '.,':
                    lc = 1.0
                elif t == "'":
                    lc = 1.5
                else:
                    lc = 3.0
                if nxt[j] > v + lc:
                    nxt[j] = v + lc
                if j < m:
                    c = v + _subc(t, S[j])
                    if nxt[j + 1] > c:
                        nxt[j + 1] = c
                    if j + 1 < m and t in DIGITS and S[j] == t and S[j + 1] == t:
                        if nxt[j + 2] > v + 1.0:
                            nxt[j + 2] = v + 1.0
    return dp[n][m]


def fmt_money(c, mark, grouped):
    ip = c // 100
    fp = c % 100
    s = str(ip)
    if grouped and len(s) > 3:
        parts = []
        while len(s) > 3:
            parts.append(s[-3:])
            s = s[:-3]
        parts.append(s)
        s = "'".join(reversed(parts))
    return s + mark + ('%02d' % fp)


def strip_pcs(tok):
    return re.sub(r'\s*pcs\s*$', '', tok.strip()).strip()


def normalize_num(tok, money):
    base = 0
    out = []
    for ch in tok:
        if ch in DIGITS:
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
            base += 1
        elif ch in '.,':
            if money:
                if 'M' in out:
                    base += 2
                else:
                    out.append('M')
            else:
                base += 2
        elif ch == "'" or ch == ' ':
            continue
        else:
            base += 2
    return tuple(out), base


def neighbors(s):
    res = set()
    L = len(s)
    for i in range(L):
        ch = s[i]
        if ch == 'M':
            continue
        for o in INV_MIS.get(ch, ''):
            res.add(s[:i] + (o,) + s[i + 1:])
        if i > 0 and s[i - 1] == ch:
            res.add(s[:i] + s[i + 1:])
    for i in range(L + 1):
        for d in DIGITS:
            res.add(s[:i] + (d,) + s[i:])
    return res


def eval_num(s, money):
    if money:
        if 'M' in s:
            k = s.index('M')
            ip = s[:k]
            fp = s[k + 1:]
            if len(fp) != 2 or len(ip) < 1:
                return None
            if len(ip) > 1 and ip[0] == '0':
                return None
            return int(''.join(ip) + ''.join(fp)), 0
        if len(s) < 3:
            return None
        ip = s[:-2]
        if len(ip) > 1 and ip[0] == '0':
            return None
        return int(''.join(s)), 1
    else:
        if len(s) < 1 or len(s) > 3:
            return None
        if s[0] == '0':
            return None
        v = int(''.join(s))
        if v < 1 or v > 500:
            return None
        return v, 0


def gen_num(tok, money, maxedits):
    start, base = normalize_num(tok, money)
    seen = {start: 0}
    frontier = [start]
    for lev in range(1, maxedits + 1):
        nf = []
        for s in frontier:
            for t in neighbors(s):
                if t not in seen:
                    seen[t] = lev
                    nf.append(t)
        frontier = nf
    out = {}
    for s, e in seen.items():
        r = eval_num(s, money)
        if r is None:
            continue
        v, x = r
        c = base + e + x
        if v not in out or out[v] > c:
            out[v] = c
    return out


def code_ok(c):
    if len(c) != 7:
        return False
    a, b = c[0], c[1]
    if not ('A' <= a <= 'Z' and 'A' <= b <= 'Z'):
        return False
    ds = c[2:]
    if not ds.isdigit():
        return False
    d = [int(x) for x in ds]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + ord(a) - 64 + ord(b) - 64) % 10 == d[4]


def _check_for(l1, l2, d4):
    return (int(d4[0]) + 2 * int(d4[1]) + 3 * int(d4[2]) + 4 * int(d4[3]) + ord(l1) - 64 + ord(l2) - 64) % 10


def fix_code(tok):
    s = re.sub(r'\s', '', tok)
    if len(s) < 2:
        s = (s + 'XX')[:2]
    lets = []
    base = 0.0
    for ch in s[:2]:
        if 'A' <= ch <= 'Z':
            lets.append([(ch, 0.0)])
        elif ch in DIG2LET:
            lets.append([(DIG2LET[ch], 1.0)])
        elif ch.isalpha():
            lets.append([(ch.upper(), 1.0)])
        else:
            lets.append([(chr(65 + k), 2.0) for k in range(26)])
    r = []
    for ch in s[2:]:
        if ch in DIGITS:
            r.append(ch)
        elif ch in L2D:
            r.append(L2D[ch])
            base += 1.0
        else:
            base += 2.0
    start = tuple(r)
    L = len(start)
    limit = 3.2 if L in (4, 5, 6) else abs(L - 5) + 1.2
    heap = [(0.0, start)]
    bestc = {start: 0.0}
    cands = []
    pops = 0
    while heap and pops < 25000:
        c, x = heapq.heappop(heap)
        if c > bestc.get(x, 99.0) + 1e-9:
            continue
        pops += 1
        n = len(x)
        if n == 5:
            ds = ''.join(x)
            cd = int(ds[4])
            for l1, c1 in lets[0]:
                for l2, c2 in lets[1]:
                    if _check_for(l1, l2, ds[:4]) == cd:
                        cands.append((base + c + c1 + c2, l1 + l2 + ds))
        moves = []
        for i in range(n):
            ch = x[i]
            for o in INV_MIS.get(ch, ''):
                moves.append((0.9 if o == '2' else 1.0, x[:i] + (o,) + x[i + 1:]))
        if n < 5:
            for i in range(n + 1):
                for d in DIGITS:
                    adj = (i > 0 and x[i - 1] == d) or (i < n and x[i] == d)
                    moves.append((0.95 if adj else 1.0, x[:i] + (d,) + x[i:]))
        if n > 5:
            for i in range(n):
                if i > 0 and x[i] == x[i - 1]:
                    moves.append((1.0, x[:i] + x[i + 1:]))
                else:
                    moves.append((2.0, x[:i] + x[i + 1:]))
        for mc, y in moves:
            nc = c + mc
            if nc + 0.95 * abs(len(y) - 5) > limit:
                continue
            if nc < bestc.get(y, 99.0) - 1e-9:
                bestc[y] = nc
                heapq.heappush(heap, (nc, y))
    if cands:
        cands.sort()
        return cands[0][1]
    ds = ''.join(start)
    ds = (ds + '00000')[:4]
    l1 = lets[0][0][0]
    l2 = lets[1][0][0]
    return l1 + l2 + ds + str(_check_for(l1, l2, ds))


KEY_RE = re.compile(r'\b(CODE|QTY|UNIT|AMOUNT)\b')
CODEISH = re.compile(r"^[A-Za-z0-9]{2}[0-9OolIiSsBZzG]{2,8}$")
NUMISH = re.compile(r"^[0-9OolIiSsBZzG.,']*(\s*pcs)?$")


def tok_cost(tok, col):
    if tok == '':
        return 1.0
    has_pcs = 'pcs' in tok
    t = strip_pcs(tok)
    has_mark = ('.' in t) or (',' in t)
    strong_code = any(ch.isalpha() and ch not in 'OlSBZG' for ch in t)
    weak_code = (len(t) >= 5 and not has_mark and "'" not in t
                 and len(t) >= 2 and t[0].isalpha() and t[1].isalpha())
    if col == 'CODE':
        if strong_code:
            return 0.0
        if weak_code:
            return 0.5
        if has_mark or has_pcs or "'" in t:
            return 5.0
        return 2.5
    if strong_code:
        return 5.0
    extra = 1.5 if weak_code else 0.0
    if col == 'QTY':
        if has_pcs:
            return 0.0 + extra
        if has_mark or "'" in t:
            return 3.0 + extra
        L = len(t)
        if L <= 3:
            return 0.0 + extra
        if L == 4:
            return 0.7 + extra
        return 2.0 + extra
    if has_pcs:
        return 5.0
    if has_mark:
        return 0.0 + extra
    return (1.0 if len(t) >= 3 else 2.0) + extra


def segment(toks, order):
    n = len(toks)
    INF = 1e18
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(4):
            for c in range(4):
                if dp[i][c] < INF:
                    nc = (c + 1) % 4
                    v = dp[i][c] + 3.0
                    if v < dp[i][nc] - 1e-12:
                        dp[i][nc] = v
                        bk[i][nc] = ('miss', i, c)
        if i == n:
            break
        tok = toks[i]
        for c in range(4):
            if dp[i][c] >= INF:
                continue
            nc = (c + 1) % 4
            v = dp[i][c] + tok_cost(tok, order[c])
            if v < dp[i + 1][nc] - 1e-12:
                dp[i + 1][nc] = v
                bk[i + 1][nc] = ('use', i, c)
            v = dp[i][c] + (2.0 if tok == '' else 6.0)
            if v < dp[i + 1][c] - 1e-12:
                dp[i + 1][c] = v
                bk[i + 1][c] = ('skip', i, c)
    ops = []
    i, c = n, 0
    guard = 0
    while bk[i][c] is not None and guard < 10 * (n + 10):
        op, pi, pc = bk[i][c]
        ops.append((op, pi))
        i, c = pi, pc
        guard += 1
    ops.reverse()
    rows = []
    cur = {}
    c = 0
    for op, ti in ops:
        if op == 'skip':
            continue
        cur[order[c]] = toks[ti] if op == 'use' else ''
        c += 1
        if c == 4:
            if any(cur[k] for k in order):
                rows.append(cur)
            cur = {}
            c = 0
    return rows


def parse_doc(text):
    lines = text.replace('\r', '').split('\n')
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        st = ln.strip()
        if st.startswith('COLUMNS'):
            ms = list(KEY_RE.finditer(ln))
            if len(ms) >= 2:
                names = [m.group(1) for m in ms]
                if len(names) == 4 and len(set(names)) == 4:
                    order = names
                sp = ln[ms[0].end():ms[1].start()]
                if '|' in sp:
                    sep = '|'
                elif ';' in sp:
                    sep = ';'
                elif '\t' in sp:
                    sep = '\t'
                else:
                    sep = '   '
            break

    def split_line(s):
        if sep in ('|', ';', '\t'):
            return [t.strip() for t in s.split(sep)]
        return [t.strip() for t in s.split('   ')]

    def is_data(toks):
        if not [t for t in toks if t]:
            return False
        for t in toks:
            if not t:
                continue
            if CODEISH.match(t) or NUMISH.match(t):
                continue
            return False
        return True

    sections = []
    cur = None
    total_tok = None
    items_tok = None
    for ln in lines:
        st = ln.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^==\s*SECTION', st):
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', st)
            if m:
                total_tok = m.group(1).strip()
                items_tok = m.group(2).strip()
            else:
                total_tok = st[5:].strip()
            continue
        toks = split_line(ln)
        if not is_data(toks):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
        cur['tokens'].extend(toks)
    out_secs = []
    for sec in sections:
        rows = segment(sec['tokens'], order)
        if rows or sec['sub'] is not None:
            out_secs.append({'rows': rows, 'sub': sec['sub']})
    return out_secs, total_tok, items_tok


def detect_style(secs, total_tok):
    toks = []
    for sec in secs:
        for r in sec['rows']:
            toks.append(r['UNIT'])
            toks.append(r['AMOUNT'])
        if sec['sub']:
            toks.append(sec['sub'])
    if total_tok:
        toks.append(total_tok)
    dot = sum(t.count('.') for t in toks)
    com = sum(t.count(',') for t in toks)
    mark = ',' if com > dot else '.'
    grouped = any("'" in t for t in toks)
    return mark, grouped


def row_candidates(row, ctx, K):
    mark = ctx['mark']
    grouped = ctx['grouped']
    qtok = strip_pcs(row['QTY'])
    utok = row['UNIT'].strip()
    atok = row['AMOUNT'].strip()
    Q = gen_num(qtok, False, 1)
    U = gen_num(utok, True, 1)
    A = gen_num(atok, True, 1)
    cands = {}

    def add(q, u, a, c):
        key = (q, u)
        if key not in cands or cands[key][0] > c:
            cands[key] = (c, q, u, a)

    for q, cq in Q.items():
        for u, cu in U.items():
            a = q * u
            ca = A.get(a)
            if ca is not None:
                add(q, u, a, cq + cu + ca)
    best = min([v[0] for v in cands.values()]) if cands else 99
    if best >= 2 and time.perf_counter() < ctx['deadline']:
        cache = {}

        def dmon(tok, v):
            k = ('m', tok, v)
            if k not in cache:
                cache[k] = dist(tok, fmt_money(v, mark, grouped))
            return cache[k]

        def dq(v):
            k = ('q', v)
            if k not in cache:
                cache[k] = dist(qtok, str(v))
            return cache[k]

        for lim in (0, 1):
            Q0 = [(q, c) for q, c in Q.items() if c <= lim]
            U0 = [(u, c) for u, c in U.items() if c <= lim]
            A0 = [(a, c) for a, c in A.items() if c <= lim]
            for q, cq in Q0:
                for u, cu in U0:
                    if cq + cu <= lim:
                        a = q * u
                        add(q, u, a, cq + cu + dmon(atok, a))
                for a, ca in A0:
                    if cq + ca <= lim and a > 0 and a % q == 0:
                        u = a // q
                        add(q, u, a, cq + ca + dmon(utok, u))
            for u, cu in U0:
                if u <= 0:
                    continue
                for a, ca in A0:
                    if cu + ca <= lim and a % u == 0:
                        q = a // u
                        if 1 <= q <= 500:
                            add(q, u, a, cu + ca + dq(q))
            best = min([v[0] for v in cands.values()]) if cands else 99
            if best < 3 or time.perf_counter() > ctx['deadline']:
                break
    if not cands:
        q = min(Q.items(), key=lambda x: (x[1], x[0]))[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: (x[1], x[0]))[0]
        elif A:
            a0 = min(A.items(), key=lambda x: (x[1], x[0]))[0]
            u = a0 // q
        else:
            u = 0
        add(q, u, q * u, 9.0)
    lst = sorted(cands.values(), key=lambda x: (x[0], x[1], x[2]))
    return [list(x) for x in lst[:K]]


def section_search(rcands, subtok, ctx, B=400, M=40, DEV=6.0):
    states = {0: (0.0, ())}
    for cl in rcands:
        ns = {}
        for s, (c, path) in states.items():
            for ci, rc in enumerate(cl):
                t = s + rc[3]
                nc = c + rc[0]
                if t not in ns or ns[t][0] > nc:
                    ns[t] = (nc, path + (ci,))
        if not ns:
            continue
        items = sorted(ns.items(), key=lambda x: x[1][0])
        bc = items[0][1][0]
        items = [it for it in items if it[1][0] <= bc + DEV][:B]
        states = dict(items)
    items = sorted(states.items(), key=lambda x: x[1][0])
    res = []
    if subtok is None:
        for s, (c, path) in items[:M]:
            res.append((c, s, path))
        return res
    S1 = gen_num(subtok, True, 1)
    mark = ctx['mark']
    grouped = ctx['grouped']
    for idx, (s, (c, path)) in enumerate(items):
        sc = S1.get(s)
        if sc is None:
            if idx < 40 and time.perf_counter() < ctx['deadline'] + 0.1:
                sc = dist(subtok, fmt_money(s, mark, grouped))
            else:
                sc = SUBCAP
        sc = min(sc, SUBCAP)
        res.append((c + sc, s, path))
    res.sort(key=lambda x: x[0])
    return res[:M]


def residual_fill(rcands, rows, subtok, ctx, res):
    if not subtok or not res or not rcands:
        return False
    mark = ctx['mark']
    grouped = ctx['grouped']
    S1 = gen_num(subtok, True, 1)
    c0, s0, path = res[0]
    if S1.get(s0, 99) == 0:
        return False
    Ss = sorted(S1.items(), key=lambda x: (x[1], x[0]))
    Ss = [v for v, c in Ss if c <= 1][:14]
    if not Ss or len(path) != len(rcands):
        return False
    picks = [rcands[i][path[i]] for i in range(len(rcands))]
    order = sorted(range(len(rcands)), key=lambda i: -picks[i][0])
    cand_rows = [i for i in order if picks[i][0] >= 1][:6]
    if not cand_rows:
        cand_rows = order[:3]
    changed = False
    for i in cand_rows:
        if time.perf_counter() > ctx['deadline2']:
            break
        row = rows[i]
        qtok = strip_pcs(row['QTY'])
        utok = row['UNIT'].strip()
        atok = row['AMOUNT'].strip()
        others = s0 - picks[i][3]
        Q2 = gen_num(qtok, False, 2)
        U1 = gen_num(utok, True, 1)
        existing = set((x[1], x[2]) for x in rcands[i])
        newc = {}
        for S in Ss:
            a = S - others
            if a <= 0:
                continue
            ca = dist(atok, fmt_money(a, mark, grouped))
            if ca > 4.0:
                continue
            for q, cq in Q2.items():
                if a % q == 0:
                    u = a // q
                    cu = U1.get(u)
                    if cu is None:
                        if cq + ca > 4.5:
                            continue
                        cu = dist(utok, fmt_money(u, mark, grouped))
                    c = cq + cu + ca
                    if c <= 5.0:
                        k = (q, u)
                        if k not in newc or newc[k][0] > c:
                            newc[k] = [c, q, u, a]
            for u, cu in U1.items():
                if u > 0 and a % u == 0:
                    q = a // u
                    if 1 <= q <= 500:
                        cq = Q2.get(q)
                        if cq is None:
                            cq = dist(qtok, str(q))
                        c = cq + cu + ca
                        if c <= 5.0:
                            k = (q, u)
                            if k not in newc or newc[k][0] > c:
                                newc[k] = [c, q, u, a]
        add = sorted([v for k, v in newc.items() if k not in existing], key=lambda x: (x[0], x[1], x[2]))[:4]
        if add:
            rcands[i].extend(add)
            changed = True
    return changed


def _solve_text(text, t0):
    secs, total_tok, items_tok = parse_doc(text)
    mark, grouped = detect_style(secs, total_tok)
    ctx = {'mark': mark, 'grouped': grouped, 'deadline': t0 + 0.45, 'deadline2': t0 + 0.7}
    all_rc = []
    codes = []
    for sec in secs:
        rcs = []
        cs = []
        for r in sec['rows']:
            rcs.append(row_candidates(r, ctx, 8))
            cs.append(fix_code(r['CODE']))
        all_rc.append(rcs)
        codes.append(cs)
    sec_res = []
    for si, sec in enumerate(secs):
        res = section_search(all_rc[si], sec['sub'], ctx)
        try:
            if residual_fill(all_rc[si], sec['rows'], sec['sub'], ctx, res):
                res = section_search(all_rc[si], sec['sub'], ctx)
        except Exception:
            pass
        sec_res.append(res)
    states = {0: (0.0, ())}
    for si in range(len(sec_res)):
        res = sec_res[si]
        if not res:
            res = [(0.0, 0, ())]
            sec_res[si] = res
        ns = {}
        for s, (c, ch) in states.items():
            for k, (sc, ss, path) in enumerate(res):
                t = s + ss
                nc = c + sc
                if t not in ns or ns[t][0] > nc:
                    ns[t] = (nc, ch + (k,))
        items = sorted(ns.items(), key=lambda x: x[1][0])[:500]
        states = dict(items)
    items = sorted(states.items(), key=lambda x: x[1][0])
    best = None
    if total_tok and items:
        T1 = gen_num(total_tok, True, 1)
        for idx, (s, (c, ch)) in enumerate(items):
            tc = T1.get(s)
            if tc is None:
                if idx < 40 and time.perf_counter() < ctx['deadline2'] + 0.1:
                    tc = dist(total_tok, fmt_money(s, mark, grouped))
                else:
                    tc = TOTCAP
            tc = min(tc, TOTCAP)
            v = c + tc
            if best is None or v < best[0]:
                best = (v, ch)
    elif items:
        best = (items[0][1][0], items[0][1][1])
    choice = best[1] if best else ()
    out = []
    for si in range(len(secs)):
        res = sec_res[si]
        if res and si < len(choice) and choice[si] < len(res):
            path = res[choice[si]][2]
        else:
            path = ()
        for ri in range(len(all_rc[si])):
            ci = path[ri] if ri < len(path) else 0
            cl = all_rc[si][ri]
            rc = cl[ci] if ci < len(cl) else cl[0]
            out.append({'code': codes[si][ri], 'qty': int(rc[1]), 'unit_cents': int(rc[2])})
    return out


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get('input', {}) or {}
    text = inp.get('text', '') or ''
    try:
        items = _solve_text(text, t0)
    except Exception:
        items = []
    state['output'] = {'items': items}
    return state

import re
import time

COLNAMES = ("CODE", "QTY", "UNIT", "AMOUNT")
# shown look-alike letter -> true digit
LOOK_D = {"O": "0", "o": "0", "D": "0", "Q": "0", "l": "1", "I": "1", "i": "1", "L": "1", "|": "1",
          "S": "5", "s": "5", "B": "8", "Z": "2", "z": "2", "G": "6", "b": "6"}
# shown look-alike digit -> true code letter
LOOK_L = {"0": "O", "1": "I", "5": "S", "8": "B", "2": "Z", "6": "G"}
# shown digit -> possible true digits (inverse of the misread channel)
INV_MIS = {"6": "05", "8": "03", "7": "12", "4": "19", "9": "34", "1": "47", "3": "58",
           "0": "68", "5": "6", "2": "7"}
ALLD = "0123456789"


# ---------------------------------------------------------------- channel inversion
def _single_edits(s, b):
    """s: digit string ('?' = unreadable char); b: integer-part length or None (mark lost).
    Yields (s2, b2) obtained by inverting one channel operation."""
    n = len(s)
    for i in range(n):
        ch = s[i]
        if ch.isdigit():
            subs = INV_MIS.get(ch, "")
        else:
            subs = ALLD
        for t in subs:
            yield s[:i] + t + s[i + 1:], b
    for p in range(n + 1):
        for t in ALLD:
            ns = s[:p] + t + s[p:]
            if b is None:
                yield ns, None
            elif p < b:
                yield ns, b + 1
            elif p > b:
                yield ns, b
            else:
                yield ns, b + 1
                yield ns, b
    for i in range(n - 1):
        if s[i] == s[i + 1]:
            ns = s[:i] + s[i + 1:]
            if b is None:
                yield ns, None
            else:
                yield ns, (b - 1 if i < b else b)


def _make_field(s, b, valid, deadline):
    """Lazy level generator: get(k) -> dict of values whose cheapest explanation costs exactly k."""
    st = {"seen": {(s, b)}, "frontier": [(s, b)], "got": set(), "levels": []}
    lvl = {}
    v = valid(s, b)
    if v is not None:
        st["got"].add(v)
        lvl[v] = 1
    st["levels"].append(lvl)

    def get(k):
        while len(st["levels"]) <= k:
            nf = []
            lvl2 = {}
            seen = st["seen"]
            got = st["got"]
            cnt = 0
            stop = False
            for (x, bb) in st["frontier"]:
                cnt += 1
                if (cnt & 63) == 0 and time.perf_counter() > deadline:
                    stop = True
                    break
                for e in _single_edits(x, bb):
                    if e in seen:
                        continue
                    seen.add(e)
                    nf.append(e)
                    vv = valid(e[0], e[1])
                    if vv is not None and vv not in got:
                        got.add(vv)
                        lvl2[vv] = 1
            st["frontier"] = nf
            st["levels"].append(lvl2)
            if stop:
                while len(st["levels"]) <= k:
                    st["levels"].append({})
        return st["levels"][k]
    return get


def _norm_digits(t):
    out = []
    for ch in t:
        if ch.isdigit():
            out.append(ch)
        elif ch in LOOK_D:
            out.append(LOOK_D[ch])
        elif ch.isalnum():
            out.append("?")
    return "".join(out)


def _money_valid(s, b):
    if "?" in s:
        return None
    if b is None:
        if len(s) < 3:
            return None
        if s[0] == "0" and len(s) > 3:
            return None
        return int(s)
    if len(s) - b != 2 or b < 1:
        return None
    if s[0] == "0" and b > 1:
        return None
    return int(s)


def _money_field(tok, dec, deadline):
    t = tok.replace(" ", "").replace("'", "").replace("`", "")
    other = "," if dec == "." else "."
    pos = t.rfind(dec)
    if pos < 0:
        p2 = t.rfind(other)
        if p2 >= 0 and len(t) - p2 - 1 <= 3:
            pos = p2
    if pos >= 0:
        ip = _norm_digits(t[:pos])
        fp = _norm_digits(t[pos + 1:])
        return _make_field(ip + fp, len(ip), _money_valid, deadline)
    return _make_field(_norm_digits(t), None, _money_valid, deadline)


def _qty_valid(s, b):
    if not s or "?" in s or s[0] == "0" or len(s) > 3:
        return None
    v = int(s)
    if 1 <= v <= 500:
        return v
    return None


def _qty_field(tok, deadline):
    t = re.sub(r"(?i)\s*p\s*c\s*s\s*$", "", tok.strip())
    return _make_field(_norm_digits(t), None, _qty_valid, deadline)


def _check_ok(letters, d):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10 == int(d[4])


def _decode_code(tok, deadline):
    t = re.sub(r"\s+", "", tok)
    if len(t) < 2:
        return t
    letters = ""
    for ch in t[:2]:
        if "A" <= ch <= "Z":
            letters += ch
        elif ch in LOOK_L:
            letters += LOOK_L[ch]
        elif "a" <= ch <= "z":
            letters += ch.upper()
        else:
            letters += "A"
    d = _norm_digits(t[2:])

    def valid(s, b):
        if len(s) != 5 or "?" in s:
            return None
        return s if _check_ok(letters, s) else None
    get = _make_field(d, None, valid, deadline + 0.01)
    for k in range(3):
        lv = get(k)
        if lv:
            cands = sorted(lv.keys())
            if len(cands) > 1:
                if len(d) == 4:
                    for c in cands:
                        if c[:4] == d:
                            return letters + c
                if len(d) == 6:
                    for c in cands:
                        if c == d[:5]:
                            return letters + c
            return letters + cands[0]
    dd = (d.replace("?", "0") + "00000")[:5]
    return letters + dd


# ---------------------------------------------------------------- row lattice
def _solve_row(fields, dec, deadline):
    code = _decode_code(fields.get("CODE", ""), deadline)
    Q = _qty_field(fields.get("QTY", ""), deadline)
    U = _money_field(fields.get("UNIT", ""), dec, deadline)
    A = _money_field(fields.get("AMOUNT", ""), dec, deadline)
    est = {0: (1, 1, 1), 1: (60, 120, 120), 2: (1500, 8000, 8000)}
    for c in range(5):
        sols = []
        out_of_time = False
        for i in range(3):
            if out_of_time:
                break
            for j in range(3):
                k = c - i - j
                if k < 0 or k > 2:
                    continue
                if c > 1 and time.perf_counter() > deadline:
                    out_of_time = True
                    break
                sq, su, sa = est[i][0], est[j][1], est[k][2]
                big = max(sq, su, sa)
                if big == sa:
                    qd = Q(i)
                    if not qd:
                        continue
                    ud = U(j)
                    if not ud:
                        continue
                    ad = A(k)
                    if not ad:
                        continue
                    for q in qd:
                        for u in ud:
                            if q * u in ad:
                                sols.append((i, j, k, q, u))
                elif big == su:
                    qd = Q(i)
                    if not qd:
                        continue
                    ad = A(k)
                    if not ad:
                        continue
                    ud = U(j)
                    if not ud:
                        continue
                    for q in qd:
                        for a in ad:
                            if a % q == 0 and (a // q) in ud:
                                sols.append((i, j, k, q, a // q))
                else:
                    ud = U(j)
                    if not ud:
                        continue
                    ad = A(k)
                    if not ad:
                        continue
                    qd = Q(i)
                    if not qd:
                        continue
                    for u in ud:
                        if u == 0:
                            continue
                        for a in ad:
                            if a % u == 0 and (a // u) in qd:
                                sols.append((i, j, k, a // u, u))
        if sols:
            def key(s):
                nf = (s[0] > 0) + (s[1] > 0) + (s[2] > 0)
                return (nf, s[1], s[0], s[3], s[4])
            sols.sort(key=key)
            best = sols[0]
            return {"code": code, "qty": int(best[3]), "unit_cents": int(best[4])}
        if out_of_time or (c >= 1 and time.perf_counter() > deadline):
            break
    # fallback: cheapest standalone readings
    q0 = None
    for k in range(2):
        lv = Q(k)
        if lv:
            q0 = min(lv)
            break
    if q0 is None:
        q0 = 1
    u0 = None
    for k in range(2):
        lv = U(k)
        if lv:
            u0 = min(lv)
            break
    if u0 is None:
        a0 = None
        for k in range(2):
            lv = A(k)
            if lv:
                a0 = min(lv)
                break
        u0 = (a0 // q0) if a0 is not None else 0
    return {"code": code, "qty": int(q0), "unit_cents": int(u0)}


# ---------------------------------------------------------------- layout repair
CODE_RE = re.compile(r"^[A-Z0-9]{2}[0-9OoDQlIiLSsBZzGb?]{4,7}$")
NUM_RE = re.compile(r"^[0-9OoDQlIiLSsBZzGb.,'`]*(\s*pcs)?$")


def _split_line(line, sep):
    if sep == " | ":
        parts = re.split(r"\s*\|\s*", line)
    elif sep == "   ":
        parts = line.split("   ")
    else:
        parts = line.split(sep)
    parts = [p.strip() for p in parts]
    if len(parts) > 1 and parts[-1] == "":
        parts = parts[:-1]
    if len(parts) > 1 and parts[0] == "" and sep in (" | ", "   "):
        parts = parts[1:]
    return parts


def _tok_type_cost(tok, col):
    q = tok.replace(" ", "")
    if col == "CODE":
        if CODE_RE.match(q):
            a = q[0]
            b = q[1]
            if ("A" <= a <= "Z") or ("A" <= b <= "Z"):
                return 0.0
            if a in LOOK_L and b in LOOK_L:
                return 1.0
            return 2.0
        return 3.0
    if not NUM_RE.match(tok):
        return 3.0
    if CODE_RE.match(q) and q[:2].isalpha() and q[:2].isupper():
        return 3.0
    if col == "QTY":
        nd = len(_norm_digits(re.sub(r"\s*pcs$", "", tok)))
        c = 0.0
        if nd > 4:
            c += 1.5
        if "." in tok or "," in tok or "'" in tok:
            c += 1.0
        return c
    c = 0.0
    if tok.endswith("pcs"):
        c += 2.0
    if not ("." in tok or "," in tok):
        c += 0.3
    if len(_norm_digits(tok)) < 2:
        c += 1.0
    return c


def _plausible_line(parts):
    nonempty = False
    for p in parts:
        if p == "":
            continue
        nonempty = True
        q = p.replace(" ", "")
        if CODE_RE.match(q):
            continue
        if NUM_RE.match(p):
            continue
        return False
    return nonempty


def _segment(tokens, cols):
    n = len(tokens)
    if n == 0:
        return []
    INF = float("inf")
    best = [INF] * (n + 1)
    back = [None] * (n + 1)
    best[0] = 0.0
    tc = [[_tok_type_cost(tokens[i], cols[k]) for k in range(4)] for i in range(n)]
    for i in range(n):
        if best[i] == INF:
            continue
        if i + 4 <= n:
            c = best[i] + tc[i][0] + tc[i + 1][1] + tc[i + 2][2] + tc[i + 3][3]
            if c < best[i + 4]:
                best[i + 4] = c
                back[i + 4] = (i, "row", None)
        if i + 3 <= n:
            for miss in range(4):
                cc = 4.0
                ti = i
                for k in range(4):
                    if k == miss:
                        continue
                    cc += tc[ti][k]
                    ti += 1
                c = best[i] + cc
                if c < best[i + 3]:
                    best[i + 3] = c
                    back[i + 3] = (i, "miss", miss)
        c = best[i] + 4.5
        if c < best[i + 1]:
            best[i + 1] = c
            back[i + 1] = (i, "skip", None)
    rows = []
    j = n
    while j > 0:
        i, kind, miss = back[j]
        if kind == "row":
            rows.append(list(tokens[i:i + 4]))
        elif kind == "miss":
            seg = list(tokens[i:i + 3])
            seg.insert(miss, "")
            rows.append(seg)
        j = i
    rows.reverse()
    return rows


def parse_layout(state, params):
    inp = state.get("input")
    text = inp.get("text", "") if isinstance(inp, dict) else ""
    if not isinstance(text, str):
        text = ""
    lines = text.replace("\r", "").split("\n")
    sep = None
    cols = list(COLNAMES)
    for ln in lines:
        m = re.search(r"COLUMNS:\s?(.*)$", ln)
        if m:
            rest = m.group(1)
            pos = []
            for nm in COLNAMES:
                mm = re.search(r"\b" + nm + r"\b", rest)
                if mm:
                    pos.append((mm.start(), mm.end(), nm))
            pos.sort()
            if len(pos) == 4:
                cols = [p[2] for p in pos]
                sep = rest[pos[0][1]:pos[1][0]]
            break
    if sep is not None:
        if "|" in sep:
            sep = " | "
        elif "\t" in sep:
            sep = "\t"
        elif ";" in sep:
            sep = ";"
        elif sep.strip() == "" and len(sep) >= 2:
            sep = "   "
    if sep not in (" | ", "\t", ";", "   "):
        cnt = {" | ": 0, "\t": 0, ";": 0, "   ": 0}
        for ln in lines:
            for s in cnt:
                cnt[s] += ln.count(s)
        sep = max(sorted(cnt), key=lambda s: cnt[s])
    groups = []
    cur = []
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith("MANIFEST") or s.startswith("COLUMNS"):
            continue
        if s.startswith("==") or "SECTION" in s or s.startswith("SUBTOTAL") or s.startswith("TOTAL"):
            if cur:
                groups.append(cur)
            cur = []
            continue
        parts = _split_line(ln, sep)
        if not _plausible_line(parts):
            continue
        cur.extend(parts)
    if cur:
        groups.append(cur)
    rows = []
    for g in groups:
        for r in _segment(g, cols):
            rows.append({cols[k]: r[k] for k in range(4)})
    dot = 0
    com = 0
    for r in rows:
        for c in ("UNIT", "AMOUNT"):
            t = r.get(c, "")
            if re.search(r"\.[0-9OlSBZG]{2}$", t):
                dot += 1
            if re.search(r",[0-9OlSBZG]{2}$", t):
                com += 1
    if dot == 0 and com == 0:
        if re.search(r"(SUBTOTAL|TOTAL)\s+[0-9']+,[0-9]{2}\b", text):
            com = 1
    state["rows"] = rows
    state["dec"] = "," if com > dot else "."
    return state


def solve_rows(state, params):
    t0 = time.perf_counter()
    rows = state.get("rows", []) or []
    dec = state.get("dec", ".")
    items = []
    n = len(rows)
    for idx, r in enumerate(rows):
        remaining = 0.7 - (time.perf_counter() - t0)
        per = max(0.001, remaining / max(1, n - idx))
        deadline = time.perf_counter() + min(per * 2.0, max(0.001, remaining))
        try:
            it = _solve_row(r, dec, deadline)
        except Exception:
            it = {"code": re.sub(r"\s", "", str(r.get("CODE", "")))[:7], "qty": 1, "unit_cents": 0}
        items.append(it)
    state["output"] = {"items": items}
    return state

import re
import time
import heapq

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INV_MIS = {}
for _o, _ss in MIS.items():
    for _s in _ss:
        INV_MIS[_s] = INV_MIS.get(_s, '') + _o
D2LSHOW = {'0': 'Oo', '1': 'lIi', '5': 'Ss', '8': 'B', '2': 'Zz', '6': 'G'}
L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
LET2DIG = {'O': '0', 'I': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6'}
DIG2LET = {v: k for k, v in LET2DIG.items()}
DIGITS = '0123456789'
SUBCAP = 4.0
TOTCAP = 4.0


def _subc(t, s):
    if t == s:
        return 0.0
    if t in DIGITS:
        if s in D2LSHOW.get(t, ''):
            return 1.0
        if s in MIS[t]:
            return 1.0
        if s in DIGITS:
            return 3.0
        return 4.0
    if t.isalpha():
        if LET2DIG.get(t) == s:
            return 1.0
        return 4.0
    if t in '.,' and s in '.,':
        return 2.0
    return 4.0


def dist(S, T):
    n = len(T)
    m = len(S)
    INF = 99.0
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            v = row[j]
            if v >= INF:
                continue
            if j < m and row[j + 1] > v + 3.0:
                row[j + 1] = v + 3.0
            if i < n:
                t = T[i]
                nxt = dp[i + 1]
                if t in DIGITS or t in '.,':
                    lc = 1.0
                elif t == "'":
                    lc = 1.5
                else:
                    lc = 3.0
                if nxt[j] > v + lc:
                    nxt[j] = v + lc
                if j < m:
                    c = v + _subc(t, S[j])
                    if nxt[j + 1] > c:
                        nxt[j + 1] = c
                    if j + 1 < m and t in DIGITS and S[j] == t and S[j + 1] == t:
                        if nxt[j + 2] > v + 1.0:
                            nxt[j + 2] = v + 1.0
    return dp[n][m]


def fmt_money(c, mark, grouped):
    ip = c // 100
    fp = c % 100
    s = str(ip)
    if grouped and len(s) > 3:
        parts = []
        while len(s) > 3:
            parts.append(s[-3:])
            s = s[:-3]
        parts.append(s)
        s = "'".join(reversed(parts))
    return s + mark + ('%02d' % fp)


def strip_pcs(tok):
    return re.sub(r'\s*pcs\s*$', '', tok.strip()).strip()


def normalize_num(tok, money):
    base = 0
    out = []
    for ch in tok:
        if ch in DIGITS:
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
            base += 1
        elif ch in '.,':
            if money:
                if 'M' in out:
                    base += 2
                else:
                    out.append('M')
            else:
                base += 2
        elif ch == "'" or ch == ' ':
            continue
        else:
            base += 2
    return tuple(out), base


def neighbors(s):
    res = set()
    L = len(s)
    for i in range(L):
        ch = s[i]
        if ch == 'M':
            continue
        for o in INV_MIS.get(ch, ''):
            res.add(s[:i] + (o,) + s[i + 1:])
        if i > 0 and s[i - 1] == ch:
            res.add(s[:i] + s[i + 1:])
    for i in range(L + 1):
        for d in DIGITS:
            res.add(s[:i] + (d,) + s[i:])
    return res


def eval_num(s, money):
    if money:
        if 'M' in s:
            k = s.index('M')
            ip = s[:k]
            fp = s[k + 1:]
            if len(fp) != 2 or len(ip) < 1:
                return None
            if len(ip) > 1 and ip[0] == '0':
                return None
            return int(''.join(ip) + ''.join(fp)), 0
        if len(s) < 3:
            return None
        ip = s[:-2]
        if len(ip) > 1 and ip[0] == '0':
            return None
        return int(''.join(s)), 1
    else:
        if len(s) < 1 or len(s) > 3:
            return None
        if s[0] == '0':
            return None
        v = int(''.join(s))
        if v < 1 or v > 500:
            return None
        return v, 0


def gen_num(tok, money, maxedits):
    start, base = normalize_num(tok, money)
    seen = {start: 0}
    frontier = [start]
    for lev in range(1, maxedits + 1):
        nf = []
        for s in frontier:
            for t in neighbors(s):
                if t not in seen:
                    seen[t] = lev
                    nf.append(t)
        frontier = nf
    out = {}
    for s, e in seen.items():
        r = eval_num(s, money)
        if r is None:
            continue
        v, x = r
        c = base + e + x
        if v not in out or out[v] > c:
            out[v] = c
    return out


def _check_for(l1, l2, d4):
    return (int(d4[0]) + 2 * int(d4[1]) + 3 * int(d4[2]) + 4 * int(d4[3]) + ord(l1) - 64 + ord(l2) - 64) % 10


def _code_parts(tok):
    s = re.sub(r'\s', '', tok)
    if len(s) < 2:
        s = (s + 'XX')[:2]
    lets = []
    for ch in s[:2]:
        if 'A' <= ch <= 'Z':
            lets.append([(ch, 1.0)])
        elif ch in DIG2LET:
            lets.append([(DIG2LET[ch], 1.0)])
        elif ch.isalpha():
            lets.append([(ch.upper(), 1.0)])
        else:
            lets.append([(chr(65 + k), 1.0 / 26) for k in range(26)])
    r = []
    for ch in s[2:]:
        if ch in DIGITS:
            r.append(ch)
        elif ch in L2D:
            r.append(L2D[ch])
    return lets, tuple(r)


def fix_code_old(tok):
    lets0, start = _code_parts(tok)
    lets = [[(l, 0.0 if p >= 1.0 else 2.0) for l, p in ls] for ls in lets0]
    base = 0.0
    L = len(start)
    limit = 3.2 if L in (4, 5, 6) else abs(L - 5) + 1.2
    heap = [(0.0, start)]
    bestc = {start: 0.0}
    cands = []
    pops = 0
    while heap and pops < 8000:
        c, x = heapq.heappop(heap)
        if c > bestc.get(x, 99.0) + 1e-9:
            continue
        pops += 1
        n = len(x)
        if n == 5:
            ds = ''.join(x)
            cd = int(ds[4])
            for l1, c1 in lets[0]:
                for l2, c2 in lets[1]:
                    if _check_for(l1, l2, ds[:4]) == cd:
                        cands.append((base + c + c1 + c2, l1 + l2 + ds))
        moves = []
        for i in range(n):
            ch = x[i]
            for o in INV_MIS.get(ch, ''):
                moves.append((0.9 if o == '2' else 1.0, x[:i] + (o,) + x[i + 1:]))
        if n < 5:
            for i in range(n + 1):
                for d in DIGITS:
                    adj = (i > 0 and x[i - 1] == d) or (i < n and x[i] == d)
                    moves.append((0.95 if adj else 1.0, x[:i] + (d,) + x[i:]))
        if n > 5:
            for i in range(n):
                if i > 0 and x[i] == x[i - 1]:
                    moves.append((1.0, x[:i] + x[i + 1:]))
                else:
                    moves.append((2.0, x[:i] + x[i + 1:]))
        for mc, y in moves:
            nc = c + mc
            if nc + 0.95 * abs(len(y) - 5) > limit:
                continue
            if nc < bestc.get(y, 99.0) - 1e-9:
                bestc[y] = nc
                heapq.heappush(heap, (nc, y))
    if cands:
        cands.sort()
        return cands[0][1]
    return _cheap_code(tok)


def _cheap_code(tok):
    lets, x = _code_parts(tok)
    ds = (''.join(x) + '00000')[:4]
    l1 = lets[0][0][0]
    l2 = lets[1][0][0]
    return l1 + l2 + ds + str(_check_for(l1, l2, ds))


def _q(o, s, rm):
    ms = MIS[o]
    if s in ms:
        return rm / len(ms)
    return rm * 0.02


def _fwd(y, x, keep, rm, rl, rp):
    m = len(x)
    F = [[0.0] * (m + 1) for _ in range(6)]
    F[0][0] = 1.0
    for i in range(5):
        o = y[i]
        Fi = F[i]
        Fn = F[i + 1]
        for j in range(m + 1):
            v = Fi[j]
            if v == 0.0:
                continue
            Fn[j] += v * rl
            if j < m:
                s = x[j]
                e1 = 1.0 if s == o else _q(o, s, rm)
                Fn[j + 1] += v * (keep if s == o else e1)
                if j + 1 < m:
                    s2 = x[j + 1]
                    e2 = 1.0 if s2 == o else _q(o, s2, rm)
                    Fn[j + 2] += v * rp * e1 * e2
    return F[5][m]


def _gen_code_cands(x, maxd):
    seen = {x}
    frontier = [x]
    for _ in range(maxd):
        nf = []
        for z in frontier:
            n = len(z)
            outs = []
            for i in range(n):
                for o in INV_MIS.get(z[i], ''):
                    outs.append(z[:i] + (o,) + z[i + 1:])
            if n < 5:
                for i in range(n + 1):
                    for dd in DIGITS:
                        outs.append(z[:i] + (dd,) + z[i:])
            if n > 5:
                for i in range(n):
                    outs.append(z[:i] + z[i + 1:])
            for w in outs:
                if w not in seen:
                    seen.add(w)
                    nf.append(w)
        frontier = nf
    if len(x) == 5:
        for i in range(5):
            z = x[:i] + x[i + 1:]
            for k in range(5):
                for dd in DIGITS:
                    seen.add(z[:k] + (dd,) + z[k:])
    return [z for z in seen if len(z) == 5]


def fix_code2(tok, rates):
    lets, x = _code_parts(tok)
    m = len(x)
    need = abs(m - 5)
    if need > 3 or m == 0:
        return fix_code_old(tok)
    rm, rl, rp = rates
    keep = max(0.5, 1.0 - rm - rl - rp)
    maxd = need + 1 if need <= 1 else need
    C = _gen_code_cands(x, maxd)

    def score_set(cs):
        best = None
        for y in cs:
            ds = ''.join(y)
            cd = int(ds[4])
            ok = []
            for l1, p1 in lets[0]:
                for l2, p2 in lets[1]:
                    if _check_for(l1, l2, ds[:4]) == cd:
                        ok.append((p1 * p2, l1 + l2))
            if not ok:
                continue
            lik = _fwd(y, x, keep, rm, rl, rp)
            for p, ll in ok:
                sc = p * lik
                key = (sc, ll + ds)
                if best is None or sc > best[0] or (sc == best[0] and ll + ds < best[1]):
                    best = key
        return best

    best = score_set(C)
    if best is None or best[0] <= 0.0:
        ext = set()
        base = C[:200] if C else []
        if not base:
            base = [tuple((list(x) + ['0'] * 5)[:5])]
        for y in base:
            for i in range(5):
                for dd in DIGITS:
                    ext.add(y[:i] + (dd,) + y[i + 1:])
        b2 = score_set(list(ext))
        if b2 is not None and (best is None or b2[0] > best[0]):
            best = b2
    if best is None:
        return fix_code_old(tok)
    return best[1]


KEY_RE = re.compile(r'\b(CODE|QTY|UNIT|AMOUNT)\b')
CODEISH = re.compile(r"^[A-Za-z0-9]{2}[0-9OolIiSsBZzG]{2,8}$")
NUMISH = re.compile(r"^[0-9OolIiSsBZzG.,']*(\s*pcs)?$")


def tok_cost(tok, col):
    if tok == '':
        return 1.0
    has_pcs = 'pcs' in tok
    t = strip_pcs(tok)
    has_mark = ('.' in t) or (',' in t)
    strong_code = any(ch.isalpha() and ch not in 'OlSBZG' for ch in t)
    weak_code = (len(t) >= 5 and not has_mark and "'" not in t
                 and len(t) >= 2 and t[0].isalpha() and t[1].isalpha())
    if col == 'CODE':
        if strong_code:
            return 0.0
        if weak_code:
            return 0.5
        if has_mark or has_pcs or "'" in t:
            return 5.0
        return 2.5
    if strong_code:
        return 5.0
    extra = 1.5 if weak_code else 0.0
    if col == 'QTY':
        if has_pcs:
            return 0.0 + extra
        if has_mark or "'" in t:
            return 3.0 + extra
        L = len(t)
        if L <= 3:
            return 0.0 + extra
        if L == 4:
            return 0.7 + extra
        return 2.0 + extra
    if has_pcs:
        return 5.0
    if has_mark:
        return 0.0 + extra
    return (1.0 if len(t) >= 3 else 2.0) + extra


def segment(toks, order):
    n = len(toks)
    INF = 1e18
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(4):
            for c in range(4):
                if dp[i][c] < INF:
                    nc = (c + 1) % 4
                    v = dp[i][c] + 3.0
                    if v < dp[i][nc] - 1e-12:
                        dp[i][nc] = v
                        bk[i][nc] = ('miss', i, c)
        if i == n:
            break
        tok = toks[i]
        for c in range(4):
            if dp[i][c] >= INF:
                continue
            nc = (c + 1) % 4
            v = dp[i][c] + tok_cost(tok, order[c])
            if v < dp[i + 1][nc] - 1e-12:
                dp[i + 1][nc] = v
                bk[i + 1][nc] = ('use', i, c)
            v = dp[i][c] + (2.0 if tok == '' else 6.0)
            if v < dp[i + 1][c] - 1e-12:
                dp[i + 1][c] = v
                bk[i + 1][c] = ('skip', i, c)
    ops = []
    i, c = n, 0
    guard = 0
    while bk[i][c] is not None and guard < 10 * (n + 10):
        op, pi, pc = bk[i][c]
        ops.append((op, pi))
        i, c = pi, pc
        guard += 1
    ops.reverse()
    rows = []
    cur = {}
    c = 0
    for op, ti in ops:
        if op == 'skip':
            continue
        cur[order[c]] = toks[ti] if op == 'use' else ''
        c += 1
        if c == 4:
            if any(cur[k] for k in order):
                rows.append(cur)
            cur = {}
            c = 0
    return rows


def parse_doc(text):
    lines = text.replace('\r', '').split('\n')
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        st = ln.strip()
        if st.startswith('COLUMNS'):
            ms = list(KEY_RE.finditer(ln))
            if len(ms) >= 2:
                names = [m.group(1) for m in ms]
                if len(names) == 4 and len(set(names)) == 4:
                    order = names
                sp = ln[ms[0].end():ms[1].start()]
                if '|' in sp:
                    sep = '|'
                elif ';' in sp:
                    sep = ';'
                elif '\t' in sp:
                    sep = '\t'
                else:
                    sep = '   '
            break

    def split_line(s):
        if sep in ('|', ';', '\t'):
            return [t.strip() for t in s.split(sep)]
        return [t.strip() for t in s.split('   ')]

    def is_data(toks):
        if not [t for t in toks if t]:
            return False
        for t in toks:
            if not t:
                continue
            if CODEISH.match(t) or NUMISH.match(t):
                continue
            return False
        return True

    sections = []
    cur = None
    total_tok = None
    items_tok = None
    for ln in lines:
        st = ln.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r'^==\s*SECTION', st):
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            cur = None
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', st)
            if m:
                total_tok = m.group(1).strip()
                items_tok = m.group(2).strip()
            else:
                total_tok = st[5:].strip()
            continue
        toks = split_line(ln)
        if not is_data(toks):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
        cur['tokens'].extend(toks)
    out_secs = []
    for sec in sections:
        rows = segment(sec['tokens'], order)
        if rows or sec['sub'] is not None:
            out_secs.append({'rows': rows, 'sub': sec['sub']})
    return out_secs, total_tok, items_tok


def detect_style(secs, total_tok):
    toks = []
    for sec in secs:
        for r in sec['rows']:
            toks.append(r['UNIT'])
            toks.append(r['AMOUNT'])
        if sec['sub']:
            toks.append(sec['sub'])
    if total_tok:
        toks.append(total_tok)
    dot = sum(t.count('.') for t in toks)
    com = sum(t.count(',') for t in toks)
    mark = ',' if com > dot else '.'
    grouped = any("'" in t for t in toks)
    return mark, grouped


def row_candidates(row, ctx, K):
    mark = ctx['mark']
    grouped = ctx['grouped']
    qtok = strip_pcs(row['QTY'])
    utok = row['UNIT'].strip()
    atok = row['AMOUNT'].strip()
    Q = gen_num(qtok, False, 1)
    U = gen_num(utok, True, 1)
    A = gen_num(atok, True, 1)
    cands = {}

    def add(q, u, a, c):
        key = (q, u)
        if key not in cands or cands[key][0] > c:
            cands[key] = (c, q, u, a)

    for q, cq in Q.items():
        for u, cu in U.items():
            a = q * u
            ca = A.get(a)
            if ca is not None:
                add(q, u, a, cq + cu + ca)
    best = min([v[0] for v in cands.values()]) if cands else 99
    if best >= 2 and time.perf_counter() < ctx['deadline']:
        cache = {}

        def dmon(tok, v):
            k = ('m', tok, v)
            if k not in cache:
                cache[k] = dist(tok, fmt_money(v, mark, grouped))
            return cache[k]

        def dq(v):
            k = ('q', v)
            if k not in cache:
                cache[k] = dist(qtok, str(v))
            return cache[k]

        for lim in (0, 1):
            Q0 = [(q, c) for q, c in Q.items() if c <= lim]
            U0 = [(u, c) for u, c in U.items() if c <= lim]
            A0 = [(a, c) for a, c in A.items() if c <= lim]
            for q, cq in Q0:
                for u, cu in U0:
                    if cq + cu <= lim:
                        a = q * u
                        add(q, u, a, cq + cu + dmon(atok, a))
                for a, ca in A0:
                    if cq + ca <= lim and a > 0 and a % q == 0:
                        u = a // q
                        add(q, u, a, cq + ca + dmon(utok, u))
            for u, cu in U0:
                if u <= 0:
                    continue
                for a, ca in A0:
                    if cu + ca <= lim and a % u == 0:
                        q = a // u
                        if 1 <= q <= 500:
                            add(q, u, a, cu + ca + dq(q))
            best = min([v[0] for v in cands.values()]) if cands else 99
            if best < 3 or time.perf_counter() > ctx['deadline']:
                break
    if not cands:
        q = min(Q.items(), key=lambda x: (x[1], x[0]))[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: (x[1], x[0]))[0]
        elif A:
            a0 = min(A.items(), key=lambda x: (x[1], x[0]))[0]
            u = a0 // q
        else:
            u = 0
        add(q, u, q * u, 9.0)
    lst = sorted(cands.values(), key=lambda x: (x[0], x[1], x[2]))
    return [list(x) for x in lst[:K]]


def section_search(rcands, subtok, ctx, B=400, M=40, DEV=6.0):
    states = {0: (0.0, ())}
    for cl in rcands:
        ns = {}
        for s, (c, path) in states.items():
            for ci, rc in enumerate(cl):
                t = s + rc[3]
                nc = c + rc[0]
                if t not in ns or ns[t][0] > nc:
                    ns[t] = (nc, path + (ci,))
        if not ns:
            continue
        items = sorted(ns.items(), key=lambda x: x[1][0])
        bc = items[0][1][0]
        items = [it for it in items if it[1][0] <= bc + DEV][:B]
        states = dict(items)
    items = sorted(states.items(), key=lambda x: x[1][0])
    res = []
    if subtok is None:
        for s, (c, path) in items[:M]:
            res.append((c, s, path))
        return res
    S1 = gen_num(subtok, True, 1)
    mark = ctx['mark']
    grouped = ctx['grouped']
    for idx, (s, (c, path)) in enumerate(items):
        sc = S1.get(s)
        if sc is None:
            if idx < 40 and time.perf_counter() < ctx['deadline'] + 0.1:
                sc = dist(subtok, fmt_money(s, mark, grouped))
            else:
                sc = SUBCAP
        sc = min(sc, SUBCAP)
        res.append((c + sc, s, path))
    res.sort(key=lambda x: x[0])
    return res[:M]


def residual_fill(rcands, rows, subtok, ctx, res):
    if not subtok or not res or not rcands:
        return False
    mark = ctx['mark']
    grouped = ctx['grouped']
    S1 = gen_num(subtok, True, 1)
    c0, s0, path = res[0]
    if S1.get(s0, 99) == 0:
        return False
    Ss = sorted(S1.items(), key=lambda x: (x[1], x[0]))
    Ss = [v for v, c in Ss if c <= 1][:14]
    if not Ss or len(path) != len(rcands):
        return False
    picks = [rcands[i][path[i]] for i in range(len(rcands))]
    order = sorted(range(len(rcands)), key=lambda i: -picks[i][0])
    cand_rows = [i for i in order if picks[i][0] >= 1][:6]
    if not cand_rows:
        cand_rows = order[:3]
    changed = False
    for i in cand_rows:
        if time.perf_counter() > ctx['deadline2']:
            break
        row = rows[i]
        qtok = strip_pcs(row['QTY'])
        utok = row['UNIT'].strip()
        atok = row['AMOUNT'].strip()
        others = s0 - picks[i][3]
        Q2 = gen_num(qtok, False, 2)
        U1 = gen_num(utok, True, 1)
        existing = set((x[1], x[2]) for x in rcands[i])
        newc = {}
        for S in Ss:
            a = S - others
            if a <= 0:
                continue
            ca = dist(atok, fmt_money(a, mark, grouped))
            if ca > 4.0:
                continue
            for q, cq in Q2.items():
                if a % q == 0:
                    u = a // q
                    cu = U1.get(u)
                    if cu is None:
                        if cq + ca > 4.5:
                            continue
                        cu = dist(utok, fmt_money(u, mark, grouped))
                    c = cq + cu + ca
                    if c <= 5.0:
                        k = (q, u)
                        if k not in newc or newc[k][0] > c:
                            newc[k] = [c, q, u, a]
            for u, cu in U1.items():
                if u > 0 and a % u == 0:
                    q = a // u
                    if 1 <= q <= 500:
                        cq = Q2.get(q)
                        if cq is None:
                            cq = dist(qtok, str(q))
                        c = cq + cu + ca
                        if c <= 5.0:
                            k = (q, u)
                            if k not in newc or newc[k][0] > c:
                                newc[k] = [c, q, u, a]
        add = sorted([v for k, v in newc.items() if k not in existing], key=lambda x: (x[0], x[1], x[2]))[:4]
        if add:
            rcands[i].extend(add)
            changed = True
    return changed


def _digits_only(tok):
    out = []
    for ch in tok:
        if ch in DIGITS:
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
    return out


def estimate_rates(rows_flat, chosen, mark, grouped):
    N = 0
    S = 0
    L = 0
    P = 0

    def acc(obs, tru):
        nonlocal N, S, L, P
        d = len(obs) - len(tru)
        if abs(d) > 2:
            return
        if d == 0:
            mm = sum(1 for a, b in zip(obs, tru) if a != b)
            if mm > 3:
                return
            S += mm
        elif d < 0:
            L += -d
        else:
            P += d
        N += len(tru)

    for row, rc in zip(rows_flat, chosen):
        q, u = rc
        acc(_digits_only(strip_pcs(row['QTY'])), list(str(q)))
        acc(_digits_only(row['UNIT']), [c for c in fmt_money(u, mark, False) if c in DIGITS])
        acc(_digits_only(row['AMOUNT']), [c for c in fmt_money(q * u, mark, False) if c in DIGITS])
        lets, x = _code_parts(row['CODE'])
        m = len(x)
        if m == 5:
            ds = ''.join(x)
            try:
                okc = any(_check_for(l1, l2, ds[:4]) == int(ds[4]) for l1, _ in lets[0] for l2, _ in lets[1])
            except Exception:
                okc = True
            if not okc:
                S += 1
            N += 5
        elif m < 5:
            L += 5 - m
            N += 5
        else:
            P += m - 5
            N += 5
    rm = (S + 1.0) / (N + 100.0)
    rl = (L + 1.0) / (N + 100.0)
    rp = (P + 1.0) / (N + 100.0)
    rm = min(max(rm, 0.002), 0.3)
    rl = min(max(rl, 0.002), 0.3)
    rp = min(max(rp, 0.002), 0.3)
    return rm, rl, rp


def _solve_text(text, t0):
    secs, total_tok, items_tok = parse_doc(text)
    mark, grouped = detect_style(secs, total_tok)
    ctx = {'mark': mark, 'grouped': grouped, 'deadline': t0 + 0.45, 'deadline2': t0 + 0.65}
    all_rc = []
    for sec in secs:
        rcs = []
        for r in sec['rows']:
            rcs.append(row_candidates(r, ctx, 8))
        all_rc.append(rcs)
    sec_res = []
    for si, sec in enumerate(secs):
        res = section_search(all_rc[si], sec['sub'], ctx)
        try:
            if residual_fill(all_rc[si], sec['rows'], sec['sub'], ctx, res):
                res = section_search(all_rc[si], sec['sub'], ctx)
        except Exception:
            pass
        sec_res.append(res)
    states = {0: (0.0, ())}
    for si in range(len(sec_res)):
        res = sec_res[si]
        if not res:
            res = [(0.0, 0, ())]
            sec_res[si] = res
        ns = {}
        for s, (c, ch) in states.items():
            for k, (sc, ss, path) in enumerate(res):
                t = s + ss
                nc = c + sc
                if t not in ns or ns[t][0] > nc:
                    ns[t] = (nc, ch + (k,))
        items = sorted(ns.items(), key=lambda x: x[1][0])[:500]
        states = dict(items)
    items = sorted(states.items(), key=lambda x: x[1][0])
    best = None
    if total_tok and items:
        T1 = gen_num(total_tok, True, 1)
        for idx, (s, (c, ch)) in enumerate(items):
            tc = T1.get(s)
            if tc is None:
                if idx < 40 and time.perf_counter() < ctx['deadline2'] + 0.05:
                    tc = dist(total_tok, fmt_money(s, mark, grouped))
                else:
                    tc = TOTCAP
            tc = min(tc, TOTCAP)
            v = c + tc
            if best is None or v < best[0]:
                best = (v, ch)
    elif items:
        best = (items[0][1][0], items[0][1][1])
    choice = best[1] if best else ()
    rows_flat = []
    chosen = []
    for si in range(len(secs)):
        res = sec_res[si]
        if res and si < len(choice) and choice[si] < len(res):
            path = res[choice[si]][2]
        else:
            path = ()
        for ri in range(len(all_rc[si])):
            ci = path[ri] if ri < len(path) else 0
            cl = all_rc[si][ri]
            rc = cl[ci] if ci < len(cl) else cl[0]
            rows_flat.append(secs[si]['rows'][ri])
            chosen.append((int(rc[1]), int(rc[2])))
    try:
        rates = estimate_rates(rows_flat, chosen, mark, grouped)
    except Exception:
        rates = (0.01, 0.01, 0.01)
    out = []
    code_deadline = t0 + 0.88
    for row, (q, u) in zip(rows_flat, chosen):
        tok = row['CODE']
        code = None
        if time.perf_counter() < code_deadline:
            try:
                code = fix_code2(tok, rates)
            except Exception:
                code = None
        if code is None:
            try:
                code = _cheap_code(tok)
            except Exception:
                code = 'AA00000'
        out.append({'code': code, 'qty': q, 'unit_cents': u})
    return out


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get('input', {}) or {}
    text = inp.get('text', '') or ''
    try:
        items = _solve_text(text, t0)
    except Exception:
        items = []
    state['output'] = {'items': items}
    return state
